) as scene(slug, parent_slug, arc_slug, backbone_ordinal, turn_ordinal_in_arc, detail_ordinal, source_range, visual_direction, publication_state)
join public.narrative_series series on series.slug = 'ramayana-dutt-consumer-v1'
join public.narrative_arcs arc on arc.series_id = series.id and arc.slug = scene.arc_slug
join public.narrative_moments parent on parent.series_id = series.id and parent.slug = scene.parent_slug
on conflict (series_id, slug) do update set
  arc_id = excluded.arc_id,
  parent_moment_id = excluded.parent_moment_id,
  moment_kind = excluded.moment_kind,
  backbone_ordinal = excluded.backbone_ordinal,
  turn_ordinal_in_arc = excluded.turn_ordinal_in_arc,
  detail_ordinal = excluded.detail_ordinal,
  source_range = excluded.source_range,
  visual_direction = excluded.visual_direction,
  rights_lane = excluded.rights_lane,
  publication_state = excluded.publication_state,
  updated_at = now();

insert into public.narrative_moment_texts (
  moment_id, language_code, title, synopsis, narrative, text_status,
  rights_lane, publication_state
)
select moment.id, copy.language_code, copy.title, copy.synopsis, copy.narrative,
  copy.text_status, 'derivative_allowed', copy.publication_state::public.publication_state
from (values
  ('turn-story-finds-a-voice', 'en', 'A story finds its voice', 'A question to Narada becomes Valmiki''s vision, then a story taught to two young singers.', 'A question to Narada becomes Valmiki''s vision, then a story taught to two young singers.', 'source_aligned', 'published'),
  ('turn-story-finds-a-voice', 'hi', 'कथा को स्वर मिलता है', 'नारद से पूछा गया प्रश्न वाल्मीकि की दृष्टि और फिर दो बाल गायकों की कथा बनता है।', 'नारद से पूछा गया प्रश्न वाल्मीकि की दृष्टि और फिर दो बाल गायकों की कथा बनता है।', 'source_aligned', 'published'),
  ('scene-valmiki-asks-for-complete-human', 'en', 'Valmiki asks whether such a person exists', 'A question about the best possible human life opens the entire Ramayana.', 'Valmiki asks Narada for someone living in the world who joins courage with compassion, truth with self-control, learning with practical judgment, and power with concern for others. He is not asking for a flawless statue, but for a life whose choices can be followed. Narada considers the demanding list and names Rama of the Ikshvaku line. He describes a prince disciplined in speech and anger, formidable in danger, attentive to duty, and able to make people feel protected rather than merely ruled. Narada races ahead: Dasharatha prepares to install Rama, Kaikeyi claims her old boons, and Rama accepts fourteen years of exile. Sita and Lakshmana choose to go with him, turning a political rupture into a shared journey away from Ayodhya. The forest story breaks when Ravana abducts Sita and Jatayu falls trying to stop him. Rama and Lakshmana''s search reaches Sugriva and Hanuman; grief becomes alliance, and scattered clues begin pointing across the ocean toward Lanka. Narada''s preview crosses Hanuman''s leap, the bridge, the war, Ravana''s fall, Sita''s recovery, and the return to Ayodhya. It ends with the selected source''s sacred vision of Rama''s reign, giving Valmiki the scale of the life he is about to tell rather than replacing the journey itself.', 'source_aligned', 'published'),
  ('scene-valmiki-asks-for-complete-human', 'hi', 'वाल्मीकि पूछते हैं—क्या ऐसा मनुष्य है?', 'एक आदर्श मनुष्य की खोज का प्रश्न पूरी रामायण का द्वार खोल देता है।', 'वाल्मीकि नारद से ऐसे जीवित मनुष्य के बारे में पूछते हैं जिसमें साहस के साथ करुणा, सत्य के साथ संयम, ज्ञान के साथ व्यवहार-बुद्धि और शक्ति के साथ सबके हित की चिंता हो। वे किसी निर्जीव आदर्श की नहीं, ऐसे जीवन की खोज कर रहे हैं जिसके निर्णयों का अनुसरण किया जा सके। नारद उस कठिन सूची पर विचार करके इक्ष्वाकु वंश के राम का नाम लेते हैं। वे ऐसे राजकुमार का परिचय देते हैं जो वाणी और क्रोध पर संयम रखता है, संकट में प्रबल है, कर्तव्य के प्रति सजग है और लोगों को केवल शासित नहीं बल्कि सुरक्षित अनुभव कराता है। नारद कथा को तेजी से आगे ले जाते हैं—दशरथ राम के राज्याभिषेक की तैयारी करते हैं, कैकेयी पुराने वरदान माँगती हैं और राम चौदह वर्ष का वनवास स्वीकार कर लेते हैं। सीता और लक्ष्मण साथ चलने का निर्णय लेते हैं; राजमहल का संकट अयोध्या से दूर एक साझा यात्रा बन जाता है। वन की कथा तब टूटती है जब रावण सीता का हरण करता है और उसे रोकते हुए जटायु गिर पड़ते हैं। राम और लक्ष्मण की खोज सुग्रीव और हनुमान तक पहुँचती है; शोक मित्रता में बदलता है और बिखरे संकेत समुद्र पार लंका की ओर इशारा करने लगते हैं। नारद की झलक हनुमान की छलाँग, सेतु, युद्ध, रावण के पतन, सीता की पुनर्प्राप्ति और अयोध्या वापसी से होकर गुजरती है। वह चुने हुए स्रोत में राम-राज्य की पवित्र कल्पना पर ठहरती है—यह आने वाली यात्रा का स्थान नहीं लेती, बल्कि वाल्मीकि को उस जीवन का विस्तार दिखाती है जिसे वे कथा बनाएँगे।', 'source_aligned', 'published'),
  ('scene-grief-becomes-first-verse', 'en', 'A hunter''s arrow turns grief into verse', 'Witnessed suffering changes ordinary speech into the form that will carry the epic.', 'After Narada leaves, Valmiki walks with his disciple Bharadwaja to the Tamasa. The clear water and mudless bank promise a calm place for bathing; the scene begins in careful attention to an ordinary, peaceful landscape. Near the water, Valmiki notices a pair of krauncha birds calling to one another and moving in complete ease. Their unguarded companionship gives the next instant its force: nothing in the scene has prepared them for violence. A hunter shoots the male bird without any quarrel or threat. He falls bleeding before Valmiki, and the surviving bird''s cry turns the death from a distant act into a felt separation witnessed at close range. Compassion and anger rise together in Valmiki. His rebuke to the hunter comes out in equal measured parts; only after speaking does he notice that grief has shaped itself into a repeatable verse, shoka becoming shloka in the story''s own explanation. Back at the hermitage, Valmiki cannot stop thinking about the needless killing. Brahma appears and tells him the metre did not arise in vain: he must use it to tell Rama''s whole story truthfully, including what he has not yet seen, so that the poem can travel through the world.', 'source_aligned', 'published'),
  ('scene-grief-becomes-first-verse', 'hi', 'शिकारी का बाण शोक को श्लोक बना देता है', 'आँखों के सामने हुआ दुःख साधारण वाणी को उस छंद में बदल देता है जो महाकाव्य को आगे ले जाएगा।', 'नारद के जाने के बाद वाल्मीकि अपने शिष्य भरद्वाज के साथ तमसा नदी तक जाते हैं। निर्मल जल और कीचड़-रहित तट स्नान के लिए शांत स्थान का आभास देते हैं; दृश्य एक साधारण, शांत भू-दृश्य को ध्यान से देखने के साथ आरंभ होता है। जल के पास वाल्मीकि क्रौंच पक्षियों के एक जोड़े को एक-दूसरे को पुकारते और निश्चिंत होकर विचरते देखते हैं। उनका सहज साथ अगले क्षण को और तीखा बना देता है—दृश्य में ऐसा कुछ नहीं था जो उन्हें हिंसा के लिए तैयार करता। एक शिकारी बिना किसी झगड़े या खतरे के नर पक्षी को मार देता है। वह वाल्मीकि के सामने रक्त से भीगा गिरता है और जीवित पक्षी का विलाप उस मृत्यु को दूर की घटना नहीं रहने देता; बिछोह सबके सामने अनुभव होने लगता है। वाल्मीकि के भीतर करुणा और आक्रोश एक साथ उठते हैं। शिकारी के लिए निकली उनकी वाणी समान लयबद्ध भागों में ढल जाती है; बोलने के बाद उन्हें समझ आता है कि शोक ने स्वयं को दोहराए जा सकने वाले श्लोक का रूप दे दिया है। आश्रम लौटकर भी वाल्मीकि उस निरर्थक हत्या को भूल नहीं पाते। ब्रह्मा प्रकट होकर कहते हैं कि वह छंद व्यर्थ नहीं आया—उसी में राम की पूरी कथा सत्यपूर्वक कही जाए, यहाँ तक कि वह भी जो अभी वाल्मीकि ने नहीं देखा, ताकि यह कथा संसार में यात्रा कर सके।', 'source_aligned', 'published'),
  ('scene-valmiki-sees-the-whole-life', 'en', 'The poet sees events near and far', 'The rapid outline becomes a lived world that Valmiki can see from beginning to end.', 'Valmiki sits facing east, steadies himself, and turns from Narada''s summary toward sustained contemplation. The story presents this as a change in access: he is no longer arranging hearsay but watching people speak, move, choose, and endure as if they were before him. He sees Rama, Sita, Lakshmana, Dasharatha, and the queens not as names in a list but laughing, speaking, and acting inside their household. That ordinary movement matters because exile will soon separate the same people and transform every familiar room. Birth, marriage, the broken bow, the lost coronation, exile, forest encounters, Sita''s abduction, the alliance with Sugriva, Hanuman''s search, and the war in Lanka unfold as connected consequences. Valmiki sees not only milestones but the conversations and grief that move people between them. The vision reaches the return, installation, and events the selected telling places later, including Sita''s eventual separation. Holding past and future together, Valmiki begins composing a story large enough for triumph, doubt, tenderness, violence, and unresolved pain.', 'source_aligned', 'published'),
  ('scene-valmiki-sees-the-whole-life', 'hi', 'कवि निकट और दूर की घटनाएँ देखते हैं', 'तेज़ी से सुनाई गई रूपरेखा एक ऐसे जीवित संसार में बदल जाती है जिसे वाल्मीकि आरंभ से अंत तक देख सकते हैं।', 'वाल्मीकि पूर्व की ओर बैठकर स्वयं को स्थिर करते हैं और नारद की संक्षिप्त रूपरेखा से गहरे ध्यान की ओर बढ़ते हैं। कथा इसे दृष्टि के परिवर्तन की तरह दिखाती है—अब वे सुनी-सुनाई बातों को नहीं जोड़ रहे, बल्कि लोगों को अपने सामने बोलते, चलते, चुनते और सहते देख रहे हैं। वे राम, सीता, लक्ष्मण, दशरथ और रानियों को नामों की सूची की तरह नहीं, बल्कि परिवार में हँसते, बोलते और काम करते देखते हैं। यह सामान्य जीवन इसलिए महत्त्वपूर्ण है क्योंकि वनवास शीघ्र ही इन्हीं लोगों को अलग करेगा और हर परिचित कक्ष का अर्थ बदल देगा। जन्म, विवाह, धनुष-भंग, रुका हुआ राज्याभिषेक, वनवास, वन के प्रसंग, सीता-हरण, सुग्रीव से मित्रता, हनुमान की खोज और लंका का युद्ध जुड़े हुए परिणामों की तरह खुलते हैं। वाल्मीकि केवल पड़ाव नहीं, उन संवादों और दुःखों को भी देखते हैं जो लोगों को एक पड़ाव से दूसरे तक ले जाते हैं। दृष्टि वापसी, राज्याभिषेक और चुनी हुई कथा में आगे आने वाली घटनाओं तक पहुँचती है, जिनमें सीता का बाद का वियोग भी शामिल है। अतीत और भविष्य को साथ रखकर वाल्मीकि ऐसी कथा रचना आरंभ करते हैं जिसमें विजय, संदेह, स्नेह, हिंसा और अधूरा दुःख सबके लिए स्थान हो।', 'source_aligned', 'published'),
  ('scene-lava-kusha-carry-the-story', 'en', 'Lava and Kusha carry the story into the world', 'A composed epic becomes a living performance and returns, through two young singers, to Rama himself.', 'After composing the Ramayana, Valmiki asks a practical question: who can bring so vast a work before real audiences? Lava and Kusha arrive at the hermitage with strong memories, musical ability, disciplined study, and the patience to learn meaning rather than merely recite sound. The brothers learn melody, measure, expression, movement, and the changing emotional colours of love, grief, humour, anger, fear, and courage. Performance is not decoration here; it is the technology that makes thousands of connected events graspable and memorable. Lava and Kusha sing before gatherings of sages. Listeners are moved, praise the clarity and beauty of the telling, and offer the young performers the simple possessions available in hermitage life. The gifts show a story already travelling through relationship, not through royal command. In Ayodhya, Rama notices the two ascetic-looking singers and brings them before his brothers and counsellors. As they begin, the court is captivated and Rama recognises signs of royalty in them; the epic''s frame closes on a startling encounter between a life, its retelling, and the people who do not yet understand every bond joining them.', 'source_aligned', 'published'),
  ('scene-lava-kusha-carry-the-story', 'hi', 'लव और कुश कथा को संसार में ले जाते हैं', 'रचा हुआ महाकाव्य दो युवा गायकों के माध्यम से जीवित प्रस्तुति बनकर स्वयं राम के सामने लौटता है।', 'रामायण की रचना के बाद वाल्मीकि एक व्यावहारिक प्रश्न पूछते हैं—इतनी विशाल कथा को वास्तविक श्रोताओं तक कौन ले जाएगा? लव और कुश आश्रम में ऐसी स्मृति, संगीत-कौशल, अनुशासन और धैर्य के साथ आते हैं जो उन्हें केवल ध्वनि नहीं, अर्थ सीखने योग्य बनाता है। दोनों भाई स्वर, ताल, अभिव्यक्ति, गति और प्रेम, शोक, हास्य, क्रोध, भय तथा वीरता के बदलते भाव सीखते हैं। यहाँ प्रस्तुति सजावट नहीं है; वही साधन है जो हजारों जुड़ी घटनाओं को समझने और याद रखने योग्य बनाता है। लव और कुश ऋषियों की सभाओं में गाते हैं। श्रोता कथा की स्पष्टता और सौंदर्य से प्रभावित होकर उनकी प्रशंसा करते हैं और आश्रम-जीवन में उपलब्ध साधारण वस्तुएँ भेंट देते हैं। ये उपहार दिखाते हैं कि कथा राजाज्ञा से नहीं, मानवीय संबंधों के सहारे यात्रा करने लगी है। अयोध्या में राम इन तपस्वी-वेशधारी गायकों को देखते हैं और उन्हें भाइयों तथा मंत्रियों की सभा में बुलाते हैं। गीत आरंभ होते ही दरबार मंत्रमुग्ध हो जाता है और राम उनमें राजवंश के संकेत पहचानते हैं; कथा का आरंभ एक विचित्र मिलन पर ठहरता है—जीवन, उसकी पुनर्कथा और वे लोग, जो अभी उन्हें जोड़ने वाले सभी संबंध नहीं जानते।', 'source_aligned', 'published'),
  ('turn-ayodhya-awaits-heirs', 'en', 'Ayodhya waits for heirs', 'Dasharatha''s longing draws the royal household toward the sacrifice and the births of four sons.', 'Dasharatha''s longing draws the royal household toward the sacrifice and the births of four sons.', 'draft', 'draft'),
  ('turn-ayodhya-awaits-heirs', 'hi', 'अयोध्या उत्तराधिकारी की प्रतीक्षा करती है', 'दशरथ की अभिलाषा राजपरिवार को यज्ञ और चार पुत्रों के जन्म तक ले जाती है।', 'दशरथ की अभिलाषा राजपरिवार को यज्ञ और चार पुत्रों के जन्म तक ले जाती है।', 'draft', 'draft'),
  ('scene-ayodhya-built-for-life', 'en', 'Ayodhya is introduced as a living capital', 'The story enters Kosala and its carefully planned capital on the Sarayu: roads, markets, craftsmen, warriors, homes, gardens, and ritual life form one interdependent city. Its abundance establishes what succession will protect—and what later exile will tear open.', 'The story enters Kosala and its carefully planned capital on the Sarayu: roads, markets, craftsmen, warriors, homes, gardens, and ritual life form one interdependent city. Its abundance establishes what succession will protect—and what later exile will tear open.', 'draft', 'draft'),
  ('scene-ayodhya-built-for-life', 'hi', 'अयोध्या एक जीवंत राजधानी के रूप में सामने आती है', 'कथा कोसल और सरयू तट की सुव्यवस्थित राजधानी में प्रवेश करती है। सड़कें, बाज़ार, शिल्पी, योद्धा, घर, उद्यान और धार्मिक जीवन मिलकर एक परस्पर जुड़ा नगर बनाते हैं। यही समृद्धि बताती है कि उत्तराधिकार किसे बचाएगा और आगे वनवास किसे तोड़ेगा।', 'कथा कोसल और सरयू तट की सुव्यवस्थित राजधानी में प्रवेश करती है। सड़कें, बाज़ार, शिल्पी, योद्धा, घर, उद्यान और धार्मिक जीवन मिलकर एक परस्पर जुड़ा नगर बनाते हैं। यही समृद्धि बताती है कि उत्तराधिकार किसे बचाएगा और आगे वनवास किसे तोड़ेगा।', 'draft', 'draft'),
  ('scene-dasharatha-rules-with-council', 'en', 'Dasharatha''s power depends on a disciplined council', 'Dasharatha is shown not as a solitary ruler but as the centre of ministers, priests, military readiness, revenue, law, and public trust. The same king who commands an enormous realm carries one private fear: he has no son to continue the line.', 'Dasharatha is shown not as a solitary ruler but as the centre of ministers, priests, military readiness, revenue, law, and public trust. The same king who commands an enormous realm carries one private fear: he has no son to continue the line.', 'draft', 'draft'),
  ('scene-dasharatha-rules-with-council', 'hi', 'दशरथ की शक्ति अनुशासित परिषद पर टिकी है', 'दशरथ अकेले शासक नहीं, बल्कि मंत्रियों, पुरोहितों, सेना, राजस्व, न्याय और जनविश्वास के केंद्र के रूप में दिखते हैं। विशाल राज्य पर अधिकार रखने वाले इसी राजा के भीतर एक निजी भय है—वंश आगे बढ़ाने वाला पुत्र नहीं है।', 'दशरथ अकेले शासक नहीं, बल्कि मंत्रियों, पुरोहितों, सेना, राजस्व, न्याय और जनविश्वास के केंद्र के रूप में दिखते हैं। विशाल राज्य पर अधिकार रखने वाले इसी राजा के भीतर एक निजी भय है—वंश आगे बढ़ाने वाला पुत्र नहीं है।', 'draft', 'draft'),
  ('scene-king-chooses-horse-sacrifice', 'en', 'The longing for heirs becomes a state decision', 'Dasharatha brings the absence of an heir before his advisers and proposes a horse sacrifice. The decision immediately becomes logistical and public: the Sarayu bank, ritual specialists, neighbouring rulers, resources, and safeguards must all be prepared.', 'Dasharatha brings the absence of an heir before his advisers and proposes a horse sacrifice. The decision immediately becomes logistical and public: the Sarayu bank, ritual specialists, neighbouring rulers, resources, and safeguards must all be prepared.', 'draft', 'draft'),
  ('scene-king-chooses-horse-sacrifice', 'hi', 'उत्तराधिकारी की इच्छा राजकीय निर्णय बनती है', 'दशरथ उत्तराधिकारी के अभाव को मंत्रियों के सामने रखते हैं और अश्वमेध का प्रस्ताव करते हैं। निर्णय तुरंत सार्वजनिक और व्यावहारिक बन जाता है—सरयू का तट, अनुष्ठान-विशेषज्ञ, पड़ोसी राजा, संसाधन और सुरक्षा सब तैयार करने होंगे।', 'दशरथ उत्तराधिकारी के अभाव को मंत्रियों के सामने रखते हैं और अश्वमेध का प्रस्ताव करते हैं। निर्णय तुरंत सार्वजनिक और व्यावहारिक बन जाता है—सरयू का तट, अनुष्ठान-विशेषज्ञ, पड़ोसी राजा, संसाधन और सुरक्षा सब तैयार करने होंगे।', 'draft', 'draft'),
  ('scene-rishyasringa-brought-from-seclusion', 'en', 'Rishyasringa is drawn from seclusion into two kingdoms', 'Sumantra recounts how drought-stricken Anga sought the secluded Rishyasringa, how courtesans crossed the boundary of his sheltered life, and how his arrival restored rain. Through Shanta and Romapada, the sage is then invited to Ayodhya for Dasharatha''s sacrifice.', 'Sumantra recounts how drought-stricken Anga sought the secluded Rishyasringa, how courtesans crossed the boundary of his sheltered life, and how his arrival restored rain. Through Shanta and Romapada, the sage is then invited to Ayodhya for Dasharatha''s sacrifice.', 'draft', 'draft'),
  ('scene-rishyasringa-brought-from-seclusion', 'hi', 'ऋष्यशृंग एकांत से दो राज्यों के जीवन में आते हैं', 'सुमंत्र बताते हैं कि अकालग्रस्त अंग ने एकांतवासी ऋष्यशृंग को कैसे खोजा, गणिकाओं ने उनके सुरक्षित संसार की सीमा कैसे पार की और उनके आगमन से वर्षा कैसे लौटी। शांता और रोमपाद के माध्यम से वही ऋषि दशरथ के यज्ञ के लिए अयोध्या आते हैं।', 'सुमंत्र बताते हैं कि अकालग्रस्त अंग ने एकांतवासी ऋष्यशृंग को कैसे खोजा, गणिकाओं ने उनके सुरक्षित संसार की सीमा कैसे पार की और उनके आगमन से वर्षा कैसे लौटी। शांता और रोमपाद के माध्यम से वही ऋषि दशरथ के यज्ञ के लिए अयोध्या आते हैं।', 'draft', 'draft'),
  ('scene-sacrifice-city-rises', 'en', 'A temporary city gathers around the sacrifice', 'Across two springs, Ayodhya builds the sacrificial ground, lodging, roads, kitchens, gifts, and protections for rulers, teachers, workers, and visitors. The horse returns, the demanding rites conclude, and Dasharatha''s public generosity accompanies his private hope.', 'Across two springs, Ayodhya builds the sacrificial ground, lodging, roads, kitchens, gifts, and protections for rulers, teachers, workers, and visitors. The horse returns, the demanding rites conclude, and Dasharatha''s public generosity accompanies his private hope.', 'draft', 'draft'),
  ('scene-sacrifice-city-rises', 'hi', 'यज्ञ के चारों ओर एक अस्थायी नगर बसता है', 'दो वसंतों के दौरान अयोध्या यज्ञभूमि, आवास, मार्ग, रसोई, दान और सुरक्षा की व्यवस्था करती है ताकि राजा, आचार्य, कर्मी और अतिथि सब सम्मिलित हो सकें। अश्व लौटता है, कठिन विधियाँ पूरी होती हैं और दशरथ की निजी आशा के साथ सार्वजनिक उदारता जुड़ती है।', 'दो वसंतों के दौरान अयोध्या यज्ञभूमि, आवास, मार्ग, रसोई, दान और सुरक्षा की व्यवस्था करती है ताकि राजा, आचार्य, कर्मी और अतिथि सब सम्मिलित हो सकें। अश्व लौटता है, कठिन विधियाँ पूरी होती हैं और दशरथ की निजी आशा के साथ सार्वजनिक उदारता जुड़ती है।', 'draft', 'draft'),
  ('scene-gods-name-ravana-problem', 'en', 'The gods name the danger behind the births', 'While Rishyasringa prepares the rite for sons, the gods approach Brahma about Ravana''s violence and the protection created by his boon. The overlooked vulnerability is human life, so the answer to Dasharatha''s household longing becomes part of a much larger struggle.', 'While Rishyasringa prepares the rite for sons, the gods approach Brahma about Ravana''s violence and the protection created by his boon. The overlooked vulnerability is human life, so the answer to Dasharatha''s household longing becomes part of a much larger struggle.', 'draft', 'draft'),
  ('scene-gods-name-ravana-problem', 'hi', 'देवता जन्मों के पीछे छिपे संकट का नाम लेते हैं', 'जब ऋष्यशृंग पुत्र-प्राप्ति का अनुष्ठान तैयार करते हैं, देवता ब्रह्मा के सामने रावण के अत्याचार और उसके वरदान से बनी सुरक्षा का प्रश्न रखते हैं। उसने मनुष्य को तुच्छ समझकर छोड़ दिया था; इसलिए दशरथ के घर की इच्छा एक बहुत बड़े संघर्ष का उत्तर बनती है।', 'जब ऋष्यशृंग पुत्र-प्राप्ति का अनुष्ठान तैयार करते हैं, देवता ब्रह्मा के सामने रावण के अत्याचार और उसके वरदान से बनी सुरक्षा का प्रश्न रखते हैं। उसने मनुष्य को तुच्छ समझकर छोड़ दिया था; इसलिए दशरथ के घर की इच्छा एक बहुत बड़े संघर्ष का उत्तर बनती है।', 'draft', 'draft'),
  ('scene-vishnu-chooses-fourfold-birth', 'en', 'Vishnu chooses birth in Dasharatha''s household', 'Vishnu agrees to enter human life through Dasharatha''s queens. A radiant being rises from the fire with the consecrated food, and the king divides it among Kausalya, Kaikeyi, and Sumitra, binding cosmic purpose to intimate acts of trust and expectation.', 'Vishnu agrees to enter human life through Dasharatha''s queens. A radiant being rises from the fire with the consecrated food, and the king divides it among Kausalya, Kaikeyi, and Sumitra, binding cosmic purpose to intimate acts of trust and expectation.', 'draft', 'draft'),
  ('scene-vishnu-chooses-fourfold-birth', 'hi', 'विष्णु दशरथ के घर जन्म चुनते हैं', 'विष्णु दशरथ की रानियों के माध्यम से मानव-जन्म स्वीकार करते हैं। अग्नि से दिव्य पुरुष पवित्र पायस लेकर प्रकट होता है और राजा उसे कौसल्या, कैकेयी तथा सुमित्रा में बाँटते हैं। इस तरह ब्रह्मांडीय उद्देश्य घर के विश्वास और प्रतीक्षा से जुड़ता है।', 'विष्णु दशरथ की रानियों के माध्यम से मानव-जन्म स्वीकार करते हैं। अग्नि से दिव्य पुरुष पवित्र पायस लेकर प्रकट होता है और राजा उसे कौसल्या, कैकेयी तथा सुमित्रा में बाँटते हैं। इस तरह ब्रह्मांडीय उद्देश्य घर के विश्वास और प्रतीक्षा से जुड़ता है।', 'draft', 'draft'),
  ('scene-allies-born-for-future-war', 'en', 'A scattered generation of allies is born', 'The gods create powerful forest-dwelling allies with different gifts, energies, and parentage for the conflict to come. Their births quietly prepare a network that Rama will not meet until exile has taken him far beyond Ayodhya.', 'The gods create powerful forest-dwelling allies with different gifts, energies, and parentage for the conflict to come. Their births quietly prepare a network that Rama will not meet until exile has taken him far beyond Ayodhya.', 'draft', 'draft'),
  ('scene-allies-born-for-future-war', 'hi', 'सहयोगियों की एक बिखरी पीढ़ी जन्म लेती है', 'देवता आने वाले संघर्ष के लिए अलग-अलग शक्तियों, स्वभावों और वंशों वाले वनवासी सहयोगियों को जन्म देते हैं। यह बिखरा हुआ जाल चुपचाप तैयार होता है; राम उनसे तब मिलेंगे जब वनवास उन्हें अयोध्या से बहुत दूर ले जाएगा।', 'देवता आने वाले संघर्ष के लिए अलग-अलग शक्तियों, स्वभावों और वंशों वाले वनवासी सहयोगियों को जन्म देते हैं। यह बिखरा हुआ जाल चुपचाप तैयार होता है; राम उनसे तब मिलेंगे जब वनवास उन्हें अयोध्या से बहुत दूर ले जाएगा।', 'draft', 'draft'),
  ('turn-princes-enter-world', 'en', 'The princes enter the wider world', 'Vishvamitra leads Rama and Lakshmana beyond the palace, through danger, learning, and the protected rite.', 'Vishvamitra leads Rama and Lakshmana beyond the palace, through danger, learning, and the protected rite.', 'draft', 'draft'),
  ('turn-princes-enter-world', 'hi', 'राजकुमार बड़े संसार में प्रवेश करते हैं', 'विश्वामित्र राम और लक्ष्मण को महल से बाहर संकट, शिक्षा और यज्ञ-रक्षा की यात्रा पर ले जाते हैं।', 'विश्वामित्र राम और लक्ष्मण को महल से बाहर संकट, शिक्षा और यज्ञ-रक्षा की यात्रा पर ले जाते हैं।', 'draft', 'draft'),
  ('scene-four-princes-grow-together', 'en', 'Four princes grow within one household', 'Rama, Bharata, Lakshmana, and Shatrughna are born, named, educated, and paired by deep affection. Rama''s gifts become visible, but the chapter first establishes the brothers as relationships rather than isolated future heroes.', 'Rama, Bharata, Lakshmana, and Shatrughna are born, named, educated, and paired by deep affection. Rama''s gifts become visible, but the chapter first establishes the brothers as relationships rather than isolated future heroes.', 'draft', 'draft'),
  ('scene-four-princes-grow-together', 'hi', 'चार राजकुमार एक ही परिवार में बड़े होते हैं', 'राम, भरत, लक्ष्मण और शत्रुघ्न जन्म लेते हैं, नाम पाते हैं, शिक्षा ग्रहण करते हैं और गहरे स्नेह के जोड़ों में जुड़ते हैं। राम की विशेषताएँ दिखती हैं, पर कथा पहले चारों भाइयों को अलग नायकों के बजाय संबंधों के रूप में स्थापित करती है।', 'राम, भरत, लक्ष्मण और शत्रुघ्न जन्म लेते हैं, नाम पाते हैं, शिक्षा ग्रहण करते हैं और गहरे स्नेह के जोड़ों में जुड़ते हैं। राम की विशेषताएँ दिखती हैं, पर कथा पहले चारों भाइयों को अलग नायकों के बजाय संबंधों के रूप में स्थापित करती है।', 'draft', 'draft'),
  ('scene-vishvamitra-asks-for-rama', 'en', 'Vishvamitra asks the king for Rama', 'Vishvamitra arrives with a precise request: Rama must guard a six-night rite from Maricha and Subahu. Dasharatha''s welcoming promise turns difficult when the guest names the young son whom the king most fears losing.', 'Vishvamitra arrives with a precise request: Rama must guard a six-night rite from Maricha and Subahu. Dasharatha''s welcoming promise turns difficult when the guest names the young son whom the king most fears losing.', 'draft', 'draft'),
  ('scene-vishvamitra-asks-for-rama', 'hi', 'विश्वामित्र राजा से राम को माँगते हैं', 'विश्वामित्र एक स्पष्ट माँग लेकर आते हैं—राम को छह रातों तक मारीच और सुबाहु से यज्ञ की रक्षा करनी होगी। अतिथि-सत्कार का दशरथ का वचन कठिन हो जाता है जब ऋषि उसी युवा पुत्र का नाम लेते हैं जिसे खोने से राजा सबसे अधिक डरते हैं।', 'विश्वामित्र एक स्पष्ट माँग लेकर आते हैं—राम को छह रातों तक मारीच और सुबाहु से यज्ञ की रक्षा करनी होगी। अतिथि-सत्कार का दशरथ का वचन कठिन हो जाता है जब ऋषि उसी युवा पुत्र का नाम लेते हैं जिसे खोने से राजा सबसे अधिक डरते हैं।', 'draft', 'draft'),
  ('scene-dasharatha-cannot-release-his-son', 'en', 'Dasharatha offers everything except his son', 'The king argues that Rama is too young, offers armies and his own command, and recoils when Ravana''s name enters the conversation. Love, fear, royal duty, and a promise spoken too quickly collide in public.', 'The king argues that Rama is too young, offers armies and his own command, and recoils when Ravana''s name enters the conversation. Love, fear, royal duty, and a promise spoken too quickly collide in public.', 'draft', 'draft'),
  ('scene-dasharatha-cannot-release-his-son', 'hi', 'दशरथ पुत्र के सिवा सब कुछ देने को तैयार हैं', 'राजा कहते हैं कि राम बहुत छोटे हैं, सेना और अपना नेतृत्व देने की पेशकश करते हैं और रावण का नाम सुनकर पीछे हटते हैं। प्रेम, भय, राजधर्म और जल्द दिया गया वचन सभा के सामने टकराते हैं।', 'राजा कहते हैं कि राम बहुत छोटे हैं, सेना और अपना नेतृत्व देने की पेशकश करते हैं और रावण का नाम सुनकर पीछे हटते हैं। प्रेम, भय, राजधर्म और जल्द दिया गया वचन सभा के सामने टकराते हैं।', 'draft', 'draft'),
  ('scene-vasishta-makes-promise-actionable', 'en', 'Vasishta turns a frightened promise into action', 'Vishvamitra''s anger threatens the court until Vasishta reminds Dasharatha that truth is the foundation of kingship and that the sage can protect and teach Rama. The father must trust a path whose outcome he cannot control.', 'Vishvamitra''s anger threatens the court until Vasishta reminds Dasharatha that truth is the foundation of kingship and that the sage can protect and teach Rama. The father must trust a path whose outcome he cannot control.', 'draft', 'draft'),
  ('scene-vasishta-makes-promise-actionable', 'hi', 'वसिष्ठ भयभीत वचन को कर्म में बदलते हैं', 'विश्वामित्र का क्रोध सभा को संकट में डाल देता है। वसिष्ठ दशरथ को स्मरण कराते हैं कि सत्य राजसत्ता की नींव है और ऋषि राम की रक्षा तथा शिक्षा कर सकते हैं। पिता को ऐसी राह पर विश्वास करना पड़ता है जिसका परिणाम उनके नियंत्रण में नहीं है।', 'विश्वामित्र का क्रोध सभा को संकट में डाल देता है। वसिष्ठ दशरथ को स्मरण कराते हैं कि सत्य राजसत्ता की नींव है और ऋषि राम की रक्षा तथा शिक्षा कर सकते हैं। पिता को ऐसी राह पर विश्वास करना पड़ता है जिसका परिणाम उनके नियंत्रण में नहीं है।', 'draft', 'draft'),
  ('scene-rama-lakshmana-leave-palace', 'en', 'Rama and Lakshmana walk out of palace life', 'After family rites and farewells, Rama follows Vishvamitra and Lakshmana follows Rama. On the Sarayu road the sage teaches Bala and Atibala, beginning an education built through fatigue, landscape, vigilance, and direct responsibility.', 'After family rites and farewells, Rama follows Vishvamitra and Lakshmana follows Rama. On the Sarayu road the sage teaches Bala and Atibala, beginning an education built through fatigue, landscape, vigilance, and direct responsibility.', 'draft', 'draft'),
  ('scene-rama-lakshmana-leave-palace', 'hi', 'राम और लक्ष्मण महल के जीवन से बाहर कदम रखते हैं', 'पारिवारिक विधियों और विदाई के बाद राम विश्वामित्र के साथ चलते हैं और लक्ष्मण राम के साथ। सरयू की राह पर ऋषि उन्हें बला और अतिबला सिखाते हैं; अब शिक्षा थकान, भूगोल, सतर्कता और प्रत्यक्ष उत्तरदायित्व से बनेगी।', 'पारिवारिक विधियों और विदाई के बाद राम विश्वामित्र के साथ चलते हैं और लक्ष्मण राम के साथ। सरयू की राह पर ऋषि उन्हें बला और अतिबला सिखाते हैं; अब शिक्षा थकान, भूगोल, सतर्कता और प्रत्यक्ष उत्तरदायित्व से बनेगी।', 'draft', 'draft'),
  ('scene-rivers-open-remembered-worlds', 'en', 'Every river crossing opens an older story', 'Morning discipline, the confluence of Sarayu and Ganga, abandoned hermitages, and the sound of waters turn travel into a layered classroom. Vishvamitra teaches the princes to read a place through the lives and consequences that remain inside it.', 'Morning discipline, the confluence of Sarayu and Ganga, abandoned hermitages, and the sound of waters turn travel into a layered classroom. Vishvamitra teaches the princes to read a place through the lives and consequences that remain inside it.', 'draft', 'draft'),
  ('scene-rivers-open-remembered-worlds', 'hi', 'हर नदी-पार एक पुरानी कथा खोलता है', 'प्रातः-अनुशासन, सरयू-गंगा का संगम, छोड़े हुए आश्रम और जल की ध्वनि यात्रा को बहुस्तरीय कक्षा बना देते हैं। विश्वामित्र राजकुमारों को स्थान को उसमें बचे जीवन और परिणामों के माध्यम से पढ़ना सिखाते हैं।', 'प्रातः-अनुशासन, सरयू-गंगा का संगम, छोड़े हुए आश्रम और जल की ध्वनि यात्रा को बहुस्तरीय कक्षा बना देते हैं। विश्वामित्र राजकुमारों को स्थान को उसमें बचे जीवन और परिणामों के माध्यम से पढ़ना सिखाते हैं।', 'draft', 'draft'),
  ('scene-tataka-forest-forces-choice', 'en', 'Tataka''s forest forces Rama''s first violent choice', 'Vishvamitra explains how Tataka''s strength, grief, curse, and attacks emptied a once-inhabited region. Rama questions the command, then accepts responsibility for restoring safety; the confrontation becomes his first irreversible act beyond palace training.', 'Vishvamitra explains how Tataka''s strength, grief, curse, and attacks emptied a once-inhabited region. Rama questions the command, then accepts responsibility for restoring safety; the confrontation becomes his first irreversible act beyond palace training.', 'draft', 'draft'),
  ('scene-tataka-forest-forces-choice', 'hi', 'ताड़का का वन राम के सामने पहला हिंसक निर्णय रखता है', 'विश्वामित्र बताते हैं कि ताड़का की शक्ति, शोक, शाप और आक्रमणों ने बसे हुए क्षेत्र को कैसे उजाड़ दिया। राम आदेश पर प्रश्न करते हैं, फिर सुरक्षा लौटाने का उत्तरदायित्व स्वीकारते हैं; यह महल की शिक्षा से बाहर उनका पहला अपरिवर्तनीय कर्म बनता है।', 'विश्वामित्र बताते हैं कि ताड़का की शक्ति, शोक, शाप और आक्रमणों ने बसे हुए क्षेत्र को कैसे उजाड़ दिया। राम आदेश पर प्रश्न करते हैं, फिर सुरक्षा लौटाने का उत्तरदायित्व स्वीकारते हैं; यह महल की शिक्षा से बाहर उनका पहला अपरिवर्तनीय कर्म बनता है।', 'draft', 'draft'),
  ('scene-weapons-arrive-with-restraint', 'en', 'Rama receives weapons—and the knowledge to withdraw them', 'Pleased by Rama''s conduct, Vishvamitra calls a vast family of personified weapons and entrusts them to him. Rama also asks for the means of recall and restraint, making control—not possession alone—the centre of power.', 'Pleased by Rama''s conduct, Vishvamitra calls a vast family of personified weapons and entrusts them to him. Rama also asks for the means of recall and restraint, making control—not possession alone—the centre of power.', 'draft', 'draft'),
  ('scene-weapons-arrive-with-restraint', 'hi', 'राम अस्त्रों के साथ उन्हें रोकने का ज्ञान भी पाते हैं', 'राम के आचरण से प्रसन्न विश्वामित्र अनेक सजीव रूपों वाले अस्त्र बुलाकर उन्हें सौंपते हैं। राम उन्हें वापस बुलाने और रोकने की विधि भी माँगते हैं; इस प्रकार शक्ति का केंद्र केवल अधिकार नहीं, संयम बनता है।', 'राम के आचरण से प्रसन्न विश्वामित्र अनेक सजीव रूपों वाले अस्त्र बुलाकर उन्हें सौंपते हैं। राम उन्हें वापस बुलाने और रोकने की विधि भी माँगते हैं; इस प्रकार शक्ति का केंद्र केवल अधिकार नहीं, संयम बनता है।', 'draft', 'draft'),
  ('scene-siddhashrama-remembers-vishnu', 'en', 'Siddhashrama remembers an earlier promise', 'At Siddhashrama, Vishvamitra connects the place to Vishnu''s austerity, Vamana, Bali, and the restoration of cosmic balance. Rama enters the coming defence knowing that the quiet ground has held earlier contests over power and rightful limits.', 'At Siddhashrama, Vishvamitra connects the place to Vishnu''s austerity, Vamana, Bali, and the restoration of cosmic balance. Rama enters the coming defence knowing that the quiet ground has held earlier contests over power and rightful limits.', 'draft', 'draft'),
  ('scene-siddhashrama-remembers-vishnu', 'hi', 'सिद्धाश्रम एक पुराने वचन को याद करता है', 'सिद्धाश्रम में विश्वामित्र इस स्थान को विष्णु की तपस्या, वामन, बलि और संतुलन की पुनर्स्थापना से जोड़ते हैं। राम जानते हैं कि यह शांत भूमि पहले भी शक्ति और उचित सीमा के संघर्षों की साक्षी रही है।', 'सिद्धाश्रम में विश्वामित्र इस स्थान को विष्णु की तपस्या, वामन, बलि और संतुलन की पुनर्स्थापना से जोड़ते हैं। राम जानते हैं कि यह शांत भूमि पहले भी शक्ति और उचित सीमा के संघर्षों की साक्षी रही है।', 'draft', 'draft'),
  ('scene-six-nights-end-in-battle', 'en', 'Six nights of vigilance end in the first battle', 'Rama and Lakshmana hold their watch until the sky darkens with the attackers'' assault. Rama hurls Maricha far away, kills Subahu, disperses the remaining force, and allows the rite to reach completion without turning victory into spectacle.', 'Rama and Lakshmana hold their watch until the sky darkens with the attackers'' assault. Rama hurls Maricha far away, kills Subahu, disperses the remaining force, and allows the rite to reach completion without turning victory into spectacle.', 'draft', 'draft'),
  ('scene-six-nights-end-in-battle', 'hi', 'छह रातों की पहरेदारी पहला युद्ध बनती है', 'राम और लक्ष्मण छह रातों तक पहरा देते हैं, फिर आक्रमण से आकाश अँधेरा हो जाता है। राम मारीच को दूर फेंकते हैं, सुबाहु का वध करते हैं, शेष सेना हटाते हैं और विजय का प्रदर्शन किए बिना यज्ञ पूरा होने देते हैं।', 'राम और लक्ष्मण छह रातों तक पहरा देते हैं, फिर आक्रमण से आकाश अँधेरा हो जाता है। राम मारीच को दूर फेंकते हैं, सुबाहु का वध करते हैं, शेष सेना हटाते हैं और विजय का प्रदर्शन किए बिना यज्ञ पूरा होने देते हैं।', 'draft', 'draft'),
  ('turn-road-to-mithila', 'en', 'The road to Mithila', 'Every halt opens another remembered world before the travellers reach Ahalya and Janaka''s city.', 'Every halt opens another remembered world before the travellers reach Ahalya and Janaka''s city.', 'draft', 'draft'),
  ('turn-road-to-mithila', 'hi', 'मिथिला की राह', 'हर पड़ाव एक पुरानी कथा खोलता है, फिर यात्री अहल्या और जनक की नगरी तक पहुँचते हैं।', 'हर पड़ाव एक पुरानी कथा खोलता है, फिर यात्री अहल्या और जनक की नगरी तक पहुँचते हैं।', 'draft', 'draft'),
  ('scene-road-leaves-siddhashrama', 'en', 'The protected rite becomes a road to Mithila', 'With the rite complete, the travelling company turns toward Janaka''s sacrifice and the extraordinary bow kept there. The road immediately begins producing remembered genealogies and local stories, widening Rama''s world beyond one completed task.', 'With the rite complete, the travelling company turns toward Janaka''s sacrifice and the extraordinary bow kept there. The road immediately begins producing remembered genealogies and local stories, widening Rama''s world beyond one completed task.', 'draft', 'draft'),
  ('scene-road-leaves-siddhashrama', 'hi', 'सुरक्षित यज्ञ मिथिला की राह बन जाता है', 'यज्ञ पूरा होने पर यात्रियों का दल जनक के यज्ञ और वहाँ रखे असाधारण धनुष की ओर बढ़ता है। राह तुरंत वंश-कथाएँ और स्थानीय स्मृतियाँ खोलती है; राम का संसार एक पूर्ण कार्य से कहीं आगे फैलता है।', 'यज्ञ पूरा होने पर यात्रियों का दल जनक के यज्ञ और वहाँ रखे असाधारण धनुष की ओर बढ़ता है। राह तुरंत वंश-कथाएँ और स्थानीय स्मृतियाँ खोलती है; राम का संसार एक पूर्ण कार्य से कहीं आगे फैलता है।', 'draft', 'draft'),
  ('scene-kusanabha-daughters-choose-agency', 'en', 'Kusanabha''s daughters refuse coercion', 'The hundred daughters of Kusanabha describe how Vayu demanded them and punished their refusal by distorting their bodies. They defend consent and family deliberation; marriage to Brahmadatta later restores them, while their answer remains the moral centre of the episode.', 'The hundred daughters of Kusanabha describe how Vayu demanded them and punished their refusal by distorting their bodies. They defend consent and family deliberation; marriage to Brahmadatta later restores them, while their answer remains the moral centre of the episode.', 'draft', 'draft'),
  ('scene-kusanabha-daughters-choose-agency', 'hi', 'कुशनाभ की पुत्रियाँ दबाव के आगे झुकने से इंकार करती हैं', 'कुशनाभ की सौ पुत्रियाँ बताती हैं कि वायु ने उन्हें पाने की माँग की और इंकार पर उनके शरीर विकृत कर दिए। वे सहमति और पारिवारिक विचार का पक्ष लेती हैं; बाद में ब्रह्मदत्त से विवाह उन्हें स्वस्थ करता है, पर उनकी अपनी वाणी प्रसंग का नैतिक केंद्र रहती है।', 'कुशनाभ की सौ पुत्रियाँ बताती हैं कि वायु ने उन्हें पाने की माँग की और इंकार पर उनके शरीर विकृत कर दिए। वे सहमति और पारिवारिक विचार का पक्ष लेती हैं; बाद में ब्रह्मदत्त से विवाह उन्हें स्वस्थ करता है, पर उनकी अपनी वाणी प्रसंग का नैतिक केंद्र रहती है।', 'draft', 'draft'),
  ('scene-ganga-and-kartikeya-origins', 'en', 'The travellers hear how Ganga and Kartikeya enter the world', 'Vishvamitra follows Ganga''s heavenly and earthly identities into the gods'' need for a commander. Fire, Ganga, the Krittikas, and the dangerous energy of birth shape the arrival of Kartikeya, turning rivers and mountains into participants in divine history.', 'Vishvamitra follows Ganga''s heavenly and earthly identities into the gods'' need for a commander. Fire, Ganga, the Krittikas, and the dangerous energy of birth shape the arrival of Kartikeya, turning rivers and mountains into participants in divine history.', 'draft', 'draft'),
  ('scene-ganga-and-kartikeya-origins', 'hi', 'यात्री गंगा और कार्तिकेय के संसार में आने की कथा सुनते हैं', 'विश्वामित्र गंगा की स्वर्गीय और पृथ्वीगत पहचान से देवताओं के सेनापति की आवश्यकता तक कथा ले जाते हैं। अग्नि, गंगा, कृत्तिकाएँ और जन्म की प्रचंड ऊर्जा कार्तिकेय के आगमन को आकार देती हैं; नदी और पर्वत दैवी इतिहास के सहभागी बन जाते हैं।', 'विश्वामित्र गंगा की स्वर्गीय और पृथ्वीगत पहचान से देवताओं के सेनापति की आवश्यकता तक कथा ले जाते हैं। अग्नि, गंगा, कृत्तिकाएँ और जन्म की प्रचंड ऊर्जा कार्तिकेय के आगमन को आकार देती हैं; नदी और पर्वत दैवी इतिहास के सहभागी बन जाते हैं।', 'draft', 'draft'),
  ('scene-sagara-line-brings-ganga-down', 'en', 'Generations labour to bring Ganga to the lost sons', 'Sagara''s sacrifice, the stolen horse, the earth-dug search, Kapila''s fire, and the deaths of sixty thousand sons create a debt no single life can resolve. Anshuman, Dilipa, and finally Bhagiratha carry the task across generations until Ganga descends through Shiva and reaches the ashes.', 'Sagara''s sacrifice, the stolen horse, the earth-dug search, Kapila''s fire, and the deaths of sixty thousand sons create a debt no single life can resolve. Anshuman, Dilipa, and finally Bhagiratha carry the task across generations until Ganga descends through Shiva and reaches the ashes.', 'draft', 'draft'),
  ('scene-sagara-line-brings-ganga-down', 'hi', 'खोए पुत्रों तक गंगा लाने के लिए पीढ़ियाँ तप करती हैं', 'सगर का यज्ञ, चुराया गया अश्व, पृथ्वी को खोदती खोज, कपिल की अग्नि और साठ हजार पुत्रों की मृत्यु ऐसा ऋण बनाते हैं जिसे एक जीवन पूरा नहीं कर सकता। अंशुमान, दिलीप और अंततः भगीरथ पीढ़ियों तक प्रयास करते हैं; गंगा शिव के माध्यम से उतरकर राख तक पहुँचती है।', 'सगर का यज्ञ, चुराया गया अश्व, पृथ्वी को खोदती खोज, कपिल की अग्नि और साठ हजार पुत्रों की मृत्यु ऐसा ऋण बनाते हैं जिसे एक जीवन पूरा नहीं कर सकता। अंशुमान, दिलीप और अंततः भगीरथ पीढ़ियों तक प्रयास करते हैं; गंगा शिव के माध्यम से उतरकर राख तक पहुँचती है।', 'draft', 'draft'),
  ('scene-ocean-churning-and-maruts', 'en', 'The road holds poison, nectar, grief, and the Maruts', 'The churning of the ocean reveals both poison and coveted nectar, while another remembered conflict follows Diti''s grief and Indra''s fear into the divided embryo that becomes the Maruts. The tales complicate easy divisions between divine victory and another person''s loss.', 'The churning of the ocean reveals both poison and coveted nectar, while another remembered conflict follows Diti''s grief and Indra''s fear into the divided embryo that becomes the Maruts. The tales complicate easy divisions between divine victory and another person''s loss.', 'draft', 'draft'),
  ('scene-ocean-churning-and-maruts', 'hi', 'राह में विष, अमृत, शोक और मरुतों की कथाएँ खुलती हैं', 'समुद्र-मंथन से विष और चाहा गया अमृत दोनों निकलते हैं। दूसरी स्मृति दिति के शोक और इंद्र के भय को उस विभाजित गर्भ तक ले जाती है जो मरुत बनता है। कथाएँ दैवी विजय और दूसरे के नुकसान के बीच सरल विभाजन को कठिन बनाती हैं।', 'समुद्र-मंथन से विष और चाहा गया अमृत दोनों निकलते हैं। दूसरी स्मृति दिति के शोक और इंद्र के भय को उस विभाजित गर्भ तक ले जाती है जो मरुत बनता है। कथाएँ दैवी विजय और दूसरे के नुकसान के बीच सरल विभाजन को कठिन बनाती हैं।', 'draft', 'draft'),
  ('scene-ahalya-hermitage-awakens', 'en', 'Ahalya''s silent hermitage receives travellers again', 'Near Mithila, Vishvamitra tells the difficult story of Ahalya, Gautama, and Indra and leads Rama into the emptied hermitage. Rama''s arrival ends the long isolation, Gautama returns, and hospitality resumes where life had been suspended.', 'Near Mithila, Vishvamitra tells the difficult story of Ahalya, Gautama, and Indra and leads Rama into the emptied hermitage. Rama''s arrival ends the long isolation, Gautama returns, and hospitality resumes where life had been suspended.', 'draft', 'draft'),
  ('scene-ahalya-hermitage-awakens', 'hi', 'अहल्या का मौन आश्रम फिर यात्रियों का स्वागत करता है', 'मिथिला के पास विश्वामित्र अहल्या, गौतम और इंद्र की कठिन कथा सुनाते हैं और राम को सूने आश्रम में ले जाते हैं। राम के आगमन से लंबा एकांत समाप्त होता है, गौतम लौटते हैं और जहाँ जीवन रुका था वहाँ अतिथि-सत्कार फिर शुरू होता है।', 'मिथिला के पास विश्वामित्र अहल्या, गौतम और इंद्र की कठिन कथा सुनाते हैं और राम को सूने आश्रम में ले जाते हैं। राम के आगमन से लंबा एकांत समाप्त होता है, गौतम लौटते हैं और जहाँ जीवन रुका था वहाँ अतिथि-सत्कार फिर शुरू होता है।', 'draft', 'draft'),
  ('scene-mithila-appears-beyond-sacrifice', 'en', 'Mithila appears with a bow at its centre', 'The travellers reach Janaka''s crowded sacrificial ground, where the king welcomes Vishvamitra and asks about the two princes. The famed bow enters conversation as a material object, a family memory, and the condition attached to Sita''s future.', 'The travellers reach Janaka''s crowded sacrificial ground, where the king welcomes Vishvamitra and asks about the two princes. The famed bow enters conversation as a material object, a family memory, and the condition attached to Sita''s future.', 'draft', 'draft'),
  ('scene-mithila-appears-beyond-sacrifice', 'hi', 'मिथिला सामने आती है—केंद्र में एक धनुष के साथ', 'यात्री जनक की भीड़भरी यज्ञभूमि पहुँचते हैं। राजा विश्वामित्र का स्वागत करते हैं और दोनों राजकुमारों के बारे में पूछते हैं। प्रसिद्ध धनुष एक वस्तु, पारिवारिक स्मृति और सीता के भविष्य से जुड़ी शर्त—तीनों रूपों में कथा में आता है।', 'यात्री जनक की भीड़भरी यज्ञभूमि पहुँचते हैं। राजा विश्वामित्र का स्वागत करते हैं और दोनों राजकुमारों के बारे में पूछते हैं। प्रसिद्ध धनुष एक वस्तु, पारिवारिक स्मृति और सीता के भविष्य से जुड़ी शर्त—तीनों रूपों में कथा में आता है।', 'draft', 'draft'),
  ('turn-sita-and-the-bow', 'en', 'Sita and the impossible bow', 'Janaka''s vow, Sita''s future, and Rama''s arrival meet when the ancient bow breaks.', 'Janaka''s vow, Sita''s future, and Rama''s arrival meet when the ancient bow breaks.', 'draft', 'draft'),
  ('turn-sita-and-the-bow', 'hi', 'सीता और असंभव धनुष', 'जनक का प्रण, सीता का भविष्य और राम का आगमन प्राचीन धनुष टूटने पर एक हो जाते हैं।', 'जनक का प्रण, सीता का भविष्य और राम का आगमन प्राचीन धनुष टूटने पर एक हो जाते हैं।', 'draft', 'draft'),
  ('scene-shatananda-greets-mothers-restorer', 'en', 'Shatananda meets the prince who restored his mother', 'Janaka''s priest Shatananda learns that Rama visited Ahalya''s hermitage and that his parents are reunited. Gratitude turns toward Vishvamitra: Shatananda begins telling Rama how much struggle lies behind the teacher now standing beside him.', 'Janaka''s priest Shatananda learns that Rama visited Ahalya''s hermitage and that his parents are reunited. Gratitude turns toward Vishvamitra: Shatananda begins telling Rama how much struggle lies behind the teacher now standing beside him.', 'draft', 'draft'),
  ('scene-shatananda-greets-mothers-restorer', 'hi', 'शतानंद उस राजकुमार से मिलते हैं जिसने उनकी माता को लौटाया', 'जनक के पुरोहित शतानंद जानते हैं कि राम अहल्या के आश्रम गए और उनके माता-पिता फिर साथ हैं। कृतज्ञता विश्वामित्र की ओर मुड़ती है; वे राम को बताते हैं कि उनके साथ खड़े गुरु के पीछे कितना लंबा संघर्ष है।', 'जनक के पुरोहित शतानंद जानते हैं कि राम अहल्या के आश्रम गए और उनके माता-पिता फिर साथ हैं। कृतज्ञता विश्वामित्र की ओर मुड़ती है; वे राम को बताते हैं कि उनके साथ खड़े गुरु के पीछे कितना लंबा संघर्ष है।', 'draft', 'draft'),
  ('scene-king-vishvamitra-meets-vasishta', 'en', 'A king discovers power he cannot seize', 'Shatananda recounts Vishvamitra''s former life as a conquering king, Vasishta''s impossible hospitality through the cow Shabala, and the king''s attempt to take that power by force. Armies and celestial weapons fail before spiritual authority, turning humiliation into a consuming new ambition.', 'Shatananda recounts Vishvamitra''s former life as a conquering king, Vasishta''s impossible hospitality through the cow Shabala, and the king''s attempt to take that power by force. Armies and celestial weapons fail before spiritual authority, turning humiliation into a consuming new ambition.', 'draft', 'draft'),
  ('scene-king-vishvamitra-meets-vasishta', 'hi', 'एक राजा ऐसी शक्ति देखता है जिसे छीन नहीं सकता', 'शतानंद विश्वामित्र के विजयी राजा वाले जीवन, वसिष्ठ की कामधेनु शबला से मिली अद्भुत आतिथ्य-शक्ति और उसे बलपूर्वक लेने के प्रयास की कथा सुनाते हैं। सेनाएँ और दिव्य अस्त्र आध्यात्मिक शक्ति के सामने हारते हैं; अपमान एक नई, सर्वग्रासी महत्वाकांक्षा बन जाता है।', 'शतानंद विश्वामित्र के विजयी राजा वाले जीवन, वसिष्ठ की कामधेनु शबला से मिली अद्भुत आतिथ्य-शक्ति और उसे बलपूर्वक लेने के प्रयास की कथा सुनाते हैं। सेनाएँ और दिव्य अस्त्र आध्यात्मिक शक्ति के सामने हारते हैं; अपमान एक नई, सर्वग्रासी महत्वाकांक्षा बन जाता है।', 'draft', 'draft'),
  ('scene-trishanku-suspended-between-worlds', 'en', 'Trishanku is suspended between rejected worlds', 'Vishvamitra''s austerity repeatedly collides with anger and rivalry. When Trishanku is rejected, cursed, and then sheltered by the sage, a sacrifice and counter-creation lift the king bodily toward heaven until resistance leaves him hanging in a new sky.', 'Vishvamitra''s austerity repeatedly collides with anger and rivalry. When Trishanku is rejected, cursed, and then sheltered by the sage, a sacrifice and counter-creation lift the king bodily toward heaven until resistance leaves him hanging in a new sky.', 'draft', 'draft'),
  ('scene-trishanku-suspended-between-worlds', 'hi', 'त्रिशंकु अस्वीकार किए गए लोकों के बीच ठहर जाते हैं', 'विश्वामित्र की तपस्या बार-बार क्रोध और प्रतिद्वंद्विता से टकराती है। त्रिशंकु अस्वीकृत और शापित होकर उनकी शरण में आते हैं; यज्ञ और प्रति-सृष्टि राजा को शरीर सहित ऊपर उठाते हैं, पर विरोध उन्हें नए आकाश में बीच ही में रोक देता है।', 'विश्वामित्र की तपस्या बार-बार क्रोध और प्रतिद्वंद्विता से टकराती है। त्रिशंकु अस्वीकृत और शापित होकर उनकी शरण में आते हैं; यज्ञ और प्रति-सृष्टि राजा को शरीर सहित ऊपर उठाते हैं, पर विरोध उन्हें नए आकाश में बीच ही में रोक देता है।', 'draft', 'draft'),
  ('scene-sunashepa-finds-words-to-live', 'en', 'Sunashepa searches for words that will let him live', 'A royal sacrifice requires a human victim, and Sunashepa is sold into that role after a family''s unequal choices. He appeals to Vishvamitra at Pushkara, learns the prayers he must speak, and survives, while the episode leaves the cost of sacrifice and kinship exposed.', 'A royal sacrifice requires a human victim, and Sunashepa is sold into that role after a family''s unequal choices. He appeals to Vishvamitra at Pushkara, learns the prayers he must speak, and survives, while the episode leaves the cost of sacrifice and kinship exposed.', 'draft', 'draft'),
  ('scene-sunashepa-finds-words-to-live', 'hi', 'शुनःशेप जीवन बचाने वाले शब्द खोजता है', 'राजकीय यज्ञ में मानव-बलि की माँग उठती है और परिवार के असमान निर्णयों के बाद शुनःशेप उस भूमिका के लिए बेच दिए जाते हैं। वे पुष्कर में विश्वामित्र से सहायता माँगते हैं, जीवन बचाने वाली प्रार्थनाएँ सीखते हैं और बच जाते हैं; पर यज्ञ और संबंधों की कीमत खुली रह जाती है।', 'राजकीय यज्ञ में मानव-बलि की माँग उठती है और परिवार के असमान निर्णयों के बाद शुनःशेप उस भूमिका के लिए बेच दिए जाते हैं। वे पुष्कर में विश्वामित्र से सहायता माँगते हैं, जीवन बचाने वाली प्रार्थनाएँ सीखते हैं और बच जाते हैं; पर यज्ञ और संबंधों की कीमत खुली रह जाती है।', 'draft', 'draft'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'en', 'Vishvamitra must outlast desire, anger, and pride', 'Long austerities are interrupted by recognition that is never enough, by Menaka and the birth of Shakuntala, and by the curse hurled at Rambha. Only when Vishvamitra can endure temptation, provocation, hunger, and silence without losing himself does Vasishta accept him as Brahmarshi.', 'Long austerities are interrupted by recognition that is never enough, by Menaka and the birth of Shakuntala, and by the curse hurled at Rambha. Only when Vishvamitra can endure temptation, provocation, hunger, and silence without losing himself does Vasishta accept him as Brahmarshi.', 'draft', 'draft'),
  ('scene-vishvamitra-outlasts-desire-and-anger', 'hi', 'विश्वामित्र को कामना, क्रोध और गर्व से आगे जाना पड़ता है', 'दीर्घ तपस्या बार-बार अधूरी मान्यता, मेनका और शकुंतला के जन्म, तथा रंभा को दिए शाप से टूटती है। जब विश्वामित्र प्रलोभन, उकसावे, भूख और मौन को स्वयं को खोए बिना सह पाते हैं, तभी वसिष्ठ उन्हें ब्रह्मर्षि स्वीकारते हैं।', 'दीर्घ तपस्या बार-बार अधूरी मान्यता, मेनका और शकुंतला के जन्म, तथा रंभा को दिए शाप से टूटती है। जब विश्वामित्र प्रलोभन, उकसावे, भूख और मौन को स्वयं को खोए बिना सह पाते हैं, तभी वसिष्ठ उन्हें ब्रह्मर्षि स्वीकारते हैं।', 'draft', 'draft'),
  ('scene-janaka-names-sitas-vow', 'en', 'Janaka explains Sita''s arrival and the vow of the bow', 'Janaka tells how Sita emerged while he was ploughing the ritual field and became his daughter, and how he tied her marriage to the ability to string Shiva''s bow. Kings have failed and attacked Mithila; the vow is therefore both a father''s decision and a history of public conflict.', 'Janaka tells how Sita emerged while he was ploughing the ritual field and became his daughter, and how he tied her marriage to the ability to string Shiva''s bow. Kings have failed and attacked Mithila; the vow is therefore both a father''s decision and a history of public conflict.', 'draft', 'draft'),
  ('scene-janaka-names-sitas-vow', 'hi', 'जनक सीता के आगमन और धनुष-प्रतिज्ञा की कथा कहते हैं', 'जनक बताते हैं कि यज्ञभूमि जोतते समय सीता धरती से मिलीं और उनकी पुत्री बनीं, तथा उन्होंने विवाह को शिव-धनुष चढ़ाने की क्षमता से बाँध दिया। अनेक राजा असफल होकर मिथिला पर चढ़ आए; इसलिए यह प्रतिज्ञा पिता का निर्णय भी है और सार्वजनिक संघर्ष का इतिहास भी।', 'जनक बताते हैं कि यज्ञभूमि जोतते समय सीता धरती से मिलीं और उनकी पुत्री बनीं, तथा उन्होंने विवाह को शिव-धनुष चढ़ाने की क्षमता से बाँध दिया। अनेक राजा असफल होकर मिथिला पर चढ़ आए; इसलिए यह प्रतिज्ञा पिता का निर्णय भी है और सार्वजनिक संघर्ष का इतिहास भी।', 'draft', 'draft'),
  ('scene-rama-breaks-the-bow', 'en', 'Rama lifts the bow and the hall changes', 'The enormous chest is rolled into the assembly and the bow is displayed before princes, sages, and Janaka''s household. At Vishvamitra''s invitation Rama lifts, strings, and breaks it; the sound overwhelms the hall, and Janaka sends for Dasharatha before treating the feat as a completed marriage.', 'The enormous chest is rolled into the assembly and the bow is displayed before princes, sages, and Janaka''s household. At Vishvamitra''s invitation Rama lifts, strings, and breaks it; the sound overwhelms the hall, and Janaka sends for Dasharatha before treating the feat as a completed marriage.', 'draft', 'draft'),
  ('scene-rama-breaks-the-bow', 'hi', 'राम धनुष उठाते हैं और सभा का संसार बदल जाता है', 'विशाल संदूक सभा में लाया जाता है और राजकुमारों, ऋषियों तथा जनक-परिवार के सामने धनुष दिखाया जाता है। विश्वामित्र के संकेत पर राम उसे उठाकर चढ़ाते हैं और वह टूट जाता है; ध्वनि सभा को स्तब्ध करती है, पर जनक विवाह पूर्ण मानने से पहले दशरथ को बुलाते हैं।', 'विशाल संदूक सभा में लाया जाता है और राजकुमारों, ऋषियों तथा जनक-परिवार के सामने धनुष दिखाया जाता है। विश्वामित्र के संकेत पर राम उसे उठाकर चढ़ाते हैं और वह टूट जाता है; ध्वनि सभा को स्तब्ध करती है, पर जनक विवाह पूर्ण मानने से पहले दशरथ को बुलाते हैं।', 'draft', 'draft'),
  ('turn-weddings-and-challenge', 'en', 'Weddings, then one last challenge', 'The families unite, but the homeward road is interrupted by Parashurama''s fierce test.', 'The families unite, but the homeward road is interrupted by Parashurama''s fierce test.', 'draft', 'draft'),
  ('turn-weddings-and-challenge', 'hi', 'विवाह, फिर अंतिम चुनौती', 'परिवार एक होते हैं, पर घर लौटती राह पर परशुराम की कठोर चुनौती सामने आती है।', 'परिवार एक होते हैं, पर घर लौटती राह पर परशुराम की कठोर चुनौती सामने आती है।', 'draft', 'draft'),
  ('scene-mithila-envoys-reach-ayodhya', 'en', 'News of the broken bow reaches Ayodhya', 'Janaka''s envoys travel three days to report Rama''s feat and request Dasharatha''s presence. The message reconnects the sons'' unsupervised journey to their family and transforms an astonishing trial into a proposed alliance requiring consent and ceremony.', 'Janaka''s envoys travel three days to report Rama''s feat and request Dasharatha''s presence. The message reconnects the sons'' unsupervised journey to their family and transforms an astonishing trial into a proposed alliance requiring consent and ceremony.', 'draft', 'draft'),
  ('scene-mithila-envoys-reach-ayodhya', 'hi', 'टूटे धनुष का समाचार अयोध्या पहुँचता है', 'जनक के दूत तीन दिन यात्रा कर राम के पराक्रम का समाचार देते हैं और दशरथ को बुलाते हैं। संदेश पुत्रों की स्वतंत्र यात्रा को फिर परिवार से जोड़ता है और असाधारण परीक्षा को सहमति तथा विधि माँगने वाले वैवाहिक प्रस्ताव में बदल देता है।', 'जनक के दूत तीन दिन यात्रा कर राम के पराक्रम का समाचार देते हैं और दशरथ को बुलाते हैं। संदेश पुत्रों की स्वतंत्र यात्रा को फिर परिवार से जोड़ता है और असाधारण परीक्षा को सहमति तथा विधि माँगने वाले वैवाहिक प्रस्ताव में बदल देता है।', 'draft', 'draft'),
  ('scene-dasharatha-travels-to-mithila', 'en', 'Dasharatha brings the household to Mithila', 'After consulting Vasishta and the court, Dasharatha accepts the invitation and travels with priests, wealth, relatives, and the structures needed for a royal marriage. Arrival turns the story from individual prowess toward two families negotiating a shared future.', 'After consulting Vasishta and the court, Dasharatha accepts the invitation and travels with priests, wealth, relatives, and the structures needed for a royal marriage. Arrival turns the story from individual prowess toward two families negotiating a shared future.', 'draft', 'draft'),
  ('scene-dasharatha-travels-to-mithila', 'hi', 'दशरथ परिवार और राज्य को लेकर मिथिला पहुँचते हैं', 'वसिष्ठ और सभा से विचार कर दशरथ निमंत्रण स्वीकारते हैं और पुरोहितों, धन, संबंधियों तथा राजविवाह की आवश्यक व्यवस्था के साथ मिथिला आते हैं। आगमन कथा को व्यक्तिगत पराक्रम से दो परिवारों के साझा भविष्य की ओर मोड़ता है।', 'वसिष्ठ और सभा से विचार कर दशरथ निमंत्रण स्वीकारते हैं और पुरोहितों, धन, संबंधियों तथा राजविवाह की आवश्यक व्यवस्था के साथ मिथिला आते हैं। आगमन कथा को व्यक्तिगत पराक्रम से दो परिवारों के साझा भविष्य की ओर मोड़ता है।', 'draft', 'draft'),
  ('scene-two-houses-recite-their-lineages', 'en', 'The two houses tell one another who they are', 'Janaka summons his brother Kushadhvaja, while Vasishta and Janaka recite the Ikshvaku and Videha lineages before the marriages are agreed. The public genealogies make kinship, reputation, and responsibility part of consent rather than decorative background.', 'Janaka summons his brother Kushadhvaja, while Vasishta and Janaka recite the Ikshvaku and Videha lineages before the marriages are agreed. The public genealogies make kinship, reputation, and responsibility part of consent rather than decorative background.', 'draft', 'draft'),
  ('scene-two-houses-recite-their-lineages', 'hi', 'दो राजघराने एक-दूसरे को अपना परिचय देते हैं', 'जनक अपने भाई कुशध्वज को बुलाते हैं और विवाह-स्वीकृति से पहले वसिष्ठ तथा जनक इक्ष्वाकु और विदेह वंशों का वर्णन करते हैं। सार्वजनिक वंश-कथाएँ संबंध, प्रतिष्ठा और उत्तरदायित्व को सजावट नहीं बल्कि सहमति का हिस्सा बनाती हैं।', 'जनक अपने भाई कुशध्वज को बुलाते हैं और विवाह-स्वीकृति से पहले वसिष्ठ तथा जनक इक्ष्वाकु और विदेह वंशों का वर्णन करते हैं। सार्वजनिक वंश-कथाएँ संबंध, प्रतिष्ठा और उत्तरदायित्व को सजावट नहीं बल्कि सहमति का हिस्सा बनाती हैं।', 'draft', 'draft'),
  ('scene-four-brothers-four-marriages', 'en', 'Four marriages join the households', 'The alliance widens beyond Rama and Sita: Lakshmana marries Urmila, Bharata marries Mandavi, and Shatrughna marries Shrutakirti. Gifts, vows, circumambulation, blessing, and celebration establish four distinct partnerships within one shared family event.', 'The alliance widens beyond Rama and Sita: Lakshmana marries Urmila, Bharata marries Mandavi, and Shatrughna marries Shrutakirti. Gifts, vows, circumambulation, blessing, and celebration establish four distinct partnerships within one shared family event.', 'draft', 'draft'),
  ('scene-four-brothers-four-marriages', 'hi', 'चार विवाह दोनों परिवारों को जोड़ते हैं', 'संबंध राम और सीता से आगे बढ़ता है—लक्ष्मण का उर्मिला, भरत का मांडवी और शत्रुघ्न का श्रुतकीर्ति से विवाह होता है। दान, संकल्प, परिक्रमा, आशीर्वाद और उत्सव एक ही पारिवारिक घटना में चार अलग साझेदारियाँ स्थापित करते हैं।', 'संबंध राम और सीता से आगे बढ़ता है—लक्ष्मण का उर्मिला, भरत का मांडवी और शत्रुघ्न का श्रुतकीर्ति से विवाह होता है। दान, संकल्प, परिक्रमा, आशीर्वाद और उत्सव एक ही पारिवारिक घटना में चार अलग साझेदारियाँ स्थापित करते हैं।', 'draft', 'draft'),
  ('scene-families-begin-homeward-road', 'en', 'The celebrations end and the road home begins', 'Vishvamitra departs for the northern mountains, Janaka sends his daughters with gifts and attendants, and Dasharatha''s expanded household turns toward Ayodhya. The mood of completion is deliberately brief: unsettling signs gather on the road.', 'Vishvamitra departs for the northern mountains, Janaka sends his daughters with gifts and attendants, and Dasharatha''s expanded household turns toward Ayodhya. The mood of completion is deliberately brief: unsettling signs gather on the road.', 'draft', 'draft'),
  ('scene-families-begin-homeward-road', 'hi', 'उत्सव समाप्त होता है और घर की राह शुरू होती है', 'विश्वामित्र उत्तर पर्वतों की ओर जाते हैं, जनक पुत्रियों को दान और परिचारकों के साथ विदा करते हैं और दशरथ का विस्तृत परिवार अयोध्या की ओर चलता है। पूर्णता का सुख बहुत छोटा है—रास्ते में अशुभ संकेत इकट्ठे होने लगते हैं।', 'विश्वामित्र उत्तर पर्वतों की ओर जाते हैं, जनक पुत्रियों को दान और परिचारकों के साथ विदा करते हैं और दशरथ का विस्तृत परिवार अयोध्या की ओर चलता है। पूर्णता का सुख बहुत छोटा है—रास्ते में अशुभ संकेत इकट्ठे होने लगते हैं।', 'draft', 'draft'),
  ('scene-parashurama-tests-rama', 'en', 'Parashurama places another bow before Rama', 'Parashurama stops the wedding party, dismisses the broken bow as insufficient proof, and presents Vishnu''s bow as a harsher test. Dasharatha pleads, Rama answers without retreat, and the transfer of power ends when Parashurama recognises what has changed and leaves the road open to Ayodhya.', 'Parashurama stops the wedding party, dismisses the broken bow as insufficient proof, and presents Vishnu''s bow as a harsher test. Dasharatha pleads, Rama answers without retreat, and the transfer of power ends when Parashurama recognises what has changed and leaves the road open to Ayodhya.', 'draft', 'draft'),
  ('scene-parashurama-tests-rama', 'hi', 'परशुराम राम के सामने दूसरा धनुष रखते हैं', 'परशुराम विवाह-दल रोकते हैं, टूटे धनुष को अपर्याप्त प्रमाण मानते हैं और विष्णु का धनुष अधिक कठोर परीक्षा के रूप में सामने रखते हैं। दशरथ विनती करते हैं, राम पीछे नहीं हटते और शक्ति का हस्तांतरण तब पूरा होता है जब परशुराम परिवर्तन पहचानकर अयोध्या की राह छोड़ देते हैं।', 'परशुराम विवाह-दल रोकते हैं, टूटे धनुष को अपर्याप्त प्रमाण मानते हैं और विष्णु का धनुष अधिक कठोर परीक्षा के रूप में सामने रखते हैं। दशरथ विनती करते हैं, राम पीछे नहीं हटते और शक्ति का हस्तांतरण तब पूरा होता है जब परशुराम परिवर्तन पहचानकर अयोध्या की राह छोड़ देते हैं।', 'draft', 'draft'),
  ('turn-coronation-dawn', 'en', 'A coronation dawns', 'Ayodhya prepares to welcome Rama as heir; joy fills the city before anyone knows the night will turn.', 'Ayodhya prepares to welcome Rama as heir; joy fills the city before anyone knows the night will turn.', 'source_aligned', 'published'),
  ('turn-coronation-dawn', 'hi', 'राज्याभिषेक की भोर', 'अयोध्या राम को युवराज बनाने की तैयारी करती है; रात बदलने से पहले नगर आनंद से भर जाता है।', 'अयोध्या राम को युवराज बनाने की तैयारी करती है; रात बदलने से पहले नगर आनंद से भर जाता है।', 'source_aligned', 'published'),
  ('scene-coronation-dawn', 'en', 'A coronation dawns', 'A whole city begins preparing for a future that will not arrive.', 'Dasharatha tells the gathered rulers and elders that age weighs on him and proposes Rama as heir. The assembly answers with unmistakable approval. Orders spread through streets, storehouses, kitchens, gateways, and shrines. Water, garlands, music, banners, food, and ceremonial objects gather for the morning. Rama receives the instructions without triumph. He and Sita fast, pray, and lie on a simple bed of kusa grass while the palace stays awake around them. People speak of Rama''s expected rule and wait for morning. The celebration feels settled; that confidence is what the coming turn will break.', 'source_aligned', 'published'),
  ('scene-coronation-dawn', 'hi', 'दशरथ भविष्य की घोषणा करते हैं', 'पूरा नगर ऐसे भविष्य की तैयारी करता है जो अब आने वाला नहीं है।', 'दशरथ राजाओं और सभासदों से कहते हैं कि आयु का भार बढ़ रहा है और राम को युवराज बनाने का प्रस्ताव रखते हैं। सभा स्पष्ट सहमति देती है। आदेश गलियों, भंडारों, रसोइयों, द्वारों और पूजा-स्थलों तक फैलते हैं। जल, मालाएँ, संगीत, ध्वज, भोजन और अभिषेक-सामग्री भोर के लिए जुटती है। राम आदेश को विजय-भाव से नहीं लेते। वे और सीता उपवास, प्रार्थना और कुश की साधारण शय्या पर रात्रि बिताते हैं, जबकि महल जागता रहता है। लोग राम के भावी शासन की चर्चा करते हुए सुबह की प्रतीक्षा करते हैं। उत्सव निश्चित लगता है—अगला मोड़ इसी विश्वास को तोड़ेगा।', 'source_aligned', 'published'),
  ('turn-two-boons', 'en', 'Two boons change the kingdom', 'Manthara awakens Kaikeyi''s fear, and an old promise becomes Bharata''s crown and Rama''s exile.', 'Manthara awakens Kaikeyi''s fear, and an old promise becomes Bharata''s crown and Rama''s exile.', 'source_aligned', 'published'),
  ('turn-two-boons', 'hi', 'दो वरदान राज्य बदल देते हैं', 'मंथरा कैकेयी का भय जगाती है और पुराना वचन भरत के राज्य तथा राम के वनवास में बदल जाता है।', 'मंथरा कैकेयी का भय जगाती है और पुराना वचन भरत के राज्य तथा राम के वनवास में बदल जाता है।', 'source_aligned', 'published'),
  ('scene-manthara-sees-city', 'en', 'Manthara sees the city', 'Celebration enters Kaikeyi''s room as a warning.', 'From the palace height, Manthara sees watered streets, banners, garlands, and crowds in festive dress. She asks what has made Ayodhya radiant. She learns that Rama will be installed the next morning. What others receive as good news, she immediately reads as a threat to Kaikeyi and Bharata. Kaikeyi does not begin in anger. She delights in the news, praises Rama, and gives Manthara an ornament—an important beginning before persuasion changes her. Manthara rejects the gift and insists Kaikeyi is celebrating her own loss. The room changes from congratulations into an argument about power and security.', 'source_aligned', 'published'),
  ('scene-manthara-sees-city', 'hi', 'नीचे सजा हुआ नगर', 'उत्सव कैकेयी के कक्ष में चेतावनी बनकर प्रवेश करता है।', 'महल की ऊँचाई से मंथरा धुली सड़कें, ध्वज, मालाएँ और उत्सव-वस्त्रों में भीड़ देखती है। वह पूछती है कि अयोध्या किस कारण चमक रही है। उसे पता चलता है कि अगली सुबह राम का राज्याभिषेक होगा। जिसे सब शुभ समाचार मानते हैं, वह उसे कैकेयी और भरत के लिए संकट समझती है। कैकेयी आरंभ में क्रोधित नहीं होतीं। वे समाचार से प्रसन्न होकर राम की प्रशंसा करती हैं और मंथरा को आभूषण देती हैं—तर्क से बदलने से पहले यही उनका शुरुआती भाव है। मंथरा उपहार अस्वीकार कर कहती है कि कैकेयी अपनी ही हानि का उत्सव मना रही हैं। कक्ष में बधाई की जगह सत्ता और सुरक्षा की बहस शुरू होती है।', 'source_aligned', 'published'),
  ('scene-fear-becomes-demands', 'en', 'Fear becomes two demands', 'A planted fear becomes a plan built around two old boons.', 'Manthara argues that Rama''s rise will diminish Bharata and Kaikeyi. She turns affection, succession, and household rank into a chain of imagined danger. Persuaded, Kaikeyi removes her ornaments, puts on soiled clothing, and lies on the floor so Dasharatha will find a visible crisis. Alarmed by her condition, Dasharatha asks what she wants and repeatedly promises to fulfil it. Kaikeyi makes the promise public in the presence of invoked witnesses. Kaikeyi calls in the boons Dasharatha once granted and demands that the prepared coronation install Bharata instead of Rama. The second demand removes Rama from the kingdom for fourteen years in forest dress. It is not merely a changed ceremony; it is the beginning of the epic road.', 'source_aligned', 'published'),
  ('scene-fear-becomes-demands', 'hi', 'भविष्य को संकट की तरह दिखाया जाता है', 'जगाया गया भय दो पुराने वरदानों की योजना बन जाता है।', 'मंथरा तर्क देती है कि राम का उदय भरत और कैकेयी को पीछे कर देगा। वह स्नेह, उत्तराधिकार और परिवार की स्थिति को आशंकाओं की शृंखला बना देती है। प्रभावित होकर कैकेयी आभूषण उतारती हैं, मलिन वस्त्र पहनती हैं और भूमि पर लेट जाती हैं ताकि दशरथ के सामने संकट स्पष्ट दिखाई दे। कैकेयी की दशा देखकर दशरथ पूछते हैं कि वे क्या चाहती हैं और बार-बार उसे पूरा करने का वचन देते हैं। कैकेयी साक्षियों का आह्वान करके उस वचन को सार्वजनिक बनाती हैं। कैकेयी दशरथ द्वारा दिए पुराने वरदान माँगती हैं और तैयार राज्याभिषेक में राम के स्थान पर भरत को स्थापित करने की माँग रखती हैं। दूसरी माँग राम को वन-वस्त्र में चौदह वर्ष के लिए राज्य से दूर भेजती है। यह केवल बदला हुआ समारोह नहीं, महाकाव्य की यात्रा का आरंभ है।', 'source_aligned', 'published'),
  ('scene-king-trapped-by-word', 'en', 'The king is trapped by his word', 'Dasharatha discovers that the promise he offered cannot coexist with the future he planned.', 'Dasharatha falls senseless, recovers, and hopes he has heard a nightmare. Kaikeyi repeats the demands without softening them. He appeals to love, reputation, family, and mercy. He offers wealth and power, but cannot make Kaikeyi release the promise. Kaikeyi says a king celebrated for truth cannot withdraw when the cost becomes painful. The language of honour becomes the lock on the chamber. Priests, citizens, music, and the objects of installation gather outside. Inside, Dasharatha can no longer speak the future everyone has come to celebrate.', 'source_aligned', 'published'),
  ('scene-king-trapped-by-word', 'hi', 'माँग का आघात', 'दशरथ देखते हैं कि दिया हुआ वचन और उनकी बनाई भविष्य-योजना साथ नहीं रह सकते।', 'दशरथ मूर्छित होकर गिरते हैं, संभलते हैं और आशा करते हैं कि यह दुःस्वप्न हो। कैकेयी बिना नरमी के माँगें दोहराती हैं। वे प्रेम, प्रतिष्ठा, परिवार और दया की दुहाई देते हैं। धन और सत्ता देने को तैयार होते हैं, पर कैकेयी वचन छोड़ने को नहीं मानतीं। कैकेयी कहती हैं कि सत्य के लिए प्रसिद्ध राजा कठिन मूल्य देखकर पीछे नहीं हट सकता। सम्मान की भाषा ही कक्ष का ताला बन जाती है। पुरोहित, नागरिक, संगीत और अभिषेक-सामग्री बाहर जुटते हैं। भीतर दशरथ उस भविष्य का नाम भी नहीं ले पाते जिसके उत्सव में सब आए हैं।', 'source_aligned', 'published'),
  ('scene-rama-crosses-celebration', 'en', 'Rama crosses the celebration', 'Rama walks through his own celebration to learn that it has become an exile.', 'Vasishta sends Sumantra to bring the king. The messenger finds Dasharatha broken and Kaikeyi directing what happens next. Kaikeyi tells Sumantra to bring Rama. Nothing in the public streets reveals that the summons is no longer for installation. Rama crosses watered roads, raised standards, musicians, and citizens expecting to see him crowned. He answers their affection without knowing how soon he will leave them. Rama finds Dasharatha unable to answer him. Kaikeyi says the king is bound by shame and then tells Rama the two demands directly.', 'source_aligned', 'published'),
  ('scene-rama-crosses-celebration', 'hi', 'समारोह तैयार है, राजा नहीं', 'राम अपने ही उत्सव के बीच से चलकर जानते हैं कि वही वनवास बन चुका है।', 'वसिष्ठ सुमंत्र को राजा बुलाने भेजते हैं। वे दशरथ को टूटा हुआ और आगे की दिशा तय करती कैकेयी को पाते हैं। कैकेयी सुमंत्र से राम को बुलाने कहती हैं। सार्वजनिक गलियों में कुछ भी नहीं बताता कि बुलावा अब राज्याभिषेक के लिए नहीं है। राम धुली सड़कों, ध्वजों, संगीत और राज्याभिषेक की प्रतीक्षा करती जनता के बीच से गुजरते हैं। वे स्नेह का उत्तर देते हैं, बिना जाने कि शीघ्र ही विदा होंगे। राम दशरथ को उत्तर देने में असमर्थ पाते हैं। कैकेयी कहती हैं कि राजा संकोच से बँधे हैं और फिर दोनों माँगें सीधे राम को बताती हैं।', 'source_aligned', 'published'),
  ('turn-exile-accepted', 'en', 'Rama accepts the exile', 'Rama chooses his father''s word; Sita and Lakshmana refuse to let him face the forest alone.', 'Rama chooses his father''s word; Sita and Lakshmana refuse to let him face the forest alone.', 'source_aligned', 'published'),
  ('turn-exile-accepted', 'hi', 'राम वनवास स्वीकार करते हैं', 'राम पिता का वचन निभाते हैं; सीता और लक्ष्मण उन्हें वन में अकेले जाने नहीं देते।', 'राम पिता का वचन निभाते हैं; सीता और लक्ष्मण उन्हें वन में अकेले जाने नहीं देते।', 'source_aligned', 'published'),
  ('scene-rama-accepts-exile', 'en', 'Rama accepts the exile', 'Rama chooses departure before anyone around him has absorbed the loss.', 'Rama says Bharata may receive the kingdom and that he will enter the forest that very day. He asks only why his father could not tell him himself. Rama reaches Kausalya while attendants and ritual preparations still anticipate his installation. He tells her that the seat prepared for him must be exchanged for forest ground. Kausalya collapses, mourns the years of waiting, and says she would follow him. The story stays with the human cost before it turns to argument about duty. Lakshmana calls the command unjust and offers force, defence, and the support of those loyal to Rama. His anger gives voice to the refusal others cannot articulate. Rama refuses to seize the kingdom or make his father''s word the cause of civil conflict. He asks Lakshmana to help dismantle the ceremony and prepare for departure.', 'source_aligned', 'published'),
  ('scene-rama-accepts-exile', 'hi', 'राम बिना सौदे के उत्तर देते हैं', 'आसपास के लोग आघात समझ भी नहीं पाते और राम प्रस्थान चुन लेते हैं।', 'राम कहते हैं कि भरत राज्य लें और वे उसी दिन वन चले जाएँगे। वे केवल पूछते हैं कि पिता स्वयं यह बात क्यों नहीं कह सके। राम कौसल्या के पास पहुँचते हैं, जहाँ सेवक और अनुष्ठान अभी भी राज्याभिषेक की प्रतीक्षा में हैं। वे बताते हैं कि उनके लिए तैयार आसन अब वन-भूमि से बदल जाएगा। कौसल्या गिर पड़ती हैं, वर्षों की प्रतीक्षा का शोक करती हैं और साथ चलने की बात कहती हैं। कथा कर्तव्य की बहस से पहले मानवीय पीड़ा पर ठहरती है। लक्ष्मण आदेश को अन्यायपूर्ण कहते हैं और बल, रक्षा तथा राम-समर्थकों का सहारा देने की बात करते हैं। उनका क्रोध उस अस्वीकार को स्वर देता है जिसे दूसरे कह नहीं पाते। राम राज्य छीनने या पिता के वचन को गृह-संघर्ष का कारण बनाने से इंकार करते हैं। वे लक्ष्मण से समारोह समेटकर प्रस्थान की तैयारी में सहायता माँगते हैं।', 'source_aligned', 'published'),
  ('scene-sita-chooses-road', 'en', 'Sita chooses the road', 'The exile becomes a shared journey because Sita insists on choosing it.', 'Sita has prepared for coronation and asks why Rama returns without royal signs, music, or attendants. His face tells her the public celebration is already false. Rama explains the command and initially asks Sita to stay in Ayodhya, honour the elders, and live carefully while he is away. Sita answers that marriage does not divide hardship into his and hers. She rejects the idea that the palace can be her proper world while his road lies elsewhere. Rama names rough ground, hunger, animals, weather, and hardship. Sita answers each warning not with ignorance, but with a repeated, deliberate choice to accompany him. After the long exchange, Rama stops trying to leave her behind. They begin giving possessions away and preparing to enter the forest together.', 'source_aligned', 'published'),
  ('scene-sita-chooses-road', 'hi', 'सीता वह देखती हैं जो नगर नहीं देखता', 'सीता के अपने निर्णय से वनवास साझा यात्रा बन जाता है।', 'सीता राज्याभिषेक की तैयारी में हैं और पूछती हैं कि राम राजचिह्न, संगीत और सेवकों के बिना क्यों लौटे। उनका चेहरा बता देता है कि बाहर का उत्सव अब सच नहीं रहा। राम आदेश बताते हैं और पहले सीता से अयोध्या में रहकर बड़ों का सम्मान करने तथा उनके लौटने तक सावधानी से जीवन बिताने को कहते हैं। सीता कहती हैं कि विवाह कठिनाई को तुम्हारी और मेरी हिस्सेदारी में नहीं बाँटता। वे इस विचार को अस्वीकार करती हैं कि उनका संसार महल हो और राम की राह कहीं और। राम कठिन भूमि, भूख, वन्य जीव, मौसम और कष्ट गिनाते हैं। सीता अज्ञान से नहीं, हर चेतावनी के बाद सोच-समझकर साथ चलने का निर्णय दोहराती हैं। लंबे संवाद के बाद राम उन्हें पीछे छोड़ने का प्रयास रोकते हैं। दोनों वस्तुएँ दान देकर साथ वन जाने की तैयारी करते हैं।', 'source_aligned', 'published'),
  ('scene-lakshmana-joins', 'en', 'Three turn toward the gate', 'Three travellers emerge from the coronation that was meant for one king.', 'Lakshmana says he will walk before Rama and Sita, gather food, guard the path, and make the forest journey his own duty. Rama sends Lakshmana for the bows and protective equipment entrusted to the household. At the same time, wealth and belongings are distributed rather than carried into exile. Kaikeyi brings forest garments. Rama and Lakshmana change; Sita''s discomfort and the elders'' protest are not treated as a ritual instruction or a triumphant spectacle. The three seek blessings from parents and mothers amid grief, counsel, argument, and embraces. Departure is a household rupture before it becomes adventure. Rama, Sita, and Lakshmana stand ready together. The city is still dressed for coronation, but the next movement is toward the gate and the forest beyond.', 'source_aligned', 'published'),
  ('scene-lakshmana-joins', 'hi', 'लक्ष्मण साथ चलने की अनुमति माँगते हैं', 'एक राजा के राज्याभिषेक की जगह तीन यात्रियों का प्रस्थान सामने आता है।', 'लक्ष्मण कहते हैं कि वे राम और सीता के आगे चलेंगे, भोजन जुटाएँगे, मार्ग की रक्षा करेंगे और वन-यात्रा को अपना दायित्व बनाएँगे। राम लक्ष्मण को परिवार के पास सुरक्षित धनुष और रक्षा-सामग्री लाने भेजते हैं। साथ ही धन और वस्तुएँ वन ले जाने के बजाय बाँटी जाती हैं। कैकेयी वन-वस्त्र लाती हैं। राम और लक्ष्मण बदलते हैं; सीता की असुविधा और बड़ों के विरोध को न अनुष्ठान-निर्देश बनाया जाता है, न विजय-दृश्य। तीनों शोक, सलाह, तर्क और आलिंगन के बीच माता-पिता और माताओं से आशीर्वाद लेते हैं। प्रस्थान रोमांच बनने से पहले परिवार का टूटना है। राम, सीता और लक्ष्मण साथ खड़े हैं। नगर अभी भी राज्याभिषेक के लिए सजा है, पर अगला कदम द्वार और उसके पार वन की ओर है।', 'source_aligned', 'published'),
  ('turn-road-out-of-ayodhya', 'en', 'The road out of Ayodhya', 'Citizens follow, Guha helps at the Ganga, and the three travellers make a forest home at Chitrakuta.', 'Citizens follow, Guha helps at the Ganga, and the three travellers make a forest home at Chitrakuta.', 'source_aligned', 'published'),
  ('turn-road-out-of-ayodhya', 'hi', 'अयोध्या से बाहर की राह', 'नगरवासी पीछे चलते हैं, गंगा पर गुह सहायता करते हैं और तीनों चित्रकूट में वन-घर बनाते हैं।', 'नगरवासी पीछे चलते हैं, गंगा पर गुह सहायता करते हैं और तीनों चित्रकूट में वन-घर बनाते हैं।', 'source_aligned', 'published'),
  ('scene-city-follows-car', 'en', 'The city follows', 'The exile leaves the palace and becomes the grief of an entire city.', 'As the car leaves, voices rise through the royal apartments. The people who depended on Rama ask where their refuge is going; private loss spills into the city. Dasharatha keeps his eyes on the departing car until even its dust disappears. Only then does his body give way and Kausalya helps raise him from the road. Inside the darkened palace, Kausalya imagines the three without familiar beds, food, or shelter. Her grief stretches ahead to the day Ayodhya might see them return. Sumitra does not erase the pain. She reminds Kausalya that Lakshmana and Sita chose to accompany Rama and insists that the road can still end in return. Citizens follow on foot and ask the horses to stop. Rama leaves the car to walk beside elders who cannot keep pace, and darkness finds the crowd still following.', 'source_aligned', 'published'),
  ('scene-city-follows-car', 'hi', 'अंतःपुर में विलाप उठता है', 'वनवास महल से निकलकर पूरे नगर का शोक बन जाता है।', 'रथ निकलते ही राजमहल के अंतःपुर में स्वर उठते हैं। राम पर निर्भर लोग पूछते हैं कि उनका सहारा कहाँ जा रहा है; निजी हानि पूरे नगर में फैल जाती है। दशरथ जाते रथ को तब तक देखते हैं जब तक उसकी धूल भी ओझल नहीं हो जाती। तभी उनका शरीर जवाब देता है और कौसल्या उन्हें मार्ग से उठाती हैं। अँधेरे महल में कौसल्या तीनों को परिचित शय्या, भोजन और आश्रय के बिना सोचती हैं। उनका शोक उस दिन तक फैलता है जब अयोध्या उन्हें लौटते देख सकेगी। सुमित्रा पीड़ा को नकारती नहीं हैं। वे कौसल्या को याद दिलाती हैं कि लक्ष्मण और सीता ने राम का साथ चुना है और यह राह वापसी पर भी समाप्त हो सकती है। नगरवासी पैदल पीछे चलते हैं और घोड़ों से रुकने की विनती करते हैं। राम धीमे चल रहे बुज़ुर्गों के साथ पैदल हो जाते हैं, और अँधेरा भीड़ को अब भी मार्ग पर पाता है।', 'source_aligned', 'published'),
  ('scene-tamasa-night', 'en', 'The first night at the Tamasa', 'The first night of exile ends with a departure the sleeping city cannot prevent.', 'At the Tamasa, Rama calls this the first night of exile. He speaks of the parents and city behind them while the forest answers with birds and animals settling into darkness. The citizens who followed lie exhausted nearby. Their determination has carried a piece of Ayodhya into the open country, but fatigue finally closes their eyes. Rama says a ruler should not let citizens destroy themselves for his hardship. He chooses to leave while they sleep rather than keep rewarding their refusal to turn home. Sumantra first drives north, then turns and takes the forest road so the trail cannot be followed. The chariot crosses the Tamasa before dawn fully arrives. At sunrise the followers find no car and lose its track. Their return to Ayodhya is not defeat in one line: homes, markets, kitchens, music, and ordinary recognition all fall silent.', 'source_aligned', 'published'),
  ('scene-tamasa-night', 'hi', 'राम पहली रात को पहचानते हैं', 'वनवास की पहली रात ऐसे प्रस्थान में बदलती है जिसे सोया नगर रोक नहीं सकता।', 'तमसा के तट पर राम इसे वनवास की पहली रात कहते हैं। वे पीछे छूटे माता-पिता और नगर की बात करते हैं, जबकि वन पक्षियों और पशुओं के रात्रि-स्वरों से उत्तर देता है। पीछे आए नगरवासी पास ही थककर लेट जाते हैं। उनका संकल्प अयोध्या का एक अंश खुले प्रदेश तक ले आया है, पर थकान अंततः उनकी आँखें बंद कर देती है। राम कहते हैं कि शासक को अपनी कठिनाई के कारण प्रजा को स्वयं कष्ट में नहीं डालना चाहिए। वे उनके जागने से पहले निकलना चुनते हैं, ताकि उनका लौटने से इंकार बढ़े नहीं। सुमंत्र पहले रथ उत्तर की ओर ले जाते हैं, फिर मोड़कर वनमार्ग पकड़ते हैं ताकि चिह्नों का पीछा न हो सके। पूर्ण भोर से पहले रथ तमसा पार कर जाता है। सूर्योदय पर अनुयायियों को रथ नहीं मिलता और उसके चिह्न खो जाते हैं। उनकी अयोध्या-वापसी एक पंक्ति की हार नहीं—घर, बाज़ार, रसोई, संगीत और रोज़मर्रा की पहचान सब मौन हो जाते हैं।', 'source_aligned', 'published'),
  ('scene-roads-beyond-kosala', 'en', 'Beyond Kosala', 'Ayodhya becomes a promise behind them as the Ganga opens ahead.', 'Passing ploughed fields and flowering woods, the travellers hear villagers condemn the decision that sent them away. The political rupture travels faster than the car. The Vedashruti, Gomati, and Sandika are crossed amid cultivated land, birds, and cattle. Each waterline makes the palace world less immediate. At the edge of Kosala, Rama turns back, salutes the city and its guardians, and says he will return after completing what he owes his father. The journey reaches a river too vast to be another passing stream. Water, sandbanks, birds, trees, and hermitages expand into a new world beside Shringaverapura. Guha comes with kin and offerings, embraces Rama, and asks after the journey. The first welcome beyond Kosala is offered as friendship, not as a faceless service stop.', 'source_aligned', 'published'),
  ('scene-roads-beyond-kosala', 'hi', 'गाँव खुलकर बोलते हैं', 'अयोध्या पीछे छूटा वचन बनती है और आगे गंगा खुलती है।', 'जुते खेतों और फूलते वनों से गुजरते हुए यात्री गाँववालों को उस निर्णय की निंदा करते सुनते हैं जिसने उन्हें भेजा। राजनीतिक टूटन रथ से भी तेज़ फैलती है। वेदश्रुति, गोमती और स्यंदिका को खेतों, पक्षियों और पशुओं के बीच पार किया जाता है। हर जलरेखा महल के संसार को थोड़ा और दूर कर देती है। कोसल की सीमा पर राम पीछे मुड़कर नगर और उसके रक्षकों को प्रणाम करते हैं और कहते हैं कि पिता का दायित्व पूरा कर वे लौटेंगे। यात्रा ऐसी नदी तक पहुँचती है जो केवल एक और धारा नहीं। जल, रेतीले तट, पक्षी, वृक्ष और आश्रम शृंगवेरपुर के पास एक नया संसार खोलते हैं। गुह अपने लोगों और भेंटों के साथ आते हैं, राम को आलिंगन देते हैं और यात्रा का हाल पूछते हैं। कोसल के बाहर पहला स्वागत मित्रता है, कोई अनाम पड़ाव नहीं।', 'source_aligned', 'published'),
  ('scene-guha-night-watch', 'en', 'Guha keeps watch', 'Hospitality becomes shared vigilance around a friendship that refuses indifference.', 'Food, beds, supplies, protection, and even the settlement are placed before Rama. Guha''s welcome has political weight as well as personal affection. Rama accepts the affection but declines comforts incompatible with the life he has undertaken. He asks only that Dasharatha''s horses be fed and tended well. After water and evening observance, Rama and Sita lie beneath the tree. The image is not serene decoration: everyone watching knows what comforts and people lie behind them. Guha offers Lakshmana rest and takes responsibility for protection. Lakshmana answers that he cannot sleep while Rama and Sita lie on grass before him. Lakshmana speaks his fear that Dasharatha and the mothers may not survive the night. Guha listens, weeps, and keeps watch with him until daybreak.', 'source_aligned', 'published'),
  ('scene-guha-night-watch', 'hi', 'गुह अपने पास का सब कुछ प्रस्तुत करते हैं', 'आतिथ्य ऐसी साझा चौकसी बनता है जिसमें मित्रता उदासीन नहीं रह सकती।', 'भोजन, शय्या, सामग्री, सुरक्षा और यहाँ तक कि अपना क्षेत्र भी गुह राम के सामने रखते हैं। उनका स्वागत निजी स्नेह के साथ राजनीतिक भार भी रखता है। राम स्नेह स्वीकार करते हैं, पर अपने चुने वनजीवन से असंगत सुख-सामग्री नहीं। वे केवल दशरथ के घोड़ों के भोजन और देखभाल का आग्रह करते हैं। जल और संध्या-क्रम के बाद राम और सीता वृक्ष के नीचे लेटते हैं। यह केवल शांत सजावट नहीं—देखने वाले जानते हैं कि उनके पीछे कौन-से सुख और लोग छूटे हैं। गुह लक्ष्मण को विश्राम देते और सुरक्षा की जिम्मेदारी लेते हैं। लक्ष्मण कहते हैं कि राम और सीता को घास पर सोते देखकर वे कैसे सो सकते हैं। लक्ष्मण अपना भय कहते हैं कि दशरथ और माताएँ शायद यह रात न सह सकें। गुह सुनते हैं, आँसू बहाते हैं और भोर तक उनके साथ पहरा देते हैं।', 'source_aligned', 'published'),
  ('scene-ganga-crossing', 'en', 'The Ganga divides two lives', 'The chariot turns back while the three travellers cross into a life that must continue on foot.', 'Bird calls announce morning and Guha has a strong boat brought to the bank. Bows, quivers, travel bundles, and Sita must all cross together. Sumantra pleads to remain for all fourteen years. He imagines Ayodhya seeing the empty car and asks how a truth so painful can be carried back. Rama asks Sumantra to steady Dasharatha, greet the mothers, summon Bharata, and report that the three do not regret keeping the command. The empty car will carry words. With Guha''s help, Rama and Lakshmana bind their hair into matted locks. The change is treated as their source-story decision, not a costume reward or instruction for the user. In the middle of the Ganga, Sita prays that the vow be completed and that all three return. The prayer belongs to this character and moment; it is not presented as universal modern vidhi.', 'source_aligned', 'published'),
  ('scene-ganga-crossing', 'hi', 'भोर में नाव तैयार है', 'रथ लौटता है और तीनों ऐसी जीवन-यात्रा में पार जाते हैं जो अब पैदल चलेगी।', 'पक्षियों के स्वर भोर बताते हैं और गुह मजबूत नाव तट पर मँगवाते हैं। धनुष, तरकश, यात्रा-सामान और सीता—सबको साथ पार होना है। सुमंत्र चौदहों वर्ष साथ रहने की विनती करते हैं। वे खाली रथ को देखती अयोध्या की कल्पना करते हैं और पूछते हैं कि इतना पीड़ादायक सत्य कैसे लौटाया जाए। राम सुमंत्र से दशरथ को संभालने, माताओं को प्रणाम कहने, भरत को बुलाने और यह बताने को कहते हैं कि तीनों आदेश निभाने पर पछता नहीं रहे। खाली रथ अब शब्द ले जाएगा। गुह की सहायता से राम और लक्ष्मण जटा बाँधते हैं। यह परिवर्तन स्रोत-कथा का उनका निर्णय है, कोई पोशाक-इनाम या उपयोगकर्ता के लिए निर्देश नहीं। गंगा की मध्यधारा में सीता प्रार्थना करती हैं कि व्रत पूरा हो और तीनों लौटें। यह इस पात्र और क्षण की प्रार्थना है, सार्वभौमिक आधुनिक विधि नहीं।', 'source_aligned', 'published'),
  ('scene-first-forest-night', 'en', 'The first forest night', 'Without road, car, or escort, grief finally speaks without ceremony.', 'Under a great tree, Rama names this the first night beyond inhabited country without Sumantra. Leaves must become the bed and the three must provide for one another. Rama imagines Dasharatha weakened, Kausalya exposed, and Kaikeyi pressing her advantage. Exile does not switch off anxiety about the household left behind. He admits that force could seize Ayodhya, then rejects the act as wrong. The scene preserves the anger and the refusal instead of flattening him into effortless calm. Lakshmana tells Rama that neither he nor Sita can live apart from him. His answer does not solve Ayodhya; it makes companionship present in this forest. The conversation ends in practical care. A bed of leaves is spread, the night is endured, and the three remain together in a place no palace plan prepared them to inhabit.', 'source_aligned', 'published'),
  ('scene-first-forest-night', 'hi', 'रथ अब जा चुका है', 'मार्ग, रथ और साथियों के बिना शोक पहली बार बिना औपचारिकता के बोलता है।', 'एक विशाल वृक्ष के नीचे राम इसे सुमंत्र और बस्ती से बाहर पहली रात कहते हैं। पत्ते शय्या बनेंगे और तीनों को एक-दूसरे की देखभाल करनी होगी। राम दशरथ को निर्बल, कौसल्या को असुरक्षित और कैकेयी को अपना लाभ बढ़ाते सोचते हैं। वनवास पीछे छूटे परिवार की चिंता बंद नहीं करता। वे स्वीकारते हैं कि बल से अयोध्या ली जा सकती है, फिर उस कर्म को अनुचित कहकर छोड़ते हैं। दृश्य उन्हें सहज शांत बनाने के बजाय क्रोध और उसके त्याग दोनों को रखता है। लक्ष्मण कहते हैं कि न वे, न सीता राम से अलग रह सकते हैं। उनका उत्तर अयोध्या की समस्या नहीं सुलझाता; वह इस वन में साथ को उपस्थित करता है। संवाद व्यावहारिक देखभाल में समाप्त होता है। पत्तों की शय्या बिछती है, रात काटी जाती है और तीनों ऐसे स्थान में साथ रहते हैं जिसके लिए किसी महल-योजना ने उन्हें तैयार नहीं किया था।', 'source_aligned', 'published'),
  ('scene-prayaga-to-yamuna', 'en', 'From the confluence to the Yamuna', 'Guidance turns an unknown forest into a chosen road toward Chitrakoot.', 'Near evening, Rama sees smoke and hears the meeting waters of Ganga and Yamuna. Signs of human practice reveal Bharadvaja''s hermitage before the travellers reach it. The three introduce themselves and explain the exile. Bharadvaja offers water, food from the forest, a place to rest, and the possibility of staying at the confluence. Rama worries that people from the city will keep coming if he stays nearby. He asks for a place where Sita can live well without making the hermitage a public court. Bharadvaja describes the mountain, its fruit, water, animals, ascetics, and paths. The next destination becomes a lived landscape rather than an abstract name. The brothers build a raft and a seat for Sita. Midstream she voices another hope of return; beyond the bank, flowers, the Syama tree, birds, and new questions make the road active.', 'source_aligned', 'published'),
  ('scene-prayaga-to-yamuna', 'hi', 'दो नदियों के ऊपर धुआँ उठता है', 'मार्गदर्शन अनजान वन को चित्रकूट की चुनी हुई राह में बदल देता है।', 'साँझ के पास राम धुआँ देखते और गंगा-यमुना के मिलते जल की ध्वनि सुनते हैं। मानवीय साधना के संकेत यात्रियों के पहुँचने से पहले भरद्वाज के आश्रम का पता देते हैं। तीनों अपना परिचय और वनवास बताते हैं। भरद्वाज जल, वन का भोजन, विश्राम-स्थान और संगम पर रहने की संभावना देते हैं। राम सोचते हैं कि पास रहने पर नगर के लोग आते रहेंगे। वे ऐसी जगह पूछते हैं जहाँ सीता ठीक रह सकें और आश्रम सार्वजनिक दरबार न बन जाए। भरद्वाज पर्वत, फल, जल, पशु, तपस्वी और मार्गों का वर्णन करते हैं। अगला पड़ाव अमूर्त नाम के बजाय रहने योग्य भू-दृश्य बन जाता है। भाई बेड़ा और सीता के लिए आसन बनाते हैं। मध्यधारा में वे फिर वापसी की आशा कहती हैं; दूसरे तट पर फूल, श्यामा-वृक्ष, पक्षी और नए प्रश्न राह को जीवित रखते हैं।', 'source_aligned', 'published'),
  ('scene-chitrakoot-home', 'en', 'A home at Chitrakoot', 'The road pauses because the travellers make—not merely find—a home.', 'Rama wakes Lakshmana to the forest''s bird calls. Flowering trees, fruit, honeycombs, peacocks, and elephants make the approach to Chitrakoot feel inhabited before any cottage exists. At Chitrakoot, water, roots, fruit, birds, and ascetic communities make subsistence imaginable. Rama says plainly: let this be our abode. In this selected Dutt edition, the travellers greet Valmiki and explain their journey. The district keeps that edition-specific sequence without claiming every Ramayana places the encounter here. Rama chooses the site and Lakshmana gathers strong wood, raises walls and doors, and thatches the roof with leaves. The first forest home appears through work. The source describes household rites before entry; Devam presents them as narrative evidence, not current user instruction. When the three enter, the text allows city-grief to loosen for the first time.', 'source_aligned', 'published'),
  ('scene-chitrakoot-home', 'hi', 'पक्षियों का स्वर अंतिम चाल शुरू करता है', 'राह इसलिए ठहरती है क्योंकि यात्री घर केवल पाते नहीं, बनाते हैं।', 'राम वन-पक्षियों के स्वर पर लक्ष्मण को जगाते हैं। फूलते वृक्ष, फल, मधुकोष, मोर और हाथी किसी कुटिया से पहले ही चित्रकूट को जीवित बना देते हैं। चित्रकूट में जल, कंद, फल, पक्षी और तपस्वी समुदाय जीवन को संभव बनाते हैं। राम स्पष्ट कहते हैं—यही हमारा निवास हो। इस चुने हुए दत्त संस्करण में यात्री वाल्मीकि को प्रणाम कर अपनी यात्रा बताते हैं। यह जिला इसी संस्करण-विशिष्ट क्रम को रखता है, इसे हर रामायण का क्रम नहीं कहता। राम स्थान चुनते हैं और लक्ष्मण मजबूत लकड़ी जुटाकर दीवारें और द्वार खड़े करते, पत्तों की छत डालते हैं। पहला वन-घर श्रम से सामने आता है। स्रोत प्रवेश से पहले गृह-क्रम बताता है; देवम् उसे कथा-साक्ष्य के रूप में रखता है, आज के उपयोगकर्ता के निर्देश की तरह नहीं। तीनों के भीतर आते ही नगर-वियोग पहली बार कुछ ढीला पड़ता है।', 'source_aligned', 'published'),
  ('scene-empty-chariot-return', 'en', 'The empty chariot returns', 'The chariot returns, but the people it carried do not.', 'After learning that Rama, Sita, and Lakshmana have reached Bharadvaja and are bound for Chitrakoot, Sumantra leaves Guha. The car that carried the exile out now bears only its witness back. At dusk, Ayodhya looks still and joyless. Hundreds surround the returning car and ask where Rama is; the answer that he crossed the Ganga moves through streets and palace windows as a fresh wave of grief. Revived from a faint, Dasharatha asks what the three eat, where they sleep, how Sita walks, and what each person said. The questions are not court business; they are a father trying to rebuild the vanished road in his mind. Sumantra carries Rama''s respectful messages to parents and Bharata, Lakshmana''s anger at the exile, and Sita''s wordless tears beside the departing car. The people are absent, but their distinct responses fill the chamber. Sumantra remembers the horses slowing and shedding tears when he turned away. He describes a kingdom whose streets, gardens, animals, and people all appear altered by the same absence; Dasharatha begs to be taken after the car again.', 'source_aligned', 'published'),
  ('scene-empty-chariot-return', 'hi', 'सुमंत्र अंततः घर की ओर मुड़ते हैं', 'रथ लौटता है, पर जिन्हें वह ले गया था वे नहीं लौटते।', 'राम, सीता और लक्ष्मण के भरद्वाज तक पहुँचने और चित्रकूट जाने का समाचार पाकर सुमंत्र गुह से विदा लेते हैं। जो रथ वनवास को बाहर ले गया था, अब केवल उसके साक्षी को वापस ला रहा है। साँझ में अयोध्या स्थिर और उदास दिखती है। सैकड़ों लोग लौटे रथ को घेरकर राम का पता पूछते हैं; गंगा पार करने का उत्तर गलियों और महल की खिड़कियों में शोक की नई लहर बन जाता है। मूर्छा से लौटकर दशरथ पूछते हैं कि तीनों क्या खाते हैं, कहाँ सोते हैं, सीता कैसे चलती हैं और किसने क्या कहा। ये राजकाज के प्रश्न नहीं—एक पिता अपने मन में खोई राह फिर से बना रहा है। सुमंत्र माता-पिता और भरत के लिए राम के सम्मानपूर्ण संदेश, वनवास पर लक्ष्मण का क्रोध और जाते रथ के पास सीता के मौन आँसू सुनाते हैं। लोग उपस्थित नहीं, पर उनकी अलग-अलग प्रतिक्रियाएँ कक्ष भर देती हैं। सुमंत्र याद करते हैं कि लौटते समय घोड़े धीमे पड़े और आँसू बहाते रहे। वे बताते हैं कि गलियाँ, उद्यान, पशु और लोग—पूरा राज्य उसी अनुपस्थिति से बदला दिखता है; दशरथ फिर रथ के पीछे ले चलने की विनती करते हैं।', 'source_aligned', 'published'),
  ('turn-king-dies-bharata-returns', 'en', 'A king dies; Bharata returns', 'Dasharatha dies in grief. Bharata returns to a crown he never asked for and learns how it was won.', 'Dasharatha dies in grief. Bharata returns to a crown he never asked for and learns how it was won.', 'source_aligned', 'published'),
  ('turn-king-dies-bharata-returns', 'hi', 'राजा का अंत, भरत की वापसी', 'दशरथ शोक में प्राण त्यागते हैं। भरत लौटकर उस सिंहासन का सत्य जानते हैं जिसे उन्होंने कभी माँगा नहीं।', 'दशरथ शोक में प्राण त्यागते हैं। भरत लौटकर उस सिंहासन का सत्य जानते हैं जिसे उन्होंने कभी माँगा नहीं।', 'source_aligned', 'published'),
  ('scene-palace-grief-dialogue', 'en', 'Grief speaks in the palace', 'The palace stops hiding the human cost of the command.', 'Kausalya asks Sumantra to turn the car toward the forest because life without the three feels impossible. Her demand is grief speaking before counsel can make the situation orderly. He says Lakshmana serves them attentively and Sita keeps asking about rivers, villages, trees, and the changing landscape. The report does not erase hardship; it gives Kausalya evidence that the travellers are still acting, noticing, and caring for one another. Kausalya asks how a gentle son, a young daughter-in-law, and Lakshmana can bear the forest after palace life. Her speech widens from family pain to a ruined city and a kingdom whose future has been damaged by its own king. Dasharatha joins his hands and asks Kausalya not to strike him with further words while he is already broken. She immediately recognizes the pain her speech added and bows, without pretending the original wrong has vanished. Kausalya says sorrow destroys patience and knowledge, and that the five nights since Rama left have stretched into years. Evening closes around a temporary reconciliation, but Dasharatha''s older memory has already begun to rise.', 'source_aligned', 'published'),
  ('scene-palace-grief-dialogue', 'hi', 'कौसल्या उनके पास ले चलने को कहती हैं', 'महल अब आदेश की मानवीय कीमत छिपा नहीं पाता।', 'कौसल्या सुमंत्र से रथ वन की ओर मोड़ने को कहती हैं, क्योंकि तीनों के बिना जीवन असंभव लगता है। व्यवस्था समझाने से पहले उनका शोक बोलता है। वे बताते हैं कि लक्ष्मण सावधानी से सेवा कर रहे हैं और सीता नदियों, गाँवों, वृक्षों और बदलते भू-दृश्य के बारे में पूछती चल रही हैं। यह कठिनाई नहीं मिटाता; बस बताता है कि तीनों अभी भी सक्रिय हैं, देख रहे हैं और एक-दूसरे का ध्यान रख रहे हैं। कौसल्या पूछती हैं कि महल के जीवन के बाद कोमल पुत्र, युवा पुत्रवधू और लक्ष्मण वन कैसे सहेंगे। उनका कथन परिवार के दर्द से फैलकर टूटे नगर और अपने ही राजा से घायल भविष्य तक पहुँचता है। दशरथ हाथ जोड़कर कौसल्या से कहते हैं कि वे पहले ही टूट चुके हैं, इसलिए शब्दों से और न घायल करें। कौसल्या तुरंत अपने शब्दों की चोट पहचानकर झुकती हैं, पर मूल अन्याय को मिटा हुआ नहीं मानतीं। कौसल्या कहती हैं कि शोक धैर्य और ज्ञान दोनों नष्ट करता है, और राम के जाने की पाँच रातें वर्षों जैसी हो गई हैं। अस्थायी मेल के चारों ओर रात उतरती है, पर दशरथ की पुरानी स्मृति जाग चुकी है।', 'source_aligned', 'published'),
  ('scene-river-sound-confession', 'en', 'The sound by the river', 'Dasharatha understands the present through an old, irreversible mistake.', 'Dasharatha wakes at midnight and tells Kausalya that actions ripen into consequences. Rama''s exile has brought back a deed from his youth that he had never escaped. As a young prince in the rainy season, Dasharatha waits beside the Sarayu and hears what he believes is an animal filling the night with water sounds. Confident in shooting by sound, he releases an arrow without seeing the target. The cry from the water is an ascetic youth gathering water for his blind parents. Mortally wounded, he worries less about himself than about the two people waiting for him and directs Dasharatha to their hermitage. The blind parents welcome approaching steps as their son''s return. Dasharatha must identify himself, confess the error, lead them to the body, and stand inside grief he caused but cannot repair. The father says Dasharatha too will die from grief for a son. Remembering the curse, the old king feels his senses dim, calls for Rama, names the family around him, and dies before the night is half gone.', 'source_aligned', 'published'),
  ('scene-river-sound-confession', 'hi', 'छठी रात एक और हानि लौटती है', 'दशरथ वर्तमान को अपनी पुरानी, अपरिवर्तनीय भूल से समझते हैं।', 'आधी रात दशरथ जागकर कौसल्या से कहते हैं कि कर्म परिणाम बनकर लौटते हैं। राम का वनवास उनकी युवावस्था की उस घटना को वापस ले आया है जिससे वे कभी मुक्त नहीं हुए। वर्षा ऋतु में युवा राजकुमार दशरथ सरयू तट पर प्रतीक्षा करते हैं और जल भरने की ध्वनि को पशु समझते हैं। ध्वनि से निशाना लगाने के कौशल पर भरोसा कर वे लक्ष्य देखे बिना बाण छोड़ देते हैं। जल से उठी पुकार अपने दृष्टिहीन माता-पिता के लिए पानी भरते एक तपस्वी युवक की है। मृत्यु के निकट वह अपने से अधिक प्रतीक्षा करते माता-पिता की चिंता करता है और दशरथ को उनके आश्रम का मार्ग बताता है। दृष्टिहीन माता-पिता आती पदचाप को पुत्र की वापसी समझते हैं। दशरथ को अपना परिचय देना, भूल स्वीकारना, उन्हें शव तक ले जाना और उस शोक के भीतर खड़ा होना पड़ता है जिसे वे सुधार नहीं सकते। पिता कहते हैं कि दशरथ भी पुत्र-वियोग में प्राण देंगे। श्राप याद आते ही वृद्ध राजा की इंद्रियाँ मंद पड़ती हैं; वे राम और परिवार को पुकारते हैं और आधी रात बीतने से पहले प्राण छोड़ देते हैं।', 'source_aligned', 'published'),
  ('scene-city-without-king', 'en', 'Ayodhya wakes without a king', 'A private death becomes a civic emergency and a suspended farewell.', 'Bards, singers, attendants, sacred water, mirrors, garments, and royal service arrive as usual. The sun rises while everyone waits for a king who will not wake. The women beside Dasharatha finally feel that his pulse no longer moves. Their cries wake Kausalya and Sumitra, and the palace understands all at once what happened during the night. Kausalya holds Dasharatha''s head and addresses Kaikeyi; the other queens gather, and grief fills halls, terraces, and streets already wounded by Rama''s absence. With the sons absent, the counsellors do not perform the final rites. Dasharatha''s body is placed in oil and the palace enters an unnatural pause between death and succession. At dawn, Vasishta and the counsellors describe the practical danger of a kingless realm—roads, trade, protection, fields, gatherings, and public trust can all unravel. The empty throne is now more than a symbol. Vasishta sends fast riders to Kekaya to bring Bharata and Shatrughna. They are ordered not to mention Dasharatha''s death or Rama''s exile; urgency must travel without its reason.', 'source_aligned', 'published'),
  ('scene-city-without-king', 'hi', 'सुबह पुरानी दिनचर्या निभाती है', 'निजी मृत्यु नगर का संकट और रुकी हुई विदाई बन जाती है।', 'गायक, वंशवाचक, सेवक, पवित्र जल, दर्पण, वस्त्र और राजसेवा हमेशा की तरह पहुँचते हैं। सूर्य उगता है, पर सब उस राजा की प्रतीक्षा करते हैं जो अब नहीं जागेगा। दशरथ के पास बैठी स्त्रियाँ अंततः पाती हैं कि उनकी नाड़ी नहीं चल रही। उनके विलाप से कौसल्या और सुमित्रा जागती हैं, और महल एक साथ रात की घटना समझ लेता है। कौसल्या दशरथ का सिर गोद में लेकर कैकेयी से बोलती हैं; अन्य रानियाँ जुटती हैं और राम की अनुपस्थिति से पहले ही घायल सभागार, छतें और गलियाँ शोक से भर जाती हैं। पुत्रों की अनुपस्थिति में मंत्री अंतिम संस्कार नहीं करते। दशरथ का शरीर तेल में सुरक्षित रखा जाता है और महल मृत्यु तथा उत्तराधिकार के बीच अस्वाभाविक ठहराव में चला जाता है। भोर में वसिष्ठ और मंत्री राजाविहीन राज्य के व्यावहारिक संकट बताते हैं—मार्ग, व्यापार, सुरक्षा, खेत, सभाएँ और सार्वजनिक भरोसा सब बिखर सकते हैं। खाली सिंहासन अब केवल प्रतीक नहीं रहा। वसिष्ठ तेज घुड़सवारों को भरत और शत्रुघ्न को लाने के लिए केकय भेजते हैं। उन्हें दशरथ की मृत्यु और राम के वनवास का उल्लेख न करने का आदेश है; कारण के बिना ही तात्कालिकता यात्रा करती है।', 'source_aligned', 'published'),
  ('scene-bharata-urgent-return', 'en', 'Bharata races toward the silence', 'Before anyone tells Bharata, the world around him begins to reveal the loss.', 'On the night the messengers arrive, Bharata dreams of his father falling, the ocean drying, the moon descending, fire dying, and a dark southward journey. Music and performance cannot make him laugh afterward. Bharata asks after Dasharatha, Rama, Lakshmana, Kausalya, Sumitra, and Kaikeyi. The envoys say those he asks about are well and insist that a matter cannot wait; their careful phrasing deepens his unease. Bharata and Shatrughna leave their maternal family and travel for seven nights across rivers, forests, settlements, and difficult crossings. The geographic sequence becomes a countdown to news they do not yet possess. From a distance Bharata sees no crowds, hears no instruments, smells no incense, and finds gardens, shops, shrines, and homes neglected. He recognizes the signs that accompany a monarch''s death. Bharata dismisses the gatekeepers'' courtesies and enters with his head bowed. His father''s quarters are empty, so the urgent journey ends at Kaikeyi''s door.', 'source_aligned', 'published'),
  ('scene-bharata-urgent-return', 'hi', 'एक स्वप्न उत्सव को अस्वीकार करता है', 'किसी के बताने से पहले ही भरत के आसपास की दुनिया हानि प्रकट करने लगती है।', 'दूतों के आने की रात भरत पिता के गिरने, समुद्र सूखने, चंद्रमा उतरने, अग्नि बुझने और अँधेरी दक्षिण दिशा की यात्रा का स्वप्न देखते हैं। उसके बाद संगीत और अभिनय भी उन्हें हँसा नहीं पाते। भरत दशरथ, राम, लक्ष्मण, कौसल्या, सुमित्रा और कैकेयी का कुशल पूछते हैं। दूत कहते हैं कि जिनका वे पूछ रहे हैं वे कुशल हैं और एक काम विलंब नहीं सहता; सँभली हुई भाषा उनकी बेचैनी बढ़ाती है। भरत और शत्रुघ्न ननिहाल से निकलकर सात रातें नदियों, वनों, बस्तियों और कठिन पारों से गुजरते हैं। भूगोल उस समाचार की उलटी गिनती बन जाता है जो उन्हें अभी नहीं मिला। दूर से भरत न भीड़ देखते हैं, न वाद्य सुनते हैं, न धूप की गंध पाते हैं; उद्यान, दुकानें, पूजा-स्थल और घर उपेक्षित हैं। वे राजा की मृत्यु के साथ आने वाले संकेत पहचान लेते हैं। भरत द्वारपालों की औपचारिकता रोककर सिर झुकाए भीतर जाते हैं। पिता का कक्ष खाली है, इसलिए तात्कालिक यात्रा कैकेयी के द्वार पर समाप्त होती है।', 'source_aligned', 'published'),
  ('scene-bharata-rejects-boons', 'en', 'Bharata rejects the boons', 'The person for whom the boons were claimed rejects their meaning and result.', 'Kaikeyi rises, embraces Bharata, asks about the journey, and expects the room to become triumphant. Bharata instead notices his father''s missing bed and asks where the king is. Kaikeyi says Dasharatha has reached the end common to all beings. Bharata collapses, grieves the father whose hand once brushed dust from him, and asks for Rama as his elder, refuge, and next father. When Bharata asks to go to Rama, Kaikeyi tells him that Rama, Sita, and Lakshmana wear bark in the forest. Bharata first assumes Rama must have committed some grave wrong; he cannot imagine exile without fault. She explains that Rama did no wrong: she herself demanded Bharata''s kingdom and Rama''s exile, Dasharatha kept his promise and died grieving, and now Bharata should perform the funeral and take power. Bharata says the kingdom cannot replace father or elder brother, denies any knowledge of the plan, rejects Kaikeyi''s purpose, and vows to bring Rama from the forest and serve him.', 'source_aligned', 'published'),
  ('scene-bharata-rejects-boons', 'hi', 'कैकेयी उस पुत्र का स्वागत करती हैं जिससे पुरस्कार की आशा थी', 'जिसके लिए वर माँगे गए थे, वही उनके अर्थ और परिणाम को अस्वीकार करता है।', 'कैकेयी उठकर भरत को गले लगाती हैं, यात्रा पूछती हैं और कक्ष के विजयी होने की अपेक्षा रखती हैं। भरत पिता की खाली शय्या देखते हैं और राजा का पता पूछते हैं। कैकेयी कहती हैं कि दशरथ सभी प्राणियों की समान अंतिम अवस्था को प्राप्त हुए। भरत गिर पड़ते हैं, उस पिता का शोक करते हैं जो उनके शरीर से धूल झाड़ता था, और राम को बड़े भाई, आश्रय और अब पिता के समान पुकारते हैं। भरत राम के पास जाने को कहते हैं तो कैकेयी बताती हैं कि राम, सीता और लक्ष्मण वल्कल पहनकर वन में हैं। भरत पहले किसी गंभीर अपराध की आशंका करते हैं; दोष बिना वनवास की कल्पना नहीं कर पाते। वे बताती हैं कि राम ने कोई अपराध नहीं किया: उन्होंने स्वयं भरत के लिए राज्य और राम का वनवास माँगा, दशरथ ने वचन निभाया और शोक में मरे, इसलिए अब भरत संस्कार कर सत्ता लें। भरत कहते हैं कि राज्य पिता या बड़े भाई का स्थान नहीं ले सकता, योजना की जानकारी से इंकार करते हैं, कैकेयी के उद्देश्य को अस्वीकार करते हैं और राम को वन से लाकर उनकी सेवा करने की प्रतिज्ञा करते हैं।', 'source_aligned', 'published'),
  ('scene-funeral-and-trust', 'en', 'Mourning becomes trust', 'Suspicion inside the family gives way to shared mourning and a verified intention.', 'Hearing Bharata''s voice, Kausalya meets him while still believing he may have wanted the kingdom. She asks to be sent to Rama rather than live inside the result of Kaikeyi''s plan. He falls at Kausalya''s feet and swears that he neither desired the kingdom nor knew of the exile. The long oath is the story''s way of making his innocence answerable, not merely asserted. Kausalya tells Bharata that his loyalty to what is right makes the oath itself painful to hear. She draws him into her lap, and their separate grief becomes a shared commitment to Rama. Vasishta asks Bharata to perform the rites. Dasharatha''s body is raised from the oil, placed on a bier, and carried with priests, queens, attendants, incense, lament, and gifts toward the funeral ground. The family performs water rites, sleeps on the ground through the mourning period, completes the shraddha, and returns to gather bones and ashes. Bharata and Shatrughna both collapse under the renewed finality. Vasishta and Sumantra lift the brothers and remind them that the remaining rites must be completed. The scene does not end grief; it establishes that action must now continue through it.', 'source_aligned', 'published'),
  ('scene-funeral-and-trust', 'hi', 'कौसल्या अभी नहीं जानतीं किस पर भरोसा करें', 'परिवार का संदेह साझा शोक और प्रमाणित संकल्प में बदलता है।', 'भरत की आवाज़ सुनकर कौसल्या उनसे मिलती हैं, पर अभी मानती हैं कि वे राज्य चाहते थे। वे कैकेयी की योजना के परिणाम में रहने के बजाय राम के पास भेजे जाने को कहती हैं। वे कौसल्या के चरणों में गिरकर शपथ लेते हैं कि न उन्होंने राज्य चाहा, न वनवास जाना। लंबी शपथ उनकी निर्दोषता को केवल कथन नहीं, उत्तरदायित्व बनाती है। कौसल्या कहती हैं कि धर्मनिष्ठ भरत की शपथ सुनना ही उन्हें और दुख देता है। वे उन्हें गोद में खींचती हैं और अलग-अलग शोक राम के प्रति साझा संकल्प बन जाता है। वसिष्ठ भरत से संस्कार करने को कहते हैं। दशरथ का शरीर तेल से उठाकर अर्थी पर रखा जाता है और पुरोहितों, रानियों, सेवकों, सुगंध, विलाप तथा दान के साथ श्मशान की ओर ले जाया जाता है। परिवार जलांजलि देता है, शोक अवधि में भूमि पर सोता है, श्राद्ध पूरा करता है और अस्थियाँ तथा राख लेने लौटता है। अंतिमता फिर सामने आते ही भरत और शत्रुघ्न दोनों टूट पड़ते हैं। वसिष्ठ और सुमंत्र भाइयों को उठाकर शेष संस्कार पूरे करने की याद दिलाते हैं। दृश्य शोक समाप्त नहीं करता; वह बताता है कि अब कर्म उसी के भीतर से आगे बढ़ेगा।', 'source_aligned', 'published'),
  ('turn-bharata-follows', 'en', 'Bharata follows the forest road', 'With the queens, ministers, and citizens, Bharata travels to bring Rama home.', 'With the queens, ministers, and citizens, Bharata travels to bring Rama home.', 'source_aligned', 'published'),
  ('turn-bharata-follows', 'hi', 'भरत वन की राह पकड़ते हैं', 'रानियों, मंत्रियों और नगरवासियों के साथ भरत राम को वापस लाने निकलते हैं।', 'रानियों, मंत्रियों और नगरवासियों के साथ भरत राम को वापस लाने निकलते हैं।', 'source_aligned', 'published'),
  ('scene-crown-refused-road', 'en', 'The crown becomes a road', 'The institutions prepared to crown Bharata are redirected toward restoring Rama.', 'Shatrughna seizes Manthara in anger over the destruction around them. Bharata stops him: harming her or killing his mother would itself estrange the very brother whose standard he intends to follow. Ministers place the installation materials before Bharata and argue that Dasharatha''s command has made the throne his. Their proposal is practical, lawful in their reading, and exactly what he refuses. He says the eldest must rule, Rama is king, and he will take the installation objects into the forest, ask Rama to return, and remain there himself if an exchange is required. Surveyors, diggers, carpenters, bridge-builders, cooks, guides, and camp workers go ahead. They level difficult ground, prepare crossings, find water, and establish the route for a huge public journey. At dawn, drums and genealogists wake Bharata with royal praise. He stops them with the words, ''I am not the king,'' before entering the great assembly called by Vasishta. When Vasishta again presents the throne, Bharata refuses before the gathered city, promises every effort to bring Rama back, and orders Sumantra to ready the car and commanders to marshal the expedition.', 'source_aligned', 'published'),
  ('scene-crown-refused-road', 'hi', 'भरत वह दंड रोकते हैं जिसे राम स्वीकार न करते', 'भरत के राज्याभिषेक को तैयार संस्थाएँ राम को लौटाने की ओर मुड़ती हैं।', 'चारों ओर हुए विनाश पर क्रोधित शत्रुघ्न मंथरा को पकड़ लेते हैं। भरत उन्हें रोकते हैं: उसे हानि पहुँचाना या माँ की हत्या करना उसी भाई से दूर कर देगा जिसकी मर्यादा वे मानना चाहते हैं। मंत्री राज्याभिषेक-सामग्री भरत के सामने रखकर कहते हैं कि दशरथ की आज्ञा ने सिंहासन उन्हें दिया है। उनका प्रस्ताव व्यावहारिक और उनकी दृष्टि में वैध है—और भरत ठीक इसी को अस्वीकार करते हैं। वे कहते हैं कि ज्येष्ठ ही शासन करेंगे, राम राजा हैं; वे अभिषेक-सामग्री वन ले जाकर राम से लौटने की विनती करेंगे और आवश्यकता पड़ी तो स्वयं वहीं रहेंगे। सर्वेक्षक, खोदने वाले, बढ़ई, पुल बनाने वाले, रसोइए, मार्गदर्शक और शिविर-कर्मी आगे जाते हैं। वे कठिन भूमि समतल करते, पार बनाते, जल जुटाते और विशाल सार्वजनिक यात्रा की राह तैयार करते हैं। भोर में नगाड़े और वंशवाचक भरत को राजस्तुति से जगाते हैं। वे ''मैं राजा नहीं हूँ'' कहकर सब रोकते हैं और वसिष्ठ की बुलाई महान सभा में जाते हैं। वसिष्ठ सभा में फिर सिंहासन प्रस्तुत करते हैं तो भरत सबके सामने इंकार करते हैं, राम को लौटाने का हर प्रयास करने की प्रतिज्ञा करते हैं और सुमंत्र को रथ तथा सेनानायकों को यात्रा तैयार करने का आदेश देते हैं।', 'source_aligned', 'published'),
  ('scene-expedition-reaches-ganga', 'en', 'A kingdom reaches the Ganga', 'A refused crown becomes a journey large enough to alarm the river world ahead.', 'At dawn Bharata sets out with Shatrughna, the mothers, priests, counsellors, citizens, craftspeople, and an immense royal force. This is not a prince''s private visit; Ayodhya itself travels to ask Rama home. Along the road people ask when they will see Rama again and speak as though his face will end the city''s darkness. Hope spreads through embraces, carts, animals, and ordinary working households moving together. The expedition reaches Shringaverapura and must become a camp. Bharata plans the crossing and offers water for Dasharatha; the river is both physical boundary and the place where grief returns. Across the river, Guha sees a force without visible end and fears Bharata has come to secure the kingdom by harming Rama. He arms the riverbank and readies hundreds of boats to deny passage if necessary. Guha carries forest food and hospitality toward Bharata while keeping his people ready. Sumantra identifies him as Rama''s friend and the person most likely to know the road ahead. When Guha asks directly whether the army means harm, Bharata answers without court language: Rama is dear as a father, and he has come only to persuade his elder brother to return.', 'source_aligned', 'published'),
  ('scene-expedition-reaches-ganga', 'hi', 'एक राज्य सिंहासन पीछे छोड़कर निकलता है', 'अस्वीकार किया गया मुकुट इतनी विशाल यात्रा बनता है कि आगे का नदी-संसार सतर्क हो उठता है।', 'भोर में भरत शत्रुघ्न, माताओं, पुरोहितों, मंत्रियों, नागरिकों, कारीगरों और विशाल राजकीय दल के साथ निकलते हैं। यह किसी राजकुमार की निजी भेंट नहीं—अयोध्या स्वयं राम को घर बुलाने चलती है। राह में लोग पूछते हैं कि राम फिर कब दिखाई देंगे और मानते हैं कि उनका दर्शन नगर का अँधेरा दूर कर देगा। आलिंगनों, गाड़ियों, पशुओं और साथ चलते परिवारों में आशा फैलती है। यात्रा शृंगवेरपुर पहुँचकर शिविर बन जाती है। भरत पार जाने की व्यवस्था और दशरथ के लिए जल अर्पण की सोचते हैं; नदी भौतिक सीमा भी है और लौटता हुआ शोक भी। नदी के पार गुह ऐसा दल देखते हैं जिसका अंत नहीं दिखता और आशंका करते हैं कि भरत राम को हानि पहुँचाकर राज्य पक्का करने आए हैं। वे तट और सैकड़ों नावें रक्षा के लिए तैयार करते हैं। गुह वन का भोजन और आतिथ्य लेकर भरत के पास जाते हैं, जबकि उनके लोग सतर्क रहते हैं। सुमंत्र उन्हें राम का मित्र और आगे की राह जानने वाला व्यक्ति बताते हैं। जब गुह सीधे पूछते हैं कि क्या यह सेना हानि पहुँचाने आई है, भरत दरबारी भाषा छोड़कर कहते हैं—राम पिता समान प्रिय हैं और वे केवल उन्हें लौटाने आए हैं।', 'source_aligned', 'published'),
  ('scene-guha-shows-first-night', 'en', 'Guha shows the first night', 'Bharata stops imagining exile and touches the traces of its first night.', 'Bharata''s answer transforms Guha''s stance. He praises a man willing to surrender an unasked-for kingdom, offers guidance to Bharadvaja, and stays near while grief keeps Bharata awake. Guha recounts offering Lakshmana a bed and guard. Lakshmana refused sleep while Rama and Sita lay on grass, fearing already that Dasharatha and the mothers might not survive the separation. Hearing how the first night passed, Bharata collapses. Shatrughna and the mothers gather around him; when he recovers, he asks where each person slept, what they ate, and who guarded them. At the Ingudi tree, Guha shows the pressed grass, fragments of silk and gold, and the place of Lakshmana''s watch. Bharata reads a whole vanished night from what the ground retained. He vows to sleep on the ground, wear bark and matted hair, and remain in the forest if Rama will not return. The plan is no longer only persuasion; Bharata is prepared to take the exile himself. At dawn Guha''s crews move people, mothers, priests, cars, animals, and supplies across the Ganga in boats and rafts; some swim. By the third watch, the expedition rests in Prayaga''s woods.', 'source_aligned', 'published'),
  ('scene-guha-shows-first-night', 'hi', 'संदेह पहचान में बदलता है', 'भरत वनवास की कल्पना से आगे बढ़कर उसकी पहली रात के निशान छूते हैं।', 'भरत का उत्तर गुह का रुख बदल देता है। वे अनचाहा राज्य छोड़ने वाले भाई की प्रशंसा करते, भरद्वाज तक मार्गदर्शन देते और शोक में जागते भरत के पास रहते हैं। गुह बताते हैं कि उन्होंने लक्ष्मण को विश्राम और पहरा देने का प्रस्ताव दिया था। राम-सीता को घास पर सोता देखकर लक्ष्मण जागते रहे और दशरथ व माताओं के जीवन के लिए भय जताते रहे। पहली रात का विवरण सुनकर भरत मूर्छित हो जाते हैं। शत्रुघ्न और माताएँ उन्हें घेर लेती हैं; सँभलकर वे पूछते हैं—कौन कहाँ सोया, क्या खाया और पहरा किसने दिया। इंगुदी वृक्ष के नीचे गुह दबा हुआ तृण, रेशम और सोने के छोटे अंश तथा लक्ष्मण की चौकसी का स्थान दिखाते हैं। भरत धरती पर बचे निशानों से पूरी बीती रात पढ़ते हैं। वे भूमि पर सोने, वल्कल और जटा धारण करने तथा राम के न लौटने पर स्वयं वन में रहने का वचन देते हैं। अब योजना केवल विनती नहीं—भरत वनवास अपने ऊपर लेने को तैयार हैं। भोर में गुह के नाविक लोगों, माताओं, पुरोहितों, रथों, पशुओं और सामग्री को नावों व बेड़ों से गंगा पार कराते हैं; कुछ तैरते हैं। तीसरे प्रहर तक यात्रा प्रयाग के वन में ठहरती है।', 'source_aligned', 'published'),
  ('scene-bharadvaja-tests-hosts', 'en', 'Bharadvaja tests and receives', 'The road earns both scrutiny and a night of impossible abundance.', 'A krosha from the hermitage, Bharata leaves the army, weapons, and courtly display behind. He follows Vasishta on foot so a royal expedition does not trample the ascetic world it seeks help from. Bharadvaja asks whether Bharata came to harm Rama and secure the kingdom. Bharata weeps at being suspected again, rejects his mother''s act, and asks only for the way to Rama''s feet. Satisfied, Bharadvaja says Rama, Sita, and Lakshmana are at Chitrakoot and asks Bharata to stay the night. The unknown forest contracts into a place that can be reached tomorrow. Bharadvaja asks for the whole force. Bharata explains he kept it away to protect trees, water, animals, and cottages. Only after the host insists does the city-sized company approach. Bharadvaja invokes an extraordinary welcome: wind, blossom rain, music, dwellings, food, water, care for animals, and rest appear around the force. For one night, dust and grief give way to abundance. At dawn Bharadvaja directs them south toward the Mandakini and Chitrakoot. The mothers appear together; Bharata names their grief, and the sage interrupts his hatred of Kaikeyi before the army moves on.', 'source_aligned', 'published'),
  ('scene-bharadvaja-tests-hosts', 'hi', 'भरत सेना के बिना आगे बढ़ते हैं', 'यात्रा परीक्षा भी पार करती है और असंभव समृद्धि की एक रात भी पाती है।', 'आश्रम से एक क्रोश पहले भरत सेना, अस्त्र और राजकीय प्रदर्शन छोड़ देते हैं। वे वसिष्ठ के पीछे पैदल जाते हैं ताकि सहायता माँगती यात्रा तपोवन को रौंद न दे। भरद्वाज पूछते हैं कि क्या भरत राम को हानि पहुँचाकर राज्य सुरक्षित करने आए हैं। फिर संदेह सुनकर भरत रो पड़ते, माँ के कर्म को अस्वीकार करते और केवल राम तक की राह माँगते हैं। संतुष्ट होकर भरद्वाज बताते हैं कि राम, सीता और लक्ष्मण चित्रकूट में हैं और भरत से रात रुकने को कहते हैं। अनजान वन अब कल पहुँची जा सकने वाली जगह बन जाता है। भरद्वाज पूरे दल को बुलाते हैं। भरत बताते हैं कि वृक्ष, जल, पशु और कुटियों की रक्षा के लिए सेना दूर रखी थी। मेज़बान के आग्रह के बाद ही विशाल दल आगे आता है। भरद्वाज अद्भुत स्वागत रचते हैं—सुगंधित वायु, पुष्पवर्षा, संगीत, आवास, भोजन, जल, पशुओं की देखभाल और विश्राम। एक रात के लिए धूल और शोक समृद्धि को स्थान देते हैं। भोर में भरद्वाज उन्हें मंदाकिनी और चित्रकूट की दक्षिणी राह बताते हैं। माताएँ साथ आती हैं; भरत उनका शोक बताते हैं और ऋषि कैकेयी के प्रति उनके घृणा-वचन को रोकते हैं।', 'source_aligned', 'published'),
  ('turn-sandals-and-promise', 'en', 'The sandals carry the promise', 'Brothers argue from love and duty; Rama stays, while Bharata takes the sandals to rule only in trust.', 'Brothers argue from love and duty; Rama stays, while Bharata takes the sandals to rule only in trust.', 'source_aligned', 'published'),
  ('turn-sandals-and-promise', 'hi', 'पादुकाएँ वचन सँभालती हैं', 'भाई प्रेम और कर्तव्य के बीच संवाद करते हैं; राम रहते हैं और भरत पादुकाओं के नाम पर राज्य सँभालते हैं।', 'भाई प्रेम और कर्तव्य के बीच संवाद करते हैं; राम रहते हैं और भरत पादुकाओं के नाम पर राज्य सँभालते हैं।', 'source_aligned', 'published'),
  ('scene-chitrakoot-hears-army', 'en', 'Chitrakoot hears an army', 'The same approaching army becomes threat from one viewpoint and reunion from another.', 'Elephants, deer, birds, and other forest life scatter before the dust and sound of Bharata''s force. The road to a loving reunion still carries the disruptive weight of a kingdom. Searchers see smoke that must belong to a dwelling or hermitage. Bharata stops the army from advancing, keeps the forest from being overrun, and follows the clue with only a small company. Before the noise arrives, Rama shows Sita Chitrakoot''s coloured rock, flowering forest, birds, cascades, and the Mandakini. Exile has become a place where the three can still make a life. The ground trembles and animals run. From a tree Lakshmana sees elephants, horses, chariots, infantry, and Bharata''s standard; he asks Rama to hide Sita, string the bow, and prepare for attack. Rama says a kingdom gained by killing Bharata would be poison. He trusts that Bharata came from grief and love, and reminds Lakshmana that harm to his brother would be harm to Rama himself. Bharata stations the force away from the hill, searches with Shatrughna, Guha, advisers, and citizens, then sees the smoke himself. Rank and spectacle fall behind as he climbs toward Rama''s cottage.', 'source_aligned', 'published'),
  ('scene-chitrakoot-hears-army', 'hi', 'वन सबसे पहले यात्रा सुनता है', 'एक ही आती सेना एक दृष्टि से संकट और दूसरी से मिलन बन जाती है।', 'भरत के दल की धूल और गर्जना से हाथी, हिरन, पक्षी और अन्य वन्य जीव भागते हैं। प्रेमपूर्ण मिलन की राह भी एक राज्य का विघटनकारी भार साथ लाती है। खोजी ऐसा धुआँ देखते हैं जो किसी निवास या आश्रम का हो सकता है। भरत सेना रोकते हैं, वन को रौंदने से बचाते हैं और छोटे दल के साथ उस संकेत की ओर बढ़ते हैं। शोर आने से पहले राम सीता को चित्रकूट की रंगीन शिलाएँ, पुष्पित वन, पक्षी, झरने और मंदाकिनी दिखाते हैं। वनवास ऐसी जगह बन गया है जहाँ तीनों जीवन रच सकते हैं। भूमि काँपती है और पशु भागते हैं। वृक्ष से लक्ष्मण हाथी, घोड़े, रथ, पैदल दल और भरत का ध्वज देखते हैं; वे सीता को सुरक्षित करने और धनुष तैयार करने को कहते हैं। राम कहते हैं कि भरत को मारकर मिला राज्य विष होगा। उन्हें विश्वास है कि भरत शोक और प्रेम से आए हैं; वे याद दिलाते हैं कि भाई को चोट पहुँचाना राम को चोट पहुँचाना होगा। भरत सेना को पर्वत से दूर रोककर शत्रुघ्न, गुह, सलाहकारों और नागरिकों के साथ खोजते हैं, फिर स्वयं धुआँ देखते हैं। पद और प्रदर्शन पीछे छूटते हैं; वे कुटिया की ओर चढ़ते हैं।', 'source_aligned', 'published'),
  ('scene-brothers-meet-death-news', 'en', 'The brothers meet, then hear the loss', 'The reunion opens, then Dasharatha''s death changes every reason for the meeting.', 'Bark signs, gathered fuel, flowers, a maintained fire, and the path to the Mandakini confirm the dwelling before anyone appears. Bharata sees the practical life Lakshmana built around the exile. Inside, Bharata sees Rama in bark and matted hair beside Sita and Lakshmana. The contrast with the court he remembers overwhelms him before he can complete more than a cry of recognition. Bharata falls at Rama''s feet; Shatrughna follows. Rama raises and embraces them, then receives Sumantra and Guha. The forest community watches four royal brothers meet in tears rather than ceremony. Not knowing Dasharatha is dead, Rama asks after father, mothers, priests, advisers, soldiers, farmers, justice, treasury, secrecy, and public welfare. He assumes Bharata carries responsibility and examines how he bears it. Bharata says the kingdom is not his, names himself servant and brother, and asks Rama to return before the mothers, ministers, and subjects who travelled to his feet. Then he tells why Dasharatha cannot come. Hearing that Dasharatha died grieving after the exile, Rama collapses. The brothers and Sita carry their mourning to the Mandakini, offer water and the food of their own forest life, then return together to the cottage.', 'source_aligned', 'published'),
  ('scene-brothers-meet-death-news', 'hi', 'भरत कुटिया के आसपास का जीवन पढ़ते हैं', 'मिलन खुलता है, फिर दशरथ की मृत्यु उसके हर कारण को बदल देती है।', 'वल्कल के संकेत, इकट्ठी लकड़ी, फूल, जीवित अग्नि और मंदाकिनी की राह किसी के दिखने से पहले निवास की पुष्टि करते हैं। भरत लक्ष्मण द्वारा रचा व्यावहारिक वन-जीवन देखते हैं। भीतर भरत राम को वल्कल और जटा में सीता व लक्ष्मण के साथ देखते हैं। स्मृति के राजदरबार और सामने के वन-जीवन का अंतर उन्हें केवल पुकार भर कहने देता है। भरत राम के चरणों में गिरते हैं; शत्रुघ्न भी आते हैं। राम दोनों को उठाकर गले लगाते, फिर सुमंत्र और गुह से मिलते हैं। वनवासी समुदाय चार भाइयों को समारोह नहीं, आँसुओं में मिलता देखता है। दशरथ की मृत्यु न जानकर राम पिता, माताओं, पुरोहितों, मंत्रियों, सैनिकों, किसानों, न्याय, कोष, गोपनीयता और लोककल्याण का समाचार पूछते हैं। वे मानते हैं कि भरत उत्तरदायित्व संभाल रहे हैं। भरत कहते हैं कि राज्य उनका नहीं, वे सेवक और भाई हैं, और उन माताओं, मंत्रियों व प्रजाजनों के सामने राम से लौटने को कहते हैं जो उनके चरणों तक आए हैं। फिर वे बताते हैं कि दशरथ क्यों नहीं आए। यह सुनकर कि वनवास के बाद शोक में दशरथ की मृत्यु हुई, राम गिर पड़ते हैं। भाई और सीता शोक लेकर मंदाकिनी जाते, जल और अपने वन-जीवन का अन्न अर्पित करते, फिर साथ कुटिया लौटते हैं।', 'source_aligned', 'published'),
  ('scene-family-asks-rama-home', 'en', 'The family asks Rama home', 'Private grief becomes a public argument that no one can end by love alone.', 'Kausalya, Sumitra, Kaikeyi, and the other queens follow the Mandakini path used for water. Kausalya sees Dasharatha''s simple offering and the work Lakshmana performs, reading the family''s changed life in ordinary objects. Rama and Lakshmana bow; the mothers wipe dust from their backs. Sita takes their feet and Kausalya embraces her. The reunion is tactile and domestic before it becomes political again. After a night of mourning and morning rites, brothers, mothers, citizens, and advisers sit in silence. The entire expedition has reached its purpose, but affection alone has not decided who must return. Bharata says the kingdom produced by Kaikeyi''s demand is legally in his hands, and he gives it to Rama. He compares himself to someone unable to sustain the great tree another person raised. Rama answers that time separates every family and Dasharatha''s command still binds both sons. Bharata must protect Ayodhya; Rama must complete fourteen years. Mourning cannot make the promise disappear. Bharata answers that an eldest living son should rule, a son may repair a father''s harmful act, and government is itself Rama''s responsibility. If Rama still chooses the forest, Bharata will remain there with him.', 'source_aligned', 'published'),
  ('scene-family-asks-rama-home', 'hi', 'माताएँ वनवास का जीवन देखती हैं', 'निजी शोक सार्वजनिक तर्क बनता है जिसे केवल प्रेम समाप्त नहीं कर सकता।', 'कौसल्या, सुमित्रा, कैकेयी और अन्य रानियाँ मंदाकिनी की जल-राह पर चलती हैं। कौसल्या दशरथ का साधारण अर्पण और लक्ष्मण का श्रम देखकर सामान्य वस्तुओं में बदला पारिवारिक जीवन पढ़ती हैं। राम और लक्ष्मण प्रणाम करते हैं; माताएँ उनकी पीठ की धूल पोंछती हैं। सीता उनके चरण पकड़ती हैं और कौसल्या उन्हें गले लगाती हैं। राजनीति से पहले मिलन स्पर्श और परिवार का है। शोक की रात और प्रातःकर्म के बाद भाई, माताएँ, नागरिक और सलाहकार मौन बैठते हैं। पूरी यात्रा अपने उद्देश्य तक पहुँच गई है, पर स्नेह ने अभी तय नहीं किया कि कौन लौटेगा। भरत कहते हैं कि कैकेयी की माँग से मिला राज्य विधि के अनुसार उनके हाथ में है और वे उसे राम को देते हैं। वे स्वयं को उस व्यक्ति जैसा बताते हैं जो दूसरे के उगाए विशाल वृक्ष को सँभाल नहीं सकता। राम कहते हैं कि समय हर परिवार को अलग करता है और दशरथ की आज्ञा दोनों पुत्रों को अब भी बाँधती है। भरत अयोध्या सँभालें, राम चौदह वर्ष पूरे करें; शोक वचन मिटा नहीं सकता। भरत उत्तर देते हैं कि जीवित ज्येष्ठ पुत्र को शासन करना चाहिए, पुत्र पिता के हानिकारक कर्म को सुधार सकता है और राजकार्य स्वयं राम का दायित्व है। फिर भी राम वन चुनें तो भरत भी वहीं रहेंगे।', 'source_aligned', 'published'),
  ('scene-sandals-hold-kingdom', 'en', 'The sandals hold the kingdom', 'When every argument reaches its limit, a pair of sandals carries a temporary answer.', 'Rama restates the boons and says each brother preserves Dasharatha''s truth by carrying his assigned part: Bharata the kingdom, Rama the forest. The four brothers must protect one promise through different work. Trying to make Rama return, Javali argues that relationships end, death ends obligation, and visible welfare should outweigh rites and promises. His speech is a position inside the debate, not the narrator''s settled conclusion. Rama rejects Javali''s reasoning: a ruler''s conduct teaches others, and truth sustains public confidence. Javali then says he used the argument strategically, revealing the exchange as persuasion rather than simple doctrine. Vasishta invokes the eldest-son tradition and his authority as teacher; he asks Rama to heed mother, brother, and people. Rama answers that parental care creates a debt he can honour only by keeping Dasharatha''s command. With persuasion exhausted, Bharata spreads grass at the cottage door and vows to lie there until Rama yields. When that too fails, he offers to serve the fourteen-year exile as Rama''s substitute. Rama will not accept a substitute, but gives Bharata his sandals. Bharata promises to govern outside Ayodhya in their name, live austerely, and return the kingdom when Rama comes back at fourteen years.', 'source_aligned', 'published'),
  ('scene-sandals-hold-kingdom', 'hi', 'राम बँटे हुए दायित्व को नाम देते हैं', 'जब हर तर्क अपनी सीमा तक पहुँचता है, पादुकाएँ अस्थायी उत्तर सँभालती हैं।', 'राम वरों को दोहराकर कहते हैं कि हर भाई अपना भाग निभाकर दशरथ का सत्य बचाए—भरत राज्य, राम वन। चारों भाइयों को अलग कार्य से एक वचन की रक्षा करनी है। राम को लौटाने के लिए जावालि कहते हैं कि संबंध समाप्त होते हैं, मृत्यु दायित्व खत्म करती है और दृश्य लोककल्याण को संस्कार व वचन से ऊपर होना चाहिए। यह बहस का पक्ष है, अंतिम निष्कर्ष नहीं। राम जावालि का तर्क अस्वीकार करते हैं—शासक का आचरण दूसरों को दिशा देता है और सत्य सार्वजनिक भरोसा सँभालता है। जावालि बताते हैं कि उन्होंने यह पक्ष रणनीतिक रूप से रखा था। वसिष्ठ ज्येष्ठ-पुत्र परंपरा और गुरु-अधिकार रखते हुए राम से माता, भाई और प्रजा की सुनने को कहते हैं। राम कहते हैं कि माता-पिता की सेवा का ऋण दशरथ की आज्ञा निभाकर ही चुक सकता है। तर्क समाप्त होने पर भरत कुटिया के द्वार पर कुश बिछाकर राम के मानने तक पड़े रहने का व्रत लेते हैं। यह भी विफल होने पर वे चौदह वर्ष का वनवास स्वयं लेने की बात रखते हैं। राम प्रतिनिधि वनवास स्वीकार नहीं करते, पर भरत को अपनी पादुकाएँ देते हैं। भरत उनके नाम पर अयोध्या के बाहर रहकर संयम से शासन और चौदह वर्ष बाद राज्य लौटाने का वचन देते हैं।', 'source_aligned', 'published'),
  ('scene-nandigrama-trust', 'en', 'The trust moves to Nandigrama', 'The journey fails to bring Rama home, but builds a visible trust that can wait for him.', 'Bharata places the sandals on his head and leaves Chitrakoot with Shatrughna, Vasishta, Javali, ministers, mothers, and citizens. Rama returns weeping to the cottage; neither road feels like victory. At Prayaga, Bharata tells Bharadvaja that Rama would not break the fourteen-year promise and that the sandals now carry the work of government. The sage recognizes the resolution without pretending the brothers agreed. The expedition crosses Yamuna and Ganga again, passes Shringaverapura, and approaches Ayodhya. The same geography that carried hope outward now carries a difficult responsibility back. Ayodhya''s closed doors, silent music, empty markets, and dark palace show that the journey did not restore ordinary life. Bharata sees a city that cannot yet celebrate and refuses to occupy its centre. After settling the mothers in Ayodhya, Bharata tells Vasishta and the counsellors he will live at Nandigrama. Rama is king; Bharata will carry the reins only while waiting for him. At Nandigrama the sandals receive the umbrella and ceremonial place. Bharata wears bark and matted hair, reports decisions in subordination to them, and defines his rule by the moment it must end: Rama''s return.', 'source_aligned', 'published'),
  ('scene-nandigrama-trust', 'hi', 'भरत उत्तर को अपने ऊपर रखते हैं', 'यात्रा राम को घर नहीं ला पाती, पर उनके लिए प्रतीक्षा कर सकने वाली दृश्य धरोहर रचती है।', 'भरत पादुकाएँ सिर पर रखकर शत्रुघ्न, वसिष्ठ, जावालि, मंत्रियों, माताओं और नागरिकों के साथ चित्रकूट से लौटते हैं। राम रोते हुए कुटिया जाते हैं; कोई भी राह विजय जैसी नहीं लगती। प्रयाग में भरत भरद्वाज को बताते हैं कि राम चौदह वर्ष का वचन नहीं तोड़ेंगे और पादुकाएँ अब शासन का कार्य सँभालेंगी। ऋषि समाधान स्वीकारते हैं, भाइयों की असहमति मिटाते नहीं। यात्रा फिर यमुना और गंगा पार कर शृंगवेरपुर से अयोध्या की ओर बढ़ती है। जो भू-दृश्य आशा को बाहर ले गया था, वही अब कठिन उत्तरदायित्व वापस ला रहा है। अयोध्या के बंद द्वार, मौन संगीत, खाली बाज़ार और अँधेरा महल बताते हैं कि यात्रा ने सामान्य जीवन नहीं लौटाया। भरत उस नगर का केंद्र लेने से इंकार करते हैं जो अभी उत्सव नहीं मना सकता। माताओं को अयोध्या में ठहराकर भरत वसिष्ठ और मंत्रियों से कहते हैं कि वे नंदिग्राम में रहेंगे। राजा राम हैं; भरत केवल उनकी प्रतीक्षा में कार्यभार सँभालेंगे। नंदिग्राम में पादुकाओं को छत्र और राजकीय स्थान मिलता है। भरत वल्कल-जटा धारण कर उनके अधीन निर्णय लेते हैं और अपने शासन को उस क्षण से परिभाषित करते हैं जब वह समाप्त होगा—राम की वापसी।', 'source_aligned', 'published'),
  ('turn-deeper-into-forest', 'en', 'Deeper into the forest', 'After the family departs, the forest grows crowded with memory and Rama moves farther from Chitrakuta.', 'After the family departs, the forest grows crowded with memory and Rama moves farther from Chitrakuta.', 'source_aligned', 'published'),
  ('turn-deeper-into-forest', 'hi', 'वन के और भीतर', 'परिवार के लौटने के बाद चित्रकूट स्मृतियों से भर जाता है और राम वन में आगे बढ़ते हैं।', 'परिवार के लौटने के बाद चित्रकूट स्मृतियों से भर जाता है और राम वन में आगे बढ़ते हैं।', 'source_aligned', 'published'),
  ('scene-chitrakoot-grows-unsafe', 'en', 'Chitrakoot can no longer hold them', 'The first forest home becomes a place the travellers cannot keep.', 'After Bharata leaves, Rama notices the neighbouring ascetics exchanging glances and preparing to move. He first asks whether he, Lakshmana, or Sita has failed them. An elder says the danger is Khara''s Janasthana world and other attackers who break vessels, spoil fires, assume frightening forms, and kill isolated ascetics. The community will move to another wood. The elder warns that Rama''s presence may draw more danger, and Rama cannot persuade them to remain. The cottage still holds the meeting with Bharata and the mothers; the ground carries the trace of the enormous camp. Chitrakoot now recalls grief more readily than shelter. Rama decides to move. Sita and Lakshmana leave with him, carrying the road forward rather than treating Chitrakoot as the whole forest exile.', 'source_aligned', 'published'),
  ('scene-chitrakoot-grows-unsafe', 'hi', 'नाम से पहले भय दिखाई देता है', 'वन का पहला घर अब ऐसा स्थान बन जाता है जहाँ यात्री रह नहीं सकते।', 'भरत के लौटने के बाद राम पड़ोसी तपस्वियों को संकेतों में बात करते और जाने की तैयारी करते देखते हैं। वे पहले पूछते हैं कि क्या उनसे, लक्ष्मण से या सीता से कोई भूल हुई है। एक वृद्ध तपस्वी बताते हैं कि संकट खर के जनस्थान-संसार और उन आक्रमणकारियों से है जो पात्र तोड़ते, अग्नि बुझाते, भयानक रूप धरते और अकेले तपस्वियों को मारते हैं। समुदाय दूसरे वन में जाने का निर्णय लेता है। वृद्ध चेताते हैं कि राम की उपस्थिति और संकट खींच सकती है, और राम उन्हें रुकने के लिए आश्वस्त नहीं कर पाते। कुटिया में भरत और माताओं की भेंट की स्मृति है; भूमि पर विशाल शिविर के चिह्न हैं। चित्रकूट अब आश्रय से अधिक शोक की याद दिलाता है। राम आगे बढ़ने का निर्णय लेते हैं। सीता और लक्ष्मण उनके साथ निकलते हैं—चित्रकूट को पूरे वनवास का अंत नहीं, आगे की राह का पहला घर मानकर।', 'source_aligned', 'published'),
  ('scene-sita-tells-her-beginning', 'en', 'Sita tells her own beginning', 'Before the story enters Dandaka, Sita tells where her own road began.', 'Atri welcomes Rama as a son and receives Sita and Lakshmana. He introduces Sita to the aged ascetic Anasuya, whose long discipline is remembered through a drought story. Anasuya praises Sita''s companionship and speaks in the strongly patriarchal language of the selected historical translation. The scene keeps that speech attributable to its speaker rather than turning it into modern instruction. Sita recalls what her mother, mother-in-law, and household taught her, then speaks of Rama''s conduct toward the royal mothers. Her response is neither silence nor a detached rule; it is personal memory inside her chosen journey. When Sita asks for nothing, Anasuya gives her garments, ornaments, a garland, and fragrant paste. The gifts mark hospitality and relationship before another difficult road. Asked to tell her story at length, Sita says Janaka found her while ploughing sacrificial ground and accepted her as his daughter. She narrates her origin rather than appearing only as someone else''s prize. Sita recounts Janaka''s anxiety, the assembly around the immovable bow, Rama lifting and breaking it, and the consultations that joined the households. Night arrives while her own voice closes the Ayodhya book.', 'source_aligned', 'published'),
  ('scene-sita-tells-her-beginning', 'hi', 'एक नया आश्रम उन्हें स्वीकारता है', 'दण्डक में प्रवेश से पहले सीता स्वयं बताती हैं कि उनकी अपनी राह कहाँ से शुरू हुई।', 'अत्रि राम का पुत्र की तरह स्वागत करते हैं और सीता-लक्ष्मण को अपनाते हैं। वे सीता को वृद्ध तपस्विनी अनसूया से मिलाते हैं, जिनकी दीर्घ साधना को अकाल की कथा में याद किया जाता है। अनसूया सीता के साथ निभाने की प्रशंसा करती हैं और चुने हुए ऐतिहासिक अनुवाद की गहरी पितृसत्तात्मक भाषा में बोलती हैं। दृश्य उस वाणी को वक्ता से जोड़कर रखता है, आधुनिक निर्देश नहीं बनाता। सीता अपनी माता, सास और परिवार से मिली सीख याद करती हैं, फिर राजमाताओं के प्रति राम के व्यवहार की बात करती हैं। उनका उत्तर न मौन है, न कोई निरपेक्ष नियम—यह उनकी चुनी हुई यात्रा के भीतर निजी स्मृति है। जब सीता कुछ नहीं माँगतीं, अनसूया उन्हें वस्त्र, आभूषण, माला और सुगंधित लेप देती हैं। ये उपहार कठिन राह से पहले आतिथ्य और संबंध का चिह्न बनते हैं। अपनी कथा विस्तार से सुनाने पर सीता कहती हैं कि यज्ञभूमि जोतते समय जनक ने उन्हें पाया और पुत्री रूप में स्वीकार किया। वे केवल किसी की प्राप्ति नहीं, अपनी उत्पत्ति स्वयं सुनाती हैं। सीता जनक की चिंता, अचल धनुष की सभा, राम द्वारा उसे उठाकर तोड़ने और दोनों परिवारों को जोड़ने वाली सहमति की कथा सुनाती हैं। उनकी अपनी आवाज़ में आयोध्या काण्ड का अंत होते-होते रात उतर आती है।', 'source_aligned', 'published'),
  ('turn-dandaka-vows', 'en', 'Vows in Dandaka', 'The travellers meet ascetics, face Viradha, and enter a forest where protection carries moral cost.', 'The travellers meet ascetics, face Viradha, and enter a forest where protection carries moral cost.', 'source_aligned', 'published'),
  ('turn-dandaka-vows', 'hi', 'दंडक वन में प्रतिज्ञाएँ', 'यात्री ऋषियों से मिलते, विराध का सामना करते और ऐसे वन में प्रवेश करते हैं जहाँ रक्षा का मूल्य है।', 'यात्री ऋषियों से मिलते, विराध का सामना करते और ऐसे वन में प्रवेश करते हैं जहाँ रक्षा का मूल्य है।', 'source_aligned', 'published'),
  ('scene-dandaka-receives-them', 'en', 'Dandaka receives three travellers', 'Dandaka opens as an inhabited world, not an empty backdrop.', 'Warned that danger lies ahead, Rama, Sita, and Lakshmana enter the deeper forest. The selected edition compares their entry to the sun passing into cloud. Dandaka reveals fire rooms, water jars, bark dwellings, gardens, lotus tanks, recitation, birds, deer, roots, and fruit. The first impression is a living network of care and work. Rama unstrings his bow before entering. The residents come forward, offer water, food, flowers, and shelter, and study the three travellers with wonder. The ascetics say that Rama remains responsible for people in his dominion whether he lives in city or forest. His own displacement does not erase their expectation of protection. The visitors eat and rest among the hermitages. At sunrise they continue, and the ordered clearings give way to a damaged forest of frightened birds and disturbed water.', 'source_aligned', 'published'),
  ('scene-dandaka-receives-them', 'hi', 'वन उनके चारों ओर गहरा जाता है', 'दण्डक कोई खाली पृष्ठभूमि नहीं, एक बसा हुआ संसार बनकर खुलता है।', 'आगे के संकट की चेतावनी लेकर राम, सीता और लक्ष्मण गहरे वन में प्रवेश करते हैं। चुना हुआ संस्करण उनके प्रवेश की तुलना बादलों में जाते सूर्य से करता है। दण्डक में अग्निशालाएँ, जलपात्र, वल्कल-कुटियाँ, उद्यान, कमल-सरोवर, पाठ, पक्षी, हिरण, कन्द और फल दिखाई देते हैं। पहला अनुभव श्रम और देखभाल के जीवित जाल का है। राम प्रवेश से पहले धनुष की प्रत्यंचा उतारते हैं। निवासी आगे आकर जल, भोजन, फूल और आश्रय देते हैं तथा तीनों यात्रियों को विस्मय से देखते हैं। तपस्वी कहते हैं कि राम नगर में हों या वन में, अपने क्षेत्र के लोगों के प्रति उत्तरदायी हैं। उनका स्वयं विस्थापित होना दूसरों की सुरक्षा की अपेक्षा मिटाता नहीं। यात्री आश्रमों में भोजन और विश्राम पाते हैं। सूर्योदय पर आगे बढ़ते ही व्यवस्थित खुली जगहों की जगह टूटे वृक्ष, डरे पक्षी और मटमैला जल आने लगता है।', 'source_aligned', 'published'),
  ('scene-viradha-breaks-the-road', 'en', 'Viradha breaks the road', 'The first Dandaka attack teaches that the usual weapon is not always the answer.', 'Viradha appears enormous, blood-marked, and carrying the bodies of animals on a spear. He declares the forest his domain and seizes Sita. Seeing Sita held, Rama connects the moment to exile, Kaikeyi, the lost kingdom, and Dasharatha''s death. Lakshmana answers the collapse with furious readiness to act. Rama''s arrows force Viradha to release Sita, but a boon keeps weapons from killing him. He charges again and lifts both brothers onto his shoulders. Left on the ground, Sita calls out and offers herself if Viradha will release Rama and Lakshmana. Her intervention gives the brothers the opening to break his arms. Blows and blades still fail. Rama recognizes the limit and orders a pit; Lakshmana digs while Rama holds Viradha down. Viradha recognizes Rama, says a curse shaped his form, and points the travellers toward Sarabhanga before the burial frees him. The attack ends by changing the road ahead.', 'source_aligned', 'published'),
  ('scene-viradha-breaks-the-road', 'hi', 'संकट अपने परिणामों के साथ आता है', 'दण्डक का पहला आक्रमण सिखाता है कि परिचित हथियार हमेशा उत्तर नहीं होता।', 'विराध विशाल, रक्त-चिह्नित और भाले पर मारे गए पशु लिए प्रकट होता है। वह वन को अपना क्षेत्र बताकर सीता को उठा लेता है। सीता को पकड़े देखकर राम इस क्षण को वनवास, कैकेयी, खोए राज्य और दशरथ की मृत्यु से जोड़ते हैं। लक्ष्मण इस टूटन का उत्तर तीव्र कार्रवाई की तैयारी से देते हैं। राम के बाण विराध को सीता छोड़ने पर विवश करते हैं, पर वरदान उसे हथियारों से मरने नहीं देता। वह फिर आक्रमण कर दोनों भाइयों को कंधों पर उठा लेता है। भूमि पर छूटकर सीता पुकारती हैं और राम-लक्ष्मण को छोड़ने के बदले स्वयं को ले जाने को कहती हैं। उनके हस्तक्षेप से भाइयों को विराध की भुजाएँ तोड़ने का अवसर मिलता है। प्रहार और तलवार भी असफल रहते हैं। राम सीमा पहचानकर गड्ढा खोदने को कहते हैं; लक्ष्मण खोदते हैं और राम विराध को रोके रखते हैं। विराध राम को पहचानकर बताता है कि शाप ने उसका रूप बनाया और मुक्त होने से पहले यात्रियों को शरभंग की ओर भेजता है। आक्रमण आगे की राह बदलकर समाप्त होता है।', 'source_aligned', 'published'),
  ('scene-forest-asks-protection', 'en', 'The forest makes its case', 'A private exile becomes a public promise made to a vulnerable forest community.', 'Near Sarabhanga''s hermitage, Rama sees Indra''s airborne company. Indra departs before meeting him, saying Rama still has work to complete. Sarabhanga says he delayed his ascent until he could see Rama. Rama declines inherited heavenly regions and asks instead where he should live in the forest. After directing Rama toward Sutikshna, Sarabhanga enters the fire and rises in a youthful form toward the worlds he had attained. The travellers witness rather than interrupt the departure. Ascetics with many disciplines gather after Sarabhanga''s departure. Their diversity makes clear that this is not one isolated household asking for help. They show the remains of people killed along the rivers and near Chitrakoot and say the attacks repeatedly interrupt their lives. They ask Rama to become a refuge. Rama says they need not beg: their protection is work he accepts alongside his father''s command. The promise sends the travellers onward to Sutikshna and will soon be questioned by Sita.', 'source_aligned', 'published'),
  ('scene-forest-asks-protection', 'hi', 'राम के आते ही दिव्य भेंट समाप्त होती है', 'निजी वनवास एक असुरक्षित वन-समुदाय से किए सार्वजनिक वचन में बदल जाता है।', 'शरभंग के आश्रम के पास राम इन्द्र का आकाशीय दल देखते हैं। इन्द्र मिलने से पहले यह कहकर चले जाते हैं कि राम का कार्य अभी बाकी है। शरभंग कहते हैं कि उन्होंने राम को देखने तक अपना प्रस्थान टाल दिया। राम मिले हुए स्वर्गलोक अस्वीकार कर पूछते हैं कि वन में उन्हें कहाँ रहना चाहिए। राम को सुतीक्ष्ण की ओर भेजकर शरभंग अग्नि में प्रवेश करते हैं और युवा रूप में अपने प्राप्त लोकों की ओर उठते हैं। यात्री इस प्रस्थान के साक्षी रहते हैं। शरभंग के प्रस्थान के बाद अनेक प्रकार की साधना करने वाले तपस्वी जुटते हैं। उनकी विविधता बताती है कि सहायता माँगने वाला कोई एक अलग घर नहीं, पूरा समुदाय है। वे नदियों और चित्रकूट के आसपास मारे गए लोगों के अवशेष दिखाते हैं और बताते हैं कि आक्रमण बार-बार उनके जीवन को तोड़ते हैं। वे राम से आश्रय बनने को कहते हैं। राम कहते हैं कि उन्हें विनती नहीं करनी चाहिए—उनकी सुरक्षा पिता की आज्ञा के साथ स्वीकार किया गया कार्य है। यही वचन यात्रियों को सुतीक्ष्ण की ओर भेजता है और शीघ्र ही सीता के प्रश्न का विषय बनेगा।', 'source_aligned', 'published'),
  ('scene-sita-questions-the-bow', 'en', 'Sita questions the bow', 'Sita makes the means of protection part of the story''s moral problem.', 'Sutikshna welcomes the travellers and offers his hermitage, but Rama worries that hunting even the troublesome deer would hurt his host. They stay one night, then ask to see the wider Dandaka world. At departure Sita gives the bows, quivers, and swords to the brothers. On the road she begins an affectionate warning about what those weapons may invite. Sita rules out falsehood and betrayal in Rama, then focuses on hostility without prior offence. The danger she sees is not protection itself, but making violence precede relationship or cause. She tells of an ascetic entrusted with a sword who carries it everywhere, gradually abandons discipline, and becomes governed by fierce thoughts. A tool held for safekeeping reshapes its keeper. Sita says a bow should rescue people already in danger, not turn every unknown forest being into an enemy. She asks Rama to think before acting, not to abandon responsibility. Rama honours Sita''s concern but says people personally sought refuge and he promised protection. He treats her challenge as speech born from love, yet holds that breaking the promise would also be wrong. The tension remains visible.', 'source_aligned', 'published'),
  ('scene-sita-questions-the-bow', 'hi', 'सुतीक्ष्ण ठहरने का स्थान देते हैं', 'सीता सुरक्षा के साधनों को कथा की नैतिक समस्या का हिस्सा बना देती हैं।', 'सुतीक्ष्ण यात्रियों का स्वागत कर अपना आश्रम देते हैं, पर राम सोचते हैं कि उपद्रवी हिरणों को मारना भी मेजबान को दुख देगा। वे एक रात रुककर व्यापक दण्डक-संसार देखने की अनुमति माँगते हैं। प्रस्थान पर सीता भाइयों को धनुष, तरकश और तलवारें देती हैं। राह में वे स्नेह से चेताती हैं कि यही हथियार किस तरह की प्रवृत्ति बुला सकते हैं। सीता राम में असत्य और विश्वासघात की संभावना नकारकर बिना पूर्व अपराध के शत्रुता पर ध्यान देती हैं। उनके लिए संकट सुरक्षा नहीं, संबंध या कारण से पहले हिंसा को रख देना है। वे एक तपस्वी की कथा सुनाती हैं जिसे तलवार धरोहर में मिली, जो उसे हर जगह ले जाते-ले जाते साधना छोड़कर उग्र विचारों के अधीन हो गया। सुरक्षित रखने का साधन अपने रक्षक को ही बदल देता है। सीता कहती हैं कि धनुष संकट में पड़े लोगों की रक्षा करे, हर अनजान वनवासी को शत्रु न बना दे। वे राम से दायित्व छोड़ने नहीं, कार्य से पहले विचार करने को कहती हैं। राम सीता की चिंता का सम्मान करते हैं, पर कहते हैं कि लोगों ने स्वयं शरण माँगी और उन्होंने रक्षा का वचन दिया है। वे उनके प्रश्न को प्रेम से निकली वाणी मानते हुए भी वचन तोड़ना अनुचित मानते हैं। तनाव समाप्त नहीं होता।', 'source_aligned', 'published'),
  ('scene-ten-years-become-map', 'en', 'Ten years become a living map', 'A long span of exile becomes a geography of stays, stories, and returns.', 'Rama leads, Sita walks between the brothers, and Lakshmana follows. Peaks, streams, islands, lotus tanks, deer, buffalo, boar, and elephants make travel feel inhabited at every scale. At Panchapsara they hear instruments and song but see no performers. Dharmabhrit tells the wondrous story of Mandakarni, five Apsaras, interrupted austerity, and a hidden dwelling beneath the water. The travellers live among many hermitages, returning to hosts and moving onward again. The forest world becomes a network rather than a single linear road. The selected edition names stays of months and years before saying ten years have passed. Devam keeps that compression visible instead of pretending every day or location is already reconstructed. After visiting the hermitage network, Rama returns to Sutikshna. The journey now needs a new destination, not simply another anonymous clearing. Rama says he has long wanted to meet Agastya. Sutikshna gives a southward route through Agastya''s brother''s hermitage, and the travellers set out the same day.', 'source_aligned', 'published'),
  ('scene-ten-years-become-map', 'hi', 'राह भू-दृश्य बन जाती है', 'वनवास का लंबा समय ठहरावों, कथाओं और वापसी की भूगोल बन जाता है।', 'राम आगे, सीता बीच और लक्ष्मण पीछे चलते हैं। पर्वत, धाराएँ, द्वीप, कमल-सरोवर, हिरण, भैंसे, सूअर और हाथी हर स्तर पर यात्रा को जीवित बनाते हैं। पञ्चाप्सरा पर वे संगीत और गायन सुनते हैं, पर कोई कलाकार दिखाई नहीं देता। धर्मभृत मन्दकर्णि, पाँच अप्सराओं, बाधित तपस्या और जल के भीतर छिपे निवास की अद्भुत कथा सुनाते हैं। यात्री अनेक आश्रमों में रहते, पुराने मेजबानों के पास लौटते और फिर आगे बढ़ते हैं। वन-संसार एक सीधी राह नहीं, आपस में जुड़ा जाल बन जाता है। चुना हुआ संस्करण महीनों और वर्षों के अलग-अलग ठहराव गिनाकर कहता है कि दस वर्ष बीत गए। देवम इस संक्षेप को स्पष्ट रखता है—हर दिन या स्थान के पूर्ण पुनर्निर्माण का दावा नहीं करता। आश्रम-जाल की यात्रा के बाद राम सुतीक्ष्ण के पास लौटते हैं। अब यात्रा को केवल एक और अनाम खुली जगह नहीं, नई दिशा चाहिए। राम कहते हैं कि वे लंबे समय से अगस्त्य से मिलना चाहते हैं। सुतीक्ष्ण अगस्त्य के भाई के आश्रम से होकर दक्षिण की राह बताते हैं, और यात्री उसी दिन निकलते हैं।', 'source_aligned', 'published'),
  ('scene-agastya-points-south', 'en', 'Agastya points toward Panchavati', 'The long forest circuit resolves into a named next home: Panchavati.', 'Rama reads smoke, fruit trees, birds, and pippali groves as signs of the route. He retells how Agastya ended the deadly deception of Vatapi and Ilwala, making the southward world habitable in this telling. At Agastya''s hermitage, Lakshmana introduces Rama, Sita, and himself to a disciple and explains the forest command that brought them there. Agastya says he had long wished for their arrival. Agastya embraces Rama, receives all three with water, food, flowers, and a seat, and names Rama a beloved guest. The encounter begins with care, not weapons. Agastya gives Rama a bow associated with Vishnu, an arrow, inexhaustible quivers, and a sword. They are presented as storied gifts inside this epic—not archaeological objects or modern ritual implements. Agastya explicitly notices that Sita has crossed hardship out of love and asks Rama to make the remaining forest life easier for her. The next home is chosen with her experience in view. Asked for a well-watered place, Agastya names Panchavati near the Godavari, gives a narrative route past the Madhuka wood and a hill, and sends the three onward. The district ends before Jatayu appears.', 'source_aligned', 'published'),
  ('scene-agastya-points-south', 'hi', 'राह पहले से कथाएँ लिए है', 'लंबी वन-यात्रा एक नए नामित घर में सिमटती है—पञ्चवटी।', 'राम धुएँ, फलदार वृक्षों, पक्षियों और पिप्पली वन को राह के संकेत की तरह पढ़ते हैं। वे बताते हैं कि इस कथा में अगस्त्य ने वातापि-इल्वल की घातक छलना समाप्त कर दक्षिण दिशा को रहने योग्य बनाया। अगस्त्य के आश्रम पर लक्ष्मण एक शिष्य को राम, सीता और अपना परिचय देकर बताते हैं कि पिता की आज्ञा उन्हें वन में लाई। अगस्त्य कहते हैं कि वे लंबे समय से उनके आने की इच्छा रखते थे। अगस्त्य राम को आलिंगन देकर तीनों का जल, भोजन, फूल और आसन से स्वागत करते हैं तथा राम को प्रिय अतिथि कहते हैं। भेंट की शुरुआत हथियारों से नहीं, देखभाल से होती है। अगस्त्य राम को विष्णु से जुड़ा धनुष, एक बाण, अक्षय तरकश और तलवार देते हैं। ये इस महाकाव्य के भीतर कथा-सम्पन्न उपहार हैं—पुरातात्त्विक वस्तु या आधुनिक अनुष्ठान-सामग्री नहीं। अगस्त्य स्पष्ट देखते हैं कि सीता प्रेम के कारण कठिन राह से गुज़री हैं और राम से शेष वनजीवन उनके लिए सहज बनाने को कहते हैं। अगला घर उनके अनुभव को ध्यान में रखकर चुना जाता है। जल और वन से भरा स्थान पूछने पर अगस्त्य गोदावरी के पास पञ्चवटी का नाम लेते हैं, मधूक वन और पहाड़ी से होकर कथा-मार्ग बताते हैं और तीनों को विदा करते हैं। यह जिला जटायु के आने से ठीक पहले समाप्त होता है।', 'source_aligned', 'published'),
  ('turn-panchavati-surpanakha', 'en', 'Panchavati and Surpanakha', 'A forest home, Jatayu''s friendship, and Surpanakha''s arrival turn quiet life toward conflict.', 'A forest home, Jatayu''s friendship, and Surpanakha''s arrival turn quiet life toward conflict.', 'source_aligned', 'published'),
  ('turn-panchavati-surpanakha', 'hi', 'पंचवटी और शूर्पणखा', 'वन-घर, जटायु की मित्रता और शूर्पणखा का आगमन शांत जीवन को संघर्ष की ओर मोड़ते हैं।', 'वन-घर, जटायु की मित्रता और शूर्पणखा का आगमन शांत जीवन को संघर्ष की ओर मोड़ते हैं।', 'source_aligned', 'published'),
  ('scene-jatayu-welcomes-panchavati', 'en', 'Jatayu welcomes them to Panchavati', 'A destination becomes a home with landscape, shelter, memory, and an elder ally.', 'On the way to Panchavati, Rama and Lakshmana see an enormous vulture and first suspect another disguised attacker. The forest still teaches caution before recognition. Jatayu speaks gently, recalls friendship with Dasharatha, and gives his lineage. A frightening unknown becomes someone connected to the family left behind. Jatayu offers to protect Sita whenever the brothers are away. Rama embraces him and accepts the bond before the group continues together. At Panchavati, Rama and Lakshmana choose ground near water, flowering woods, animals, and open sightlines. The setting is selected as a lived place, not a blank backdrop. Lakshmana gathers timber, earth, grass, and leaves to build the cottage. Rama praises his care, and the travellers enter Panchavati as a household. As winter arrives, the brothers walk to the Godavari and Lakshmana speaks of Bharata waiting in hardship. Quiet Panchavati still remains connected to distant Nandigrama.', 'source_aligned', 'published'),
  ('scene-jatayu-welcomes-panchavati', 'hi', 'एक विशाल आकृति राह रोकती है', 'एक पड़ाव भू-दृश्य, आश्रय, स्मृति और एक वृद्ध साथी के साथ घर बन जाता है।', 'पंचवटी जाते हुए राम और लक्ष्मण एक विशाल गिद्ध को देखकर पहले उसे रूप बदले आक्रमणकारी समझते हैं। पहचान से पहले वन उन्हें सावधानी सिखाता है। जटायु कोमल स्वर में बोलते हैं, दशरथ से अपनी मित्रता याद करते हैं और अपना वंश बताते हैं। भयावह अजनबी पीछे छूटे परिवार से जुड़ा साथी बन जाता है। जटायु कहते हैं कि भाइयों के दूर रहने पर वे सीता की रक्षा करेंगे। राम उन्हें गले लगाकर यह संबंध स्वीकार करते हैं और सब साथ आगे बढ़ते हैं। पंचवटी में राम और लक्ष्मण जल, फूलों से भरे वन, पशुओं और खुली दृष्टि वाले स्थान को चुनते हैं। यह कोई खाली पृष्ठभूमि नहीं, जीने योग्य जगह है। लक्ष्मण लकड़ी, मिट्टी, घास और पत्तों से कुटिया बनाते हैं। राम उनके स्नेहपूर्ण श्रम की प्रशंसा करते हैं और तीनों पंचवटी में परिवार की तरह प्रवेश करते हैं। शीत आने पर भाई गोदावरी की ओर चलते हैं और लक्ष्मण कठिन जीवन जी रहे भरत को याद करते हैं। शांत पंचवटी दूर नंदिग्राम से जुड़ी रहती है।', 'source_aligned', 'published'),
  ('scene-surpanakha-breaks-quiet', 'en', 'Surpanakha breaks Panchavati''s quiet', 'Panchavati''s domestic quiet becomes a conflict that will travel far beyond the cottage.', 'Surpanakha encounters Rama near the cottage and asks who these ascetic-looking armed travellers are. Rama introduces himself, Sita, and Lakshmana and explains the exile. She names her own power and family, declares desire for Rama, and dismisses Sita and Lakshmana as obstacles. The conversation is charged before it becomes dangerous. Rama points to his marriage and jokingly redirects Surpanakha toward Lakshmana; Lakshmana answers with another jest. The scene preserves the playfulness while making its escalating consequence visible. Humiliated and enraged, Surpanakha rushes at Sita. Rama stops treating the encounter as play and orders immediate protection. Lakshmana disfigures Surpanakha. Bleeding and furious, she leaves for Khara; Devam presents the violence as the selected narrative''s escalation, not as comic punishment or endorsed conduct.', 'source_aligned', 'published'),
  ('scene-surpanakha-breaks-quiet', 'hi', 'शूर्पणखा खुले स्थान में आती हैं', 'पंचवटी की घरेलू शांति ऐसे संघर्ष में बदलती है जो कुटिया से बहुत दूर जाएगा।', 'शूर्पणखा कुटिया के पास राम से मिलती हैं और तपस्वी वेश में शस्त्रधारी यात्रियों का परिचय पूछती हैं। राम अपना, सीता और लक्ष्मण का परिचय देकर वनवास बताते हैं। वह अपनी शक्ति और परिवार का परिचय देकर राम के प्रति इच्छा व्यक्त करती हैं तथा सीता और लक्ष्मण को बाधा कहती हैं। संवाद हिंसक होने से पहले ही तनाव से भर जाता है। राम अपने विवाह की बात कहकर परिहास में शूर्पणखा को लक्ष्मण की ओर भेजते हैं; लक्ष्मण भी परिहास में उत्तर देते हैं। दृश्य हास्य को रखते हुए उसके बढ़ते परिणाम को भी दिखाता है। अपमानित और क्रोधित शूर्पणखा सीता पर झपटती हैं। राम अब इस भेंट को खेल नहीं मानते और तत्काल रक्षा का आदेश देते हैं। लक्ष्मण शूर्पणखा को घायल और विरूप कर देते हैं। रक्तस्राव और क्रोध में वह खर के पास जाती हैं; देवम इस हिंसा को चुनी कथा की बढ़ती घटना मानता है, हास्यपूर्ण दंड या समर्थित आचरण नहीं।', 'source_aligned', 'published'),
  ('turn-war-at-janasthana', 'en', 'War reaches Janasthana', 'Surpanakha calls Khara''s forces; their destruction carries news of Rama to Ravana.', 'Surpanakha calls Khara''s forces; their destruction carries news of Rama to Ravana.', 'source_aligned', 'published'),
  ('turn-war-at-janasthana', 'hi', 'जनस्थान तक युद्ध पहुँचता है', 'शूर्पणखा खर की सेना बुलाती है; उसका विनाश राम का समाचार रावण तक पहुँचाता है।', 'शूर्पणखा खर की सेना बुलाती है; उसका विनाश राम का समाचार रावण तक पहुँचाता है।', 'source_aligned', 'published'),
  ('scene-janasthana-falls', 'en', 'Janasthana falls', 'A cottage conflict expands into war, and its only surviving report points toward Lanka.', 'Surpanakha reaches Khara, names Rama, Lakshmana, and Sita, and frames her injury as an attack demanding blood. Khara first sends fourteen fighters with her. At Panchavati, Rama places Sita under Lakshmana''s protection and defeats the attacking group. Surpanakha returns to Khara with the failure, making retreat less likely. Pressed by Surpanakha, Khara orders Dushana to mobilize the larger force. Omens gather along the march, while Rama reads the approaching danger and sends Sita and Lakshmana to shelter. The battle unfolds in waves around Rama. Dushana and Trishira fall, and Khara''s confidence narrows into a direct confrontation. Rama defeats Khara after their exchange of accusation, boast, and weapons. The selected epic describes a devastating victory; the interface keeps its consequence larger than spectacle. Akampana reaches Ravana and reports the destruction. Instead of recommending direct combat with Rama, he proposes making Sita the point of separation.', 'source_aligned', 'published'),
  ('scene-janasthana-falls', 'hi', 'शूर्पणखा प्रतिकार माँगती हैं', 'कुटिया का संघर्ष युद्ध में फैलता है और बचा हुआ समाचार लंका की ओर जाता है।', 'शूर्पणखा खर के पास पहुँचकर राम, लक्ष्मण और सीता का नाम लेती हैं तथा अपनी चोट को प्रतिशोध माँगता आक्रमण बताती हैं। खर पहले चौदह योद्धा उनके साथ भेजता है। पंचवटी में राम सीता को लक्ष्मण की सुरक्षा में रखकर आए दल को पराजित करते हैं। शूर्पणखा असफलता लेकर खर के पास लौटती हैं और पीछे हटने की संभावना घट जाती है। शूर्पणखा के दबाव में खर दूषण को बड़ी सेना तैयार करने का आदेश देता है। यात्रा में अपशकुन उभरते हैं; राम खतरा पहचानकर सीता और लक्ष्मण को आश्रय में भेजते हैं। राम के चारों ओर युद्ध लहरों में फैलता है। दूषण और त्रिशिरा गिरते हैं तथा खर का विश्वास सीधे द्वंद्व तक सिमट जाता है। आरोप, गर्वोक्ति और शस्त्रों के आदान-प्रदान के बाद राम खर को पराजित करते हैं। चुना महाकाव्य विनाशकारी विजय बताता है; दृश्य तमाशे से अधिक उसके परिणाम पर टिकता है। अकम्पन रावण तक पहुँचकर विनाश का समाचार देता है। राम से सीधे युद्ध के स्थान पर वह सीता को अलगाव का केंद्र बनाने की योजना सुझाता है।', 'source_aligned', 'published'),
  ('turn-golden-deer-plot', 'en', 'The golden deer plot', 'Ravana bends Maricha''s fear into a deception designed to separate the forest household.', 'Ravana bends Maricha''s fear into a deception designed to separate the forest household.', 'source_aligned', 'published'),
  ('turn-golden-deer-plot', 'hi', 'स्वर्ण-मृग की योजना', 'रावण मारीच के भय को छल में बदलता है ताकि वन का परिवार अलग हो जाए।', 'रावण मारीच के भय को छल में बदलता है ताकि वन का परिवार अलग हो जाए।', 'source_aligned', 'published'),
  ('scene-ravana-chooses-deception', 'en', 'Ravana chooses deception', 'Janasthana''s defeat becomes a deliberate plan to isolate Sita rather than confront Rama openly.', 'Ravana first approaches Maricha after Akampana''s report. Maricha recalls Rama''s power and persuades him to turn back—for the moment. Surpanakha reaches Ravana''s court, condemns his inattention, describes the defeat, and makes Sita''s beauty part of her argument for action. Ravana questions Surpanakha about Rama''s appearance, weapons, exile, and companions. Her answer turns curiosity into fixation and revenge into acquisition. When Ravana returns, Maricha recounts earlier encounters with Rama and describes a life ruled by the fear of seeing Rama everywhere. His counsel is specific, personal, and unwelcome. Ravana rejects the warning, threatens Maricha, and dictates the golden-deer role. Maricha chooses the danger he believes will at least end at Rama''s hand.', 'source_aligned', 'published'),
  ('scene-ravana-chooses-deception', 'hi', 'मारीच पहली योजना के विरुद्ध चेताते हैं', 'जनस्थान की हार राम से खुले युद्ध के बजाय सीता को अलग करने की सोची-समझी योजना बनती है।', 'अकम्पन के समाचार के बाद रावण पहली बार मारीच के पास जाता है। मारीच राम की शक्ति याद दिलाकर उसे कुछ समय के लिए लौटने पर विवश करते हैं। शूर्पणखा रावण की सभा में पहुँचकर उसकी असावधानी को ललकारती हैं, हार का वर्णन करती हैं और सीता के सौंदर्य को कार्रवाई के तर्क में बदल देती हैं। रावण शूर्पणखा से राम के रूप, शस्त्र, वनवास और साथियों के बारे में पूछता है। उत्तर जिज्ञासा को आसक्ति और प्रतिशोध को अधिकार की इच्छा में बदल देता है। रावण के लौटने पर मारीच राम से पुरानी मुठभेड़ों और हर ओर राम दिखाई देने वाले भय का वर्णन करते हैं। उनकी सलाह निजी, स्पष्ट और अप्रिय है। रावण चेतावनी ठुकराकर मारीच को धमकाता और स्वर्ण-मृग की भूमिका तय करता है। मारीच उस खतरे को चुनता है जिसका अंत कम से कम राम के हाथों होने की वह आशा करता है।', 'source_aligned', 'published'),
  ('scene-golden-deer-separates-house', 'en', 'The golden deer separates the house', 'An impossible image turns wonder into distance and leaves the Panchavati household exposed.', 'Maricha appears near the cottage as a deer marked with gold, silver, and jewel-like colour. Sita calls Rama and Lakshmana to see what has interrupted the ordinary forest. Sita asks Rama to capture the deer if possible, imagining it alive at their forest home or remembered later in Ayodhya. The request connects present delight with a future return. Lakshmana says no natural deer bears such colours and suspects Maricha. Rama accepts the danger but decides that either capture or ending the threat justifies pursuit. The deer moves close, vanishes, reappears, and draws Rama far from Panchavati. When the deception can no longer be contained, Rama releases the fatal arrow. Dying, Maricha imitates Rama''s voice and cries out for Sita and Lakshmana. Rama immediately fears what the sound may do at the distant cottage.', 'source_aligned', 'published'),
  ('scene-golden-deer-separates-house', 'hi', 'एक असंभव मृग खुले स्थान में आता है', 'एक असंभव दृश्य आश्चर्य को दूरी में बदलकर पंचवटी के परिवार को असुरक्षित छोड़ देता है।', 'मारीच सोने, चाँदी और रत्न-जैसे रंगों से अंकित मृग बनकर कुटिया के पास आते हैं। सीता राम और लक्ष्मण को इस असामान्य वन-दृश्य को देखने बुलाती हैं। सीता राम से संभव हो तो मृग को पकड़ने को कहती हैं—वन-घर में जीवित साथी की तरह या अयोध्या लौटने पर स्मृति की तरह। इच्छा वर्तमान आनंद को भविष्य की वापसी से जोड़ती है। लक्ष्मण कहते हैं कि स्वाभाविक मृग के ऐसे रंग नहीं होते और मारीच पर संदेह करते हैं। राम खतरा मानते हुए भी उसे पकड़ने या संकट समाप्त करने के लिए पीछा करने का निर्णय लेते हैं। मृग पास आता, गायब होता और फिर दिखकर राम को पंचवटी से दूर ले जाता है। जब छल को रोका नहीं जा सकता, राम घातक बाण छोड़ते हैं। मरते समय मारीच राम की आवाज़ में सीता और लक्ष्मण को पुकारते हैं। राम तुरंत समझते हैं कि दूर कुटिया पर यह ध्वनि क्या कर सकती है।', 'source_aligned', 'published'),
  ('turn-sita-is-taken', 'en', 'Sita is taken', 'The cry draws Lakshmana away; Ravana seizes Sita, and Jatayu rises against him in the sky.', 'The cry draws Lakshmana away; Ravana seizes Sita, and Jatayu rises against him in the sky.', 'source_aligned', 'published'),
  ('turn-sita-is-taken', 'hi', 'सीता का हरण', 'पुकार लक्ष्मण को दूर ले जाती है; रावण सीता का हरण करता है और जटायु आकाश में उसका सामना करते हैं।', 'पुकार लक्ष्मण को दूर ले जाती है; रावण सीता का हरण करता है और जटायु आकाश में उसका सामना करते हैं।', 'source_aligned', 'published'),
  ('scene-mendicant-at-empty-cottage', 'en', 'A mendicant reaches the empty cottage', 'Fear draws Lakshmana away, and hospitality opens the final unguarded threshold.', 'The imitated cry reaches Panchavati. Sita believes Rama is in danger and urges Lakshmana to go, while Lakshmana insists no ordinary foe could overcome him. As Lakshmana remains, Sita speaks harsh accusations born from panic. Lakshmana rejects them, warns of ominous signs, and finally leaves to find Rama. Ravana approaches in the appearance of a mendicant, with dress and objects that invoke hospitality. The forest and cottage are described as recoiling even before Sita knows his identity. Sita offers water and food and, when questioned, tells her identity, marriage, and exile. Her account is spoken before the guest-mask falls. Sita wonders why Rama and Lakshmana have not returned. Ravana''s questions and praise become increasingly possessive, and the protected logic of guest and host begins to collapse.', 'source_aligned', 'published'),
  ('scene-mendicant-at-empty-cottage', 'hi', 'सीता संकट में राम की आवाज़ सुनती हैं', 'भय लक्ष्मण को दूर खींचता है और आतिथ्य अंतिम असुरक्षित देहरी खोलता है।', 'नकली पुकार पंचवटी पहुँचती है। सीता मानती हैं कि राम संकट में हैं और लक्ष्मण को जाने को कहती हैं, जबकि लक्ष्मण कहते हैं कि कोई साधारण शत्रु राम को हरा नहीं सकता। लक्ष्मण के रुकने पर घबराहट में सीता कठोर आरोप कहती हैं। लक्ष्मण उन्हें अस्वीकार कर अपशकुन की चेतावनी देते हैं और अंततः राम को खोजने निकलते हैं। रावण भिक्षु के रूप, वस्त्र और चिह्नों के साथ आते हैं जो आतिथ्य की अपेक्षा जगाते हैं। सीता के पहचानने से पहले ही वन और कुटिया मानो पीछे हटते दिखाई देते हैं। सीता जल और भोजन देती हैं तथा पूछे जाने पर अपना परिचय, विवाह और वनवास बताती हैं। अतिथि का मुखौटा उतरने से पहले उनकी कथा उनके अपने शब्दों में आती है। सीता सोचती हैं कि राम और लक्ष्मण अभी तक क्यों नहीं लौटे। रावण के प्रश्न और प्रशंसा अधिकार जताने लगते हैं और अतिथि-गृहस्थ का सुरक्षित संबंध टूटने लगता है।', 'source_aligned', 'published'),
  ('scene-sita-carried-south', 'en', 'Sita calls the forest to witness', 'Ravana reveals himself, but Sita''s refusal and witness-making remain active inside the abduction.', 'Sita describes Rama''s character, strength, and commitment before asking the visitor''s identity. Her speech establishes the relationship Ravana is trying to erase. Ravana names himself, boasts of Lanka and power, and proposes that Sita leave with him. The mendicant guise gives way to the figure behind the threat. Sita rejects Ravana''s threats and comparisons, warns that taking her is impossible to separate from confronting Rama, and refuses to convert fear into consent. As Ravana seizes and lifts her away, Sita cries to trees, river, mountain, birds, and animals to carry news to Rama. The landscape becomes an active network of witnesses. Panchavati recedes as Sita continues to resist, reason, threaten, and call for help. The story does not reduce the scene to silent removal.', 'source_aligned', 'published'),
  ('scene-sita-carried-south', 'hi', 'सीता पहले राम का नाम लेकर उत्तर देती हैं', 'रावण अपना रूप प्रकट करता है, पर हरण के बीच भी सीता का इंकार और साक्षी बनाना सक्रिय रहता है।', 'सीता आगंतुक की पहचान पूछने से पहले राम के चरित्र, शक्ति और निष्ठा का वर्णन करती हैं। उनकी वाणी उस संबंध को स्थापित करती है जिसे रावण मिटाना चाहता है। रावण अपना नाम, लंका और शक्ति का गर्व बताते हुए सीता को साथ चलने का प्रस्ताव देता है। भिक्षु का वेश हटकर संकट का वास्तविक रूप सामने आता है। सीता रावण की धमकियों और तुलना को अस्वीकार करती हैं, कहती हैं कि उनका हरण राम से सामना किए बिना संभव नहीं और भय को सहमति में बदलने से इंकार करती हैं। रावण के उठाकर ले जाते समय सीता वृक्षों, नदी, पर्वत, पक्षियों और पशुओं से राम तक समाचार पहुँचाने की पुकार करती हैं। भू-दृश्य साक्षियों का सक्रिय जाल बन जाता है। पंचवटी नीचे दूर होती जाती है और सीता विरोध, तर्क, चेतावनी तथा सहायता की पुकार जारी रखती हैं। कथा इस दृश्य को मौन ले जाए जाने तक सीमित नहीं करती।', 'source_aligned', 'published'),
  ('scene-jatayu-rises-sky-road', 'en', 'Jatayu rises against Ravana', 'Jatayu cannot stop the abduction, but resistance creates delay, witness, and a recoverable trail.', 'Hearing Sita, Jatayu sees Ravana carrying her away. The guardian''s earlier promise returns at the moment it is most difficult to keep. Jatayu invokes age, friendship, kingship, and duty, urging Ravana to release Sita. He does not mistake unequal strength for permission to remain still. Jatayu attacks the chariot, weapons, and Ravana himself, disrupting the abduction and bringing the struggle close to the ground. Sita watches resistance appear where there had been no defender. Ravana cuts down the aged defender and resumes the southward journey. Sita embraces the fallen ally in grief before being forced onward. Carried onward, Sita continues to condemn Ravana and call for Rama and Lakshmana. Her voice keeps the route populated by witnesses rather than empty distance. Seeing five vanaras below, Sita drops cloth and ornaments in the hope that they can carry news. The district ends with evidence falling back into the world, not with the route erased.', 'source_aligned', 'published'),
  ('scene-jatayu-rises-sky-road', 'hi', 'जटायु सीता की पुकार से जागते हैं', 'जटायु हरण रोक नहीं पाते, पर उनका प्रतिरोध समय, साक्ष्य और खोजने योग्य निशान बनाता है।', 'सीता की पुकार सुनकर जटायु रावण को उन्हें ले जाते देखते हैं। पहले दिया रक्षा-वचन उसी क्षण लौटता है जब उसे निभाना सबसे कठिन है। जटायु आयु, मित्रता, राजधर्म और कर्तव्य की बात करके रावण से सीता को छोड़ने को कहते हैं। असमान शक्ति उनके लिए निष्क्रिय रहने की अनुमति नहीं बनती। जटायु रथ, शस्त्र और स्वयं रावण पर आक्रमण कर हरण की गति तोड़ते और संघर्ष को धरती के पास ले आते हैं। जहाँ कोई रक्षक नहीं था, वहाँ सीता प्रतिरोध उभरते देखती हैं। रावण वृद्ध रक्षक को गिराकर दक्षिण की यात्रा फिर शुरू करता है। आगे ले जाए जाने से पहले सीता शोक में घायल साथी को गले लगाती हैं। आगे ले जाए जाते हुए सीता रावण की निंदा और राम-लक्ष्मण को पुकारना जारी रखती हैं। उनकी आवाज़ मार्ग को खाली दूरी नहीं, साक्षियों से भरा संसार बनाए रखती है। नीचे पाँच वानरों को देखकर सीता वस्त्र और आभूषण इस आशा से गिराती हैं कि वे समाचार पहुँचा सकें। जिला रास्ता मिटने पर नहीं, संसार में खोज-साक्ष्य गिरने पर समाप्त होता है।', 'source_aligned', 'published'),
  ('turn-broken-trail', 'en', 'The broken trail', 'Rama and Lakshmana return to emptiness, search through grief, and find the dying Jatayu.', 'Rama and Lakshmana return to emptiness, search through grief, and find the dying Jatayu.', 'draft', 'draft'),
  ('turn-broken-trail', 'hi', 'टूटी हुई खोज-राह', 'राम और लक्ष्मण खाली आश्रम लौटते हैं, शोक में खोजते हैं और अंतिम साँस लेते जटायु को पाते हैं।', 'राम और लक्ष्मण खाली आश्रम लौटते हैं, शोक में खोजते हैं और अंतिम साँस लेते जटायु को पाते हैं।', 'draft', 'draft'),
  ('turn-toward-pampa', 'en', 'Toward Pampa and a new ally', 'Kabandha points toward Sugriva; Savari''s welcome carries the brothers to Pampa and the next world.', 'Kabandha points toward Sugriva; Savari''s welcome carries the brothers to Pampa and the next world.', 'draft', 'draft'),
  ('turn-toward-pampa', 'hi', 'पंपा और नए साथी की ओर', 'कबंध सुग्रीव की दिशा बताते हैं; शबरी का स्वागत भाइयों को पंपा और अगले संसार तक पहुँचाता है।', 'कबंध सुग्रीव की दिशा बताते हैं; शबरी का स्वागत भाइयों को पंपा और अगले संसार तक पहुँचाता है।', 'draft', 'draft'),
  ('turn-hanuman-meets-rama', 'en', 'Hanuman meets Rama', 'At Pampa, a careful stranger''s questions become recognition and a path to Sugriva.', 'At Pampa, a careful stranger''s questions become recognition and a path to Sugriva.', 'draft', 'draft'),
  ('turn-hanuman-meets-rama', 'hi', 'हनुमान राम से मिलते हैं', 'पंपा पर एक सावधान अजनबी के प्रश्न पहचान और सुग्रीव तक पहुँचने की राह बनते हैं।', 'पंपा पर एक सावधान अजनबी के प्रश्न पहचान और सुग्रीव तक पहुँचने की राह बनते हैं।', 'draft', 'draft'),
  ('turn-two-losses-one-alliance', 'en', 'Two losses, one alliance', 'Rama and Sugriva exchange their wounds and promises; proof of strength turns hope into a plan.', 'Rama and Sugriva exchange their wounds and promises; proof of strength turns hope into a plan.', 'draft', 'draft'),
  ('turn-two-losses-one-alliance', 'hi', 'दो वियोग, एक मैत्री', 'राम और सुग्रीव अपने दुख और वचन साझा करते हैं; शक्ति का प्रमाण आशा को योजना बनाता है।', 'राम और सुग्रीव अपने दुख और वचन साझा करते हैं; शक्ति का प्रमाण आशा को योजना बनाता है।', 'draft', 'draft'),
  ('turn-vali-falls', 'en', 'Vali falls; Kishkindha changes', 'The brothers fight, Rama''s arrow intervenes, and grief, argument, succession, and responsibility follow.', 'The brothers fight, Rama''s arrow intervenes, and grief, argument, succession, and responsibility follow.', 'draft', 'draft'),
  ('turn-vali-falls', 'hi', 'वालि का अंत, किष्किंधा का परिवर्तन', 'भाइयों का युद्ध होता है, राम का बाण हस्तक्षेप करता है और फिर शोक, तर्क, उत्तराधिकार तथा दायित्व आते हैं।', 'भाइयों का युद्ध होता है, राम का बाण हस्तक्षेप करता है और फिर शोक, तर्क, उत्तराधिकार तथा दायित्व आते हैं।', 'draft', 'draft'),
  ('turn-rains-and-delay', 'en', 'Rains, waiting, and a forgotten promise', 'The monsoon closes the roads; when it clears, Rama''s grief collides with Sugriva''s delay.', 'The monsoon closes the roads; when it clears, Rama''s grief collides with Sugriva''s delay.', 'draft', 'draft'),
  ('turn-rains-and-delay', 'hi', 'वर्षा, प्रतीक्षा और भूला वचन', 'वर्षा मार्ग बंद करती है; उसके बाद राम का शोक सुग्रीव की देरी से टकराता है।', 'वर्षा मार्ग बंद करती है; उसके बाद राम का शोक सुग्रीव की देरी से टकराता है।', 'draft', 'draft'),
  ('turn-search-every-horizon', 'en', 'Search every horizon', 'Vast teams receive landscapes, dangers, deadlines, and one purpose: discover where Sita was taken.', 'Vast teams receive landscapes, dangers, deadlines, and one purpose: discover where Sita was taken.', 'draft', 'draft'),
  ('turn-search-every-horizon', 'hi', 'हर दिशा में खोज', 'विशाल दलों को भू-दृश्य, संकट, समय-सीमा और एक लक्ष्य मिलता है—सीता को खोजना।', 'विशाल दलों को भू-दृश्य, संकट, समय-सीमा और एक लक्ष्य मिलता है—सीता को खोजना।', 'draft', 'draft'),
  ('turn-sampati-reveals-lanka', 'en', 'At the edge of despair, Sampati sees Lanka', 'The southern party nearly gives up; Jatayu''s brother turns grief into the missing direction.', 'The southern party nearly gives up; Jatayu''s brother turns grief into the missing direction.', 'draft', 'draft'),
  ('turn-sampati-reveals-lanka', 'hi', 'निराशा के किनारे संपाति लंका देखते हैं', 'दक्षिणी दल हार मानने वाला होता है; जटायु के भाई का शोक उन्हें सही दिशा देता है।', 'दक्षिणी दल हार मानने वाला होता है; जटायु के भाई का शोक उन्हें सही दिशा देता है।', 'draft', 'draft'),
  ('turn-hanuman-remembers', 'en', 'Hanuman remembers his strength', 'Each hero measures the ocean; Jambavan''s words awaken the one leap that can continue the story.', 'Each hero measures the ocean; Jambavan''s words awaken the one leap that can continue the story.', 'draft', 'draft'),
  ('turn-hanuman-remembers', 'hi', 'हनुमान अपनी शक्ति याद करते हैं', 'हर वीर समुद्र की दूरी आँकता है; जाम्बवान के शब्द उस छलाँग की शक्ति जगाते हैं जो कथा आगे बढ़ाएगी।', 'हर वीर समुद्र की दूरी आँकता है; जाम्बवान के शब्द उस छलाँग की शक्ति जगाते हैं जो कथा आगे बढ़ाएगी।', 'draft', 'draft'),
  ('turn-leap-across-ocean', 'en', 'The leap across the ocean', 'Hanuman expands into his task, meets wonders and obstacles in the sky, and reaches Lanka alone.', 'Hanuman expands into his task, meets wonders and obstacles in the sky, and reaches Lanka alone.', 'draft', 'draft'),
  ('turn-leap-across-ocean', 'hi', 'समुद्र पार की छलाँग', 'हनुमान अपने कार्य के अनुरूप विशाल होते हैं, आकाश के संकट पार कर अकेले लंका पहुँचते हैं।', 'हनुमान अपने कार्य के अनुरूप विशाल होते हैं, आकाश के संकट पार कर अकेले लंका पहुँचते हैं।', 'draft', 'draft'),
  ('turn-searching-lanka', 'en', 'Searching the sleeping city', 'Hanuman moves unseen through palaces and streets, resisting false conclusions until another grove appears.', 'Hanuman moves unseen through palaces and streets, resisting false conclusions until another grove appears.', 'draft', 'draft'),
  ('turn-searching-lanka', 'hi', 'सोती नगरी में खोज', 'हनुमान महलों और गलियों में अदृश्य चलते हैं, जल्दबाज़ी के निष्कर्ष रोकते हैं और एक नए उपवन तक पहुँचते हैं।', 'हनुमान महलों और गलियों में अदृश्य चलते हैं, जल्दबाज़ी के निष्कर्ष रोकते हैं और एक नए उपवन तक पहुँचते हैं।', 'draft', 'draft'),
  ('turn-sita-in-ashoka-grove', 'en', 'Sita in the ashoka grove', 'Hanuman finds Sita surrounded by threats, hears Ravana''s demand, and waits for a safe way to speak.', 'Hanuman finds Sita surrounded by threats, hears Ravana''s demand, and waits for a safe way to speak.', 'draft', 'draft'),
  ('turn-sita-in-ashoka-grove', 'hi', 'अशोक वाटिका में सीता', 'हनुमान सीता को धमकियों के बीच पाते हैं, रावण की माँग सुनते हैं और बोलने का सुरक्षित समय खोजते हैं।', 'हनुमान सीता को धमकियों के बीच पाते हैं, रावण की माँग सुनते हैं और बोलने का सुरक्षित समय खोजते हैं।', 'draft', 'draft'),
  ('turn-messenger-and-token', 'en', 'A messenger, a ring, and a reply', 'Rama''s story earns Sita''s trust; tokens and private memories become proof carried in both directions.', 'Rama''s story earns Sita''s trust; tokens and private memories become proof carried in both directions.', 'draft', 'draft'),
  ('turn-messenger-and-token', 'hi', 'दूत, मुद्रिका और उत्तर', 'राम की कथा सीता का विश्वास जीतती है; चिह्न और निजी स्मृतियाँ दोनों दिशाओं में प्रमाण बनती हैं।', 'राम की कथा सीता का विश्वास जीतती है; चिह्न और निजी स्मृतियाँ दोनों दिशाओं में प्रमाण बनती हैं।', 'draft', 'draft'),
  ('turn-lanka-burns', 'en', 'The garden breaks; Lanka burns', 'Hanuman chooses visible disruption, faces Ravana''s court, and turns the punishment of his tail into fire.', 'Hanuman chooses visible disruption, faces Ravana''s court, and turns the punishment of his tail into fire.', 'draft', 'draft'),
  ('turn-lanka-burns', 'hi', 'वाटिका टूटती है, लंका जलती है', 'हनुमान खुली चुनौती चुनते हैं, रावण की सभा का सामना करते हैं और पूँछ की सज़ा को अग्नि बना देते हैं।', 'हनुमान खुली चुनौती चुनते हैं, रावण की सभा का सामना करते हैं और पूँछ की सज़ा को अग्नि बना देते हैं।', 'draft', 'draft'),
  ('turn-return-over-ocean', 'en', 'The return over the ocean', 'Hanuman confirms Sita is safe, crosses back, and lets the waiting search party hear success in his roar.', 'Hanuman confirms Sita is safe, crosses back, and lets the waiting search party hear success in his roar.', 'draft', 'draft'),
  ('turn-return-over-ocean', 'hi', 'समुद्र के ऊपर वापसी', 'हनुमान सीता की कुशलता देखकर लौटते हैं और उनकी गर्जना से प्रतीक्षारत दल सफलता पहचान लेता है।', 'हनुमान सीता की कुशलता देखकर लौटते हैं और उनकी गर्जना से प्रतीक्षारत दल सफलता पहचान लेता है।', 'draft', 'draft'),
  ('turn-news-reaches-rama', 'en', 'The news reaches Rama', 'Celebration spills through Madhuvana before Hanuman gives Rama Sita''s jewel, words, and remaining time.', 'Celebration spills through Madhuvana before Hanuman gives Rama Sita''s jewel, words, and remaining time.', 'draft', 'draft'),
  ('turn-news-reaches-rama', 'hi', 'समाचार राम तक पहुँचता है', 'मधुवन में उत्सव के बाद हनुमान राम को सीता की मणि, संदेश और शेष समय बताते हैं।', 'मधुवन में उत्सव के बाद हनुमान राम को सीता की मणि, संदेश और शेष समय बताते हैं।', 'draft', 'draft'),
  ('turn-ocean-and-bridge', 'en', 'The ocean, Vibhishana, and the bridge', 'The allies reach the sea, receive Ravana''s brother, confront the ocean, and make a road to Lanka.', 'The allies reach the sea, receive Ravana''s brother, confront the ocean, and make a road to Lanka.', 'draft', 'draft'),
  ('turn-ocean-and-bridge', 'hi', 'समुद्र, विभीषण और सेतु', 'साथी समुद्र तक पहुँचते हैं, रावण के भाई को स्वीकार करते हैं और लंका तक सेतु बनाते हैं।', 'साथी समुद्र तक पहुँचते हैं, रावण के भाई को स्वीकार करते हैं और लंका तक सेतु बनाते हैं।', 'draft', 'draft'),
  ('turn-lanka-surrounded', 'en', 'Lanka is surrounded', 'Spies, counsel, a final embassy, and the first assaults make retreat less possible for every side.', 'Spies, counsel, a final embassy, and the first assaults make retreat less possible for every side.', 'draft', 'draft'),
  ('turn-lanka-surrounded', 'hi', 'लंका घिर जाती है', 'गुप्तचर, सलाह, अंतिम दूत और शुरुआती आक्रमण दोनों पक्षों के लिए पीछे हटना कठिन कर देते हैं।', 'गुप्तचर, सलाह, अंतिम दूत और शुरुआती आक्रमण दोनों पक्षों के लिए पीछे हटना कठिन कर देते हैं।', 'draft', 'draft'),
  ('turn-kumbhakarna-rises', 'en', 'Kumbhakarna rises', 'War consumes commanders until the sleeping giant enters, questions Ravana, fights, and falls.', 'War consumes commanders until the sleeping giant enters, questions Ravana, fights, and falls.', 'draft', 'draft'),
  ('turn-kumbhakarna-rises', 'hi', 'कुंभकर्ण उठता है', 'युद्ध सेनापतियों को निगलता है; फिर निद्रा से उठा कुंभकर्ण रावण से प्रश्न कर युद्ध में गिरता है।', 'युद्ध सेनापतियों को निगलता है; फिर निद्रा से उठा कुंभकर्ण रावण से प्रश्न कर युद्ध में गिरता है।', 'draft', 'draft'),
  ('turn-indrajits-last-war', 'en', 'Indrajit''s last war', 'Illusion, hidden weapons, and the battle at Nikumbhila lead Lakshmana to Ravana''s formidable son.', 'Illusion, hidden weapons, and the battle at Nikumbhila lead Lakshmana to Ravana''s formidable son.', 'draft', 'draft'),
  ('turn-indrajits-last-war', 'hi', 'इंद्रजीत का अंतिम युद्ध', 'माया, अदृश्य अस्त्र और निकुंभिला का युद्ध लक्ष्मण को रावण के प्रबल पुत्र तक ले जाता है।', 'माया, अदृश्य अस्त्र और निकुंभिला का युद्ध लक्ष्मण को रावण के प्रबल पुत्र तक ले जाता है।', 'draft', 'draft'),
  ('turn-ravanas-final-battle', 'en', 'Ravana''s final battle', 'After Lakshmana is wounded and restored, Rama meets Ravana through a long final exchange of weapons.', 'After Lakshmana is wounded and restored, Rama meets Ravana through a long final exchange of weapons.', 'draft', 'draft'),
  ('turn-ravanas-final-battle', 'hi', 'रावण का अंतिम युद्ध', 'लक्ष्मण के घायल होकर बचने के बाद राम और रावण का दीर्घ अंतिम अस्त्र-युद्ध होता है।', 'लक्ष्मण के घायल होकर बचने के बाद राम और रावण का दीर्घ अंतिम अस्त्र-युद्ध होता है।', 'draft', 'draft'),
  ('turn-sita-and-aftermath', 'en', 'Sita and the aftermath of victory', 'Grief enters Lanka; Sita is brought before Rama, faces public ordeal, and the gods answer the battlefield.', 'Grief enters Lanka; Sita is brought before Rama, faces public ordeal, and the gods answer the battlefield.', 'draft', 'draft'),
  ('turn-sita-and-aftermath', 'hi', 'सीता और विजय का परिणाम', 'लंका शोक में डूबती है; सीता राम के सामने आती हैं, सार्वजनिक परीक्षा का सामना करती हैं और देवता उत्तर देते हैं।', 'लंका शोक में डूबती है; सीता राम के सामने आती हैं, सार्वजनिक परीक्षा का सामना करती हैं और देवता उत्तर देते हैं।', 'draft', 'draft'),
  ('turn-road-home', 'en', 'The road home', 'The Pushpaka retraces the whole world, news reaches Bharata, and Ayodhya receives the returning company.', 'The Pushpaka retraces the whole world, news reaches Bharata, and Ayodhya receives the returning company.', 'source_aligned', 'published'),
  ('turn-road-home', 'hi', 'घर वापसी की राह', 'पुष्पक पूरे संसार की राह लौटता है, समाचार भरत तक पहुँचता है और अयोध्या लौटते दल का स्वागत करती है।', 'पुष्पक पूरे संसार की राह लौटता है, समाचार भरत तक पहुँचता है और अयोध्या लौटते दल का स्वागत करती है।', 'source_aligned', 'published'),
  ('scene-leave-lanka', 'en', 'Leave Lanka', 'Victory becomes a shared journey home.', 'Vibhishana asks what remains to be done. Rama''s first answer is not about himself: honour the vanaras and bears who risked their lives in the war. Rama releases his allies to their own homes. They ask instead to travel with him, see Ayodhya, witness the coronation, and only then depart. Sita and Lakshmana board with Rama. Sugriva, Vibhishana, vanaras, bears, and rakshasa companions fill the extraordinary craft without being left behind. At Rama''s command, the Pushpaka rises into the sky. For the first time since the exile began, home is not only a hope—it is the direction of travel.', 'source_aligned', 'published'),
  ('scene-leave-lanka', 'hi', 'प्रस्थान से पहले', 'विजय अब सबकी साझा घर-वापसी बनती है।', 'विभीषण पूछते हैं कि अब क्या करना बाकी है। राम का पहला उत्तर अपने लिए नहीं है—उन वानरों और भालुओं का सम्मान हो जिन्होंने युद्ध में अपना जीवन दाँव पर लगाया। राम अपने साथियों को उनके घर लौटने की अनुमति देते हैं। वे आग्रह करते हैं कि पहले उनके साथ अयोध्या चलें, राज्याभिषेक देखें, फिर विदा हों। सीता और लक्ष्मण राम के साथ चढ़ते हैं। सुग्रीव, विभीषण, वानर, भालू और राक्षस साथी भी उस अद्भुत विमान में स्थान पाते हैं। राम के आदेश पर पुष्पक आकाश में उठता है। वनवास शुरू होने के बाद पहली बार घर केवल आशा नहीं, यात्रा की दिशा बन जाता है।', 'source_aligned', 'published'),
  ('scene-sky-road', 'en', 'The sky road remembers', 'The route home becomes a map of everything the travellers survived.', 'Rama shows Sita Lanka, the battlefield, the ocean, and the bridge. Each place carries the memory of companions, losses, choices, and the effort made to find her. At Kishkindha, Sita asks that Tara and the other vanara women join them. The homecoming expands again: it will be witnessed by the families behind the alliance. Rishyamuka, Pampa, Panchavati, the Godavari, Chitrakuta, Yamuna, Ganga, and Shringavera appear below. The names are not a list: friendship, grief, abduction, searching, and endurance return with them. Ayodhya finally comes into view. Rama asks Sita to bow toward it, and the whole company rises to look at the city they have crossed an epic to reach.', 'source_aligned', 'published'),
  ('scene-sky-road', 'hi', 'नीचे छूटी कीमत', 'घर की राह उनके पूरे संघर्ष का जीवित मानचित्र बन जाती है।', 'राम सीता को लंका, युद्धभूमि, समुद्र और सेतु दिखाते हैं। हर स्थान साथियों, हानि, निर्णय और उन्हें खोजने के प्रयास की स्मृति लिए है। किष्किंधा में सीता चाहती हैं कि तारा और अन्य वानर स्त्रियाँ भी साथ चलें। घर-वापसी फिर बड़ी हो जाती है—अब गठबंधन के पीछे खड़े परिवार भी उसके साक्षी होंगे। ऋष्यमूक, पम्पा, पंचवटी, गोदावरी, चित्रकूट, यमुना, गंगा और शृंगवेरपुर नीचे उभरते हैं। ये केवल नाम नहीं—मित्रता, शोक, हरण, खोज और धैर्य फिर जीवित होते हैं। अंततः अयोध्या दिखाई देती है। राम सीता से उसे प्रणाम करने को कहते हैं, और पूरा दल उस नगरी को देखने उठ खड़ा होता है जहाँ पहुँचने के लिए उन्होंने एक महाकाव्य पार किया है।', 'source_aligned', 'published'),
  ('scene-bharadvaja-hermitage', 'en', 'Home is near', 'After fourteen years, Rama learns that Bharata is still waiting.', 'With the fourteen years complete, Rama reaches Bharadvaja''s hermitage and bows. Before asking about celebration or power, he asks whether Ayodhya is well, Bharata still protects it, and his mothers live. Bharadvaja answers that Bharata waits with matted hair, honouring Rama''s sandals and ruling in obedience to his command. The household is safe. The sage recounts the exile''s great turns—Sita''s abduction, Sugriva''s alliance, Hanuman''s search, the bridge, and Ravana''s defeat. Rama arrives not as a rumour but as someone whose ordeal is understood. Rama asks for one boon: let the road ahead bear fruit and honey for his companions. The trees flower out of season, and the weary vanaras find abundance on the final approach.', 'source_aligned', 'published'),
  ('scene-bharadvaja-hermitage', 'hi', 'प्रतिज्ञा की अवधि पूरी', 'चौदह वर्ष बाद राम जान पाते हैं कि भरत अब भी प्रतीक्षा कर रहे हैं।', 'चौदह वर्ष पूरे होने पर राम भरद्वाज के आश्रम पहुँचकर प्रणाम करते हैं। उत्सव या सत्ता से पहले वे पूछते हैं—क्या अयोध्या कुशल है, क्या भरत अब भी उसकी रक्षा कर रहे हैं, क्या उनकी माताएँ जीवित हैं। भरद्वाज बताते हैं कि भरत जटाएँ धारण किए राम की पादुकाओं का सम्मान करते हुए उनकी आज्ञा के अनुसार राज्य संभाल रहे हैं। राजपरिवार सुरक्षित है। ऋषि वनवास के बड़े मोड़ गिनाते हैं—सीता का हरण, सुग्रीव से मैत्री, हनुमान की खोज, सेतु और रावण की पराजय। राम किसी अफवाह की तरह नहीं, समझे गए संघर्ष के साथ लौटते हैं। राम एक वर माँगते हैं—आगे की राह पर उनके साथियों के लिए फल और मधु उपलब्ध हों। वृक्ष असमय फूल-फल उठते हैं और अंतिम पड़ाव पर थके वानरों को भरपूर आहार मिलता है।', 'source_aligned', 'published'),
  ('scene-hanuman-goes-ahead', 'en', 'Hanuman goes ahead', 'The last distance is crossed first by a trusted messenger.', 'Rama sends Hanuman ahead not only to announce the return, but to observe Bharata''s face, words, and wishes. Fourteen years with a kingdom could have changed anyone. Hanuman first reaches Guha at Shringavera and tells him that his friend Rama is safe and near. The return follows the same human bonds that once helped the exiles leave. At Nandigrama, Hanuman finds Bharata thin from restraint, dressed like an ascetic, ruling with Rama''s sandals before him. The years of waiting are visible before a word is spoken. Hanuman says that Rama has defeated Ravana, recovered Sita, and returned with Lakshmana and his allies. Bharata collapses in sudden joy, then rises to hear everything.', 'source_aligned', 'published'),
  ('scene-hanuman-goes-ahead', 'hi', 'एक संवेदनशील दायित्व', 'अंतिम दूरी सबसे पहले एक विश्वस्त संदेशवाहक पार करता है।', 'राम हनुमान को केवल वापसी का समाचार देने नहीं, भरत के चेहरे, शब्द और इच्छा को समझने भी भेजते हैं। चौदह वर्ष और एक राज्य किसी को भी बदल सकते थे। हनुमान पहले शृंगवेरपुर में गुह के पास पहुँचकर बताते हैं कि उनके मित्र राम सुरक्षित और निकट हैं। वापसी उन्हीं मानवीय संबंधों से होकर गुजरती है जिन्होंने वनवास के आरंभ में सहारा दिया था। नंदिग्राम में हनुमान भरत को संयम से क्षीण, तपस्वी वेश में और सामने राम की पादुकाएँ रखकर शासन करते देखते हैं। एक शब्द बोले जाने से पहले ही वर्षों की प्रतीक्षा दिखाई देती है। हनुमान बताते हैं कि राम ने रावण को पराजित किया, सीता को वापस पाया और लक्ष्मण व साथियों के साथ लौट आए हैं। भरत अचानक आनंद से मूर्छित हो जाते हैं, फिर उठकर पूरी कथा सुनना चाहते हैं।', 'source_aligned', 'published'),
  ('scene-bharata-hears', 'en', 'Bharata hears the news', 'A distant victory becomes a story Bharata can finally hold.', 'Bharata does not stop at the headline that Rama lives. He asks Hanuman how Rama met the vanaras and how the years after Chitrakuta unfolded. Hanuman tells of the forest dangers, Surpanakha, the golden deer, Sita''s abduction, and Jatayu''s fall. The reunion ahead is measured against what was taken away. He recounts the meeting with Sugriva, the vanara search, Sampati''s clue, his own leap to Lanka, Sita in the ashoka grove, and the ring that proved Rama had found a path to her. The bridge, the battle, Ravana''s defeat, and the Pushpaka return bring the account to the present. Bharata folds his hands: after so long, the desire to see Rama can finally be fulfilled.', 'source_aligned', 'published'),
  ('scene-bharata-hears', 'hi', 'यह सब कैसे संभव हुआ?', 'दूर की विजय अब भरत के सामने पूरी कथा बनकर आती है।', 'भरत केवल यह सुनकर नहीं रुकते कि राम जीवित हैं। वे हनुमान से पूछते हैं कि राम वानरों से कैसे मिले और चित्रकूट के बाद के वर्ष कैसे बीते। हनुमान वन के संकट, शूर्पणखा, स्वर्ण-मृग, सीता के हरण और जटायु के पतन की कथा कहते हैं। आने वाला मिलन अब उस सबके सामने दिखाई देता है जो छिन गया था। वे सुग्रीव से भेंट, वानर दलों की खोज, संपाती के संकेत, अपनी लंका-छलाँग, अशोक-वाटिका में सीता और राम की मुद्रिका की कथा सुनाते हैं। सेतु, युद्ध, रावण की पराजय और पुष्पक से वापसी कथा को वर्तमान तक ले आते हैं। भरत हाथ जोड़ते हैं—इतने लंबे समय बाद राम को देखने की इच्छा अब पूरी होगी।', 'source_aligned', 'published'),
  ('scene-ayodhya-prepares', 'en', 'Ayodhya prepares', 'Private waiting becomes a public homecoming.', 'Bharata orders worship, music, and a welcome open to the royal household, soldiers, families, artists, and citizens. Rama''s return belongs to the city, not only the palace. Shatrughna has the route from Nandigrama levelled, watered, strewn with flowers, and lined with flags. The landscape itself becomes part of the welcome. Still dressed in bark, Bharata carries Rama''s sandals on his head as the queens, ministers, citizens, horses, chariots, and elephants move toward Nandigrama. The Pushpaka descends. Rama lifts Bharata into an embrace; Bharata greets Sita, Lakshmana, and the allies, then places the sandals back at Rama''s feet and returns the kingdom held in trust.', 'source_aligned', 'published'),
  ('scene-ayodhya-prepares', 'hi', 'सबको समाचार दो', 'निजी प्रतीक्षा अब पूरे नगर की घर-वापसी बनती है।', 'भरत पूजा, संगीत और ऐसा स्वागत तैयार करने का आदेश देते हैं जिसमें राजपरिवार, सैनिक, परिवार, कलाकार और नागरिक सब शामिल हों। राम की वापसी केवल महल की नहीं, पूरे नगर की है। शत्रुघ्न नंदिग्राम से आने वाली राह समतल और जल-सिंचित करवाते हैं; फूल बिखरते हैं और ध्वज लगते हैं। भू-दृश्य स्वयं स्वागत का हिस्सा बन जाता है। अब भी वल्कल पहने भरत राम की पादुकाएँ सिर पर रखते हैं। रानियाँ, मंत्री, नागरिक, घोड़े, रथ और हाथी नंदिग्राम की ओर बढ़ते हैं। पुष्पक उतरता है। राम भरत को उठाकर गले लगाते हैं; भरत सीता, लक्ष्मण और साथियों का स्वागत करते हैं, फिर पादुकाएँ राम के चरणों में रखकर धरोहर की तरह संभाला राज्य लौटा देते हैं।', 'source_aligned', 'published'),
  ('scene-kingdom-returned', 'en', 'The kingdom is returned', 'Homecoming becomes the acceptance of public responsibility.', 'Bharata tells Rama that the kingdom was never his possession and that he cannot carry its burden in Rama''s place. Rama answers, ''So be it.'' Rama, Lakshmana, Bharata, Sugriva, and Vibhishana bathe; the matted hair is cut and ceremonial clothes are prepared. Sita and the vanara women are adorned for the entry. Music and crowds accompany the entry. Rama publicly tells Ayodhya about Sugriva''s friendship, Hanuman''s prowess, and the work of the allies, so the victory is not reduced to one hero. Vasishta and the gathered officiants install Rama with Sita beside him. Honours move outward to the allies; Sita gives Hanuman the pearl necklace, remembering his service. The companions eventually return to their own worlds, and governance begins. The selected telling closes with an idealized vision of Rama''s reign; Devam presents that as this source''s sacred narrative, not a modern historical statistic.', 'source_aligned', 'published'),
  ('scene-kingdom-returned', 'hi', 'जिसे संभाला, उसे वापस लो', 'घर-वापसी सार्वजनिक उत्तरदायित्व स्वीकार करने में बदलती है।', 'भरत राम से कहते हैं कि राज्य कभी उनकी संपत्ति नहीं था और वे राम के स्थान पर उसका भार नहीं उठा सकते। राम स्वीकार करते हैं। राम, लक्ष्मण, भरत, सुग्रीव और विभीषण स्नान करते हैं; जटाएँ काटी जाती हैं और राजकीय वस्त्र तैयार होते हैं। सीता और वानर स्त्रियाँ नगर-प्रवेश के लिए सजती हैं। संगीत और जनसमूह नगर-प्रवेश के साथ चलते हैं। राम अयोध्या को सुग्रीव की मित्रता, हनुमान के पराक्रम और सभी साथियों के कार्य बताते हैं, ताकि विजय केवल एक नायक की न रह जाए। वसिष्ठ और अन्य आचार्य सीता के साथ राम का राज्याभिषेक करते हैं। सम्मान साथियों तक पहुँचता है; सीता हनुमान की सेवा याद कर उन्हें मोतियों का हार देती हैं। साथी अंततः अपने-अपने लोक लौटते हैं और शासन आरंभ होता है। चुना हुआ पाठ राम-राज्य की आदर्श छवि के साथ समाप्त होता है; देवम इसे इसी स्रोत की पवित्र कथा मानता है, आधुनिक ऐतिहासिक आँकड़ा नहीं।', 'source_aligned', 'published'),
  ('turn-origins-behind-war', 'en', 'The histories behind the war', 'Visiting sages unfold the origins, ambitions, boons, families, and earlier conflicts behind Ravana''s world.', 'Visiting sages unfold the origins, ambitions, boons, families, and earlier conflicts behind Ravana''s world.', 'draft', 'draft'),
  ('turn-origins-behind-war', 'hi', 'युद्ध के पीछे की कथाएँ', 'आए हुए ऋषि रावण के संसार के जन्म, वरदान, परिवार, महत्वाकांक्षा और पुराने संघर्ष खोलते हैं।', 'आए हुए ऋषि रावण के संसार के जन्म, वरदान, परिवार, महत्वाकांक्षा और पुराने संघर्ष खोलते हैं।', 'draft', 'draft'),
  ('turn-companions-depart', 'en', 'Companions depart; public voices remain', 'Allies return home while Rama asks what the city says; private happiness meets public reputation.', 'Allies return home while Rama asks what the city says; private happiness meets public reputation.', 'draft', 'draft'),
  ('turn-companions-depart', 'hi', 'साथी विदा होते हैं, लोक-वाणी रह जाती है', 'साथी अपने घर लौटते हैं और राम नगर की वाणी पूछते हैं; निजी सुख लोक-प्रतिष्ठा से टकराता है।', 'साथी अपने घर लौटते हैं और राम नगर की वाणी पूछते हैं; निजी सुख लोक-प्रतिष्ठा से टकराता है।', 'draft', 'draft'),
  ('turn-sita-sent-away', 'en', 'Sita is sent away', 'Rama responds to censure by ordering Lakshmana to leave the pregnant Sita near Valmiki''s hermitage.', 'Rama responds to censure by ordering Lakshmana to leave the pregnant Sita near Valmiki''s hermitage.', 'draft', 'draft'),
  ('turn-sita-sent-away', 'hi', 'सीता को वन भेजा जाता है', 'लोक-निंदा के उत्तर में राम लक्ष्मण को गर्भवती सीता को वाल्मीकि आश्रम के पास छोड़ने कहते हैं।', 'लोक-निंदा के उत्तर में राम लक्ष्मण को गर्भवती सीता को वाल्मीकि आश्रम के पास छोड़ने कहते हैं।', 'draft', 'draft'),
  ('turn-kingdom-tales-and-twins', 'en', 'Kingdom tales and the birth of the twins', 'Later acts of rule interweave with Shatrughna''s campaign and the birth and naming of Lava and Kusha.', 'Later acts of rule interweave with Shatrughna''s campaign and the birth and naming of Lava and Kusha.', 'draft', 'draft'),
  ('turn-kingdom-tales-and-twins', 'hi', 'राज्य-कथाएँ और जुड़वाँ पुत्रों का जन्म', 'राज्य के प्रसंग शत्रुघ्न के अभियान तथा लव-कुश के जन्म और नामकरण से जुड़ते हैं।', 'राज्य के प्रसंग शत्रुघ्न के अभियान तथा लव-कुश के जन्म और नामकरण से जुड़ते हैं।', 'draft', 'draft'),
  ('turn-later-reign', 'en', 'The later reign turns toward sacrifice', 'Judgments, visitors, and kingdom narratives accumulate until Rama begins the great horse sacrifice.', 'Judgments, visitors, and kingdom narratives accumulate until Rama begins the great horse sacrifice.', 'draft', 'draft'),
  ('turn-later-reign', 'hi', 'उत्तरकालीन शासन यज्ञ की ओर बढ़ता है', 'निर्णय, अतिथि और राज्य-कथाएँ एकत्र होती हैं और अंततः राम अश्वमेध आरंभ करते हैं।', 'निर्णय, अतिथि और राज्य-कथाएँ एकत्र होती हैं और अंततः राम अश्वमेध आरंभ करते हैं।', 'draft', 'draft'),
  ('turn-twins-sing-sita-returns', 'en', 'The twins sing; Sita returns', 'Lava and Kusha sing the Ramayana before Rama; recognition leads to Sita''s final public testimony and return to Earth.', 'Lava and Kusha sing the Ramayana before Rama; recognition leads to Sita''s final public testimony and return to Earth.', 'draft', 'draft'),
  ('turn-twins-sing-sita-returns', 'hi', 'जुड़वाँ कथा गाते हैं, सीता लौटती हैं', 'लव-कुश राम के सामने रामायण गाते हैं; पहचान सीता की अंतिम सार्वजनिक साक्षी और पृथ्वी में वापसी तक जाती है।', 'लव-कुश राम के सामने रामायण गाते हैं; पहचान सीता की अंतिम सार्वजनिक साक्षी और पृथ्वी में वापसी तक जाती है।', 'draft', 'draft'),
  ('turn-last-departures', 'en', 'The last departures', 'The reign continues, then Lakshmana and Rama meet the limits of vows and walk toward the Sarayu.', 'The reign continues, then Lakshmana and Rama meet the limits of vows and walk toward the Sarayu.', 'draft', 'draft'),
  ('turn-last-departures', 'hi', 'अंतिम प्रस्थान', 'शासन चलता रहता है; फिर लक्ष्मण और राम वचनों की अंतिम सीमा पर सरयू की ओर बढ़ते हैं।', 'शासन चलता रहता है; फिर लक्ष्मण और राम वचनों की अंतिम सीमा पर सरयू की ओर बढ़ते हैं।', 'draft', 'draft')
) as copy(moment_slug, language_code, title, synopsis, narrative, text_status, publication_state)
