  ('scene-sky-road', 'places-become-memories', 3, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":123,"sourceOrdinal":123,"sourceEndOrdinal":123,"spanSha256":"ac4a5d9e558ad6f19bb7e8558f899971321a5f810116030fcd0843f5a0872010"}'::jsonb, '{"visualCue":"Landmarks ignite one by one along a flowing aerial route, each with a brief story echo.","characterIds":["rama","sita","lakshmana"]}'::jsonb),
  ('scene-sky-road', 'ayodhya-in-sight', 4, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":123,"sourceOrdinal":123,"sourceEndOrdinal":123,"spanSha256":"ac4a5d9e558ad6f19bb7e8558f899971321a5f810116030fcd0843f5a0872010"}'::jsonb, '{"visualCue":"A distant luminous city emerges through cloud while the travellers rise together.","characterIds":["rama","sita","lakshmana"]}'::jsonb),
  ('scene-bharadvaja-hermitage', 'fourteen-years-complete', 1, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":124,"sourceOrdinal":124,"sourceEndOrdinal":124,"spanSha256":"2b5f780068a77fe5465ff61956b5355b78afdfeb1c872c4e4dff768cb20dabe4"}'::jsonb, '{"visualCue":"The bright craft settles beyond a quiet hermitage at the end of a long road.","characterIds":["rama","bharadvaja"]}'::jsonb),
  ('scene-bharadvaja-hermitage', 'bharata-waits', 2, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":124,"sourceOrdinal":124,"sourceEndOrdinal":124,"spanSha256":"2b5f780068a77fe5465ff61956b5355b78afdfeb1c872c4e4dff768cb20dabe4"}'::jsonb, '{"visualCue":"A vision of Nandigrama appears: sandals before a waiting figure in bark cloth.","characterIds":["bharadvaja","bharata","rama"]}'::jsonb),
  ('scene-bharadvaja-hermitage', 'the-journey-is-known', 3, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":124,"sourceOrdinal":124,"sourceEndOrdinal":124,"spanSha256":"2b5f780068a77fe5465ff61956b5355b78afdfeb1c872c4e4dff768cb20dabe4"}'::jsonb, '{"visualCue":"Brief layered echoes of forest, ocean, bridge, and battle orbit the listeners.","characterIds":["bharadvaja","rama","sita","hanuman","sugriva"]}'::jsonb),
  ('scene-bharadvaja-hermitage', 'road-of-fruit', 4, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":124,"sourceOrdinal":124,"sourceEndOrdinal":124,"spanSha256":"2b5f780068a77fe5465ff61956b5355b78afdfeb1c872c4e4dff768cb20dabe4"}'::jsonb, '{"visualCue":"Dry branches transform into a luminous orchard as the company moves beneath them.","characterIds":["rama","bharadvaja"]}'::jsonb),
  ('scene-hanuman-goes-ahead', 'read-bharatas-heart', 1, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":125,"sourceOrdinal":125,"sourceEndOrdinal":125,"spanSha256":"4d3da830889d7d0c551c2cabb152f6dcb0695b7a5a2d50dc8854713699f14fb6"}'::jsonb, '{"visualCue":"Rama gives quiet instructions while Ayodhya glows beyond the horizon.","characterIds":["rama","hanuman","bharata"]}'::jsonb),
  ('scene-hanuman-goes-ahead', 'news-for-guha', 2, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":125,"sourceOrdinal":125,"sourceEndOrdinal":125,"spanSha256":"4d3da830889d7d0c551c2cabb152f6dcb0695b7a5a2d50dc8854713699f14fb6"}'::jsonb, '{"visualCue":"A swift figure lands beside the river settlement as recognition spreads.","characterIds":["hanuman","guha","rama"]}'::jsonb),
  ('scene-hanuman-goes-ahead', 'nandigrama-waiting', 3, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":125,"sourceOrdinal":125,"sourceEndOrdinal":125,"spanSha256":"4d3da830889d7d0c551c2cabb152f6dcb0695b7a5a2d50dc8854713699f14fb6"}'::jsonb, '{"visualCue":"The sandals hold the foreground; the waiting prince sits beyond them in a spare hermitage court.","characterIds":["hanuman","bharata"]}'::jsonb),
  ('scene-hanuman-goes-ahead', 'the-message-lands', 4, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":125,"sourceOrdinal":125,"sourceEndOrdinal":125,"spanSha256":"4d3da830889d7d0c551c2cabb152f6dcb0695b7a5a2d50dc8854713699f14fb6"}'::jsonb, '{"visualCue":"The austere stillness breaks as attendants rush forward and hope floods the scene.","characterIds":["hanuman","bharata","rama","sita","lakshmana"]}'::jsonb),
  ('scene-bharata-hears', 'tell-me-how', 1, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":126,"sourceOrdinal":126,"sourceEndOrdinal":126,"spanSha256":"2db463f691012175d4ba4583da53837c3576158a88b2d78d4606e51117b37c31"}'::jsonb, '{"visualCue":"Bharata and Hanuman sit close while the waiting court falls silent.","characterIds":["bharata","hanuman"]}'::jsonb),
  ('scene-bharata-hears', 'forest-turns', 2, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":126,"sourceOrdinal":126,"sourceEndOrdinal":126,"spanSha256":"2db463f691012175d4ba4583da53837c3576158a88b2d78d4606e51117b37c31"}'::jsonb, '{"visualCue":"Story shadows move across the ground: deer, empty hut, wing, and southward trail.","characterIds":["hanuman","rama","sita","lakshmana"]}'::jsonb),
  ('scene-bharata-hears', 'alliance-and-search', 3, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":126,"sourceOrdinal":126,"sourceEndOrdinal":126,"spanSha256":"2db463f691012175d4ba4583da53837c3576158a88b2d78d4606e51117b37c31"}'::jsonb, '{"visualCue":"The spoken story opens into a moving arc from Kishkindha across the ocean to the ashoka grove.","characterIds":["hanuman","sugriva","sita","rama"]}'::jsonb),
  ('scene-bharata-hears', 'bridge-battle-return', 4, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":126,"sourceOrdinal":126,"sourceEndOrdinal":126,"spanSha256":"2db463f691012175d4ba4583da53837c3576158a88b2d78d4606e51117b37c31"}'::jsonb, '{"visualCue":"The story''s moving images resolve into the real dust of the approaching company.","characterIds":["bharata","hanuman","rama"]}'::jsonb),
  ('scene-ayodhya-prepares', 'city-awakens', 1, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":127,"sourceOrdinal":127,"sourceEndOrdinal":127,"spanSha256":"097c1dc22e4d379c367cf61a656856ea2f26face1092709ada5a1d75345c1837"}'::jsonb, '{"visualCue":"Courtyards ignite with preparation as messengers fan across Ayodhya.","characterIds":["bharata","shatrughna"]}'::jsonb),
  ('scene-ayodhya-prepares', 'prepare-the-road', 2, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":127,"sourceOrdinal":127,"sourceEndOrdinal":127,"spanSha256":"097c1dc22e4d379c367cf61a656856ea2f26face1092709ada5a1d75345c1837"}'::jsonb, '{"visualCue":"Workers, water, flowers, and standards transform the road in layered motion.","characterIds":["shatrughna","bharata"]}'::jsonb),
  ('scene-ayodhya-prepares', 'sandals-lead-procession', 3, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":127,"sourceOrdinal":127,"sourceEndOrdinal":127,"spanSha256":"097c1dc22e4d379c367cf61a656856ea2f26face1092709ada5a1d75345c1837"}'::jsonb, '{"visualCue":"The sandals form the luminous centre of a vast procession moving through dust and music.","characterIds":["bharata","shatrughna"]}'::jsonb),
  ('scene-ayodhya-prepares', 'brothers-meet', 4, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":127,"sourceOrdinal":127,"sourceEndOrdinal":127,"spanSha256":"097c1dc22e4d379c367cf61a656856ea2f26face1092709ada5a1d75345c1837"}'::jsonb, '{"visualCue":"The two moving worlds meet around an embrace, then settle around the returned sandals.","characterIds":["rama","bharata","sita","lakshmana","sugriva","vibhishana"]}'::jsonb),
  ('scene-kingdom-returned', 'bharata-returns-burden', 1, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":128,"sourceOrdinal":128,"sourceEndOrdinal":128,"spanSha256":"0eab6905146d65e1f905b5e974d473712234c86fa12bf1902fcf9f1f435e9405"}'::jsonb, '{"visualCue":"Bharata speaks before the gathered household while Rama listens from a low seat.","characterIds":["bharata","rama"]}'::jsonb),
  ('scene-kingdom-returned', 'exile-clothes-fall-away', 2, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":128,"sourceOrdinal":128,"sourceEndOrdinal":128,"spanSha256":"0eab6905146d65e1f905b5e974d473712234c86fa12bf1902fcf9f1f435e9405"}'::jsonb, '{"visualCue":"Bark, dust, water, cloth, and ornaments mark a visible transition between lives.","characterIds":["rama","sita","lakshmana","bharata","sugriva","vibhishana"]}'::jsonb),
  ('scene-kingdom-returned', 'city-entry', 3, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":128,"sourceOrdinal":128,"sourceEndOrdinal":128,"spanSha256":"0eab6905146d65e1f905b5e974d473712234c86fa12bf1902fcf9f1f435e9405"}'::jsonb, '{"visualCue":"The procession enters beneath flags while brief visions of the allies'' deeds rise over the crowd.","characterIds":["rama","hanuman","sugriva","vibhishana"]}'::jsonb),
  ('scene-kingdom-returned', 'coronation-and-gifts', 4, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":128,"sourceOrdinal":128,"sourceEndOrdinal":128,"spanSha256":"0eab6905146d65e1f905b5e974d473712234c86fa12bf1902fcf9f1f435e9405"}'::jsonb, '{"visualCue":"Water, crown, white umbrellas, and the pearl necklace form four bright visual beats.","characterIds":["rama","sita","vasishta","hanuman","sugriva","vibhishana"]}'::jsonb),
  ('scene-kingdom-returned', 'rule-begins', 5, '{"snapshotContract":"DEVAM_RAMAYANA_CONSUMER_NARRATIVE_SNAPSHOT_V1","sourceSha256":"8d1b8901823f5b5bd8b3207370991ddf95e5c76cb30ad5271aef835c9708464b","sourceGlobalOrdinal":128,"sourceOrdinal":128,"sourceEndOrdinal":128,"spanSha256":"0eab6905146d65e1f905b5e974d473712234c86fa12bf1902fcf9f1f435e9405"}'::jsonb, '{"visualCue":"Departing paths spread from Ayodhya as the city settles into a dawn panorama.","characterIds":["rama","bharata","lakshmana","sugriva","vibhishana"]}'::jsonb)
) as beat(moment_slug, slug, beat_ordinal, source_range, visual_direction)
join public.narrative_series series on series.slug = 'ramayana-dutt-consumer-v1'
join public.narrative_moments moment on moment.series_id = series.id and moment.slug = beat.moment_slug
on conflict (moment_id, slug) do update set
  beat_ordinal = excluded.beat_ordinal,
  source_range = excluded.source_range,
  visual_direction = excluded.visual_direction,
  rights_lane = excluded.rights_lane,
  publication_state = excluded.publication_state,
  updated_at = now();

insert into public.narrative_beat_texts (
  beat_id, language_code, title, narration, text_status,
  rights_lane, publication_state
)
select beat.id, copy.language_code, copy.title, copy.narration,
  'source_aligned', 'derivative_allowed', 'published'
from (values
  ('scene-valmiki-asks-for-complete-human', 'valmiki-sets-impossible-question', 'en', 'Can all these qualities live in one person?', 'Valmiki asks Narada for someone living in the world who joins courage with compassion, truth with self-control, learning with practical judgment, and power with concern for others. He is not asking for a flawless statue, but for a life whose choices can be followed.'),
  ('scene-valmiki-asks-for-complete-human', 'valmiki-sets-impossible-question', 'hi', 'क्या ये सभी गुण एक मनुष्य में मिल सकते हैं?', 'वाल्मीकि नारद से ऐसे जीवित मनुष्य के बारे में पूछते हैं जिसमें साहस के साथ करुणा, सत्य के साथ संयम, ज्ञान के साथ व्यवहार-बुद्धि और शक्ति के साथ सबके हित की चिंता हो। वे किसी निर्जीव आदर्श की नहीं, ऐसे जीवन की खोज कर रहे हैं जिसके निर्णयों का अनुसरण किया जा सके।'),
  ('scene-valmiki-asks-for-complete-human', 'narada-names-rama', 'en', 'Narada answers with one name', 'Narada considers the demanding list and names Rama of the Ikshvaku line. He describes a prince disciplined in speech and anger, formidable in danger, attentive to duty, and able to make people feel protected rather than merely ruled.'),
  ('scene-valmiki-asks-for-complete-human', 'narada-names-rama', 'hi', 'नारद एक नाम लेते हैं', 'नारद उस कठिन सूची पर विचार करके इक्ष्वाकु वंश के राम का नाम लेते हैं। वे ऐसे राजकुमार का परिचय देते हैं जो वाणी और क्रोध पर संयम रखता है, संकट में प्रबल है, कर्तव्य के प्रति सजग है और लोगों को केवल शासित नहीं बल्कि सुरक्षित अनुभव कराता है।'),
  ('scene-valmiki-asks-for-complete-human', 'a-crown-turns-into-exile', 'en', 'A promised crown becomes a forest road', 'Narada races ahead: Dasharatha prepares to install Rama, Kaikeyi claims her old boons, and Rama accepts fourteen years of exile. Sita and Lakshmana choose to go with him, turning a political rupture into a shared journey away from Ayodhya.'),
  ('scene-valmiki-asks-for-complete-human', 'a-crown-turns-into-exile', 'hi', 'राज्याभिषेक की सुबह वन की राह बन जाती है', 'नारद कथा को तेजी से आगे ले जाते हैं—दशरथ राम के राज्याभिषेक की तैयारी करते हैं, कैकेयी पुराने वरदान माँगती हैं और राम चौदह वर्ष का वनवास स्वीकार कर लेते हैं। सीता और लक्ष्मण साथ चलने का निर्णय लेते हैं; राजमहल का संकट अयोध्या से दूर एक साझा यात्रा बन जाता है।'),
  ('scene-valmiki-asks-for-complete-human', 'loss-creates-an-alliance', 'en', 'Sita is taken, and strangers become allies', 'The forest story breaks when Ravana abducts Sita and Jatayu falls trying to stop him. Rama and Lakshmana''s search reaches Sugriva and Hanuman; grief becomes alliance, and scattered clues begin pointing across the ocean toward Lanka.'),
  ('scene-valmiki-asks-for-complete-human', 'loss-creates-an-alliance', 'hi', 'सीता का हरण होता है और अजनबी साथी बनते हैं', 'वन की कथा तब टूटती है जब रावण सीता का हरण करता है और उसे रोकते हुए जटायु गिर पड़ते हैं। राम और लक्ष्मण की खोज सुग्रीव और हनुमान तक पहुँचती है; शोक मित्रता में बदलता है और बिखरे संकेत समुद्र पार लंका की ओर इशारा करने लगते हैं।'),
  ('scene-valmiki-asks-for-complete-human', 'narada-reaches-the-return', 'en', 'The whole life flashes to its return', 'Narada''s preview crosses Hanuman''s leap, the bridge, the war, Ravana''s fall, Sita''s recovery, and the return to Ayodhya. It ends with the selected source''s sacred vision of Rama''s reign, giving Valmiki the scale of the life he is about to tell rather than replacing the journey itself.'),
  ('scene-valmiki-asks-for-complete-human', 'narada-reaches-the-return', 'hi', 'पूरे जीवन की झलक वापसी तक पहुँचती है', 'नारद की झलक हनुमान की छलाँग, सेतु, युद्ध, रावण के पतन, सीता की पुनर्प्राप्ति और अयोध्या वापसी से होकर गुजरती है। वह चुने हुए स्रोत में राम-राज्य की पवित्र कल्पना पर ठहरती है—यह आने वाली यात्रा का स्थान नहीं लेती, बल्कि वाल्मीकि को उस जीवन का विस्तार दिखाती है जिसे वे कथा बनाएँगे।'),
  ('scene-grief-becomes-first-verse', 'tamasa-seems-clear', 'en', 'A river as clear as a good mind', 'After Narada leaves, Valmiki walks with his disciple Bharadwaja to the Tamasa. The clear water and mudless bank promise a calm place for bathing; the scene begins in careful attention to an ordinary, peaceful landscape.'),
  ('scene-grief-becomes-first-verse', 'tamasa-seems-clear', 'hi', 'सज्जन मन की तरह निर्मल नदी', 'नारद के जाने के बाद वाल्मीकि अपने शिष्य भरद्वाज के साथ तमसा नदी तक जाते हैं। निर्मल जल और कीचड़-रहित तट स्नान के लिए शांत स्थान का आभास देते हैं; दृश्य एक साधारण, शांत भू-दृश्य को ध्यान से देखने के साथ आरंभ होता है।'),
  ('scene-grief-becomes-first-verse', 'krauncha-pair-in-peace', 'en', 'Two birds move without fear', 'Near the water, Valmiki notices a pair of krauncha birds calling to one another and moving in complete ease. Their unguarded companionship gives the next instant its force: nothing in the scene has prepared them for violence.'),
  ('scene-grief-becomes-first-verse', 'krauncha-pair-in-peace', 'hi', 'दो पक्षी निश्चिंत होकर विचरते हैं', 'जल के पास वाल्मीकि क्रौंच पक्षियों के एक जोड़े को एक-दूसरे को पुकारते और निश्चिंत होकर विचरते देखते हैं। उनका सहज साथ अगले क्षण को और तीखा बना देता है—दृश्य में ऐसा कुछ नहीं था जो उन्हें हिंसा के लिए तैयार करता।'),
  ('scene-grief-becomes-first-verse', 'arrow-breaks-the-pair', 'en', 'An arrow tears the scene in two', 'A hunter shoots the male bird without any quarrel or threat. He falls bleeding before Valmiki, and the surviving bird''s cry turns the death from a distant act into a felt separation witnessed at close range.'),
  ('scene-grief-becomes-first-verse', 'arrow-breaks-the-pair', 'hi', 'एक बाण दृश्य को दो भागों में तोड़ देता है', 'एक शिकारी बिना किसी झगड़े या खतरे के नर पक्षी को मार देता है। वह वाल्मीकि के सामने रक्त से भीगा गिरता है और जीवित पक्षी का विलाप उस मृत्यु को दूर की घटना नहीं रहने देता; बिछोह सबके सामने अनुभव होने लगता है।'),
  ('scene-grief-becomes-first-verse', 'grief-finds-meter', 'en', 'Grief speaks in a rhythm of its own', 'Compassion and anger rise together in Valmiki. His rebuke to the hunter comes out in equal measured parts; only after speaking does he notice that grief has shaped itself into a repeatable verse, shoka becoming shloka in the story''s own explanation.'),
  ('scene-grief-becomes-first-verse', 'grief-finds-meter', 'hi', 'शोक अपनी लय में बोल उठता है', 'वाल्मीकि के भीतर करुणा और आक्रोश एक साथ उठते हैं। शिकारी के लिए निकली उनकी वाणी समान लयबद्ध भागों में ढल जाती है; बोलने के बाद उन्हें समझ आता है कि शोक ने स्वयं को दोहराए जा सकने वाले श्लोक का रूप दे दिया है।'),
  ('scene-grief-becomes-first-verse', 'brahma-gives-the-verse-a-road', 'en', 'Brahma turns one verse into a commission', 'Back at the hermitage, Valmiki cannot stop thinking about the needless killing. Brahma appears and tells him the metre did not arise in vain: he must use it to tell Rama''s whole story truthfully, including what he has not yet seen, so that the poem can travel through the world.'),
  ('scene-grief-becomes-first-verse', 'brahma-gives-the-verse-a-road', 'hi', 'ब्रह्मा एक श्लोक को पूरी कथा का दायित्व देते हैं', 'आश्रम लौटकर भी वाल्मीकि उस निरर्थक हत्या को भूल नहीं पाते। ब्रह्मा प्रकट होकर कहते हैं कि वह छंद व्यर्थ नहीं आया—उसी में राम की पूरी कथा सत्यपूर्वक कही जाए, यहाँ तक कि वह भी जो अभी वाल्मीकि ने नहीं देखा, ताकि यह कथा संसार में यात्रा कर सके।'),
  ('scene-valmiki-sees-the-whole-life', 'valmiki-enters-contemplation', 'en', 'The storyteller becomes a witness', 'Valmiki sits facing east, steadies himself, and turns from Narada''s summary toward sustained contemplation. The story presents this as a change in access: he is no longer arranging hearsay but watching people speak, move, choose, and endure as if they were before him.'),
  ('scene-valmiki-sees-the-whole-life', 'valmiki-enters-contemplation', 'hi', 'कथाकार साक्षी बनता है', 'वाल्मीकि पूर्व की ओर बैठकर स्वयं को स्थिर करते हैं और नारद की संक्षिप्त रूपरेखा से गहरे ध्यान की ओर बढ़ते हैं। कथा इसे दृष्टि के परिवर्तन की तरह दिखाती है—अब वे सुनी-सुनाई बातों को नहीं जोड़ रहे, बल्कि लोगों को अपने सामने बोलते, चलते, चुनते और सहते देख रहे हैं।'),
  ('scene-valmiki-sees-the-whole-life', 'household-appears-in-motion', 'en', 'A family appears before it breaks', 'He sees Rama, Sita, Lakshmana, Dasharatha, and the queens not as names in a list but laughing, speaking, and acting inside their household. That ordinary movement matters because exile will soon separate the same people and transform every familiar room.'),
  ('scene-valmiki-sees-the-whole-life', 'household-appears-in-motion', 'hi', 'टूटने से पहले पूरा परिवार दिखाई देता है', 'वे राम, सीता, लक्ष्मण, दशरथ और रानियों को नामों की सूची की तरह नहीं, बल्कि परिवार में हँसते, बोलते और काम करते देखते हैं। यह सामान्य जीवन इसलिए महत्त्वपूर्ण है क्योंकि वनवास शीघ्र ही इन्हीं लोगों को अलग करेगा और हर परिचित कक्ष का अर्थ बदल देगा।'),
  ('scene-valmiki-sees-the-whole-life', 'the-road-opens-in-every-direction', 'en', 'The whole journey becomes visible', 'Birth, marriage, the broken bow, the lost coronation, exile, forest encounters, Sita''s abduction, the alliance with Sugriva, Hanuman''s search, and the war in Lanka unfold as connected consequences. Valmiki sees not only milestones but the conversations and grief that move people between them.'),
  ('scene-valmiki-sees-the-whole-life', 'the-road-opens-in-every-direction', 'hi', 'पूरी यात्रा एक साथ दिखाई देने लगती है', 'जन्म, विवाह, धनुष-भंग, रुका हुआ राज्याभिषेक, वनवास, वन के प्रसंग, सीता-हरण, सुग्रीव से मित्रता, हनुमान की खोज और लंका का युद्ध जुड़े हुए परिणामों की तरह खुलते हैं। वाल्मीकि केवल पड़ाव नहीं, उन संवादों और दुःखों को भी देखते हैं जो लोगों को एक पड़ाव से दूसरे तक ले जाते हैं।'),
  ('scene-valmiki-sees-the-whole-life', 'future-enters-the-composition', 'en', 'The ending is not hidden from the poet', 'The vision reaches the return, installation, and events the selected telling places later, including Sita''s eventual separation. Holding past and future together, Valmiki begins composing a story large enough for triumph, doubt, tenderness, violence, and unresolved pain.'),
  ('scene-valmiki-sees-the-whole-life', 'future-enters-the-composition', 'hi', 'कवि से आगे का अंत भी छिपा नहीं रहता', 'दृष्टि वापसी, राज्याभिषेक और चुनी हुई कथा में आगे आने वाली घटनाओं तक पहुँचती है, जिनमें सीता का बाद का वियोग भी शामिल है। अतीत और भविष्य को साथ रखकर वाल्मीकि ऐसी कथा रचना आरंभ करते हैं जिसमें विजय, संदेह, स्नेह, हिंसा और अधूरा दुःख सबके लिए स्थान हो।'),
  ('scene-lava-kusha-carry-the-story', 'valmiki-needs-voices', 'en', 'A story is unfinished until someone can carry it', 'After composing the Ramayana, Valmiki asks a practical question: who can bring so vast a work before real audiences? Lava and Kusha arrive at the hermitage with strong memories, musical ability, disciplined study, and the patience to learn meaning rather than merely recite sound.'),
  ('scene-lava-kusha-carry-the-story', 'valmiki-needs-voices', 'hi', 'कथा तब तक अधूरी है जब तक कोई उसे आगे न ले जाए', 'रामायण की रचना के बाद वाल्मीकि एक व्यावहारिक प्रश्न पूछते हैं—इतनी विशाल कथा को वास्तविक श्रोताओं तक कौन ले जाएगा? लव और कुश आश्रम में ऐसी स्मृति, संगीत-कौशल, अनुशासन और धैर्य के साथ आते हैं जो उन्हें केवल ध्वनि नहीं, अर्थ सीखने योग्य बनाता है।'),
  ('scene-lava-kusha-carry-the-story', 'story-learns-music-and-feeling', 'en', 'The epic learns how to move an audience', 'The brothers learn melody, measure, expression, movement, and the changing emotional colours of love, grief, humour, anger, fear, and courage. Performance is not decoration here; it is the technology that makes thousands of connected events graspable and memorable.'),
  ('scene-lava-kusha-carry-the-story', 'story-learns-music-and-feeling', 'hi', 'महाकाव्य श्रोताओं के मन तक पहुँचना सीखता है', 'दोनों भाई स्वर, ताल, अभिव्यक्ति, गति और प्रेम, शोक, हास्य, क्रोध, भय तथा वीरता के बदलते भाव सीखते हैं। यहाँ प्रस्तुति सजावट नहीं है; वही साधन है जो हजारों जुड़ी घटनाओं को समझने और याद रखने योग्य बनाता है।'),
  ('scene-lava-kusha-carry-the-story', 'hermitages-become-first-audiences', 'en', 'The first listeners know they have heard something vast', 'Lava and Kusha sing before gatherings of sages. Listeners are moved, praise the clarity and beauty of the telling, and offer the young performers the simple possessions available in hermitage life. The gifts show a story already travelling through relationship, not through royal command.'),
  ('scene-lava-kusha-carry-the-story', 'hermitages-become-first-audiences', 'hi', 'पहले श्रोता समझते हैं कि उन्होंने कुछ विशाल सुना है', 'लव और कुश ऋषियों की सभाओं में गाते हैं। श्रोता कथा की स्पष्टता और सौंदर्य से प्रभावित होकर उनकी प्रशंसा करते हैं और आश्रम-जीवन में उपलब्ध साधारण वस्तुएँ भेंट देते हैं। ये उपहार दिखाते हैं कि कथा राजाज्ञा से नहीं, मानवीय संबंधों के सहारे यात्रा करने लगी है।'),
  ('scene-lava-kusha-carry-the-story', 'rama-hears-his-own-life', 'en', 'The song reaches the person inside it', 'In Ayodhya, Rama notices the two ascetic-looking singers and brings them before his brothers and counsellors. As they begin, the court is captivated and Rama recognises signs of royalty in them; the epic''s frame closes on a startling encounter between a life, its retelling, and the people who do not yet understand every bond joining them.'),
  ('scene-lava-kusha-carry-the-story', 'rama-hears-his-own-life', 'hi', 'गीत उस व्यक्ति तक पहुँचता है जिसकी यह कथा है', 'अयोध्या में राम इन तपस्वी-वेशधारी गायकों को देखते हैं और उन्हें भाइयों तथा मंत्रियों की सभा में बुलाते हैं। गीत आरंभ होते ही दरबार मंत्रमुग्ध हो जाता है और राम उनमें राजवंश के संकेत पहचानते हैं; कथा का आरंभ एक विचित्र मिलन पर ठहरता है—जीवन, उसकी पुनर्कथा और वे लोग, जो अभी उन्हें जोड़ने वाले सभी संबंध नहीं जानते।'),
  ('scene-coronation-dawn', 'dasharatha-names-heir', 'en', 'Dasharatha names the future', 'Dasharatha tells the gathered rulers and elders that age weighs on him and proposes Rama as heir. The assembly answers with unmistakable approval.'),
  ('scene-coronation-dawn', 'dasharatha-names-heir', 'hi', 'दशरथ भविष्य की घोषणा करते हैं', 'दशरथ राजाओं और सभासदों से कहते हैं कि आयु का भार बढ़ रहा है और राम को युवराज बनाने का प्रस्ताव रखते हैं। सभा स्पष्ट सहमति देती है।'),
  ('scene-coronation-dawn', 'city-prepares-coronation', 'en', 'Ayodhya moves at once', 'Orders spread through streets, storehouses, kitchens, gateways, and shrines. Water, garlands, music, banners, food, and ceremonial objects gather for the morning.'),
  ('scene-coronation-dawn', 'city-prepares-coronation', 'hi', 'अयोध्या तुरंत जुट जाती है', 'आदेश गलियों, भंडारों, रसोइयों, द्वारों और पूजा-स्थलों तक फैलते हैं। जल, मालाएँ, संगीत, ध्वज, भोजन और अभिषेक-सामग्री भोर के लिए जुटती है।'),
  ('scene-coronation-dawn', 'rama-sita-keep-vigil', 'en', 'Rama and Sita keep vigil', 'Rama receives the instructions without triumph. He and Sita fast, pray, and lie on a simple bed of kusa grass while the palace stays awake around them.'),
  ('scene-coronation-dawn', 'rama-sita-keep-vigil', 'hi', 'राम और सीता रात्रि-व्रत रखते हैं', 'राम आदेश को विजय-भाव से नहीं लेते। वे और सीता उपवास, प्रार्थना और कुश की साधारण शय्या पर रात्रि बिताते हैं, जबकि महल जागता रहता है।'),
  ('scene-coronation-dawn', 'city-waits-for-dawn', 'en', 'The city waits for dawn', 'People speak of Rama''s expected rule and wait for morning. The celebration feels settled; that confidence is what the coming turn will break.'),
  ('scene-coronation-dawn', 'city-waits-for-dawn', 'hi', 'नगर भोर की प्रतीक्षा करता है', 'लोग राम के भावी शासन की चर्चा करते हुए सुबह की प्रतीक्षा करते हैं। उत्सव निश्चित लगता है—अगला मोड़ इसी विश्वास को तोड़ेगा।'),
  ('scene-manthara-sees-city', 'manthara-sees-rooftops', 'en', 'A decorated city below', 'From the palace height, Manthara sees watered streets, banners, garlands, and crowds in festive dress. She asks what has made Ayodhya radiant.'),
  ('scene-manthara-sees-city', 'manthara-sees-rooftops', 'hi', 'नीचे सजा हुआ नगर', 'महल की ऊँचाई से मंथरा धुली सड़कें, ध्वज, मालाएँ और उत्सव-वस्त्रों में भीड़ देखती है। वह पूछती है कि अयोध्या किस कारण चमक रही है।'),
  ('scene-manthara-sees-city', 'news-reaches-manthara', 'en', 'The answer changes her face', 'She learns that Rama will be installed the next morning. What others receive as good news, she immediately reads as a threat to Kaikeyi and Bharata.'),
  ('scene-manthara-sees-city', 'news-reaches-manthara', 'hi', 'उत्तर सुनते ही भाव बदलते हैं', 'उसे पता चलता है कि अगली सुबह राम का राज्याभिषेक होगा। जिसे सब शुभ समाचार मानते हैं, वह उसे कैकेयी और भरत के लिए संकट समझती है।'),
  ('scene-manthara-sees-city', 'kaikeyi-first-rejoices', 'en', 'Kaikeyi first rejoices', 'Kaikeyi does not begin in anger. She delights in the news, praises Rama, and gives Manthara an ornament—an important beginning before persuasion changes her.'),
  ('scene-manthara-sees-city', 'kaikeyi-first-rejoices', 'hi', 'कैकेयी पहले प्रसन्न होती हैं', 'कैकेयी आरंभ में क्रोधित नहीं होतीं। वे समाचार से प्रसन्न होकर राम की प्रशंसा करती हैं और मंथरा को आभूषण देती हैं—तर्क से बदलने से पहले यही उनका शुरुआती भाव है।'),
  ('scene-manthara-sees-city', 'gift-is-thrown-aside', 'en', 'The gift is thrown aside', 'Manthara rejects the gift and insists Kaikeyi is celebrating her own loss. The room changes from congratulations into an argument about power and security.'),
  ('scene-manthara-sees-city', 'gift-is-thrown-aside', 'hi', 'उपहार फेंक दिया जाता है', 'मंथरा उपहार अस्वीकार कर कहती है कि कैकेयी अपनी ही हानि का उत्सव मना रही हैं। कक्ष में बधाई की जगह सत्ता और सुरक्षा की बहस शुरू होती है।'),
  ('scene-fear-becomes-demands', 'manthara-reframes-future', 'en', 'The future is reframed as danger', 'Manthara argues that Rama''s rise will diminish Bharata and Kaikeyi. She turns affection, succession, and household rank into a chain of imagined danger.'),
  ('scene-fear-becomes-demands', 'manthara-reframes-future', 'hi', 'भविष्य को संकट की तरह दिखाया जाता है', 'मंथरा तर्क देती है कि राम का उदय भरत और कैकेयी को पीछे कर देगा। वह स्नेह, उत्तराधिकार और परिवार की स्थिति को आशंकाओं की शृंखला बना देती है।'),
  ('scene-fear-becomes-demands', 'kaikeyi-enters-anger-room', 'en', 'Kaikeyi enters the chamber of anger', 'Persuaded, Kaikeyi removes her ornaments, puts on soiled clothing, and lies on the floor so Dasharatha will find a visible crisis.'),
  ('scene-fear-becomes-demands', 'kaikeyi-enters-anger-room', 'hi', 'कैकेयी कोपभवन में जाती हैं', 'प्रभावित होकर कैकेयी आभूषण उतारती हैं, मलिन वस्त्र पहनती हैं और भूमि पर लेट जाती हैं ताकि दशरथ के सामने संकट स्पष्ट दिखाई दे।'),
  ('scene-fear-becomes-demands', 'dasharatha-renews-promise', 'en', 'Dasharatha promises before hearing', 'Alarmed by her condition, Dasharatha asks what she wants and repeatedly promises to fulfil it. Kaikeyi makes the promise public in the presence of invoked witnesses.'),
  ('scene-fear-becomes-demands', 'dasharatha-renews-promise', 'hi', 'दशरथ सुनने से पहले वचन देते हैं', 'कैकेयी की दशा देखकर दशरथ पूछते हैं कि वे क्या चाहती हैं और बार-बार उसे पूरा करने का वचन देते हैं। कैकेयी साक्षियों का आह्वान करके उस वचन को सार्वजनिक बनाती हैं।'),
  ('scene-fear-becomes-demands', 'first-demand-bharata', 'en', 'The first demand: Bharata', 'Kaikeyi calls in the boons Dasharatha once granted and demands that the prepared coronation install Bharata instead of Rama.'),
  ('scene-fear-becomes-demands', 'first-demand-bharata', 'hi', 'पहली माँग: भरत', 'कैकेयी दशरथ द्वारा दिए पुराने वरदान माँगती हैं और तैयार राज्याभिषेक में राम के स्थान पर भरत को स्थापित करने की माँग रखती हैं।'),
  ('scene-fear-becomes-demands', 'second-demand-fourteen-years', 'en', 'The second demand: fourteen years', 'The second demand removes Rama from the kingdom for fourteen years in forest dress. It is not merely a changed ceremony; it is the beginning of the epic road.'),
  ('scene-fear-becomes-demands', 'second-demand-fourteen-years', 'hi', 'दूसरी माँग: चौदह वर्ष', 'दूसरी माँग राम को वन-वस्त्र में चौदह वर्ष के लिए राज्य से दूर भेजती है। यह केवल बदला हुआ समारोह नहीं, महाकाव्य की यात्रा का आरंभ है।'),
  ('scene-king-trapped-by-word', 'dasharatha-collapses', 'en', 'The demand lands', 'Dasharatha falls senseless, recovers, and hopes he has heard a nightmare. Kaikeyi repeats the demands without softening them.'),
  ('scene-king-trapped-by-word', 'dasharatha-collapses', 'hi', 'माँग का आघात', 'दशरथ मूर्छित होकर गिरते हैं, संभलते हैं और आशा करते हैं कि यह दुःस्वप्न हो। कैकेयी बिना नरमी के माँगें दोहराती हैं।'),
  ('scene-king-trapped-by-word', 'king-pleads-through-night', 'en', 'A king pleads through the night', 'He appeals to love, reputation, family, and mercy. He offers wealth and power, but cannot make Kaikeyi release the promise.'),
  ('scene-king-trapped-by-word', 'king-pleads-through-night', 'hi', 'राजा पूरी रात विनती करते हैं', 'वे प्रेम, प्रतिष्ठा, परिवार और दया की दुहाई देते हैं। धन और सत्ता देने को तैयार होते हैं, पर कैकेयी वचन छोड़ने को नहीं मानतीं।'),
  ('scene-king-trapped-by-word', 'kaikeyi-invokes-truth', 'en', 'Kaikeyi invokes the king''s truth', 'Kaikeyi says a king celebrated for truth cannot withdraw when the cost becomes painful. The language of honour becomes the lock on the chamber.'),
  ('scene-king-trapped-by-word', 'kaikeyi-invokes-truth', 'hi', 'कैकेयी राजा के सत्य का आह्वान करती हैं', 'कैकेयी कहती हैं कि सत्य के लिए प्रसिद्ध राजा कठिन मूल्य देखकर पीछे नहीं हट सकता। सम्मान की भाषा ही कक्ष का ताला बन जाती है।'),
  ('scene-king-trapped-by-word', 'morning-waits-outside', 'en', 'Morning waits outside', 'Priests, citizens, music, and the objects of installation gather outside. Inside, Dasharatha can no longer speak the future everyone has come to celebrate.'),
  ('scene-king-trapped-by-word', 'morning-waits-outside', 'hi', 'सुबह बाहर प्रतीक्षा करती है', 'पुरोहित, नागरिक, संगीत और अभिषेक-सामग्री बाहर जुटते हैं। भीतर दशरथ उस भविष्य का नाम भी नहीं ले पाते जिसके उत्सव में सब आए हैं।'),
  ('scene-rama-crosses-celebration', 'vasishta-finds-delay', 'en', 'The ceremony is ready; the king is absent', 'Vasishta sends Sumantra to bring the king. The messenger finds Dasharatha broken and Kaikeyi directing what happens next.'),
  ('scene-rama-crosses-celebration', 'vasishta-finds-delay', 'hi', 'समारोह तैयार है, राजा नहीं', 'वसिष्ठ सुमंत्र को राजा बुलाने भेजते हैं। वे दशरथ को टूटा हुआ और आगे की दिशा तय करती कैकेयी को पाते हैं।'),
  ('scene-rama-crosses-celebration', 'sumantra-summons-rama', 'en', 'Rama is summoned', 'Kaikeyi tells Sumantra to bring Rama. Nothing in the public streets reveals that the summons is no longer for installation.'),
  ('scene-rama-crosses-celebration', 'sumantra-summons-rama', 'hi', 'राम को बुलाया जाता है', 'कैकेयी सुमंत्र से राम को बुलाने कहती हैं। सार्वजनिक गलियों में कुछ भी नहीं बताता कि बुलावा अब राज्याभिषेक के लिए नहीं है।'),
  ('scene-rama-crosses-celebration', 'rama-crosses-festival-city', 'en', 'Through a city saying his name', 'Rama crosses watered roads, raised standards, musicians, and citizens expecting to see him crowned. He answers their affection without knowing how soon he will leave them.'),
  ('scene-rama-crosses-celebration', 'rama-crosses-festival-city', 'hi', 'नाम पुकारते नगर के बीच', 'राम धुली सड़कों, ध्वजों, संगीत और राज्याभिषेक की प्रतीक्षा करती जनता के बीच से गुजरते हैं। वे स्नेह का उत्तर देते हैं, बिना जाने कि शीघ्र ही विदा होंगे।'),
  ('scene-rama-crosses-celebration', 'kaikeyi-speaks-demand', 'en', 'The silent father; the spoken demand', 'Rama finds Dasharatha unable to answer him. Kaikeyi says the king is bound by shame and then tells Rama the two demands directly.'),
  ('scene-rama-crosses-celebration', 'kaikeyi-speaks-demand', 'hi', 'मौन पिता, बोली गई माँग', 'राम दशरथ को उत्तर देने में असमर्थ पाते हैं। कैकेयी कहती हैं कि राजा संकोच से बँधे हैं और फिर दोनों माँगें सीधे राम को बताती हैं।'),
  ('scene-rama-accepts-exile', 'rama-says-he-will-go', 'en', 'Rama answers without bargaining', 'Rama says Bharata may receive the kingdom and that he will enter the forest that very day. He asks only why his father could not tell him himself.'),
  ('scene-rama-accepts-exile', 'rama-says-he-will-go', 'hi', 'राम बिना सौदे के उत्तर देते हैं', 'राम कहते हैं कि भरत राज्य लें और वे उसी दिन वन चले जाएँगे। वे केवल पूछते हैं कि पिता स्वयं यह बात क्यों नहीं कह सके।'),
  ('scene-rama-accepts-exile', 'rama-goes-to-kausalya', 'en', 'Celebration still surrounds Kausalya', 'Rama reaches Kausalya while attendants and ritual preparations still anticipate his installation. He tells her that the seat prepared for him must be exchanged for forest ground.'),
  ('scene-rama-accepts-exile', 'rama-goes-to-kausalya', 'hi', 'कौसल्या के चारों ओर अभी भी उत्सव है', 'राम कौसल्या के पास पहुँचते हैं, जहाँ सेवक और अनुष्ठान अभी भी राज्याभिषेक की प्रतीक्षा में हैं। वे बताते हैं कि उनके लिए तैयार आसन अब वन-भूमि से बदल जाएगा।'),
  ('scene-rama-accepts-exile', 'kausalya-grief-and-choice', 'en', 'Kausalya''s grief is not hurried past', 'Kausalya collapses, mourns the years of waiting, and says she would follow him. The story stays with the human cost before it turns to argument about duty.'),
  ('scene-rama-accepts-exile', 'kausalya-grief-and-choice', 'hi', 'कौसल्या के शोक को जल्दी नहीं टाला जाता', 'कौसल्या गिर पड़ती हैं, वर्षों की प्रतीक्षा का शोक करती हैं और साथ चलने की बात कहती हैं। कथा कर्तव्य की बहस से पहले मानवीय पीड़ा पर ठहरती है।'),
  ('scene-rama-accepts-exile', 'lakshmana-urges-resistance', 'en', 'Lakshmana urges resistance', 'Lakshmana calls the command unjust and offers force, defence, and the support of those loyal to Rama. His anger gives voice to the refusal others cannot articulate.'),
  ('scene-rama-accepts-exile', 'lakshmana-urges-resistance', 'hi', 'लक्ष्मण प्रतिरोध की बात करते हैं', 'लक्ष्मण आदेश को अन्यायपूर्ण कहते हैं और बल, रक्षा तथा राम-समर्थकों का सहारा देने की बात करते हैं। उनका क्रोध उस अस्वीकार को स्वर देता है जिसे दूसरे कह नहीं पाते।'),
  ('scene-rama-accepts-exile', 'rama-turns-anger-to-preparation', 'en', 'Rama turns anger toward preparation', 'Rama refuses to seize the kingdom or make his father''s word the cause of civil conflict. He asks Lakshmana to help dismantle the ceremony and prepare for departure.'),
  ('scene-rama-accepts-exile', 'rama-turns-anger-to-preparation', 'hi', 'राम क्रोध को तैयारी में बदलते हैं', 'राम राज्य छीनने या पिता के वचन को गृह-संघर्ष का कारण बनाने से इंकार करते हैं। वे लक्ष्मण से समारोह समेटकर प्रस्थान की तैयारी में सहायता माँगते हैं।'),
  ('scene-sita-chooses-road', 'sita-sees-changed-face', 'en', 'Sita sees what the city cannot', 'Sita has prepared for coronation and asks why Rama returns without royal signs, music, or attendants. His face tells her the public celebration is already false.'),
  ('scene-sita-chooses-road', 'sita-sees-changed-face', 'hi', 'सीता वह देखती हैं जो नगर नहीं देखता', 'सीता राज्याभिषेक की तैयारी में हैं और पूछती हैं कि राम राजचिह्न, संगीत और सेवकों के बिना क्यों लौटे। उनका चेहरा बता देता है कि बाहर का उत्सव अब सच नहीं रहा।'),
  ('scene-sita-chooses-road', 'rama-asks-sita-stay', 'en', 'Rama asks her to remain', 'Rama explains the command and initially asks Sita to stay in Ayodhya, honour the elders, and live carefully while he is away.'),
  ('scene-sita-chooses-road', 'rama-asks-sita-stay', 'hi', 'राम उन्हें रुकने को कहते हैं', 'राम आदेश बताते हैं और पहले सीता से अयोध्या में रहकर बड़ों का सम्मान करने तथा उनके लौटने तक सावधानी से जीवन बिताने को कहते हैं।'),
  ('scene-sita-chooses-road', 'sita-claims-shared-fortune', 'en', 'Sita claims a shared fortune', 'Sita answers that marriage does not divide hardship into his and hers. She rejects the idea that the palace can be her proper world while his road lies elsewhere.'),
  ('scene-sita-chooses-road', 'sita-claims-shared-fortune', 'hi', 'सीता साझा भाग्य का दावा करती हैं', 'सीता कहती हैं कि विवाह कठिनाई को तुम्हारी और मेरी हिस्सेदारी में नहीं बाँटता। वे इस विचार को अस्वीकार करती हैं कि उनका संसार महल हो और राम की राह कहीं और।'),
  ('scene-sita-chooses-road', 'forest-fears-are-named', 'en', 'The forest fears are named', 'Rama names rough ground, hunger, animals, weather, and hardship. Sita answers each warning not with ignorance, but with a repeated, deliberate choice to accompany him.'),
  ('scene-sita-chooses-road', 'forest-fears-are-named', 'hi', 'वन के भय स्पष्ट किए जाते हैं', 'राम कठिन भूमि, भूख, वन्य जीव, मौसम और कष्ट गिनाते हैं। सीता अज्ञान से नहीं, हर चेतावनी के बाद सोच-समझकर साथ चलने का निर्णय दोहराती हैं।'),
  ('scene-sita-chooses-road', 'rama-accepts-sita-choice', 'en', 'Rama accepts her choice', 'After the long exchange, Rama stops trying to leave her behind. They begin giving possessions away and preparing to enter the forest together.'),
  ('scene-sita-chooses-road', 'rama-accepts-sita-choice', 'hi', 'राम सीता का निर्णय स्वीकार करते हैं', 'लंबे संवाद के बाद राम उन्हें पीछे छोड़ने का प्रयास रोकते हैं। दोनों वस्तुएँ दान देकर साथ वन जाने की तैयारी करते हैं।'),
  ('scene-lakshmana-joins', 'lakshmana-asks-to-come', 'en', 'Lakshmana asks for the road', 'Lakshmana says he will walk before Rama and Sita, gather food, guard the path, and make the forest journey his own duty.'),
  ('scene-lakshmana-joins', 'lakshmana-asks-to-come', 'hi', 'लक्ष्मण साथ चलने की अनुमति माँगते हैं', 'लक्ष्मण कहते हैं कि वे राम और सीता के आगे चलेंगे, भोजन जुटाएँगे, मार्ग की रक्षा करेंगे और वन-यात्रा को अपना दायित्व बनाएँगे।'),
  ('scene-lakshmana-joins', 'weapons-and-gifts-prepared', 'en', 'Preparation replaces ceremony', 'Rama sends Lakshmana for the bows and protective equipment entrusted to the household. At the same time, wealth and belongings are distributed rather than carried into exile.'),
  ('scene-lakshmana-joins', 'weapons-and-gifts-prepared', 'hi', 'समारोह की जगह यात्रा-तैयारी', 'राम लक्ष्मण को परिवार के पास सुरक्षित धनुष और रक्षा-सामग्री लाने भेजते हैं। साथ ही धन और वस्तुएँ वन ले जाने के बजाय बाँटी जाती हैं।'),
  ('scene-lakshmana-joins', 'bark-garments-arrive', 'en', 'Bark garments replace royal dress', 'Kaikeyi brings forest garments. Rama and Lakshmana change; Sita''s discomfort and the elders'' protest are not treated as a ritual instruction or a triumphant spectacle.'),
  ('scene-lakshmana-joins', 'bark-garments-arrive', 'hi', 'राजवस्त्रों की जगह वल्कल आते हैं', 'कैकेयी वन-वस्त्र लाती हैं। राम और लक्ष्मण बदलते हैं; सीता की असुविधा और बड़ों के विरोध को न अनुष्ठान-निर्देश बनाया जाता है, न विजय-दृश्य।'),
  ('scene-lakshmana-joins', 'farewell-to-mothers', 'en', 'Farewell moves through the family', 'The three seek blessings from parents and mothers amid grief, counsel, argument, and embraces. Departure is a household rupture before it becomes adventure.'),
  ('scene-lakshmana-joins', 'farewell-to-mothers', 'hi', 'विदाई पूरे परिवार से गुजरती है', 'तीनों शोक, सलाह, तर्क और आलिंगन के बीच माता-पिता और माताओं से आशीर्वाद लेते हैं। प्रस्थान रोमांच बनने से पहले परिवार का टूटना है।'),
  ('scene-lakshmana-joins', 'three-turn-toward-gate', 'en', 'Three turn toward the gate', 'Rama, Sita, and Lakshmana stand ready together. The city is still dressed for coronation, but the next movement is toward the gate and the forest beyond.'),
  ('scene-lakshmana-joins', 'three-turn-toward-gate', 'hi', 'तीनों द्वार की ओर मुड़ते हैं', 'राम, सीता और लक्ष्मण साथ खड़े हैं। नगर अभी भी राज्याभिषेक के लिए सजा है, पर अगला कदम द्वार और उसके पार वन की ओर है।'),
  ('scene-city-follows-car', 'inner-rooms-erupt', 'en', 'The inner rooms erupt', 'As the car leaves, voices rise through the royal apartments. The people who depended on Rama ask where their refuge is going; private loss spills into the city.'),
  ('scene-city-follows-car', 'inner-rooms-erupt', 'hi', 'अंतःपुर में विलाप उठता है', 'रथ निकलते ही राजमहल के अंतःपुर में स्वर उठते हैं। राम पर निर्भर लोग पूछते हैं कि उनका सहारा कहाँ जा रहा है; निजी हानि पूरे नगर में फैल जाती है।'),
  ('scene-city-follows-car', 'dasharatha-watches-dust', 'en', 'Dasharatha watches the dust', 'Dasharatha keeps his eyes on the departing car until even its dust disappears. Only then does his body give way and Kausalya helps raise him from the road.'),
  ('scene-city-follows-car', 'dasharatha-watches-dust', 'hi', 'दशरथ धूल को देखते रहते हैं', 'दशरथ जाते रथ को तब तक देखते हैं जब तक उसकी धूल भी ओझल नहीं हो जाती। तभी उनका शरीर जवाब देता है और कौसल्या उन्हें मार्ग से उठाती हैं।'),
  ('scene-city-follows-car', 'kausalya-imagines-road', 'en', 'Kausalya imagines the road', 'Inside the darkened palace, Kausalya imagines the three without familiar beds, food, or shelter. Her grief stretches ahead to the day Ayodhya might see them return.'),
  ('scene-city-follows-car', 'kausalya-imagines-road', 'hi', 'कौसल्या आगे की राह कल्पना करती हैं', 'अँधेरे महल में कौसल्या तीनों को परिचित शय्या, भोजन और आश्रय के बिना सोचती हैं। उनका शोक उस दिन तक फैलता है जब अयोध्या उन्हें लौटते देख सकेगी।'),
  ('scene-city-follows-car', 'sumitra-holds-return', 'en', 'Sumitra keeps return imaginable', 'Sumitra does not erase the pain. She reminds Kausalya that Lakshmana and Sita chose to accompany Rama and insists that the road can still end in return.'),
  ('scene-city-follows-car', 'sumitra-holds-return', 'hi', 'सुमित्रा वापसी की आशा थामती हैं', 'सुमित्रा पीड़ा को नकारती नहीं हैं। वे कौसल्या को याद दिलाती हैं कि लक्ष्मण और सीता ने राम का साथ चुना है और यह राह वापसी पर भी समाप्त हो सकती है।'),
  ('scene-city-follows-car', 'citizens-take-road', 'en', 'The citizens take the road', 'Citizens follow on foot and ask the horses to stop. Rama leaves the car to walk beside elders who cannot keep pace, and darkness finds the crowd still following.'),
  ('scene-city-follows-car', 'citizens-take-road', 'hi', 'नगरवासी भी राह पकड़ते हैं', 'नगरवासी पैदल पीछे चलते हैं और घोड़ों से रुकने की विनती करते हैं। राम धीमे चल रहे बुज़ुर्गों के साथ पैदल हो जाते हैं, और अँधेरा भीड़ को अब भी मार्ग पर पाता है।'),
  ('scene-tamasa-night', 'first-night-named', 'en', 'Rama names the first night', 'At the Tamasa, Rama calls this the first night of exile. He speaks of the parents and city behind them while the forest answers with birds and animals settling into darkness.'),
  ('scene-tamasa-night', 'first-night-named', 'hi', 'राम पहली रात को पहचानते हैं', 'तमसा के तट पर राम इसे वनवास की पहली रात कहते हैं। वे पीछे छूटे माता-पिता और नगर की बात करते हैं, जबकि वन पक्षियों और पशुओं के रात्रि-स्वरों से उत्तर देता है।'),
  ('scene-tamasa-night', 'city-sleeps-under-trees', 'en', 'Ayodhya sleeps beneath trees', 'The citizens who followed lie exhausted nearby. Their determination has carried a piece of Ayodhya into the open country, but fatigue finally closes their eyes.'),
  ('scene-tamasa-night', 'city-sleeps-under-trees', 'hi', 'अयोध्या वृक्षों के नीचे सोती है', 'पीछे आए नगरवासी पास ही थककर लेट जाते हैं। उनका संकल्प अयोध्या का एक अंश खुले प्रदेश तक ले आया है, पर थकान अंततः उनकी आँखें बंद कर देती है।'),
  ('scene-tamasa-night', 'leave-before-dawn', 'en', 'Compassion requires leaving', 'Rama says a ruler should not let citizens destroy themselves for his hardship. He chooses to leave while they sleep rather than keep rewarding their refusal to turn home.'),
  ('scene-tamasa-night', 'leave-before-dawn', 'hi', 'करुणा अब चले जाने को कहती है', 'राम कहते हैं कि शासक को अपनी कठिनाई के कारण प्रजा को स्वयं कष्ट में नहीं डालना चाहिए। वे उनके जागने से पहले निकलना चुनते हैं, ताकि उनका लौटने से इंकार बढ़े नहीं।'),
  ('scene-tamasa-night', 'tracks-turn-north', 'en', 'The tracks tell the wrong story', 'Sumantra first drives north, then turns and takes the forest road so the trail cannot be followed. The chariot crosses the Tamasa before dawn fully arrives.'),
  ('scene-tamasa-night', 'tracks-turn-north', 'hi', 'रथचिह्न दूसरी कहानी कहते हैं', 'सुमंत्र पहले रथ उत्तर की ओर ले जाते हैं, फिर मोड़कर वनमार्ग पकड़ते हैं ताकि चिह्नों का पीछा न हो सके। पूर्ण भोर से पहले रथ तमसा पार कर जाता है।'),
  ('scene-tamasa-night', 'citizens-wake-to-absence', 'en', 'The citizens wake to absence', 'At sunrise the followers find no car and lose its track. Their return to Ayodhya is not defeat in one line: homes, markets, kitchens, music, and ordinary recognition all fall silent.'),
  ('scene-tamasa-night', 'citizens-wake-to-absence', 'hi', 'नगरवासी रिक्तता में जागते हैं', 'सूर्योदय पर अनुयायियों को रथ नहीं मिलता और उसके चिह्न खो जाते हैं। उनकी अयोध्या-वापसी एक पंक्ति की हार नहीं—घर, बाज़ार, रसोई, संगीत और रोज़मर्रा की पहचान सब मौन हो जाते हैं।'),
  ('scene-roads-beyond-kosala', 'villages-speak-aloud', 'en', 'The villages speak aloud', 'Passing ploughed fields and flowering woods, the travellers hear villagers condemn the decision that sent them away. The political rupture travels faster than the car.'),
  ('scene-roads-beyond-kosala', 'villages-speak-aloud', 'hi', 'गाँव खुलकर बोलते हैं', 'जुते खेतों और फूलते वनों से गुजरते हुए यात्री गाँववालों को उस निर्णय की निंदा करते सुनते हैं जिसने उन्हें भेजा। राजनीतिक टूटन रथ से भी तेज़ फैलती है।'),
  ('scene-roads-beyond-kosala', 'rivers-mark-distance', 'en', 'Rivers measure the distance', 'The Vedashruti, Gomati, and Sandika are crossed amid cultivated land, birds, and cattle. Each waterline makes the palace world less immediate.'),
  ('scene-roads-beyond-kosala', 'rivers-mark-distance', 'hi', 'नदियाँ दूरी मापती हैं', 'वेदश्रुति, गोमती और स्यंदिका को खेतों, पक्षियों और पशुओं के बीच पार किया जाता है। हर जलरेखा महल के संसार को थोड़ा और दूर कर देती है।'),
  ('scene-roads-beyond-kosala', 'rama-faces-ayodhya', 'en', 'Rama faces Ayodhya once more', 'At the edge of Kosala, Rama turns back, salutes the city and its guardians, and says he will return after completing what he owes his father.'),
  ('scene-roads-beyond-kosala', 'rama-faces-ayodhya', 'hi', 'राम एक बार फिर अयोध्या की ओर देखते हैं', 'कोसल की सीमा पर राम पीछे मुड़कर नगर और उसके रक्षकों को प्रणाम करते हैं और कहते हैं कि पिता का दायित्व पूरा कर वे लौटेंगे।'),
  ('scene-roads-beyond-kosala', 'ganga-fills-horizon', 'en', 'The Ganga fills the horizon', 'The journey reaches a river too vast to be another passing stream. Water, sandbanks, birds, trees, and hermitages expand into a new world beside Shringaverapura.'),
  ('scene-roads-beyond-kosala', 'ganga-fills-horizon', 'hi', 'गंगा क्षितिज भर देती है', 'यात्रा ऐसी नदी तक पहुँचती है जो केवल एक और धारा नहीं। जल, रेतीले तट, पक्षी, वृक्ष और आश्रम शृंगवेरपुर के पास एक नया संसार खोलते हैं।'),
  ('scene-roads-beyond-kosala', 'guha-arrives-as-friend', 'en', 'Guha arrives as a friend', 'Guha comes with kin and offerings, embraces Rama, and asks after the journey. The first welcome beyond Kosala is offered as friendship, not as a faceless service stop.'),
  ('scene-roads-beyond-kosala', 'guha-arrives-as-friend', 'hi', 'गुह मित्र बनकर आते हैं', 'गुह अपने लोगों और भेंटों के साथ आते हैं, राम को आलिंगन देते हैं और यात्रा का हाल पूछते हैं। कोसल के बाहर पहला स्वागत मित्रता है, कोई अनाम पड़ाव नहीं।'),
  ('scene-guha-night-watch', 'guha-offers-a-kingdom', 'en', 'Guha offers everything at hand', 'Food, beds, supplies, protection, and even the settlement are placed before Rama. Guha''s welcome has political weight as well as personal affection.'),
  ('scene-guha-night-watch', 'guha-offers-a-kingdom', 'hi', 'गुह अपने पास का सब कुछ प्रस्तुत करते हैं', 'भोजन, शय्या, सामग्री, सुरक्षा और यहाँ तक कि अपना क्षेत्र भी गुह राम के सामने रखते हैं। उनका स्वागत निजी स्नेह के साथ राजनीतिक भार भी रखता है।'),
  ('scene-guha-night-watch', 'vow-shapes-acceptance', 'en', 'The vow shapes what can be accepted', 'Rama accepts the affection but declines comforts incompatible with the life he has undertaken. He asks only that Dasharatha''s horses be fed and tended well.'),
  ('scene-guha-night-watch', 'vow-shapes-acceptance', 'hi', 'व्रत तय करता है कि क्या स्वीकार होगा', 'राम स्नेह स्वीकार करते हैं, पर अपने चुने वनजीवन से असंगत सुख-सामग्री नहीं। वे केवल दशरथ के घोड़ों के भोजन और देखभाल का आग्रह करते हैं।'),
  ('scene-guha-night-watch', 'ground-bed-by-ganga', 'en', 'Rama and Sita sleep on the ground', 'After water and evening observance, Rama and Sita lie beneath the tree. The image is not serene decoration: everyone watching knows what comforts and people lie behind them.'),
  ('scene-guha-night-watch', 'ground-bed-by-ganga', 'hi', 'राम और सीता धरती पर सोते हैं', 'जल और संध्या-क्रम के बाद राम और सीता वृक्ष के नीचे लेटते हैं। यह केवल शांत सजावट नहीं—देखने वाले जानते हैं कि उनके पीछे कौन-से सुख और लोग छूटे हैं।'),
  ('scene-guha-night-watch', 'lakshmana-refuses-bed', 'en', 'Lakshmana refuses the bed', 'Guha offers Lakshmana rest and takes responsibility for protection. Lakshmana answers that he cannot sleep while Rama and Sita lie on grass before him.'),
  ('scene-guha-night-watch', 'lakshmana-refuses-bed', 'hi', 'लक्ष्मण शय्या अस्वीकार करते हैं', 'गुह लक्ष्मण को विश्राम देते और सुरक्षा की जिम्मेदारी लेते हैं। लक्ष्मण कहते हैं कि राम और सीता को घास पर सोते देखकर वे कैसे सो सकते हैं।'),
  ('scene-guha-night-watch', 'two-friends-keep-watch', 'en', 'Two friends keep watch', 'Lakshmana speaks his fear that Dasharatha and the mothers may not survive the night. Guha listens, weeps, and keeps watch with him until daybreak.'),
  ('scene-guha-night-watch', 'two-friends-keep-watch', 'hi', 'दो मित्र रात भर पहरा देते हैं', 'लक्ष्मण अपना भय कहते हैं कि दशरथ और माताएँ शायद यह रात न सह सकें। गुह सुनते हैं, आँसू बहाते हैं और भोर तक उनके साथ पहरा देते हैं।'),
  ('scene-ganga-crossing', 'boat-waits-at-dawn', 'en', 'A boat waits at dawn', 'Bird calls announce morning and Guha has a strong boat brought to the bank. Bows, quivers, travel bundles, and Sita must all cross together.'),
  ('scene-ganga-crossing', 'boat-waits-at-dawn', 'hi', 'भोर में नाव तैयार है', 'पक्षियों के स्वर भोर बताते हैं और गुह मजबूत नाव तट पर मँगवाते हैं। धनुष, तरकश, यात्रा-सामान और सीता—सबको साथ पार होना है।'),
  ('scene-ganga-crossing', 'sumantra-asks-to-stay', 'en', 'Sumantra asks not to return alone', 'Sumantra pleads to remain for all fourteen years. He imagines Ayodhya seeing the empty car and asks how a truth so painful can be carried back.'),
  ('scene-ganga-crossing', 'sumantra-asks-to-stay', 'hi', 'सुमंत्र अकेले लौटने से मना करते हैं', 'सुमंत्र चौदहों वर्ष साथ रहने की विनती करते हैं। वे खाली रथ को देखती अयोध्या की कल्पना करते हैं और पूछते हैं कि इतना पीड़ादायक सत्य कैसे लौटाया जाए।'),
  ('scene-ganga-crossing', 'messages-return-to-ayodhya', 'en', 'Messages return in their place', 'Rama asks Sumantra to steady Dasharatha, greet the mothers, summon Bharata, and report that the three do not regret keeping the command. The empty car will carry words.'),
  ('scene-ganga-crossing', 'messages-return-to-ayodhya', 'hi', 'उनकी जगह संदेश लौटते हैं', 'राम सुमंत्र से दशरथ को संभालने, माताओं को प्रणाम कहने, भरत को बुलाने और यह बताने को कहते हैं कि तीनों आदेश निभाने पर पछता नहीं रहे। खाली रथ अब शब्द ले जाएगा।'),
  ('scene-ganga-crossing', 'forest-vow-takes-form', 'en', 'The forest vow becomes visible', 'With Guha''s help, Rama and Lakshmana bind their hair into matted locks. The change is treated as their source-story decision, not a costume reward or instruction for the user.'),
  ('scene-ganga-crossing', 'forest-vow-takes-form', 'hi', 'वन-व्रत दिखाई देने लगता है', 'गुह की सहायता से राम और लक्ष्मण जटा बाँधते हैं। यह परिवर्तन स्रोत-कथा का उनका निर्णय है, कोई पोशाक-इनाम या उपयोगकर्ता के लिए निर्देश नहीं।'),
  ('scene-ganga-crossing', 'sita-prays-midstream', 'en', 'Sita speaks hope in midstream', 'In the middle of the Ganga, Sita prays that the vow be completed and that all three return. The prayer belongs to this character and moment; it is not presented as universal modern vidhi.'),
  ('scene-ganga-crossing', 'sita-prays-midstream', 'hi', 'मध्यधारा में सीता आशा बोलती हैं', 'गंगा की मध्यधारा में सीता प्रार्थना करती हैं कि व्रत पूरा हो और तीनों लौटें। यह इस पात्र और क्षण की प्रार्थना है, सार्वभौमिक आधुनिक विधि नहीं।'),
  ('scene-first-forest-night', 'first-night-without-sumantra', 'en', 'The chariot is gone', 'Under a great tree, Rama names this the first night beyond inhabited country without Sumantra. Leaves must become the bed and the three must provide for one another.'),
  ('scene-first-forest-night', 'first-night-without-sumantra', 'hi', 'रथ अब जा चुका है', 'एक विशाल वृक्ष के नीचे राम इसे सुमंत्र और बस्ती से बाहर पहली रात कहते हैं। पत्ते शय्या बनेंगे और तीनों को एक-दूसरे की देखभाल करनी होगी।'),
  ('scene-first-forest-night', 'rama-fears-for-home', 'en', 'Rama fears for those at home', 'Rama imagines Dasharatha weakened, Kausalya exposed, and Kaikeyi pressing her advantage. Exile does not switch off anxiety about the household left behind.'),
  ('scene-first-forest-night', 'rama-fears-for-home', 'hi', 'राम घरवालों के लिए डरते हैं', 'राम दशरथ को निर्बल, कौसल्या को असुरक्षित और कैकेयी को अपना लाभ बढ़ाते सोचते हैं। वनवास पीछे छूटे परिवार की चिंता बंद नहीं करता।'),
  ('scene-first-forest-night', 'anger-is-spoken-not-acted', 'en', 'Anger is spoken, not acted', 'He admits that force could seize Ayodhya, then rejects the act as wrong. The scene preserves the anger and the refusal instead of flattening him into effortless calm.'),
  ('scene-first-forest-night', 'anger-is-spoken-not-acted', 'hi', 'क्रोध कहा जाता है, किया नहीं जाता', 'वे स्वीकारते हैं कि बल से अयोध्या ली जा सकती है, फिर उस कर्म को अनुचित कहकर छोड़ते हैं। दृश्य उन्हें सहज शांत बनाने के बजाय क्रोध और उसके त्याग दोनों को रखता है।'),
  ('scene-first-forest-night', 'lakshmana-answers-belonging', 'en', 'Lakshmana answers with belonging', 'Lakshmana tells Rama that neither he nor Sita can live apart from him. His answer does not solve Ayodhya; it makes companionship present in this forest.'),
  ('scene-first-forest-night', 'lakshmana-answers-belonging', 'hi', 'लक्ष्मण साथ होने का उत्तर देते हैं', 'लक्ष्मण कहते हैं कि न वे, न सीता राम से अलग रह सकते हैं। उनका उत्तर अयोध्या की समस्या नहीं सुलझाता; वह इस वन में साथ को उपस्थित करता है।'),
  ('scene-first-forest-night', 'leaves-become-a-bed', 'en', 'Leaves become the first bed', 'The conversation ends in practical care. A bed of leaves is spread, the night is endured, and the three remain together in a place no palace plan prepared them to inhabit.'),
  ('scene-first-forest-night', 'leaves-become-a-bed', 'hi', 'पत्ते पहली शय्या बनते हैं', 'संवाद व्यावहारिक देखभाल में समाप्त होता है। पत्तों की शय्या बिछती है, रात काटी जाती है और तीनों ऐसे स्थान में साथ रहते हैं जिसके लिए किसी महल-योजना ने उन्हें तैयार नहीं किया था।'),
  ('scene-prayaga-to-yamuna', 'smoke-above-confluence', 'en', 'Smoke rises above two rivers', 'Near evening, Rama sees smoke and hears the meeting waters of Ganga and Yamuna. Signs of human practice reveal Bharadvaja''s hermitage before the travellers reach it.'),
  ('scene-prayaga-to-yamuna', 'smoke-above-confluence', 'hi', 'दो नदियों के ऊपर धुआँ उठता है', 'साँझ के पास राम धुआँ देखते और गंगा-यमुना के मिलते जल की ध्वनि सुनते हैं। मानवीय साधना के संकेत यात्रियों के पहुँचने से पहले भरद्वाज के आश्रम का पता देते हैं।'),
  ('scene-prayaga-to-yamuna', 'bharadvaja-receives-travellers', 'en', 'Bharadvaja receives the travellers', 'The three introduce themselves and explain the exile. Bharadvaja offers water, food from the forest, a place to rest, and the possibility of staying at the confluence.'),
  ('scene-prayaga-to-yamuna', 'bharadvaja-receives-travellers', 'hi', 'भरद्वाज यात्रियों का स्वागत करते हैं', 'तीनों अपना परिचय और वनवास बताते हैं। भरद्वाज जल, वन का भोजन, विश्राम-स्थान और संगम पर रहने की संभावना देते हैं।'),
  ('scene-prayaga-to-yamuna', 'rama-chooses-deeper-solitude', 'en', 'Rama asks for a more distant home', 'Rama worries that people from the city will keep coming if he stays nearby. He asks for a place where Sita can live well without making the hermitage a public court.'),
  ('scene-prayaga-to-yamuna', 'rama-chooses-deeper-solitude', 'hi', 'राम अधिक दूर घर माँगते हैं', 'राम सोचते हैं कि पास रहने पर नगर के लोग आते रहेंगे। वे ऐसी जगह पूछते हैं जहाँ सीता ठीक रह सकें और आश्रम सार्वजनिक दरबार न बन जाए।'),
  ('scene-prayaga-to-yamuna', 'chitrakoot-road-is-drawn', 'en', 'The road to Chitrakoot is drawn', 'Bharadvaja describes the mountain, its fruit, water, animals, ascetics, and paths. The next destination becomes a lived landscape rather than an abstract name.'),
  ('scene-prayaga-to-yamuna', 'chitrakoot-road-is-drawn', 'hi', 'चित्रकूट की राह खींची जाती है', 'भरद्वाज पर्वत, फल, जल, पशु, तपस्वी और मार्गों का वर्णन करते हैं। अगला पड़ाव अमूर्त नाम के बजाय रहने योग्य भू-दृश्य बन जाता है।'),
  ('scene-prayaga-to-yamuna', 'raft-crosses-yamuna', 'en', 'A raft crosses the Yamuna', 'The brothers build a raft and a seat for Sita. Midstream she voices another hope of return; beyond the bank, flowers, the Syama tree, birds, and new questions make the road active.'),
  ('scene-prayaga-to-yamuna', 'raft-crosses-yamuna', 'hi', 'बेड़ा यमुना पार करता है', 'भाई बेड़ा और सीता के लिए आसन बनाते हैं। मध्यधारा में वे फिर वापसी की आशा कहती हैं; दूसरे तट पर फूल, श्यामा-वृक्ष, पक्षी और नए प्रश्न राह को जीवित रखते हैं।'),
  ('scene-chitrakoot-home', 'birds-call-them-forward', 'en', 'Birdsong begins the final walk', 'Rama wakes Lakshmana to the forest''s bird calls. Flowering trees, fruit, honeycombs, peacocks, and elephants make the approach to Chitrakoot feel inhabited before any cottage exists.'),
  ('scene-chitrakoot-home', 'birds-call-them-forward', 'hi', 'पक्षियों का स्वर अंतिम चाल शुरू करता है', 'राम वन-पक्षियों के स्वर पर लक्ष्मण को जगाते हैं। फूलते वृक्ष, फल, मधुकोष, मोर और हाथी किसी कुटिया से पहले ही चित्रकूट को जीवित बना देते हैं।'),
  ('scene-chitrakoot-home', 'mountain-becomes-place', 'en', 'The mountain becomes a place to stay', 'At Chitrakoot, water, roots, fruit, birds, and ascetic communities make subsistence imaginable. Rama says plainly: let this be our abode.'),
  ('scene-chitrakoot-home', 'mountain-becomes-place', 'hi', 'पर्वत रहने की जगह बनता है', 'चित्रकूट में जल, कंद, फल, पक्षी और तपस्वी समुदाय जीवन को संभव बनाते हैं। राम स्पष्ट कहते हैं—यही हमारा निवास हो।'),
  ('scene-chitrakoot-home', 'valmiki-welcomes-them', 'en', 'A hermitage receives them', 'In this selected Dutt edition, the travellers greet Valmiki and explain their journey. The district keeps that edition-specific sequence without claiming every Ramayana places the encounter here.'),
  ('scene-chitrakoot-home', 'valmiki-welcomes-them', 'hi', 'एक आश्रम उन्हें स्वीकारता है', 'इस चुने हुए दत्त संस्करण में यात्री वाल्मीकि को प्रणाम कर अपनी यात्रा बताते हैं। यह जिला इसी संस्करण-विशिष्ट क्रम को रखता है, इसे हर रामायण का क्रम नहीं कहता।'),
  ('scene-chitrakoot-home', 'lakshmana-builds-cottage', 'en', 'Lakshmana builds the cottage', 'Rama chooses the site and Lakshmana gathers strong wood, raises walls and doors, and thatches the roof with leaves. The first forest home appears through work.'),
  ('scene-chitrakoot-home', 'lakshmana-builds-cottage', 'hi', 'लक्ष्मण कुटिया बनाते हैं', 'राम स्थान चुनते हैं और लक्ष्मण मजबूत लकड़ी जुटाकर दीवारें और द्वार खड़े करते, पत्तों की छत डालते हैं। पहला वन-घर श्रम से सामने आता है।'),
  ('scene-chitrakoot-home', 'three-enter-their-home', 'en', 'The three enter their home', 'The source describes household rites before entry; Devam presents them as narrative evidence, not current user instruction. When the three enter, the text allows city-grief to loosen for the first time.'),
  ('scene-chitrakoot-home', 'three-enter-their-home', 'hi', 'तीनों अपने घर में प्रवेश करते हैं', 'स्रोत प्रवेश से पहले गृह-क्रम बताता है; देवम् उसे कथा-साक्ष्य के रूप में रखता है, आज के उपयोगकर्ता के निर्देश की तरह नहीं। तीनों के भीतर आते ही नगर-वियोग पहली बार कुछ ढीला पड़ता है।'),
  ('scene-empty-chariot-return', 'sumantra-turns-home', 'en', 'Sumantra finally turns home', 'After learning that Rama, Sita, and Lakshmana have reached Bharadvaja and are bound for Chitrakoot, Sumantra leaves Guha. The car that carried the exile out now bears only its witness back.'),
  ('scene-empty-chariot-return', 'sumantra-turns-home', 'hi', 'सुमंत्र अंततः घर की ओर मुड़ते हैं', 'राम, सीता और लक्ष्मण के भरद्वाज तक पहुँचने और चित्रकूट जाने का समाचार पाकर सुमंत्र गुह से विदा लेते हैं। जो रथ वनवास को बाहर ले गया था, अब केवल उसके साक्षी को वापस ला रहा है।'),
  ('scene-empty-chariot-return', 'crowds-find-empty-car', 'en', 'The city runs toward an absence', 'At dusk, Ayodhya looks still and joyless. Hundreds surround the returning car and ask where Rama is; the answer that he crossed the Ganga moves through streets and palace windows as a fresh wave of grief.'),
  ('scene-empty-chariot-return', 'crowds-find-empty-car', 'hi', 'नगर एक अनुपस्थिति की ओर दौड़ता है', 'साँझ में अयोध्या स्थिर और उदास दिखती है। सैकड़ों लोग लौटे रथ को घेरकर राम का पता पूछते हैं; गंगा पार करने का उत्तर गलियों और महल की खिड़कियों में शोक की नई लहर बन जाता है।'),
  ('scene-empty-chariot-return', 'dasharatha-asks-every-detail', 'en', 'Dasharatha asks how they live', 'Revived from a faint, Dasharatha asks what the three eat, where they sleep, how Sita walks, and what each person said. The questions are not court business; they are a father trying to rebuild the vanished road in his mind.'),
  ('scene-empty-chariot-return', 'dasharatha-asks-every-detail', 'hi', 'दशरथ पूछते हैं वे कैसे जी रहे हैं', 'मूर्छा से लौटकर दशरथ पूछते हैं कि तीनों क्या खाते हैं, कहाँ सोते हैं, सीता कैसे चलती हैं और किसने क्या कहा। ये राजकाज के प्रश्न नहीं—एक पिता अपने मन में खोई राह फिर से बना रहा है।'),
  ('scene-empty-chariot-return', 'messages-fill-chamber', 'en', 'Three voices return through one witness', 'Sumantra carries Rama''s respectful messages to parents and Bharata, Lakshmana''s anger at the exile, and Sita''s wordless tears beside the departing car. The people are absent, but their distinct responses fill the chamber.'),
  ('scene-empty-chariot-return', 'messages-fill-chamber', 'hi', 'एक साक्षी से तीन स्वर लौटते हैं', 'सुमंत्र माता-पिता और भरत के लिए राम के सम्मानपूर्ण संदेश, वनवास पर लक्ष्मण का क्रोध और जाते रथ के पास सीता के मौन आँसू सुनाते हैं। लोग उपस्थित नहीं, पर उनकी अलग-अलग प्रतिक्रियाएँ कक्ष भर देती हैं।'),
  ('scene-empty-chariot-return', 'horses-and-city-grieve', 'en', 'Even the road returned reluctantly', 'Sumantra remembers the horses slowing and shedding tears when he turned away. He describes a kingdom whose streets, gardens, animals, and people all appear altered by the same absence; Dasharatha begs to be taken after the car again.'),
  ('scene-empty-chariot-return', 'horses-and-city-grieve', 'hi', 'राह भी अनिच्छा से लौटी', 'सुमंत्र याद करते हैं कि लौटते समय घोड़े धीमे पड़े और आँसू बहाते रहे। वे बताते हैं कि गलियाँ, उद्यान, पशु और लोग—पूरा राज्य उसी अनुपस्थिति से बदला दिखता है; दशरथ फिर रथ के पीछे ले चलने की विनती करते हैं।'),
  ('scene-palace-grief-dialogue', 'kausalya-asks-for-car', 'en', 'Kausalya asks to be taken to them', 'Kausalya asks Sumantra to turn the car toward the forest because life without the three feels impossible. Her demand is grief speaking before counsel can make the situation orderly.'),
  ('scene-palace-grief-dialogue', 'kausalya-asks-for-car', 'hi', 'कौसल्या उनके पास ले चलने को कहती हैं', 'कौसल्या सुमंत्र से रथ वन की ओर मोड़ने को कहती हैं, क्योंकि तीनों के बिना जीवन असंभव लगता है। व्यवस्था समझाने से पहले उनका शोक बोलता है।'),
  ('scene-palace-grief-dialogue', 'sumantra-describes-road', 'en', 'Sumantra offers what reassurance he can', 'He says Lakshmana serves them attentively and Sita keeps asking about rivers, villages, trees, and the changing landscape. The report does not erase hardship; it gives Kausalya evidence that the travellers are still acting, noticing, and caring for one another.'),
  ('scene-palace-grief-dialogue', 'sumantra-describes-road', 'hi', 'सुमंत्र जितना हो सके उतना आश्वासन देते हैं', 'वे बताते हैं कि लक्ष्मण सावधानी से सेवा कर रहे हैं और सीता नदियों, गाँवों, वृक्षों और बदलते भू-दृश्य के बारे में पूछती चल रही हैं। यह कठिनाई नहीं मिटाता; बस बताता है कि तीनों अभी भी सक्रिय हैं, देख रहे हैं और एक-दूसरे का ध्यान रख रहे हैं।'),
  ('scene-palace-grief-dialogue', 'kausalya-confronts-king', 'en', 'Kausalya names what was destroyed', 'Kausalya asks how a gentle son, a young daughter-in-law, and Lakshmana can bear the forest after palace life. Her speech widens from family pain to a ruined city and a kingdom whose future has been damaged by its own king.'),
  ('scene-palace-grief-dialogue', 'kausalya-confronts-king', 'hi', 'कौसल्या बताती हैं क्या-क्या टूट गया', 'कौसल्या पूछती हैं कि महल के जीवन के बाद कोमल पुत्र, युवा पुत्रवधू और लक्ष्मण वन कैसे सहेंगे। उनका कथन परिवार के दर्द से फैलकर टूटे नगर और अपने ही राजा से घायल भविष्य तक पहुँचता है।'),
  ('scene-palace-grief-dialogue', 'dasharatha-asks-forgiveness', 'en', 'The king asks his grieving wife for mercy', 'Dasharatha joins his hands and asks Kausalya not to strike him with further words while he is already broken. She immediately recognizes the pain her speech added and bows, without pretending the original wrong has vanished.'),
  ('scene-palace-grief-dialogue', 'dasharatha-asks-forgiveness', 'hi', 'राजा शोकाकुल पत्नी से क्षमा माँगते हैं', 'दशरथ हाथ जोड़कर कौसल्या से कहते हैं कि वे पहले ही टूट चुके हैं, इसलिए शब्दों से और न घायल करें। कौसल्या तुरंत अपने शब्दों की चोट पहचानकर झुकती हैं, पर मूल अन्याय को मिटा हुआ नहीं मानतीं।'),
  ('scene-palace-grief-dialogue', 'fifth-night-stretches', 'en', 'Five nights feel like five years', 'Kausalya says sorrow destroys patience and knowledge, and that the five nights since Rama left have stretched into years. Evening closes around a temporary reconciliation, but Dasharatha''s older memory has already begun to rise.'),
  ('scene-palace-grief-dialogue', 'fifth-night-stretches', 'hi', 'पाँच रातें पाँच वर्ष लगती हैं', 'कौसल्या कहती हैं कि शोक धैर्य और ज्ञान दोनों नष्ट करता है, और राम के जाने की पाँच रातें वर्षों जैसी हो गई हैं। अस्थायी मेल के चारों ओर रात उतरती है, पर दशरथ की पुरानी स्मृति जाग चुकी है।'),
  ('scene-river-sound-confession', 'sixth-night-memory', 'en', 'On the sixth night, another loss returns', 'Dasharatha wakes at midnight and tells Kausalya that actions ripen into consequences. Rama''s exile has brought back a deed from his youth that he had never escaped.'),
  ('scene-river-sound-confession', 'sixth-night-memory', 'hi', 'छठी रात एक और हानि लौटती है', 'आधी रात दशरथ जागकर कौसल्या से कहते हैं कि कर्म परिणाम बनकर लौटते हैं। राम का वनवास उनकी युवावस्था की उस घटना को वापस ले आया है जिससे वे कभी मुक्त नहीं हुए।'),
  ('scene-river-sound-confession', 'rain-and-unseen-sound', 'en', 'A hunter aims at a sound', 'As a young prince in the rainy season, Dasharatha waits beside the Sarayu and hears what he believes is an animal filling the night with water sounds. Confident in shooting by sound, he releases an arrow without seeing the target.'),
  ('scene-river-sound-confession', 'rain-and-unseen-sound', 'hi', 'शिकारी एक ध्वनि पर निशाना लगाता है', 'वर्षा ऋतु में युवा राजकुमार दशरथ सरयू तट पर प्रतीक्षा करते हैं और जल भरने की ध्वनि को पशु समझते हैं। ध्वनि से निशाना लगाने के कौशल पर भरोसा कर वे लक्ष्य देखे बिना बाण छोड़ देते हैं।'),
  ('scene-river-sound-confession', 'human-cry-answers', 'en', 'A human voice answers the arrow', 'The cry from the water is an ascetic youth gathering water for his blind parents. Mortally wounded, he worries less about himself than about the two people waiting for him and directs Dasharatha to their hermitage.'),
  ('scene-river-sound-confession', 'human-cry-answers', 'hi', 'बाण का उत्तर मानव स्वर देता है', 'जल से उठी पुकार अपने दृष्टिहीन माता-पिता के लिए पानी भरते एक तपस्वी युवक की है। मृत्यु के निकट वह अपने से अधिक प्रतीक्षा करते माता-पिता की चिंता करता है और दशरथ को उनके आश्रम का मार्ग बताता है।'),
  ('scene-river-sound-confession', 'parents-hear-footsteps', 'en', 'The parents hear the wrong footsteps', 'The blind parents welcome approaching steps as their son''s return. Dasharatha must identify himself, confess the error, lead them to the body, and stand inside grief he caused but cannot repair.'),
  ('scene-river-sound-confession', 'parents-hear-footsteps', 'hi', 'माता-पिता गलत पदचाप सुनते हैं', 'दृष्टिहीन माता-पिता आती पदचाप को पुत्र की वापसी समझते हैं। दशरथ को अपना परिचय देना, भूल स्वीकारना, उन्हें शव तक ले जाना और उस शोक के भीतर खड़ा होना पड़ता है जिसे वे सुधार नहीं सकते।'),
  ('scene-river-sound-confession', 'curse-reaches-present', 'en', 'The old words reach the present night', 'The father says Dasharatha too will die from grief for a son. Remembering the curse, the old king feels his senses dim, calls for Rama, names the family around him, and dies before the night is half gone.'),
  ('scene-river-sound-confession', 'curse-reaches-present', 'hi', 'पुराने शब्द वर्तमान रात तक पहुँचते हैं', 'पिता कहते हैं कि दशरथ भी पुत्र-वियोग में प्राण देंगे। श्राप याद आते ही वृद्ध राजा की इंद्रियाँ मंद पड़ती हैं; वे राम और परिवार को पुकारते हैं और आधी रात बीतने से पहले प्राण छोड़ देते हैं।'),
  ('scene-city-without-king', 'morning-music-arrives', 'en', 'Morning performs the old routine', 'Bards, singers, attendants, sacred water, mirrors, garments, and royal service arrive as usual. The sun rises while everyone waits for a king who will not wake.'),
  ('scene-city-without-king', 'morning-music-arrives', 'hi', 'सुबह पुरानी दिनचर्या निभाती है', 'गायक, वंशवाचक, सेवक, पवित्र जल, दर्पण, वस्त्र और राजसेवा हमेशा की तरह पहुँचते हैं। सूर्य उगता है, पर सब उस राजा की प्रतीक्षा करते हैं जो अब नहीं जागेगा।'),
  ('scene-city-without-king', 'stillness-is-discovered', 'en', 'Touch confirms the stillness', 'The women beside Dasharatha finally feel that his pulse no longer moves. Their cries wake Kausalya and Sumitra, and the palace understands all at once what happened during the night.'),
  ('scene-city-without-king', 'stillness-is-discovered', 'hi', 'स्पर्श स्थिरता की पुष्टि करता है', 'दशरथ के पास बैठी स्त्रियाँ अंततः पाती हैं कि उनकी नाड़ी नहीं चल रही। उनके विलाप से कौसल्या और सुमित्रा जागती हैं, और महल एक साथ रात की घटना समझ लेता है।'),
  ('scene-city-without-king', 'queens-and-city-wail', 'en', 'The lament leaves the room', 'Kausalya holds Dasharatha''s head and addresses Kaikeyi; the other queens gather, and grief fills halls, terraces, and streets already wounded by Rama''s absence.'),
  ('scene-city-without-king', 'queens-and-city-wail', 'hi', 'विलाप कक्ष से बाहर फैलता है', 'कौसल्या दशरथ का सिर गोद में लेकर कैकेयी से बोलती हैं; अन्य रानियाँ जुटती हैं और राम की अनुपस्थिति से पहले ही घायल सभागार, छतें और गलियाँ शोक से भर जाती हैं।'),
  ('scene-city-without-king', 'farewell-must-wait', 'en', 'The funeral cannot yet begin', 'With the sons absent, the counsellors do not perform the final rites. Dasharatha''s body is placed in oil and the palace enters an unnatural pause between death and succession.'),
  ('scene-city-without-king', 'farewell-must-wait', 'hi', 'अंत्येष्टि अभी शुरू नहीं हो सकती', 'पुत्रों की अनुपस्थिति में मंत्री अंतिम संस्कार नहीं करते। दशरथ का शरीर तेल में सुरक्षित रखा जाता है और महल मृत्यु तथा उत्तराधिकार के बीच अस्वाभाविक ठहराव में चला जाता है।'),
  ('scene-city-without-king', 'council-faces-empty-throne', 'en', 'The council faces a kingdom without a centre', 'At dawn, Vasishta and the counsellors describe the practical danger of a kingless realm—roads, trade, protection, fields, gatherings, and public trust can all unravel. The empty throne is now more than a symbol.'),
  ('scene-city-without-king', 'council-faces-empty-throne', 'hi', 'सभा केंद्रहीन राज्य का सामना करती है', 'भोर में वसिष्ठ और मंत्री राजाविहीन राज्य के व्यावहारिक संकट बताते हैं—मार्ग, व्यापार, सुरक्षा, खेत, सभाएँ और सार्वजनिक भरोसा सब बिखर सकते हैं। खाली सिंहासन अब केवल प्रतीक नहीं रहा।'),
  ('scene-city-without-king', 'messengers-carry-silence', 'en', 'Messengers leave with guarded words', 'Vasishta sends fast riders to Kekaya to bring Bharata and Shatrughna. They are ordered not to mention Dasharatha''s death or Rama''s exile; urgency must travel without its reason.'),
  ('scene-city-without-king', 'messengers-carry-silence', 'hi', 'दूत सँभले हुए शब्द लेकर निकलते हैं', 'वसिष्ठ तेज घुड़सवारों को भरत और शत्रुघ्न को लाने के लिए केकय भेजते हैं। उन्हें दशरथ की मृत्यु और राम के वनवास का उल्लेख न करने का आदेश है; कारण के बिना ही तात्कालिकता यात्रा करती है।'),
  ('scene-bharata-urgent-return', 'bharata-dark-dream', 'en', 'A dream refuses celebration', 'On the night the messengers arrive, Bharata dreams of his father falling, the ocean drying, the moon descending, fire dying, and a dark southward journey. Music and performance cannot make him laugh afterward.'),
  ('scene-bharata-urgent-return', 'bharata-dark-dream', 'hi', 'एक स्वप्न उत्सव को अस्वीकार करता है', 'दूतों के आने की रात भरत पिता के गिरने, समुद्र सूखने, चंद्रमा उतरने, अग्नि बुझने और अँधेरी दक्षिण दिशा की यात्रा का स्वप्न देखते हैं। उसके बाद संगीत और अभिनय भी उन्हें हँसा नहीं पाते।'),
  ('scene-bharata-urgent-return', 'envoys-answer-carefully', 'en', 'Every question receives half an answer', 'Bharata asks after Dasharatha, Rama, Lakshmana, Kausalya, Sumitra, and Kaikeyi. The envoys say those he asks about are well and insist that a matter cannot wait; their careful phrasing deepens his unease.'),
  ('scene-bharata-urgent-return', 'envoys-answer-carefully', 'hi', 'हर प्रश्न को आधा उत्तर मिलता है', 'भरत दशरथ, राम, लक्ष्मण, कौसल्या, सुमित्रा और कैकेयी का कुशल पूछते हैं। दूत कहते हैं कि जिनका वे पूछ रहे हैं वे कुशल हैं और एक काम विलंब नहीं सहता; सँभली हुई भाषा उनकी बेचैनी बढ़ाती है।'),
  ('scene-bharata-urgent-return', 'seven-night-ride', 'en', 'The road is crossed without rest', 'Bharata and Shatrughna leave their maternal family and travel for seven nights across rivers, forests, settlements, and difficult crossings. The geographic sequence becomes a countdown to news they do not yet possess.'),
  ('scene-bharata-urgent-return', 'seven-night-ride', 'hi', 'राह बिना विश्राम पार होती है', 'भरत और शत्रुघ्न ननिहाल से निकलकर सात रातें नदियों, वनों, बस्तियों और कठिन पारों से गुजरते हैं। भूगोल उस समाचार की उलटी गिनती बन जाता है जो उन्हें अभी नहीं मिला।'),
  ('scene-bharata-urgent-return', 'ayodhya-silence-speaks', 'en', 'Ayodhya tells him before people do', 'From a distance Bharata sees no crowds, hears no instruments, smells no incense, and finds gardens, shops, shrines, and homes neglected. He recognizes the signs that accompany a monarch''s death.'),
  ('scene-bharata-urgent-return', 'ayodhya-silence-speaks', 'hi', 'लोगों से पहले अयोध्या बता देती है', 'दूर से भरत न भीड़ देखते हैं, न वाद्य सुनते हैं, न धूप की गंध पाते हैं; उद्यान, दुकानें, पूजा-स्थल और घर उपेक्षित हैं। वे राजा की मृत्यु के साथ आने वाले संकेत पहचान लेते हैं।'),
  ('scene-bharata-urgent-return', 'bharata-enters-palace', 'en', 'The palace has no answer at its centre', 'Bharata dismisses the gatekeepers'' courtesies and enters with his head bowed. His father''s quarters are empty, so the urgent journey ends at Kaikeyi''s door.'),
  ('scene-bharata-urgent-return', 'bharata-enters-palace', 'hi', 'महल के केंद्र में कोई उत्तर नहीं', 'भरत द्वारपालों की औपचारिकता रोककर सिर झुकाए भीतर जाते हैं। पिता का कक्ष खाली है, इसलिए तात्कालिक यात्रा कैकेयी के द्वार पर समाप्त होती है।'),
  ('scene-bharata-rejects-boons', 'kaikeyi-welcomes-son', 'en', 'Kaikeyi welcomes the son she expected to reward', 'Kaikeyi rises, embraces Bharata, asks about the journey, and expects the room to become triumphant. Bharata instead notices his father''s missing bed and asks where the king is.'),
  ('scene-bharata-rejects-boons', 'kaikeyi-welcomes-son', 'hi', 'कैकेयी उस पुत्र का स्वागत करती हैं जिससे पुरस्कार की आशा थी', 'कैकेयी उठकर भरत को गले लगाती हैं, यात्रा पूछती हैं और कक्ष के विजयी होने की अपेक्षा रखती हैं। भरत पिता की खाली शय्या देखते हैं और राजा का पता पूछते हैं।'),
  ('scene-bharata-rejects-boons', 'father-death-spoken', 'en', 'The first truth drops him to the floor', 'Kaikeyi says Dasharatha has reached the end common to all beings. Bharata collapses, grieves the father whose hand once brushed dust from him, and asks for Rama as his elder, refuge, and next father.'),
  ('scene-bharata-rejects-boons', 'father-death-spoken', 'hi', 'पहला सत्य उन्हें भूमि पर गिरा देता है', 'कैकेयी कहती हैं कि दशरथ सभी प्राणियों की समान अंतिम अवस्था को प्राप्त हुए। भरत गिर पड़ते हैं, उस पिता का शोक करते हैं जो उनके शरीर से धूल झाड़ता था, और राम को बड़े भाई, आश्रय और अब पिता के समान पुकारते हैं।'),
  ('scene-bharata-rejects-boons', 'exile-revealed-next', 'en', 'Rama is not in the next room', 'When Bharata asks to go to Rama, Kaikeyi tells him that Rama, Sita, and Lakshmana wear bark in the forest. Bharata first assumes Rama must have committed some grave wrong; he cannot imagine exile without fault.'),
  ('scene-bharata-rejects-boons', 'exile-revealed-next', 'hi', 'राम अगले कक्ष में नहीं हैं', 'भरत राम के पास जाने को कहते हैं तो कैकेयी बताती हैं कि राम, सीता और लक्ष्मण वल्कल पहनकर वन में हैं। भरत पहले किसी गंभीर अपराध की आशंका करते हैं; दोष बिना वनवास की कल्पना नहीं कर पाते।'),
  ('scene-bharata-rejects-boons', 'kaikeyi-claims-success', 'en', 'Kaikeyi names the boons as success', 'She explains that Rama did no wrong: she herself demanded Bharata''s kingdom and Rama''s exile, Dasharatha kept his promise and died grieving, and now Bharata should perform the funeral and take power.'),
  ('scene-bharata-rejects-boons', 'kaikeyi-claims-success', 'hi', 'कैकेयी वरों को सफलता बताती हैं', 'वे बताती हैं कि राम ने कोई अपराध नहीं किया: उन्होंने स्वयं भरत के लिए राज्य और राम का वनवास माँगा, दशरथ ने वचन निभाया और शोक में मरे, इसलिए अब भरत संस्कार कर सत्ता लें।'),
  ('scene-bharata-rejects-boons', 'bharata-rejects-result', 'en', 'Bharata refuses to become the ending', 'Bharata says the kingdom cannot replace father or elder brother, denies any knowledge of the plan, rejects Kaikeyi''s purpose, and vows to bring Rama from the forest and serve him.'),
  ('scene-bharata-rejects-boons', 'bharata-rejects-result', 'hi', 'भरत इस परिणाम का अंत बनने से इंकार करते हैं', 'भरत कहते हैं कि राज्य पिता या बड़े भाई का स्थान नहीं ले सकता, योजना की जानकारी से इंकार करते हैं, कैकेयी के उद्देश्य को अस्वीकार करते हैं और राम को वन से लाकर उनकी सेवा करने की प्रतिज्ञा करते हैं।'),
  ('scene-funeral-and-trust', 'kausalya-fears-complicity', 'en', 'Kausalya cannot yet know whom to trust', 'Hearing Bharata''s voice, Kausalya meets him while still believing he may have wanted the kingdom. She asks to be sent to Rama rather than live inside the result of Kaikeyi''s plan.'),
  ('scene-funeral-and-trust', 'kausalya-fears-complicity', 'hi', 'कौसल्या अभी नहीं जानतीं किस पर भरोसा करें', 'भरत की आवाज़ सुनकर कौसल्या उनसे मिलती हैं, पर अभी मानती हैं कि वे राज्य चाहते थे। वे कैकेयी की योजना के परिणाम में रहने के बजाय राम के पास भेजे जाने को कहती हैं।'),
  ('scene-funeral-and-trust', 'bharata-clears-himself', 'en', 'Bharata puts his whole self behind the denial', 'He falls at Kausalya''s feet and swears that he neither desired the kingdom nor knew of the exile. The long oath is the story''s way of making his innocence answerable, not merely asserted.'),
  ('scene-funeral-and-trust', 'bharata-clears-himself', 'hi', 'भरत अपने पूरे अस्तित्व से इंकार करते हैं', 'वे कौसल्या के चरणों में गिरकर शपथ लेते हैं कि न उन्होंने राज्य चाहा, न वनवास जाना। लंबी शपथ उनकी निर्दोषता को केवल कथन नहीं, उत्तरदायित्व बनाती है।'),
  ('scene-funeral-and-trust', 'kausalya-embraces-bharata', 'en', 'Kausalya recognizes another grieving son', 'Kausalya tells Bharata that his loyalty to what is right makes the oath itself painful to hear. She draws him into her lap, and their separate grief becomes a shared commitment to Rama.'),
  ('scene-funeral-and-trust', 'kausalya-embraces-bharata', 'hi', 'कौसल्या एक और शोकाकुल पुत्र को पहचानती हैं', 'कौसल्या कहती हैं कि धर्मनिष्ठ भरत की शपथ सुनना ही उन्हें और दुख देता है। वे उन्हें गोद में खींचती हैं और अलग-अलग शोक राम के प्रति साझा संकल्प बन जाता है।'),
  ('scene-funeral-and-trust', 'dasharatha-leaves-palace', 'en', 'The suspended farewell moves to the Sarayu', 'Vasishta asks Bharata to perform the rites. Dasharatha''s body is raised from the oil, placed on a bier, and carried with priests, queens, attendants, incense, lament, and gifts toward the funeral ground.'),
  ('scene-funeral-and-trust', 'dasharatha-leaves-palace', 'hi', 'रुकी हुई विदाई सरयू की ओर बढ़ती है', 'वसिष्ठ भरत से संस्कार करने को कहते हैं। दशरथ का शरीर तेल से उठाकर अर्थी पर रखा जाता है और पुरोहितों, रानियों, सेवकों, सुगंध, विलाप तथा दान के साथ श्मशान की ओर ले जाया जाता है।'),
  ('scene-funeral-and-trust', 'ten-days-and-ashes', 'en', 'Mourning is allowed to take time', 'The family performs water rites, sleeps on the ground through the mourning period, completes the shraddha, and returns to gather bones and ashes. Bharata and Shatrughna both collapse under the renewed finality.'),
  ('scene-funeral-and-trust', 'ten-days-and-ashes', 'hi', 'शोक को समय लेने दिया जाता है', 'परिवार जलांजलि देता है, शोक अवधि में भूमि पर सोता है, श्राद्ध पूरा करता है और अस्थियाँ तथा राख लेने लौटता है। अंतिमता फिर सामने आते ही भरत और शत्रुघ्न दोनों टूट पड़ते हैं।'),
  ('scene-funeral-and-trust', 'duties-remain-after-grief', 'en', 'The living are called back to unfinished duties', 'Vasishta and Sumantra lift the brothers and remind them that the remaining rites must be completed. The scene does not end grief; it establishes that action must now continue through it.'),
  ('scene-funeral-and-trust', 'duties-remain-after-grief', 'hi', 'जीवितों को अधूरे कर्तव्यों की ओर लौटाया जाता है', 'वसिष्ठ और सुमंत्र भाइयों को उठाकर शेष संस्कार पूरे करने की याद दिलाते हैं। दृश्य शोक समाप्त नहीं करता; वह बताता है कि अब कर्म उसी के भीतर से आगे बढ़ेगा।'),
  ('scene-crown-refused-road', 'bharata-stops-vengeance', 'en', 'Bharata stops the punishment Rama would reject', 'Shatrughna seizes Manthara in anger over the destruction around them. Bharata stops him: harming her or killing his mother would itself estrange the very brother whose standard he intends to follow.'),
  ('scene-crown-refused-road', 'bharata-stops-vengeance', 'hi', 'भरत वह दंड रोकते हैं जिसे राम स्वीकार न करते', 'चारों ओर हुए विनाश पर क्रोधित शत्रुघ्न मंथरा को पकड़ लेते हैं। भरत उन्हें रोकते हैं: उसे हानि पहुँचाना या माँ की हत्या करना उसी भाई से दूर कर देगा जिसकी मर्यादा वे मानना चाहते हैं।'),
  ('scene-crown-refused-road', 'ministers-offer-crown', 'en', 'The kingdom offers the available answer', 'Ministers place the installation materials before Bharata and argue that Dasharatha''s command has made the throne his. Their proposal is practical, lawful in their reading, and exactly what he refuses.'),
  ('scene-crown-refused-road', 'ministers-offer-crown', 'hi', 'राज्य उपलब्ध उत्तर प्रस्तुत करता है', 'मंत्री राज्याभिषेक-सामग्री भरत के सामने रखकर कहते हैं कि दशरथ की आज्ञा ने सिंहासन उन्हें दिया है। उनका प्रस्ताव व्यावहारिक और उनकी दृष्टि में वैध है—और भरत ठीक इसी को अस्वीकार करते हैं।'),
  ('scene-crown-refused-road', 'rama-named-king', 'en', 'Bharata names the absent king', 'He says the eldest must rule, Rama is king, and he will take the installation objects into the forest, ask Rama to return, and remain there himself if an exchange is required.'),
  ('scene-crown-refused-road', 'rama-named-king', 'hi', 'भरत अनुपस्थित राजा का नाम लेते हैं', 'वे कहते हैं कि ज्येष्ठ ही शासन करेंगे, राम राजा हैं; वे अभिषेक-सामग्री वन ले जाकर राम से लौटने की विनती करेंगे और आवश्यकता पड़ी तो स्वयं वहीं रहेंगे।'),
  ('scene-crown-refused-road', 'road-builders-go-first', 'en', 'A decision becomes physical work', 'Surveyors, diggers, carpenters, bridge-builders, cooks, guides, and camp workers go ahead. They level difficult ground, prepare crossings, find water, and establish the route for a huge public journey.'),
  ('scene-crown-refused-road', 'road-builders-go-first', 'hi', 'निर्णय भौतिक कार्य बनता है', 'सर्वेक्षक, खोदने वाले, बढ़ई, पुल बनाने वाले, रसोइए, मार्गदर्शक और शिविर-कर्मी आगे जाते हैं। वे कठिन भूमि समतल करते, पार बनाते, जल जुटाते और विशाल सार्वजनिक यात्रा की राह तैयार करते हैं।'),
  ('scene-crown-refused-road', 'i-am-not-the-king', 'en', 'Morning praise is silenced', 'At dawn, drums and genealogists wake Bharata with royal praise. He stops them with the words, ''I am not the king,'' before entering the great assembly called by Vasishta.'),
  ('scene-crown-refused-road', 'i-am-not-the-king', 'hi', 'सुबह की राजस्तुति रोक दी जाती है', 'भोर में नगाड़े और वंशवाचक भरत को राजस्तुति से जगाते हैं। वे ''मैं राजा नहीं हूँ'' कहकर सब रोकते हैं और वसिष्ठ की बुलाई महान सभा में जाते हैं।'),
  ('scene-crown-refused-road', 'assembly-orders-journey', 'en', 'The whole city turns toward Rama', 'When Vasishta again presents the throne, Bharata refuses before the gathered city, promises every effort to bring Rama back, and orders Sumantra to ready the car and commanders to marshal the expedition.'),
  ('scene-crown-refused-road', 'assembly-orders-journey', 'hi', 'पूरा नगर राम की ओर मुड़ता है', 'वसिष्ठ सभा में फिर सिंहासन प्रस्तुत करते हैं तो भरत सबके सामने इंकार करते हैं, राम को लौटाने का हर प्रयास करने की प्रतिज्ञा करते हैं और सुमंत्र को रथ तथा सेनानायकों को यात्रा तैयार करने का आदेश देते हैं।'),
  ('scene-expedition-reaches-ganga', 'whole-city-sets-out', 'en', 'A kingdom leaves its throne behind', 'At dawn Bharata sets out with Shatrughna, the mothers, priests, counsellors, citizens, craftspeople, and an immense royal force. This is not a prince''s private visit; Ayodhya itself travels to ask Rama home.'),
  ('scene-expedition-reaches-ganga', 'whole-city-sets-out', 'hi', 'एक राज्य सिंहासन पीछे छोड़कर निकलता है', 'भोर में भरत शत्रुघ्न, माताओं, पुरोहितों, मंत्रियों, नागरिकों, कारीगरों और विशाल राजकीय दल के साथ निकलते हैं। यह किसी राजकुमार की निजी भेंट नहीं—अयोध्या स्वयं राम को घर बुलाने चलती है।'),
  ('scene-expedition-reaches-ganga', 'hope-moves-through-crowd', 'en', 'People imagine the return before it happens', 'Along the road people ask when they will see Rama again and speak as though his face will end the city''s darkness. Hope spreads through embraces, carts, animals, and ordinary working households moving together.'),
  ('scene-expedition-reaches-ganga', 'hope-moves-through-crowd', 'hi', 'लोग वापसी को होने से पहले देख लेते हैं', 'राह में लोग पूछते हैं कि राम फिर कब दिखाई देंगे और मानते हैं कि उनका दर्शन नगर का अँधेरा दूर कर देगा। आलिंगनों, गाड़ियों, पशुओं और साथ चलते परिवारों में आशा फैलती है।'),
  ('scene-expedition-reaches-ganga', 'ganga-stops-the-road', 'en', 'The Ganga stops an army-sized road', 'The expedition reaches Shringaverapura and must become a camp. Bharata plans the crossing and offers water for Dasharatha; the river is both physical boundary and the place where grief returns.'),
  ('scene-expedition-reaches-ganga', 'ganga-stops-the-road', 'hi', 'गंगा सेना-जितनी राह रोकती है', 'यात्रा शृंगवेरपुर पहुँचकर शिविर बन जाती है। भरत पार जाने की व्यवस्था और दशरथ के लिए जल अर्पण की सोचते हैं; नदी भौतिक सीमा भी है और लौटता हुआ शोक भी।'),
  ('scene-expedition-reaches-ganga', 'guha-sees-war', 'en', 'Guha sees banners before intentions', 'Across the river, Guha sees a force without visible end and fears Bharata has come to secure the kingdom by harming Rama. He arms the riverbank and readies hundreds of boats to deny passage if necessary.'),
  ('scene-expedition-reaches-ganga', 'guha-sees-war', 'hi', 'गुह इरादों से पहले ध्वज देखते हैं', 'नदी के पार गुह ऐसा दल देखते हैं जिसका अंत नहीं दिखता और आशंका करते हैं कि भरत राम को हानि पहुँचाकर राज्य पक्का करने आए हैं। वे तट और सैकड़ों नावें रक्षा के लिए तैयार करते हैं।'),
  ('scene-expedition-reaches-ganga', 'gifts-cross-before-trust', 'en', 'A host approaches with gifts and caution', 'Guha carries forest food and hospitality toward Bharata while keeping his people ready. Sumantra identifies him as Rama''s friend and the person most likely to know the road ahead.'),
  ('scene-expedition-reaches-ganga', 'gifts-cross-before-trust', 'hi', 'आतिथ्य और सावधानी साथ आगे बढ़ते हैं', 'गुह वन का भोजन और आतिथ्य लेकर भरत के पास जाते हैं, जबकि उनके लोग सतर्क रहते हैं। सुमंत्र उन्हें राम का मित्र और आगे की राह जानने वाला व्यक्ति बताते हैं।'),
  ('scene-expedition-reaches-ganga', 'bharata-names-purpose', 'en', 'Bharata names the only purpose', 'When Guha asks directly whether the army means harm, Bharata answers without court language: Rama is dear as a father, and he has come only to persuade his elder brother to return.'),
  ('scene-expedition-reaches-ganga', 'bharata-names-purpose', 'hi', 'भरत अपना एकमात्र उद्देश्य बताते हैं', 'जब गुह सीधे पूछते हैं कि क्या यह सेना हानि पहुँचाने आई है, भरत दरबारी भाषा छोड़कर कहते हैं—राम पिता समान प्रिय हैं और वे केवल उन्हें लौटाने आए हैं।'),
  ('scene-guha-shows-first-night', 'guha-recognizes-bharata', 'en', 'Suspicion becomes recognition', 'Bharata''s answer transforms Guha''s stance. He praises a man willing to surrender an unasked-for kingdom, offers guidance to Bharadvaja, and stays near while grief keeps Bharata awake.'),
  ('scene-guha-shows-first-night', 'guha-recognizes-bharata', 'hi', 'संदेह पहचान में बदलता है', 'भरत का उत्तर गुह का रुख बदल देता है। वे अनचाहा राज्य छोड़ने वाले भाई की प्रशंसा करते, भरद्वाज तक मार्गदर्शन देते और शोक में जागते भरत के पास रहते हैं।'),
  ('scene-guha-shows-first-night', 'lakshmana-vigil-retold', 'en', 'Guha retells Lakshmana''s vigil', 'Guha recounts offering Lakshmana a bed and guard. Lakshmana refused sleep while Rama and Sita lay on grass, fearing already that Dasharatha and the mothers might not survive the separation.'),
  ('scene-guha-shows-first-night', 'lakshmana-vigil-retold', 'hi', 'गुह लक्ष्मण की जागी रात सुनाते हैं', 'गुह बताते हैं कि उन्होंने लक्ष्मण को विश्राम और पहरा देने का प्रस्ताव दिया था। राम-सीता को घास पर सोता देखकर लक्ष्मण जागते रहे और दशरथ व माताओं के जीवन के लिए भय जताते रहे।'),
  ('scene-guha-shows-first-night', 'bharata-collapses-at-news', 'en', 'The details strike harder than the headline', 'Hearing how the first night passed, Bharata collapses. Shatrughna and the mothers gather around him; when he recovers, he asks where each person slept, what they ate, and who guarded them.'),
  ('scene-guha-shows-first-night', 'bharata-collapses-at-news', 'hi', 'विवरण समाचार से अधिक चोट करते हैं', 'पहली रात का विवरण सुनकर भरत मूर्छित हो जाते हैं। शत्रुघ्न और माताएँ उन्हें घेर लेती हैं; सँभलकर वे पूछते हैं—कौन कहाँ सोया, क्या खाया और पहरा किसने दिया।'),
  ('scene-guha-shows-first-night', 'grass-bed-remains', 'en', 'The grass still carries a shape', 'At the Ingudi tree, Guha shows the pressed grass, fragments of silk and gold, and the place of Lakshmana''s watch. Bharata reads a whole vanished night from what the ground retained.'),
  ('scene-guha-shows-first-night', 'grass-bed-remains', 'hi', 'घास में अब भी आकृति बची है', 'इंगुदी वृक्ष के नीचे गुह दबा हुआ तृण, रेशम और सोने के छोटे अंश तथा लक्ष्मण की चौकसी का स्थान दिखाते हैं। भरत धरती पर बचे निशानों से पूरी बीती रात पढ़ते हैं।'),
  ('scene-guha-shows-first-night', 'bharata-chooses-exile-exchange', 'en', 'Bharata offers to exchange lives', 'He vows to sleep on the ground, wear bark and matted hair, and remain in the forest if Rama will not return. The plan is no longer only persuasion; Bharata is prepared to take the exile himself.'),
  ('scene-guha-shows-first-night', 'bharata-chooses-exile-exchange', 'hi', 'भरत जीवन बदलने का संकल्प लेते हैं', 'वे भूमि पर सोने, वल्कल और जटा धारण करने तथा राम के न लौटने पर स्वयं वन में रहने का वचन देते हैं। अब योजना केवल विनती नहीं—भरत वनवास अपने ऊपर लेने को तैयार हैं।'),
  ('scene-guha-shows-first-night', 'five-hundred-boats-move', 'en', 'A city crosses by many kinds of courage', 'At dawn Guha''s crews move people, mothers, priests, cars, animals, and supplies across the Ganga in boats and rafts; some swim. By the third watch, the expedition rests in Prayaga''s woods.'),
  ('scene-guha-shows-first-night', 'five-hundred-boats-move', 'hi', 'एक नगर अनेक साहसों से नदी पार करता है', 'भोर में गुह के नाविक लोगों, माताओं, पुरोहितों, रथों, पशुओं और सामग्री को नावों व बेड़ों से गंगा पार कराते हैं; कुछ तैरते हैं। तीसरे प्रहर तक यात्रा प्रयाग के वन में ठहरती है।'),
  ('scene-bharadvaja-tests-hosts', 'bharata-leaves-army-behind', 'en', 'Bharata approaches without force', 'A krosha from the hermitage, Bharata leaves the army, weapons, and courtly display behind. He follows Vasishta on foot so a royal expedition does not trample the ascetic world it seeks help from.'),
  ('scene-bharadvaja-tests-hosts', 'bharata-leaves-army-behind', 'hi', 'भरत सेना के बिना आगे बढ़ते हैं', 'आश्रम से एक क्रोश पहले भरत सेना, अस्त्र और राजकीय प्रदर्शन छोड़ देते हैं। वे वसिष्ठ के पीछे पैदल जाते हैं ताकि सहायता माँगती यात्रा तपोवन को रौंद न दे।'),
  ('scene-bharadvaja-tests-hosts', 'bharadvaja-tests-intention', 'en', 'A second guardian asks the same hard question', 'Bharadvaja asks whether Bharata came to harm Rama and secure the kingdom. Bharata weeps at being suspected again, rejects his mother''s act, and asks only for the way to Rama''s feet.'),
  ('scene-bharadvaja-tests-hosts', 'bharadvaja-tests-intention', 'hi', 'दूसरे संरक्षक का वही कठिन प्रश्न', 'भरद्वाज पूछते हैं कि क्या भरत राम को हानि पहुँचाकर राज्य सुरक्षित करने आए हैं। फिर संदेह सुनकर भरत रो पड़ते, माँ के कर्म को अस्वीकार करते और केवल राम तक की राह माँगते हैं।'),
  ('scene-bharadvaja-tests-hosts', 'test-becomes-direction', 'en', 'The test becomes a direction', 'Satisfied, Bharadvaja says Rama, Sita, and Lakshmana are at Chitrakoot and asks Bharata to stay the night. The unknown forest contracts into a place that can be reached tomorrow.'),
  ('scene-bharadvaja-tests-hosts', 'test-becomes-direction', 'hi', 'परीक्षा दिशा बन जाती है', 'संतुष्ट होकर भरद्वाज बताते हैं कि राम, सीता और लक्ष्मण चित्रकूट में हैं और भरत से रात रुकने को कहते हैं। अनजान वन अब कल पहुँची जा सकने वाली जगह बन जाता है।'),
  ('scene-bharadvaja-tests-hosts', 'army-invited-carefully', 'en', 'Hospitality expands without erasing restraint', 'Bharadvaja asks for the whole force. Bharata explains he kept it away to protect trees, water, animals, and cottages. Only after the host insists does the city-sized company approach.'),
  ('scene-bharadvaja-tests-hosts', 'army-invited-carefully', 'hi', 'संयम बनाए रखते हुए आतिथ्य फैलता है', 'भरद्वाज पूरे दल को बुलाते हैं। भरत बताते हैं कि वृक्ष, जल, पशु और कुटियों की रक्षा के लिए सेना दूर रखी थी। मेज़बान के आग्रह के बाद ही विशाल दल आगे आता है।'),
  ('scene-bharadvaja-tests-hosts', 'hermitage-becomes-wonder', 'en', 'The exhausted road enters a wonder', 'Bharadvaja invokes an extraordinary welcome: wind, blossom rain, music, dwellings, food, water, care for animals, and rest appear around the force. For one night, dust and grief give way to abundance.'),
  ('scene-bharadvaja-tests-hosts', 'hermitage-becomes-wonder', 'hi', 'थकी हुई यात्रा एक अद्भुत संसार में प्रवेश करती है', 'भरद्वाज अद्भुत स्वागत रचते हैं—सुगंधित वायु, पुष्पवर्षा, संगीत, आवास, भोजन, जल, पशुओं की देखभाल और विश्राम। एक रात के लिए धूल और शोक समृद्धि को स्थान देते हैं।'),
  ('scene-bharadvaja-tests-hosts', 'route-through-mandakini', 'en', 'Morning restores the purpose', 'At dawn Bharadvaja directs them south toward the Mandakini and Chitrakoot. The mothers appear together; Bharata names their grief, and the sage interrupts his hatred of Kaikeyi before the army moves on.'),
  ('scene-bharadvaja-tests-hosts', 'route-through-mandakini', 'hi', 'सुबह उद्देश्य फिर सामने आता है', 'भोर में भरद्वाज उन्हें मंदाकिनी और चित्रकूट की दक्षिणी राह बताते हैं। माताएँ साथ आती हैं; भरत उनका शोक बताते हैं और ऋषि कैकेयी के प्रति उनके घृणा-वचन को रोकते हैं।'),
  ('scene-chitrakoot-hears-army', 'forest-flees-before-force', 'en', 'The forest hears the expedition first', 'Elephants, deer, birds, and other forest life scatter before the dust and sound of Bharata''s force. The road to a loving reunion still carries the disruptive weight of a kingdom.'),
  ('scene-chitrakoot-hears-army', 'forest-flees-before-force', 'hi', 'वन सबसे पहले यात्रा सुनता है', 'भरत के दल की धूल और गर्जना से हाथी, हिरन, पक्षी और अन्य वन्य जीव भागते हैं। प्रेमपूर्ण मिलन की राह भी एक राज्य का विघटनकारी भार साथ लाती है।'),
  ('scene-chitrakoot-hears-army', 'smoke-becomes-clue', 'en', 'A line of smoke narrows the world', 'Searchers see smoke that must belong to a dwelling or hermitage. Bharata stops the army from advancing, keeps the forest from being overrun, and follows the clue with only a small company.'),
  ('scene-chitrakoot-hears-army', 'smoke-becomes-clue', 'hi', 'धुएँ की रेखा संसार को एक दिशा देती है', 'खोजी ऐसा धुआँ देखते हैं जो किसी निवास या आश्रम का हो सकता है। भरत सेना रोकते हैं, वन को रौंदने से बचाते हैं और छोटे दल के साथ उस संकेत की ओर बढ़ते हैं।'),
  ('scene-chitrakoot-hears-army', 'chitrakoot-before-alarm', 'en', 'Inside the cottage world, life is briefly whole', 'Before the noise arrives, Rama shows Sita Chitrakoot''s coloured rock, flowering forest, birds, cascades, and the Mandakini. Exile has become a place where the three can still make a life.'),
  ('scene-chitrakoot-hears-army', 'chitrakoot-before-alarm', 'hi', 'कुटिया-संसार में जीवन क्षण भर पूरा है', 'शोर आने से पहले राम सीता को चित्रकूट की रंगीन शिलाएँ, पुष्पित वन, पक्षी, झरने और मंदाकिनी दिखाते हैं। वनवास ऐसी जगह बन गया है जहाँ तीनों जीवन रच सकते हैं।'),
  ('scene-chitrakoot-hears-army', 'lakshmana-climbs-to-see', 'en', 'Lakshmana climbs into fear', 'The ground trembles and animals run. From a tree Lakshmana sees elephants, horses, chariots, infantry, and Bharata''s standard; he asks Rama to hide Sita, string the bow, and prepare for attack.'),
  ('scene-chitrakoot-hears-army', 'lakshmana-climbs-to-see', 'hi', 'लक्ष्मण भय की ओर चढ़ते हैं', 'भूमि काँपती है और पशु भागते हैं। वृक्ष से लक्ष्मण हाथी, घोड़े, रथ, पैदल दल और भरत का ध्वज देखते हैं; वे सीता को सुरक्षित करने और धनुष तैयार करने को कहते हैं।'),
  ('scene-chitrakoot-hears-army', 'rama-refuses-suspicion', 'en', 'Rama refuses to make a brother an enemy', 'Rama says a kingdom gained by killing Bharata would be poison. He trusts that Bharata came from grief and love, and reminds Lakshmana that harm to his brother would be harm to Rama himself.'),
  ('scene-chitrakoot-hears-army', 'rama-refuses-suspicion', 'hi', 'राम भाई को शत्रु मानने से इंकार करते हैं', 'राम कहते हैं कि भरत को मारकर मिला राज्य विष होगा। उन्हें विश्वास है कि भरत शोक और प्रेम से आए हैं; वे याद दिलाते हैं कि भाई को चोट पहुँचाना राम को चोट पहुँचाना होगा।'),
  ('scene-chitrakoot-hears-army', 'bharata-walks-last-distance', 'en', 'The last distance is taken on foot', 'Bharata stations the force away from the hill, searches with Shatrughna, Guha, advisers, and citizens, then sees the smoke himself. Rank and spectacle fall behind as he climbs toward Rama''s cottage.'),
  ('scene-chitrakoot-hears-army', 'bharata-walks-last-distance', 'hi', 'अंतिम दूरी पैदल तय होती है', 'भरत सेना को पर्वत से दूर रोककर शत्रुघ्न, गुह, सलाहकारों और नागरिकों के साथ खोजते हैं, फिर स्वयं धुआँ देखते हैं। पद और प्रदर्शन पीछे छूटते हैं; वे कुटिया की ओर चढ़ते हैं।'),
  ('scene-brothers-meet-death-news', 'cottage-signs-lead-in', 'en', 'Bharata reads the life around the cottage', 'Bark signs, gathered fuel, flowers, a maintained fire, and the path to the Mandakini confirm the dwelling before anyone appears. Bharata sees the practical life Lakshmana built around the exile.'),
  ('scene-brothers-meet-death-news', 'cottage-signs-lead-in', 'hi', 'भरत कुटिया के आसपास का जीवन पढ़ते हैं', 'वल्कल के संकेत, इकट्ठी लकड़ी, फूल, जीवित अग्नि और मंदाकिनी की राह किसी के दिखने से पहले निवास की पुष्टि करते हैं। भरत लक्ष्मण द्वारा रचा व्यावहारिक वन-जीवन देखते हैं।'),
  ('scene-brothers-meet-death-news', 'bharata-sees-rama', 'en', 'The person sought is finally visible', 'Inside, Bharata sees Rama in bark and matted hair beside Sita and Lakshmana. The contrast with the court he remembers overwhelms him before he can complete more than a cry of recognition.'),
  ('scene-brothers-meet-death-news', 'bharata-sees-rama', 'hi', 'जिसे खोजा गया वह अंततः सामने है', 'भीतर भरत राम को वल्कल और जटा में सीता व लक्ष्मण के साथ देखते हैं। स्मृति के राजदरबार और सामने के वन-जीवन का अंतर उन्हें केवल पुकार भर कहने देता है।'),
  ('scene-brothers-meet-death-news', 'brothers-fall-and-embrace', 'en', 'Words fail; the brothers meet', 'Bharata falls at Rama''s feet; Shatrughna follows. Rama raises and embraces them, then receives Sumantra and Guha. The forest community watches four royal brothers meet in tears rather than ceremony.'),
  ('scene-brothers-meet-death-news', 'brothers-fall-and-embrace', 'hi', 'शब्द चूकते हैं; भाई मिलते हैं', 'भरत राम के चरणों में गिरते हैं; शत्रुघ्न भी आते हैं। राम दोनों को उठाकर गले लगाते, फिर सुमंत्र और गुह से मिलते हैं। वनवासी समुदाय चार भाइयों को समारोह नहीं, आँसुओं में मिलता देखता है।'),
  ('scene-brothers-meet-death-news', 'rama-asks-as-if-king', 'en', 'Rama asks questions meant for a ruler', 'Not knowing Dasharatha is dead, Rama asks after father, mothers, priests, advisers, soldiers, farmers, justice, treasury, secrecy, and public welfare. He assumes Bharata carries responsibility and examines how he bears it.'),
  ('scene-brothers-meet-death-news', 'rama-asks-as-if-king', 'hi', 'राम शासक से पूछे जाने वाले प्रश्न करते हैं', 'दशरथ की मृत्यु न जानकर राम पिता, माताओं, पुरोहितों, मंत्रियों, सैनिकों, किसानों, न्याय, कोष, गोपनीयता और लोककल्याण का समाचार पूछते हैं। वे मानते हैं कि भरत उत्तरदायित्व संभाल रहे हैं।'),
  ('scene-brothers-meet-death-news', 'bharata-asks-return', 'en', 'Bharata answers with the empty centre', 'Bharata says the kingdom is not his, names himself servant and brother, and asks Rama to return before the mothers, ministers, and subjects who travelled to his feet. Then he tells why Dasharatha cannot come.'),
  ('scene-brothers-meet-death-news', 'bharata-asks-return', 'hi', 'भरत खाली केंद्र से उत्तर देते हैं', 'भरत कहते हैं कि राज्य उनका नहीं, वे सेवक और भाई हैं, और उन माताओं, मंत्रियों व प्रजाजनों के सामने राम से लौटने को कहते हैं जो उनके चरणों तक आए हैं। फिर वे बताते हैं कि दशरथ क्यों नहीं आए।'),
  ('scene-brothers-meet-death-news', 'death-news-breaks-reunion', 'en', 'The news fells Rama', 'Hearing that Dasharatha died grieving after the exile, Rama collapses. The brothers and Sita carry their mourning to the Mandakini, offer water and the food of their own forest life, then return together to the cottage.'),
  ('scene-brothers-meet-death-news', 'death-news-breaks-reunion', 'hi', 'समाचार राम को गिरा देता है', 'यह सुनकर कि वनवास के बाद शोक में दशरथ की मृत्यु हुई, राम गिर पड़ते हैं। भाई और सीता शोक लेकर मंदाकिनी जाते, जल और अपने वन-जीवन का अन्न अर्पित करते, फिर साथ कुटिया लौटते हैं।'),
  ('scene-family-asks-rama-home', 'mothers-follow-river-path', 'en', 'The mothers see how exile lives', 'Kausalya, Sumitra, Kaikeyi, and the other queens follow the Mandakini path used for water. Kausalya sees Dasharatha''s simple offering and the work Lakshmana performs, reading the family''s changed life in ordinary objects.'),
  ('scene-family-asks-rama-home', 'mothers-follow-river-path', 'hi', 'माताएँ वनवास का जीवन देखती हैं', 'कौसल्या, सुमित्रा, कैकेयी और अन्य रानियाँ मंदाकिनी की जल-राह पर चलती हैं। कौसल्या दशरथ का साधारण अर्पण और लक्ष्मण का श्रम देखकर सामान्य वस्तुओं में बदला पारिवारिक जीवन पढ़ती हैं।'),
  ('scene-family-asks-rama-home', 'family-embraces-dust', 'en', 'The palace family meets the forest family', 'Rama and Lakshmana bow; the mothers wipe dust from their backs. Sita takes their feet and Kausalya embraces her. The reunion is tactile and domestic before it becomes political again.'),
  ('scene-family-asks-rama-home', 'family-embraces-dust', 'hi', 'महल का परिवार वन के परिवार से मिलता है', 'राम और लक्ष्मण प्रणाम करते हैं; माताएँ उनकी पीठ की धूल पोंछती हैं। सीता उनके चरण पकड़ती हैं और कौसल्या उन्हें गले लगाती हैं। राजनीति से पहले मिलन स्पर्श और परिवार का है।'),
  ('scene-family-asks-rama-home', 'silence-before-argument', 'en', 'Everyone waits for the first claim', 'After a night of mourning and morning rites, brothers, mothers, citizens, and advisers sit in silence. The entire expedition has reached its purpose, but affection alone has not decided who must return.'),
  ('scene-family-asks-rama-home', 'silence-before-argument', 'hi', 'सब पहले तर्क की प्रतीक्षा करते हैं', 'शोक की रात और प्रातःकर्म के बाद भाई, माताएँ, नागरिक और सलाहकार मौन बैठते हैं। पूरी यात्रा अपने उद्देश्य तक पहुँच गई है, पर स्नेह ने अभी तय नहीं किया कि कौन लौटेगा।'),
  ('scene-family-asks-rama-home', 'bharata-grants-kingdom-back', 'en', 'Bharata returns what he never accepted', 'Bharata says the kingdom produced by Kaikeyi''s demand is legally in his hands, and he gives it to Rama. He compares himself to someone unable to sustain the great tree another person raised.'),
  ('scene-family-asks-rama-home', 'bharata-grants-kingdom-back', 'hi', 'भरत वह लौटाते हैं जिसे कभी स्वीकार नहीं किया', 'भरत कहते हैं कि कैकेयी की माँग से मिला राज्य विधि के अनुसार उनके हाथ में है और वे उसे राम को देते हैं। वे स्वयं को उस व्यक्ति जैसा बताते हैं जो दूसरे के उगाए विशाल वृक्ष को सँभाल नहीं सकता।'),
  ('scene-family-asks-rama-home', 'rama-holds-fathers-word', 'en', 'Rama will not turn grief into broken truth', 'Rama answers that time separates every family and Dasharatha''s command still binds both sons. Bharata must protect Ayodhya; Rama must complete fourteen years. Mourning cannot make the promise disappear.'),
  ('scene-family-asks-rama-home', 'rama-holds-fathers-word', 'hi', 'राम शोक को टूटे वचन में नहीं बदलते', 'राम कहते हैं कि समय हर परिवार को अलग करता है और दशरथ की आज्ञा दोनों पुत्रों को अब भी बाँधती है। भरत अयोध्या सँभालें, राम चौदह वर्ष पूरे करें; शोक वचन मिटा नहीं सकता।'),
  ('scene-family-asks-rama-home', 'bharata-argues-duty-to-living', 'en', 'Bharata argues that duty must repair harm', 'Bharata answers that an eldest living son should rule, a son may repair a father''s harmful act, and government is itself Rama''s responsibility. If Rama still chooses the forest, Bharata will remain there with him.'),
  ('scene-family-asks-rama-home', 'bharata-argues-duty-to-living', 'hi', 'भरत कहते हैं कि धर्म को हानि सुधारनी चाहिए', 'भरत उत्तर देते हैं कि जीवित ज्येष्ठ पुत्र को शासन करना चाहिए, पुत्र पिता के हानिकारक कर्म को सुधार सकता है और राजकार्य स्वयं राम का दायित्व है। फिर भी राम वन चुनें तो भरत भी वहीं रहेंगे।'),
  ('scene-sandals-hold-kingdom', 'rama-restates-division', 'en', 'Rama names the divided obligation', 'Rama restates the boons and says each brother preserves Dasharatha''s truth by carrying his assigned part: Bharata the kingdom, Rama the forest. The four brothers must protect one promise through different work.'),
  ('scene-sandals-hold-kingdom', 'rama-restates-division', 'hi', 'राम बँटे हुए दायित्व को नाम देते हैं', 'राम वरों को दोहराकर कहते हैं कि हर भाई अपना भाग निभाकर दशरथ का सत्य बचाए—भरत राज्य, राम वन। चारों भाइयों को अलग कार्य से एक वचन की रक्षा करनी है।'),
  ('scene-sandals-hold-kingdom', 'javali-offers-radical-exit', 'en', 'Javali attacks the premise', 'Trying to make Rama return, Javali argues that relationships end, death ends obligation, and visible welfare should outweigh rites and promises. His speech is a position inside the debate, not the narrator''s settled conclusion.'),
  ('scene-sandals-hold-kingdom', 'javali-offers-radical-exit', 'hi', 'जावालि आधार पर ही प्रश्न उठाते हैं', 'राम को लौटाने के लिए जावालि कहते हैं कि संबंध समाप्त होते हैं, मृत्यु दायित्व खत्म करती है और दृश्य लोककल्याण को संस्कार व वचन से ऊपर होना चाहिए। यह बहस का पक्ष है, अंतिम निष्कर्ष नहीं।'),
  ('scene-sandals-hold-kingdom', 'rama-answers-with-public-trust', 'en', 'Rama answers that conduct becomes public trust', 'Rama rejects Javali''s reasoning: a ruler''s conduct teaches others, and truth sustains public confidence. Javali then says he used the argument strategically, revealing the exchange as persuasion rather than simple doctrine.'),
  ('scene-sandals-hold-kingdom', 'rama-answers-with-public-trust', 'hi', 'राम कहते हैं कि आचरण सार्वजनिक विश्वास बनता है', 'राम जावालि का तर्क अस्वीकार करते हैं—शासक का आचरण दूसरों को दिशा देता है और सत्य सार्वजनिक भरोसा सँभालता है। जावालि बताते हैं कि उन्होंने यह पक्ष रणनीतिक रूप से रखा था।'),
  ('scene-sandals-hold-kingdom', 'vasishta-adds-lineage-and-care', 'en', 'Vasishta adds lineage, mother, and teacher', 'Vasishta invokes the eldest-son tradition and his authority as teacher; he asks Rama to heed mother, brother, and people. Rama answers that parental care creates a debt he can honour only by keeping Dasharatha''s command.'),
  ('scene-sandals-hold-kingdom', 'vasishta-adds-lineage-and-care', 'hi', 'वसिष्ठ वंश, माता और गुरु का पक्ष जोड़ते हैं', 'वसिष्ठ ज्येष्ठ-पुत्र परंपरा और गुरु-अधिकार रखते हुए राम से माता, भाई और प्रजा की सुनने को कहते हैं। राम कहते हैं कि माता-पिता की सेवा का ऋण दशरथ की आज्ञा निभाकर ही चुक सकता है।'),
  ('scene-sandals-hold-kingdom', 'bharata-lies-at-door', 'en', 'Bharata refuses food and movement', 'With persuasion exhausted, Bharata spreads grass at the cottage door and vows to lie there until Rama yields. When that too fails, he offers to serve the fourteen-year exile as Rama''s substitute.'),
  ('scene-sandals-hold-kingdom', 'bharata-lies-at-door', 'hi', 'भरत अन्न और गति दोनों रोक देते हैं', 'तर्क समाप्त होने पर भरत कुटिया के द्वार पर कुश बिछाकर राम के मानने तक पड़े रहने का व्रत लेते हैं। यह भी विफल होने पर वे चौदह वर्ष का वनवास स्वयं लेने की बात रखते हैं।'),
  ('scene-sandals-hold-kingdom', 'sandals-become-trust', 'en', 'The sandals become a bounded trust', 'Rama will not accept a substitute, but gives Bharata his sandals. Bharata promises to govern outside Ayodhya in their name, live austerely, and return the kingdom when Rama comes back at fourteen years.'),
  ('scene-sandals-hold-kingdom', 'sandals-become-trust', 'hi', 'पादुकाएँ सीमित धरोहर बनती हैं', 'राम प्रतिनिधि वनवास स्वीकार नहीं करते, पर भरत को अपनी पादुकाएँ देते हैं। भरत उनके नाम पर अयोध्या के बाहर रहकर संयम से शासन और चौदह वर्ष बाद राज्य लौटाने का वचन देते हैं।'),
  ('scene-nandigrama-trust', 'sandals-leave-chitrakoot', 'en', 'Bharata carries the answer above himself', 'Bharata places the sandals on his head and leaves Chitrakoot with Shatrughna, Vasishta, Javali, ministers, mothers, and citizens. Rama returns weeping to the cottage; neither road feels like victory.'),
  ('scene-nandigrama-trust', 'sandals-leave-chitrakoot', 'hi', 'भरत उत्तर को अपने ऊपर रखते हैं', 'भरत पादुकाएँ सिर पर रखकर शत्रुघ्न, वसिष्ठ, जावालि, मंत्रियों, माताओं और नागरिकों के साथ चित्रकूट से लौटते हैं। राम रोते हुए कुटिया जाते हैं; कोई भी राह विजय जैसी नहीं लगती।'),
  ('scene-nandigrama-trust', 'bharadvaja-hears-outcome', 'en', 'The road reports back', 'At Prayaga, Bharata tells Bharadvaja that Rama would not break the fourteen-year promise and that the sandals now carry the work of government. The sage recognizes the resolution without pretending the brothers agreed.'),
  ('scene-nandigrama-trust', 'bharadvaja-hears-outcome', 'hi', 'राह अपना परिणाम बताती है', 'प्रयाग में भरत भरद्वाज को बताते हैं कि राम चौदह वर्ष का वचन नहीं तोड़ेंगे और पादुकाएँ अब शासन का कार्य सँभालेंगी। ऋषि समाधान स्वीकारते हैं, भाइयों की असहमति मिटाते नहीं।'),
  ('scene-nandigrama-trust', 'rivers-reverse-direction', 'en', 'Every crossing now points away from Rama', 'The expedition crosses Yamuna and Ganga again, passes Shringaverapura, and approaches Ayodhya. The same geography that carried hope outward now carries a difficult responsibility back.'),
  ('scene-nandigrama-trust', 'rivers-reverse-direction', 'hi', 'हर नदी अब राम से दूर ले जाती है', 'यात्रा फिर यमुना और गंगा पार कर शृंगवेरपुर से अयोध्या की ओर बढ़ती है। जो भू-दृश्य आशा को बाहर ले गया था, वही अब कठिन उत्तरदायित्व वापस ला रहा है।'),
  ('scene-nandigrama-trust', 'ayodhya-still-without-rama', 'en', 'The city is still waiting', 'Ayodhya''s closed doors, silent music, empty markets, and dark palace show that the journey did not restore ordinary life. Bharata sees a city that cannot yet celebrate and refuses to occupy its centre.'),
  ('scene-nandigrama-trust', 'ayodhya-still-without-rama', 'hi', 'नगर अब भी प्रतीक्षा में है', 'अयोध्या के बंद द्वार, मौन संगीत, खाली बाज़ार और अँधेरा महल बताते हैं कि यात्रा ने सामान्य जीवन नहीं लौटाया। भरत उस नगर का केंद्र लेने से इंकार करते हैं जो अभी उत्सव नहीं मना सकता।'),
  ('scene-nandigrama-trust', 'bharata-chooses-nandigrama', 'en', 'Bharata chooses to govern from outside', 'After settling the mothers in Ayodhya, Bharata tells Vasishta and the counsellors he will live at Nandigrama. Rama is king; Bharata will carry the reins only while waiting for him.'),
  ('scene-nandigrama-trust', 'bharata-chooses-nandigrama', 'hi', 'भरत बाहर से शासन चुनते हैं', 'माताओं को अयोध्या में ठहराकर भरत वसिष्ठ और मंत्रियों से कहते हैं कि वे नंदिग्राम में रहेंगे। राजा राम हैं; भरत केवल उनकी प्रतीक्षा में कार्यभार सँभालेंगे।'),
  ('scene-nandigrama-trust', 'trust-installed-not-king', 'en', 'A trust is installed, not another king', 'At Nandigrama the sandals receive the umbrella and ceremonial place. Bharata wears bark and matted hair, reports decisions in subordination to them, and defines his rule by the moment it must end: Rama''s return.'),
  ('scene-nandigrama-trust', 'trust-installed-not-king', 'hi', 'राजा नहीं, धरोहर स्थापित होती है', 'नंदिग्राम में पादुकाओं को छत्र और राजकीय स्थान मिलता है। भरत वल्कल-जटा धारण कर उनके अधीन निर्णय लेते हैं और अपने शासन को उस क्षण से परिभाषित करते हैं जब वह समाप्त होगा—राम की वापसी।'),
  ('scene-chitrakoot-grows-unsafe', 'ascetics-speak-in-signs', 'en', 'Fear appears before its name', 'After Bharata leaves, Rama notices the neighbouring ascetics exchanging glances and preparing to move. He first asks whether he, Lakshmana, or Sita has failed them.'),
  ('scene-chitrakoot-grows-unsafe', 'ascetics-speak-in-signs', 'hi', 'नाम से पहले भय दिखाई देता है', 'भरत के लौटने के बाद राम पड़ोसी तपस्वियों को संकेतों में बात करते और जाने की तैयारी करते देखते हैं। वे पहले पूछते हैं कि क्या उनसे, लक्ष्मण से या सीता से कोई भूल हुई है।'),
  ('scene-chitrakoot-grows-unsafe', 'khara-name-enters', 'en', 'The threat has a name', 'An elder says the danger is Khara''s Janasthana world and other attackers who break vessels, spoil fires, assume frightening forms, and kill isolated ascetics.'),
  ('scene-chitrakoot-grows-unsafe', 'khara-name-enters', 'hi', 'संकट का एक नाम है', 'एक वृद्ध तपस्वी बताते हैं कि संकट खर के जनस्थान-संसार और उन आक्रमणकारियों से है जो पात्र तोड़ते, अग्नि बुझाते, भयानक रूप धरते और अकेले तपस्वियों को मारते हैं।'),
  ('scene-chitrakoot-grows-unsafe', 'hermitages-choose-survival', 'en', 'The hermitages choose to survive', 'The community will move to another wood. The elder warns that Rama''s presence may draw more danger, and Rama cannot persuade them to remain.'),
  ('scene-chitrakoot-grows-unsafe', 'hermitages-choose-survival', 'hi', 'आश्रम जीवित रहने का निर्णय लेते हैं', 'समुदाय दूसरे वन में जाने का निर्णय लेता है। वृद्ध चेताते हैं कि राम की उपस्थिति और संकट खींच सकती है, और राम उन्हें रुकने के लिए आश्वस्त नहीं कर पाते।'),
  ('scene-chitrakoot-grows-unsafe', 'memory-covers-chitrakoot', 'en', 'Bharata''s visit remains everywhere', 'The cottage still holds the meeting with Bharata and the mothers; the ground carries the trace of the enormous camp. Chitrakoot now recalls grief more readily than shelter.'),
  ('scene-chitrakoot-grows-unsafe', 'memory-covers-chitrakoot', 'hi', 'भरत की यात्रा हर ओर रह जाती है', 'कुटिया में भरत और माताओं की भेंट की स्मृति है; भूमि पर विशाल शिविर के चिह्न हैं। चित्रकूट अब आश्रय से अधिक शोक की याद दिलाता है।'),
  ('scene-chitrakoot-grows-unsafe', 'three-leave-first-home', 'en', 'Three leave the home they made', 'Rama decides to move. Sita and Lakshmana leave with him, carrying the road forward rather than treating Chitrakoot as the whole forest exile.'),
  ('scene-chitrakoot-grows-unsafe', 'three-leave-first-home', 'hi', 'तीनों अपने बनाए घर से निकलते हैं', 'राम आगे बढ़ने का निर्णय लेते हैं। सीता और लक्ष्मण उनके साथ निकलते हैं—चित्रकूट को पूरे वनवास का अंत नहीं, आगे की राह का पहला घर मानकर।'),
  ('scene-sita-tells-her-beginning', 'atri-receives-travellers', 'en', 'A new hermitage receives them', 'Atri welcomes Rama as a son and receives Sita and Lakshmana. He introduces Sita to the aged ascetic Anasuya, whose long discipline is remembered through a drought story.'),
  ('scene-sita-tells-her-beginning', 'atri-receives-travellers', 'hi', 'एक नया आश्रम उन्हें स्वीकारता है', 'अत्रि राम का पुत्र की तरह स्वागत करते हैं और सीता-लक्ष्मण को अपनाते हैं। वे सीता को वृद्ध तपस्विनी अनसूया से मिलाते हैं, जिनकी दीर्घ साधना को अकाल की कथा में याद किया जाता है।'),
  ('scene-sita-tells-her-beginning', 'historical-teaching-stays-spoken', 'en', 'An elder gives the teaching she inherited', 'Anasuya praises Sita''s companionship and speaks in the strongly patriarchal language of the selected historical translation. The scene keeps that speech attributable to its speaker rather than turning it into modern instruction.'),
  ('scene-sita-tells-her-beginning', 'historical-teaching-stays-spoken', 'hi', 'एक वृद्धा अपनी मिली हुई शिक्षा देती हैं', 'अनसूया सीता के साथ निभाने की प्रशंसा करती हैं और चुने हुए ऐतिहासिक अनुवाद की गहरी पितृसत्तात्मक भाषा में बोलती हैं। दृश्य उस वाणी को वक्ता से जोड़कर रखता है, आधुनिक निर्देश नहीं बनाता।'),
  ('scene-sita-tells-her-beginning', 'sita-answers-from-memory', 'en', 'Sita answers with memories of her own', 'Sita recalls what her mother, mother-in-law, and household taught her, then speaks of Rama''s conduct toward the royal mothers. Her response is neither silence nor a detached rule; it is personal memory inside her chosen journey.'),
  ('scene-sita-tells-her-beginning', 'sita-answers-from-memory', 'hi', 'सीता अपनी स्मृतियों से उत्तर देती हैं', 'सीता अपनी माता, सास और परिवार से मिली सीख याद करती हैं, फिर राजमाताओं के प्रति राम के व्यवहार की बात करती हैं। उनका उत्तर न मौन है, न कोई निरपेक्ष नियम—यह उनकी चुनी हुई यात्रा के भीतर निजी स्मृति है।'),
  ('scene-sita-tells-her-beginning', 'anasuya-gives-with-affection', 'en', 'Affection becomes something carried', 'When Sita asks for nothing, Anasuya gives her garments, ornaments, a garland, and fragrant paste. The gifts mark hospitality and relationship before another difficult road.'),
  ('scene-sita-tells-her-beginning', 'anasuya-gives-with-affection', 'hi', 'स्नेह साथ ले जाने योग्य बनता है', 'जब सीता कुछ नहीं माँगतीं, अनसूया उन्हें वस्त्र, आभूषण, माला और सुगंधित लेप देती हैं। ये उपहार कठिन राह से पहले आतिथ्य और संबंध का चिह्न बनते हैं।'),
  ('scene-sita-tells-her-beginning', 'sita-begins-with-earth', 'en', 'Sita begins with the earth and Janaka', 'Asked to tell her story at length, Sita says Janaka found her while ploughing sacrificial ground and accepted her as his daughter. She narrates her origin rather than appearing only as someone else''s prize.'),
  ('scene-sita-tells-her-beginning', 'sita-begins-with-earth', 'hi', 'सीता पृथ्वी और जनक से आरम्भ करती हैं', 'अपनी कथा विस्तार से सुनाने पर सीता कहती हैं कि यज्ञभूमि जोतते समय जनक ने उन्हें पाया और पुत्री रूप में स्वीकार किया। वे केवल किसी की प्राप्ति नहीं, अपनी उत्पत्ति स्वयं सुनाती हैं।'),
  ('scene-sita-tells-her-beginning', 'bow-and-choice-retold', 'en', 'The bow, the assembly, and the choice are retold', 'Sita recounts Janaka''s anxiety, the assembly around the immovable bow, Rama lifting and breaking it, and the consultations that joined the households. Night arrives while her own voice closes the Ayodhya book.'),
  ('scene-sita-tells-her-beginning', 'bow-and-choice-retold', 'hi', 'धनुष, सभा और चुनाव फिर सुनाए जाते हैं', 'सीता जनक की चिंता, अचल धनुष की सभा, राम द्वारा उसे उठाकर तोड़ने और दोनों परिवारों को जोड़ने वाली सहमति की कथा सुनाती हैं। उनकी अपनी आवाज़ में आयोध्या काण्ड का अंत होते-होते रात उतर आती है।'),
  ('scene-dandaka-receives-them', 'sun-enters-clouds', 'en', 'The forest closes around them', 'Warned that danger lies ahead, Rama, Sita, and Lakshmana enter the deeper forest. The selected edition compares their entry to the sun passing into cloud.'),
  ('scene-dandaka-receives-them', 'sun-enters-clouds', 'hi', 'वन उनके चारों ओर गहरा जाता है', 'आगे के संकट की चेतावनी लेकर राम, सीता और लक्ष्मण गहरे वन में प्रवेश करते हैं। चुना हुआ संस्करण उनके प्रवेश की तुलना बादलों में जाते सूर्य से करता है।'),
  ('scene-dandaka-receives-them', 'hermitages-form-constellation', 'en', 'Homes appear between the trees', 'Dandaka reveals fire rooms, water jars, bark dwellings, gardens, lotus tanks, recitation, birds, deer, roots, and fruit. The first impression is a living network of care and work.'),
  ('scene-dandaka-receives-them', 'hermitages-form-constellation', 'hi', 'वृक्षों के बीच घर उभरते हैं', 'दण्डक में अग्निशालाएँ, जलपात्र, वल्कल-कुटियाँ, उद्यान, कमल-सरोवर, पाठ, पक्षी, हिरण, कन्द और फल दिखाई देते हैं। पहला अनुभव श्रम और देखभाल के जीवित जाल का है।'),
  ('scene-dandaka-receives-them', 'bows-unstrung-at-threshold', 'en', 'The bow lowers at the threshold', 'Rama unstrings his bow before entering. The residents come forward, offer water, food, flowers, and shelter, and study the three travellers with wonder.'),
  ('scene-dandaka-receives-them', 'bows-unstrung-at-threshold', 'hi', 'देहरी पर धनुष नीचे होता है', 'राम प्रवेश से पहले धनुष की प्रत्यंचा उतारते हैं। निवासी आगे आकर जल, भोजन, फूल और आश्रय देते हैं तथा तीनों यात्रियों को विस्मय से देखते हैं।'),
  ('scene-dandaka-receives-them', 'king-without-city', 'en', 'A king without a city is still addressed', 'The ascetics say that Rama remains responsible for people in his dominion whether he lives in city or forest. His own displacement does not erase their expectation of protection.'),
  ('scene-dandaka-receives-them', 'king-without-city', 'hi', 'नगर बिना भी राजा को पुकारा जाता है', 'तपस्वी कहते हैं कि राम नगर में हों या वन में, अपने क्षेत्र के लोगों के प्रति उत्तरदायी हैं। उनका स्वयं विस्थापित होना दूसरों की सुरक्षा की अपेक्षा मिटाता नहीं।'),
  ('scene-dandaka-receives-them', 'hospitality-before-danger', 'en', 'The world feeds them before testing them', 'The visitors eat and rest among the hermitages. At sunrise they continue, and the ordered clearings give way to a damaged forest of frightened birds and disturbed water.'),
  ('scene-dandaka-receives-them', 'hospitality-before-danger', 'hi', 'संसार परीक्षा से पहले उन्हें भोजन देता है', 'यात्री आश्रमों में भोजन और विश्राम पाते हैं। सूर्योदय पर आगे बढ़ते ही व्यवस्थित खुली जगहों की जगह टूटे वृक्ष, डरे पक्षी और मटमैला जल आने लगता है।'),
  ('scene-viradha-breaks-the-road', 'viradha-appears-with-aftermath', 'en', 'Danger arrives carrying its aftermath', 'Viradha appears enormous, blood-marked, and carrying the bodies of animals on a spear. He declares the forest his domain and seizes Sita.'),
  ('scene-viradha-breaks-the-road', 'viradha-appears-with-aftermath', 'hi', 'संकट अपने परिणामों के साथ आता है', 'विराध विशाल, रक्त-चिह्नित और भाले पर मारे गए पशु लिए प्रकट होता है। वह वन को अपना क्षेत्र बताकर सीता को उठा लेता है।'),
  ('scene-viradha-breaks-the-road', 'old-grief-breaks-surface', 'en', 'An old grief breaks through Rama', 'Seeing Sita held, Rama connects the moment to exile, Kaikeyi, the lost kingdom, and Dasharatha''s death. Lakshmana answers the collapse with furious readiness to act.'),
  ('scene-viradha-breaks-the-road', 'old-grief-breaks-surface', 'hi', 'राम के भीतर पुराना शोक फूटता है', 'सीता को पकड़े देखकर राम इस क्षण को वनवास, कैकेयी, खोए राज्य और दशरथ की मृत्यु से जोड़ते हैं। लक्ष्मण इस टूटन का उत्तर तीव्र कार्रवाई की तैयारी से देते हैं।'),
  ('scene-viradha-breaks-the-road', 'arrows-do-not-end-it', 'en', 'The arrows land, but do not end it', 'Rama''s arrows force Viradha to release Sita, but a boon keeps weapons from killing him. He charges again and lifts both brothers onto his shoulders.'),
  ('scene-viradha-breaks-the-road', 'arrows-do-not-end-it', 'hi', 'बाण लगते हैं, पर संकट समाप्त नहीं होता', 'राम के बाण विराध को सीता छोड़ने पर विवश करते हैं, पर वरदान उसे हथियारों से मरने नहीं देता। वह फिर आक्रमण कर दोनों भाइयों को कंधों पर उठा लेता है।'),
  ('scene-viradha-breaks-the-road', 'sita-intervenes-alone', 'en', 'Sita refuses to disappear from the action', 'Left on the ground, Sita calls out and offers herself if Viradha will release Rama and Lakshmana. Her intervention gives the brothers the opening to break his arms.'),
  ('scene-viradha-breaks-the-road', 'sita-intervenes-alone', 'hi', 'सीता कार्रवाई से गायब नहीं होतीं', 'भूमि पर छूटकर सीता पुकारती हैं और राम-लक्ष्मण को छोड़ने के बदले स्वयं को ले जाने को कहती हैं। उनके हस्तक्षेप से भाइयों को विराध की भुजाएँ तोड़ने का अवसर मिलता है।'),
  ('scene-viradha-breaks-the-road', 'method-must-change', 'en', 'They change the method', 'Blows and blades still fail. Rama recognizes the limit and orders a pit; Lakshmana digs while Rama holds Viradha down.'),
  ('scene-viradha-breaks-the-road', 'method-must-change', 'hi', 'वे तरीका बदलते हैं', 'प्रहार और तलवार भी असफल रहते हैं। राम सीमा पहचानकर गड्ढा खोदने को कहते हैं; लक्ष्मण खोदते हैं और राम विराध को रोके रखते हैं।'),
  ('scene-viradha-breaks-the-road', 'enemy-becomes-direction', 'en', 'The defeated enemy becomes a direction', 'Viradha recognizes Rama, says a curse shaped his form, and points the travellers toward Sarabhanga before the burial frees him. The attack ends by changing the road ahead.'),
  ('scene-viradha-breaks-the-road', 'enemy-becomes-direction', 'hi', 'पराजित शत्रु दिशा बन जाता है', 'विराध राम को पहचानकर बताता है कि शाप ने उसका रूप बनाया और मुक्त होने से पहले यात्रियों को शरभंग की ओर भेजता है। आक्रमण आगे की राह बदलकर समाप्त होता है।'),
  ('scene-forest-asks-protection', 'indra-leaves-before-meeting', 'en', 'A celestial meeting ends as Rama arrives', 'Near Sarabhanga''s hermitage, Rama sees Indra''s airborne company. Indra departs before meeting him, saying Rama still has work to complete.'),
  ('scene-forest-asks-protection', 'indra-leaves-before-meeting', 'hi', 'राम के आते ही दिव्य भेंट समाप्त होती है', 'शरभंग के आश्रम के पास राम इन्द्र का आकाशीय दल देखते हैं। इन्द्र मिलने से पहले यह कहकर चले जाते हैं कि राम का कार्य अभी बाकी है।'),
  ('scene-forest-asks-protection', 'sarabhanga-waits-for-rama', 'en', 'Sarabhanga waited before leaving', 'Sarabhanga says he delayed his ascent until he could see Rama. Rama declines inherited heavenly regions and asks instead where he should live in the forest.'),
  ('scene-forest-asks-protection', 'sarabhanga-waits-for-rama', 'hi', 'शरभंग जाने से पहले प्रतीक्षा करते हैं', 'शरभंग कहते हैं कि उन्होंने राम को देखने तक अपना प्रस्थान टाल दिया। राम मिले हुए स्वर्गलोक अस्वीकार कर पूछते हैं कि वन में उन्हें कहाँ रहना चाहिए।'),
  ('scene-forest-asks-protection', 'sarabhanga-enters-fire', 'en', 'An old body becomes a new departure', 'After directing Rama toward Sutikshna, Sarabhanga enters the fire and rises in a youthful form toward the worlds he had attained. The travellers witness rather than interrupt the departure.'),
  ('scene-forest-asks-protection', 'sarabhanga-enters-fire', 'hi', 'वृद्ध देह नया प्रस्थान बनती है', 'राम को सुतीक्ष्ण की ओर भेजकर शरभंग अग्नि में प्रवेश करते हैं और युवा रूप में अपने प्राप्त लोकों की ओर उठते हैं। यात्री इस प्रस्थान के साक्षी रहते हैं।'),
  ('scene-forest-asks-protection', 'many-communities-gather', 'en', 'The forest arrives in many forms', 'Ascetics with many disciplines gather after Sarabhanga''s departure. Their diversity makes clear that this is not one isolated household asking for help.'),
  ('scene-forest-asks-protection', 'many-communities-gather', 'hi', 'वन अनेक समुदायों के रूप में आता है', 'शरभंग के प्रस्थान के बाद अनेक प्रकार की साधना करने वाले तपस्वी जुटते हैं। उनकी विविधता बताती है कि सहायता माँगने वाला कोई एक अलग घर नहीं, पूरा समुदाय है।'),
  ('scene-forest-asks-protection', 'bodies-make-cost-visible', 'en', 'The cost is made visible', 'They show the remains of people killed along the rivers and near Chitrakoot and say the attacks repeatedly interrupt their lives. They ask Rama to become a refuge.'),
  ('scene-forest-asks-protection', 'bodies-make-cost-visible', 'hi', 'हानि आँखों के सामने रखी जाती है', 'वे नदियों और चित्रकूट के आसपास मारे गए लोगों के अवशेष दिखाते हैं और बताते हैं कि आक्रमण बार-बार उनके जीवन को तोड़ते हैं। वे राम से आश्रय बनने को कहते हैं।'),
  ('scene-forest-asks-protection', 'rama-makes-forest-promise', 'en', 'Rama accepts a wider obligation', 'Rama says they need not beg: their protection is work he accepts alongside his father''s command. The promise sends the travellers onward to Sutikshna and will soon be questioned by Sita.'),
  ('scene-forest-asks-protection', 'rama-makes-forest-promise', 'hi', 'राम व्यापक दायित्व स्वीकारते हैं', 'राम कहते हैं कि उन्हें विनती नहीं करनी चाहिए—उनकी सुरक्षा पिता की आज्ञा के साथ स्वीकार किया गया कार्य है। यही वचन यात्रियों को सुतीक्ष्ण की ओर भेजता है और शीघ्र ही सीता के प्रश्न का विषय बनेगा।'),
  ('scene-sita-questions-the-bow', 'sutikshna-offers-stay', 'en', 'Sutikshna offers a place to remain', 'Sutikshna welcomes the travellers and offers his hermitage, but Rama worries that hunting even the troublesome deer would hurt his host. They stay one night, then ask to see the wider Dandaka world.'),
  ('scene-sita-questions-the-bow', 'sutikshna-offers-stay', 'hi', 'सुतीक्ष्ण ठहरने का स्थान देते हैं', 'सुतीक्ष्ण यात्रियों का स्वागत कर अपना आश्रम देते हैं, पर राम सोचते हैं कि उपद्रवी हिरणों को मारना भी मेजबान को दुख देगा। वे एक रात रुककर व्यापक दण्डक-संसार देखने की अनुमति माँगते हैं।'),
  ('scene-sita-questions-the-bow', 'sita-hands-over-weapons', 'en', 'Sita hands them the weapons—and then speaks', 'At departure Sita gives the bows, quivers, and swords to the brothers. On the road she begins an affectionate warning about what those weapons may invite.'),
  ('scene-sita-questions-the-bow', 'sita-hands-over-weapons', 'hi', 'सीता हथियार देती हैं—और फिर बोलती हैं', 'प्रस्थान पर सीता भाइयों को धनुष, तरकश और तलवारें देती हैं। राह में वे स्नेह से चेताती हैं कि यही हथियार किस तरह की प्रवृत्ति बुला सकते हैं।'),
  ('scene-sita-questions-the-bow', 'three-dangerous-desires', 'en', 'She names three ways desire distorts action', 'Sita rules out falsehood and betrayal in Rama, then focuses on hostility without prior offence. The danger she sees is not protection itself, but making violence precede relationship or cause.'),
  ('scene-sita-questions-the-bow', 'three-dangerous-desires', 'hi', 'वे इच्छा से बिगड़ते तीन मार्ग गिनाती हैं', 'सीता राम में असत्य और विश्वासघात की संभावना नकारकर बिना पूर्व अपराध के शत्रुता पर ध्यान देती हैं। उनके लिए संकट सुरक्षा नहीं, संबंध या कारण से पहले हिंसा को रख देना है।'),
  ('scene-sita-questions-the-bow', 'sword-changes-ascetic', 'en', 'A sword changes the person guarding it', 'She tells of an ascetic entrusted with a sword who carries it everywhere, gradually abandons discipline, and becomes governed by fierce thoughts. A tool held for safekeeping reshapes its keeper.'),
  ('scene-sita-questions-the-bow', 'sword-changes-ascetic', 'hi', 'तलवार अपने रक्षक को बदल देती है', 'वे एक तपस्वी की कथा सुनाती हैं जिसे तलवार धरोहर में मिली, जो उसे हर जगह ले जाते-ले जाते साधना छोड़कर उग्र विचारों के अधीन हो गया। सुरक्षित रखने का साधन अपने रक्षक को ही बदल देता है।'),
  ('scene-sita-questions-the-bow', 'protect-do-not-preempt', 'en', 'Protection is not the same as pre-emption', 'Sita says a bow should rescue people already in danger, not turn every unknown forest being into an enemy. She asks Rama to think before acting, not to abandon responsibility.'),
  ('scene-sita-questions-the-bow', 'protect-do-not-preempt', 'hi', 'रक्षा और पहले से आक्रमण एक नहीं', 'सीता कहती हैं कि धनुष संकट में पड़े लोगों की रक्षा करे, हर अनजान वनवासी को शत्रु न बना दे। वे राम से दायित्व छोड़ने नहीं, कार्य से पहले विचार करने को कहती हैं।'),
  ('scene-sita-questions-the-bow', 'rama-answers-from-promise', 'en', 'Rama answers from the promise already made', 'Rama honours Sita''s concern but says people personally sought refuge and he promised protection. He treats her challenge as speech born from love, yet holds that breaking the promise would also be wrong. The tension remains visible.'),
  ('scene-sita-questions-the-bow', 'rama-answers-from-promise', 'hi', 'राम पहले किए वचन से उत्तर देते हैं', 'राम सीता की चिंता का सम्मान करते हैं, पर कहते हैं कि लोगों ने स्वयं शरण माँगी और उन्होंने रक्षा का वचन दिया है। वे उनके प्रश्न को प्रेम से निकली वाणी मानते हुए भी वचन तोड़ना अनुचित मानते हैं। तनाव समाप्त नहीं होता।'),
  ('scene-ten-years-become-map', 'forest-opens-in-layers', 'en', 'The road becomes landscape', 'Rama leads, Sita walks between the brothers, and Lakshmana follows. Peaks, streams, islands, lotus tanks, deer, buffalo, boar, and elephants make travel feel inhabited at every scale.'),
  ('scene-ten-years-become-map', 'forest-opens-in-layers', 'hi', 'राह भू-दृश्य बन जाती है', 'राम आगे, सीता बीच और लक्ष्मण पीछे चलते हैं। पर्वत, धाराएँ, द्वीप, कमल-सरोवर, हिरण, भैंसे, सूअर और हाथी हर स्तर पर यात्रा को जीवित बनाते हैं।'),
  ('scene-ten-years-become-map', 'music-without-musicians', 'en', 'A lake sings without visible musicians', 'At Panchapsara they hear instruments and song but see no performers. Dharmabhrit tells the wondrous story of Mandakarni, five Apsaras, interrupted austerity, and a hidden dwelling beneath the water.'),
  ('scene-ten-years-become-map', 'music-without-musicians', 'hi', 'एक सरोवर बिना दिखते वादकों के गाता है', 'पञ्चाप्सरा पर वे संगीत और गायन सुनते हैं, पर कोई कलाकार दिखाई नहीं देता। धर्मभृत मन्दकर्णि, पाँच अप्सराओं, बाधित तपस्या और जल के भीतर छिपे निवास की अद्भुत कथा सुनाते हैं।'),
  ('scene-ten-years-become-map', 'hermitages-not-one-stop', 'en', 'Dandaka is not one destination', 'The travellers live among many hermitages, returning to hosts and moving onward again. The forest world becomes a network rather than a single linear road.'),
  ('scene-ten-years-become-map', 'hermitages-not-one-stop', 'hi', 'दण्डक कोई एक पड़ाव नहीं', 'यात्री अनेक आश्रमों में रहते, पुराने मेजबानों के पास लौटते और फिर आगे बढ़ते हैं। वन-संसार एक सीधी राह नहीं, आपस में जुड़ा जाल बन जाता है।'),
  ('scene-ten-years-become-map', 'ten-years-pass-in-stays', 'en', 'Ten years pass through uneven stays', 'The selected edition names stays of months and years before saying ten years have passed. Devam keeps that compression visible instead of pretending every day or location is already reconstructed.'),
  ('scene-ten-years-become-map', 'ten-years-pass-in-stays', 'hi', 'दस वर्ष असमान ठहरावों में बीतते हैं', 'चुना हुआ संस्करण महीनों और वर्षों के अलग-अलग ठहराव गिनाकर कहता है कि दस वर्ष बीत गए। देवम इस संक्षेप को स्पष्ट रखता है—हर दिन या स्थान के पूर्ण पुनर्निर्माण का दावा नहीं करता।'),
  ('scene-ten-years-become-map', 'return-to-sutikshna', 'en', 'The long circuit returns to Sutikshna', 'After visiting the hermitage network, Rama returns to Sutikshna. The journey now needs a new destination, not simply another anonymous clearing.'),
  ('scene-ten-years-become-map', 'return-to-sutikshna', 'hi', 'लंबा चक्र सुतीक्ष्ण के पास लौटता है', 'आश्रम-जाल की यात्रा के बाद राम सुतीक्ष्ण के पास लौटते हैं। अब यात्रा को केवल एक और अनाम खुली जगह नहीं, नई दिशा चाहिए।'),
  ('scene-ten-years-become-map', 'agastya-becomes-direction', 'en', 'A name becomes the next direction', 'Rama says he has long wanted to meet Agastya. Sutikshna gives a southward route through Agastya''s brother''s hermitage, and the travellers set out the same day.'),
  ('scene-ten-years-become-map', 'agastya-becomes-direction', 'hi', 'एक नाम अगली दिशा बनता है', 'राम कहते हैं कि वे लंबे समय से अगस्त्य से मिलना चाहते हैं। सुतीक्ष्ण अगस्त्य के भाई के आश्रम से होकर दक्षिण की राह बताते हैं, और यात्री उसी दिन निकलते हैं।'),
  ('scene-agastya-points-south', 'southern-road-has-stories', 'en', 'The road already carries remembered stories', 'Rama reads smoke, fruit trees, birds, and pippali groves as signs of the route. He retells how Agastya ended the deadly deception of Vatapi and Ilwala, making the southward world habitable in this telling.'),
  ('scene-agastya-points-south', 'southern-road-has-stories', 'hi', 'राह पहले से कथाएँ लिए है', 'राम धुएँ, फलदार वृक्षों, पक्षियों और पिप्पली वन को राह के संकेत की तरह पढ़ते हैं। वे बताते हैं कि इस कथा में अगस्त्य ने वातापि-इल्वल की घातक छलना समाप्त कर दक्षिण दिशा को रहने योग्य बनाया।'),
  ('scene-agastya-points-south', 'lakshmana-announces-arrival', 'en', 'Lakshmana carries the names across the threshold', 'At Agastya''s hermitage, Lakshmana introduces Rama, Sita, and himself to a disciple and explains the forest command that brought them there. Agastya says he had long wished for their arrival.'),
  ('scene-agastya-points-south', 'lakshmana-announces-arrival', 'hi', 'लक्ष्मण देहरी पर नाम पहुँचाते हैं', 'अगस्त्य के आश्रम पर लक्ष्मण एक शिष्य को राम, सीता और अपना परिचय देकर बताते हैं कि पिता की आज्ञा उन्हें वन में लाई। अगस्त्य कहते हैं कि वे लंबे समय से उनके आने की इच्छा रखते थे।'),
  ('scene-agastya-points-south', 'agastya-receives-guests', 'en', 'Hospitality comes before instruction', 'Agastya embraces Rama, receives all three with water, food, flowers, and a seat, and names Rama a beloved guest. The encounter begins with care, not weapons.'),
  ('scene-agastya-points-south', 'agastya-receives-guests', 'hi', 'निर्देश से पहले आतिथ्य आता है', 'अगस्त्य राम को आलिंगन देकर तीनों का जल, भोजन, फूल और आसन से स्वागत करते हैं तथा राम को प्रिय अतिथि कहते हैं। भेंट की शुरुआत हथियारों से नहीं, देखभाल से होती है।'),
  ('scene-agastya-points-south', 'weapons-enter-as-stories', 'en', 'The weapons arrive with histories attached', 'Agastya gives Rama a bow associated with Vishnu, an arrow, inexhaustible quivers, and a sword. They are presented as storied gifts inside this epic—not archaeological objects or modern ritual implements.'),
  ('scene-agastya-points-south', 'weapons-enter-as-stories', 'hi', 'हथियार अपनी कथाओं के साथ आते हैं', 'अगस्त्य राम को विष्णु से जुड़ा धनुष, एक बाण, अक्षय तरकश और तलवार देते हैं। ये इस महाकाव्य के भीतर कथा-सम्पन्न उपहार हैं—पुरातात्त्विक वस्तु या आधुनिक अनुष्ठान-सामग्री नहीं।'),
  ('scene-agastya-points-south', 'agastya-sees-sitas-fatigue', 'en', 'Agastya sees Sita''s fatigue', 'Agastya explicitly notices that Sita has crossed hardship out of love and asks Rama to make the remaining forest life easier for her. The next home is chosen with her experience in view.'),
  ('scene-agastya-points-south', 'agastya-sees-sitas-fatigue', 'hi', 'अगस्त्य सीता की थकान देखते हैं', 'अगस्त्य स्पष्ट देखते हैं कि सीता प्रेम के कारण कठिन राह से गुज़री हैं और राम से शेष वनजीवन उनके लिए सहज बनाने को कहते हैं। अगला घर उनके अनुभव को ध्यान में रखकर चुना जाता है।'),
  ('scene-agastya-points-south', 'panchavati-opens-ahead', 'en', 'Panchavati becomes the next home', 'Asked for a well-watered place, Agastya names Panchavati near the Godavari, gives a narrative route past the Madhuka wood and a hill, and sends the three onward. The district ends before Jatayu appears.'),
  ('scene-agastya-points-south', 'panchavati-opens-ahead', 'hi', 'पञ्चवटी अगला घर बनती है', 'जल और वन से भरा स्थान पूछने पर अगस्त्य गोदावरी के पास पञ्चवटी का नाम लेते हैं, मधूक वन और पहाड़ी से होकर कथा-मार्ग बताते हैं और तीनों को विदा करते हैं। यह जिला जटायु के आने से ठीक पहले समाप्त होता है।'),
  ('scene-jatayu-welcomes-panchavati', 'vulture-shape-stops-road', 'en', 'A huge shape stops the road', 'On the way to Panchavati, Rama and Lakshmana see an enormous vulture and first suspect another disguised attacker. The forest still teaches caution before recognition.'),
  ('scene-jatayu-welcomes-panchavati', 'vulture-shape-stops-road', 'hi', 'एक विशाल आकृति राह रोकती है', 'पंचवटी जाते हुए राम और लक्ष्मण एक विशाल गिद्ध को देखकर पहले उसे रूप बदले आक्रमणकारी समझते हैं। पहचान से पहले वन उन्हें सावधानी सिखाता है।'),
  ('scene-jatayu-welcomes-panchavati', 'jatayu-names-friendship', 'en', 'Jatayu names an old friendship', 'Jatayu speaks gently, recalls friendship with Dasharatha, and gives his lineage. A frightening unknown becomes someone connected to the family left behind.'),
  ('scene-jatayu-welcomes-panchavati', 'jatayu-names-friendship', 'hi', 'जटायु पुरानी मित्रता का नाम लेते हैं', 'जटायु कोमल स्वर में बोलते हैं, दशरथ से अपनी मित्रता याद करते हैं और अपना वंश बताते हैं। भयावह अजनबी पीछे छूटे परिवार से जुड़ा साथी बन जाता है।'),
  ('scene-jatayu-welcomes-panchavati', 'guardian-offers-watch', 'en', 'An elder offers to keep watch', 'Jatayu offers to protect Sita whenever the brothers are away. Rama embraces him and accepts the bond before the group continues together.'),
  ('scene-jatayu-welcomes-panchavati', 'guardian-offers-watch', 'hi', 'एक वृद्ध साथी पहरा देने का वचन देते हैं', 'जटायु कहते हैं कि भाइयों के दूर रहने पर वे सीता की रक्षा करेंगे। राम उन्हें गले लगाकर यह संबंध स्वीकार करते हैं और सब साथ आगे बढ़ते हैं।'),
  ('scene-jatayu-welcomes-panchavati', 'godavari-home-is-chosen', 'en', 'The Godavari gives the home its shape', 'At Panchavati, Rama and Lakshmana choose ground near water, flowering woods, animals, and open sightlines. The setting is selected as a lived place, not a blank backdrop.'),
  ('scene-jatayu-welcomes-panchavati', 'godavari-home-is-chosen', 'hi', 'गोदावरी घर को आकार देती है', 'पंचवटी में राम और लक्ष्मण जल, फूलों से भरे वन, पशुओं और खुली दृष्टि वाले स्थान को चुनते हैं। यह कोई खाली पृष्ठभूमि नहीं, जीने योग्य जगह है।'),
  ('scene-jatayu-welcomes-panchavati', 'lakshmana-builds-panchavati', 'en', 'Lakshmana builds; the three enter', 'Lakshmana gathers timber, earth, grass, and leaves to build the cottage. Rama praises his care, and the travellers enter Panchavati as a household.'),
  ('scene-jatayu-welcomes-panchavati', 'lakshmana-builds-panchavati', 'hi', 'लक्ष्मण बनाते हैं; तीनों प्रवेश करते हैं', 'लक्ष्मण लकड़ी, मिट्टी, घास और पत्तों से कुटिया बनाते हैं। राम उनके स्नेहपूर्ण श्रम की प्रशंसा करते हैं और तीनों पंचवटी में परिवार की तरह प्रवेश करते हैं।'),
  ('scene-jatayu-welcomes-panchavati', 'winter-morning-remembers-bharata', 'en', 'A winter morning remembers Bharata', 'As winter arrives, the brothers walk to the Godavari and Lakshmana speaks of Bharata waiting in hardship. Quiet Panchavati still remains connected to distant Nandigrama.'),
  ('scene-jatayu-welcomes-panchavati', 'winter-morning-remembers-bharata', 'hi', 'शीत की सुबह भरत को याद करती है', 'शीत आने पर भाई गोदावरी की ओर चलते हैं और लक्ष्मण कठिन जीवन जी रहे भरत को याद करते हैं। शांत पंचवटी दूर नंदिग्राम से जुड़ी रहती है।'),
  ('scene-surpanakha-breaks-quiet', 'surpanakha-sees-rama', 'en', 'Surpanakha enters the clearing', 'Surpanakha encounters Rama near the cottage and asks who these ascetic-looking armed travellers are. Rama introduces himself, Sita, and Lakshmana and explains the exile.'),
  ('scene-surpanakha-breaks-quiet', 'surpanakha-sees-rama', 'hi', 'शूर्पणखा खुले स्थान में आती हैं', 'शूर्पणखा कुटिया के पास राम से मिलती हैं और तपस्वी वेश में शस्त्रधारी यात्रियों का परिचय पूछती हैं। राम अपना, सीता और लक्ष्मण का परिचय देकर वनवास बताते हैं।'),
  ('scene-surpanakha-breaks-quiet', 'desire-turns-to-proposal', 'en', 'Desire becomes a direct proposal', 'She names her own power and family, declares desire for Rama, and dismisses Sita and Lakshmana as obstacles. The conversation is charged before it becomes dangerous.'),
  ('scene-surpanakha-breaks-quiet', 'desire-turns-to-proposal', 'hi', 'आकर्षण सीधा प्रस्ताव बनता है', 'वह अपनी शक्ति और परिवार का परिचय देकर राम के प्रति इच्छा व्यक्त करती हैं तथा सीता और लक्ष्मण को बाधा कहती हैं। संवाद हिंसक होने से पहले ही तनाव से भर जाता है।'),
  ('scene-surpanakha-breaks-quiet', 'jest-passes-between-brothers', 'en', 'A jest passes responsibility away', 'Rama points to his marriage and jokingly redirects Surpanakha toward Lakshmana; Lakshmana answers with another jest. The scene preserves the playfulness while making its escalating consequence visible.'),
  ('scene-surpanakha-breaks-quiet', 'jest-passes-between-brothers', 'hi', 'परिहास उत्तरदायित्व को आगे बढ़ाता है', 'राम अपने विवाह की बात कहकर परिहास में शूर्पणखा को लक्ष्मण की ओर भेजते हैं; लक्ष्मण भी परिहास में उत्तर देते हैं। दृश्य हास्य को रखते हुए उसके बढ़ते परिणाम को भी दिखाता है।'),
  ('scene-surpanakha-breaks-quiet', 'rivalry-targets-sita', 'en', 'Rivalry turns toward Sita', 'Humiliated and enraged, Surpanakha rushes at Sita. Rama stops treating the encounter as play and orders immediate protection.'),
  ('scene-surpanakha-breaks-quiet', 'rivalry-targets-sita', 'hi', 'प्रतिस्पर्धा सीता की ओर मुड़ती है', 'अपमानित और क्रोधित शूर्पणखा सीता पर झपटती हैं। राम अब इस भेंट को खेल नहीं मानते और तत्काल रक्षा का आदेश देते हैं।'),
  ('scene-surpanakha-breaks-quiet', 'injury-opens-janasthana', 'en', 'A violent injury opens the road to Janasthana', 'Lakshmana disfigures Surpanakha. Bleeding and furious, she leaves for Khara; Devam presents the violence as the selected narrative''s escalation, not as comic punishment or endorsed conduct.'),
  ('scene-surpanakha-breaks-quiet', 'injury-opens-janasthana', 'hi', 'हिंसक चोट जनस्थान की राह खोलती है', 'लक्ष्मण शूर्पणखा को घायल और विरूप कर देते हैं। रक्तस्राव और क्रोध में वह खर के पास जाती हैं; देवम इस हिंसा को चुनी कथा की बढ़ती घटना मानता है, हास्यपूर्ण दंड या समर्थित आचरण नहीं।'),
  ('scene-janasthana-falls', 'surpanakha-reaches-khara', 'en', 'Surpanakha demands an answer', 'Surpanakha reaches Khara, names Rama, Lakshmana, and Sita, and frames her injury as an attack demanding blood. Khara first sends fourteen fighters with her.'),
  ('scene-janasthana-falls', 'surpanakha-reaches-khara', 'hi', 'शूर्पणखा प्रतिकार माँगती हैं', 'शूर्पणखा खर के पास पहुँचकर राम, लक्ष्मण और सीता का नाम लेती हैं तथा अपनी चोट को प्रतिशोध माँगता आक्रमण बताती हैं। खर पहले चौदह योद्धा उनके साथ भेजता है।'),
  ('scene-janasthana-falls', 'first-force-does-not-return', 'en', 'The first force does not return', 'At Panchavati, Rama places Sita under Lakshmana''s protection and defeats the attacking group. Surpanakha returns to Khara with the failure, making retreat less likely.'),
  ('scene-janasthana-falls', 'first-force-does-not-return', 'hi', 'पहला दल वापस नहीं आता', 'पंचवटी में राम सीता को लक्ष्मण की सुरक्षा में रखकर आए दल को पराजित करते हैं। शूर्पणखा असफलता लेकर खर के पास लौटती हैं और पीछे हटने की संभावना घट जाती है।'),
  ('scene-janasthana-falls', 'khara-mobilizes-janasthana', 'en', 'Khara mobilizes Janasthana', 'Pressed by Surpanakha, Khara orders Dushana to mobilize the larger force. Omens gather along the march, while Rama reads the approaching danger and sends Sita and Lakshmana to shelter.'),
  ('scene-janasthana-falls', 'khara-mobilizes-janasthana', 'hi', 'खर जनस्थान को युद्ध में उतारता है', 'शूर्पणखा के दबाव में खर दूषण को बड़ी सेना तैयार करने का आदेश देता है। यात्रा में अपशकुन उभरते हैं; राम खतरा पहचानकर सीता और लक्ष्मण को आश्रय में भेजते हैं।'),
  ('scene-janasthana-falls', 'rama-holds-open-ground', 'en', 'Rama holds the open ground alone', 'The battle unfolds in waves around Rama. Dushana and Trishira fall, and Khara''s confidence narrows into a direct confrontation.'),
  ('scene-janasthana-falls', 'rama-holds-open-ground', 'hi', 'राम खुले मैदान में अकेले ठहरते हैं', 'राम के चारों ओर युद्ध लहरों में फैलता है। दूषण और त्रिशिरा गिरते हैं तथा खर का विश्वास सीधे द्वंद्व तक सिमट जाता है।'),
  ('scene-janasthana-falls', 'khara-falls-at-janasthana', 'en', 'Khara falls; Janasthana changes hands', 'Rama defeats Khara after their exchange of accusation, boast, and weapons. The selected epic describes a devastating victory; the interface keeps its consequence larger than spectacle.'),
  ('scene-janasthana-falls', 'khara-falls-at-janasthana', 'hi', 'खर गिरता है; जनस्थान बदल जाता है', 'आरोप, गर्वोक्ति और शस्त्रों के आदान-प्रदान के बाद राम खर को पराजित करते हैं। चुना महाकाव्य विनाशकारी विजय बताता है; दृश्य तमाशे से अधिक उसके परिणाम पर टिकता है।'),
  ('scene-janasthana-falls', 'akampana-carries-news', 'en', 'One report escapes toward Ravana', 'Akampana reaches Ravana and reports the destruction. Instead of recommending direct combat with Rama, he proposes making Sita the point of separation.'),
  ('scene-janasthana-falls', 'akampana-carries-news', 'hi', 'एक समाचार रावण की ओर बच निकलता है', 'अकम्पन रावण तक पहुँचकर विनाश का समाचार देता है। राम से सीधे युद्ध के स्थान पर वह सीता को अलगाव का केंद्र बनाने की योजना सुझाता है।'),
  ('scene-ravana-chooses-deception', 'first-warning-from-maricha', 'en', 'Maricha warns against the first plan', 'Ravana first approaches Maricha after Akampana''s report. Maricha recalls Rama''s power and persuades him to turn back—for the moment.'),
  ('scene-ravana-chooses-deception', 'first-warning-from-maricha', 'hi', 'मारीच पहली योजना के विरुद्ध चेताते हैं', 'अकम्पन के समाचार के बाद रावण पहली बार मारीच के पास जाता है। मारीच राम की शक्ति याद दिलाकर उसे कुछ समय के लिए लौटने पर विवश करते हैं।'),
  ('scene-ravana-chooses-deception', 'surpanakha-enters-lanka', 'en', 'Surpanakha carries Janasthana into court', 'Surpanakha reaches Ravana''s court, condemns his inattention, describes the defeat, and makes Sita''s beauty part of her argument for action.'),
  ('scene-ravana-chooses-deception', 'surpanakha-enters-lanka', 'hi', 'शूर्पणखा जनस्थान को राजसभा तक लाती हैं', 'शूर्पणखा रावण की सभा में पहुँचकर उसकी असावधानी को ललकारती हैं, हार का वर्णन करती हैं और सीता के सौंदर्य को कार्रवाई के तर्क में बदल देती हैं।'),
  ('scene-ravana-chooses-deception', 'ravana-asks-for-every-detail', 'en', 'Ravana asks who Rama and Sita are', 'Ravana questions Surpanakha about Rama''s appearance, weapons, exile, and companions. Her answer turns curiosity into fixation and revenge into acquisition.'),
  ('scene-ravana-chooses-deception', 'ravana-asks-for-every-detail', 'hi', 'रावण राम और सीता का पूरा परिचय पूछता है', 'रावण शूर्पणखा से राम के रूप, शस्त्र, वनवास और साथियों के बारे में पूछता है। उत्तर जिज्ञासा को आसक्ति और प्रतिशोध को अधिकार की इच्छा में बदल देता है।'),
  ('scene-ravana-chooses-deception', 'maricha-remembers-rama', 'en', 'Maricha answers with remembered fear', 'When Ravana returns, Maricha recounts earlier encounters with Rama and describes a life ruled by the fear of seeing Rama everywhere. His counsel is specific, personal, and unwelcome.'),
  ('scene-ravana-chooses-deception', 'maricha-remembers-rama', 'hi', 'मारीच स्मृति के भय से उत्तर देते हैं', 'रावण के लौटने पर मारीच राम से पुरानी मुठभेड़ों और हर ओर राम दिखाई देने वाले भय का वर्णन करते हैं। उनकी सलाह निजी, स्पष्ट और अप्रिय है।'),
  ('scene-ravana-chooses-deception', 'warning-becomes-coercion', 'en', 'Warning becomes coercion', 'Ravana rejects the warning, threatens Maricha, and dictates the golden-deer role. Maricha chooses the danger he believes will at least end at Rama''s hand.'),
  ('scene-ravana-chooses-deception', 'warning-becomes-coercion', 'hi', 'चेतावनी दबाव में बदलती है', 'रावण चेतावनी ठुकराकर मारीच को धमकाता और स्वर्ण-मृग की भूमिका तय करता है। मारीच उस खतरे को चुनता है जिसका अंत कम से कम राम के हाथों होने की वह आशा करता है।'),
  ('scene-golden-deer-separates-house', 'impossible-deer-enters-light', 'en', 'An impossible deer enters the clearing', 'Maricha appears near the cottage as a deer marked with gold, silver, and jewel-like colour. Sita calls Rama and Lakshmana to see what has interrupted the ordinary forest.'),
  ('scene-golden-deer-separates-house', 'impossible-deer-enters-light', 'hi', 'एक असंभव मृग खुले स्थान में आता है', 'मारीच सोने, चाँदी और रत्न-जैसे रंगों से अंकित मृग बनकर कुटिया के पास आते हैं। सीता राम और लक्ष्मण को इस असामान्य वन-दृश्य को देखने बुलाती हैं।'),
  ('scene-golden-deer-separates-house', 'sita-asks-for-wonder', 'en', 'Sita asks to keep the wonder near', 'Sita asks Rama to capture the deer if possible, imagining it alive at their forest home or remembered later in Ayodhya. The request connects present delight with a future return.'),
  ('scene-golden-deer-separates-house', 'sita-asks-for-wonder', 'hi', 'सीता उस आश्चर्य को पास रखने की इच्छा कहती हैं', 'सीता राम से संभव हो तो मृग को पकड़ने को कहती हैं—वन-घर में जीवित साथी की तरह या अयोध्या लौटने पर स्मृति की तरह। इच्छा वर्तमान आनंद को भविष्य की वापसी से जोड़ती है।'),
  ('scene-golden-deer-separates-house', 'lakshmana-names-deception', 'en', 'Lakshmana suspects the image', 'Lakshmana says no natural deer bears such colours and suspects Maricha. Rama accepts the danger but decides that either capture or ending the threat justifies pursuit.'),
  ('scene-golden-deer-separates-house', 'lakshmana-names-deception', 'hi', 'लक्ष्मण दृश्य पर संदेह करते हैं', 'लक्ष्मण कहते हैं कि स्वाभाविक मृग के ऐसे रंग नहीं होते और मारीच पर संदेह करते हैं। राम खतरा मानते हुए भी उसे पकड़ने या संकट समाप्त करने के लिए पीछा करने का निर्णय लेते हैं।'),
  ('scene-golden-deer-separates-house', 'rama-follows-changing-distance', 'en', 'The chase keeps changing distance', 'The deer moves close, vanishes, reappears, and draws Rama far from Panchavati. When the deception can no longer be contained, Rama releases the fatal arrow.'),
  ('scene-golden-deer-separates-house', 'rama-follows-changing-distance', 'hi', 'पीछा लगातार दूरी बदलता है', 'मृग पास आता, गायब होता और फिर दिखकर राम को पंचवटी से दूर ले जाता है। जब छल को रोका नहीं जा सकता, राम घातक बाण छोड़ते हैं।'),
  ('scene-golden-deer-separates-house', 'maricha-borrows-rama-voice', 'en', 'Maricha sends one last weapon back', 'Dying, Maricha imitates Rama''s voice and cries out for Sita and Lakshmana. Rama immediately fears what the sound may do at the distant cottage.'),
  ('scene-golden-deer-separates-house', 'maricha-borrows-rama-voice', 'hi', 'मारीच अंतिम अस्त्र वापस भेजते हैं', 'मरते समय मारीच राम की आवाज़ में सीता और लक्ष्मण को पुकारते हैं। राम तुरंत समझते हैं कि दूर कुटिया पर यह ध्वनि क्या कर सकती है।'),
  ('scene-mendicant-at-empty-cottage', 'sita-hears-borrowed-cry', 'en', 'Sita hears Rama''s voice in danger', 'The imitated cry reaches Panchavati. Sita believes Rama is in danger and urges Lakshmana to go, while Lakshmana insists no ordinary foe could overcome him.'),
  ('scene-mendicant-at-empty-cottage', 'sita-hears-borrowed-cry', 'hi', 'सीता संकट में राम की आवाज़ सुनती हैं', 'नकली पुकार पंचवटी पहुँचती है। सीता मानती हैं कि राम संकट में हैं और लक्ष्मण को जाने को कहती हैं, जबकि लक्ष्मण कहते हैं कि कोई साधारण शत्रु राम को हरा नहीं सकता।'),
  ('scene-mendicant-at-empty-cottage', 'fear-wounds-the-conversation', 'en', 'Fear wounds the conversation', 'As Lakshmana remains, Sita speaks harsh accusations born from panic. Lakshmana rejects them, warns of ominous signs, and finally leaves to find Rama.'),
  ('scene-mendicant-at-empty-cottage', 'fear-wounds-the-conversation', 'hi', 'भय संवाद को घायल करता है', 'लक्ष्मण के रुकने पर घबराहट में सीता कठोर आरोप कहती हैं। लक्ष्मण उन्हें अस्वीकार कर अपशकुन की चेतावनी देते हैं और अंततः राम को खोजने निकलते हैं।'),
  ('scene-mendicant-at-empty-cottage', 'ravana-enters-as-guest', 'en', 'Ravana enters under the sign of a guest', 'Ravana approaches in the appearance of a mendicant, with dress and objects that invoke hospitality. The forest and cottage are described as recoiling even before Sita knows his identity.'),
  ('scene-mendicant-at-empty-cottage', 'ravana-enters-as-guest', 'hi', 'रावण अतिथि के रूप में प्रवेश करता है', 'रावण भिक्षु के रूप, वस्त्र और चिह्नों के साथ आते हैं जो आतिथ्य की अपेक्षा जगाते हैं। सीता के पहचानने से पहले ही वन और कुटिया मानो पीछे हटते दिखाई देते हैं।'),
  ('scene-mendicant-at-empty-cottage', 'sita-offers-water-and-name', 'en', 'Sita offers hospitality and names herself', 'Sita offers water and food and, when questioned, tells her identity, marriage, and exile. Her account is spoken before the guest-mask falls.'),
  ('scene-mendicant-at-empty-cottage', 'sita-offers-water-and-name', 'hi', 'सीता आतिथ्य देती और अपना परिचय बताती हैं', 'सीता जल और भोजन देती हैं तथा पूछे जाने पर अपना परिचय, विवाह और वनवास बताती हैं। अतिथि का मुखौटा उतरने से पहले उनकी कथा उनके अपने शब्दों में आती है।'),
  ('scene-mendicant-at-empty-cottage', 'waiting-becomes-recognition', 'en', 'Waiting becomes recognition', 'Sita wonders why Rama and Lakshmana have not returned. Ravana''s questions and praise become increasingly possessive, and the protected logic of guest and host begins to collapse.'),
  ('scene-mendicant-at-empty-cottage', 'waiting-becomes-recognition', 'hi', 'प्रतीक्षा पहचान में बदलती है', 'सीता सोचती हैं कि राम और लक्ष्मण अभी तक क्यों नहीं लौटे। रावण के प्रश्न और प्रशंसा अधिकार जताने लगते हैं और अतिथि-गृहस्थ का सुरक्षित संबंध टूटने लगता है।'),
  ('scene-sita-carried-south', 'sita-names-rama-first', 'en', 'Sita answers by naming Rama', 'Sita describes Rama''s character, strength, and commitment before asking the visitor''s identity. Her speech establishes the relationship Ravana is trying to erase.'),
  ('scene-sita-carried-south', 'sita-names-rama-first', 'hi', 'सीता पहले राम का नाम लेकर उत्तर देती हैं', 'सीता आगंतुक की पहचान पूछने से पहले राम के चरित्र, शक्ति और निष्ठा का वर्णन करती हैं। उनकी वाणी उस संबंध को स्थापित करती है जिसे रावण मिटाना चाहता है।'),
  ('scene-sita-carried-south', 'ravana-reveals-name-and-power', 'en', 'The guest reveals Ravana', 'Ravana names himself, boasts of Lanka and power, and proposes that Sita leave with him. The mendicant guise gives way to the figure behind the threat.'),
  ('scene-sita-carried-south', 'ravana-reveals-name-and-power', 'hi', 'अतिथि अपना रावण रूप प्रकट करता है', 'रावण अपना नाम, लंका और शक्ति का गर्व बताते हुए सीता को साथ चलने का प्रस्ताव देता है। भिक्षु का वेश हटकर संकट का वास्तविक रूप सामने आता है।'),
  ('scene-sita-carried-south', 'sita-refuses-the-claim', 'en', 'Sita refuses possession', 'Sita rejects Ravana''s threats and comparisons, warns that taking her is impossible to separate from confronting Rama, and refuses to convert fear into consent.'),
  ('scene-sita-carried-south', 'sita-refuses-the-claim', 'hi', 'सीता अधिकार के दावे को ठुकराती हैं', 'सीता रावण की धमकियों और तुलना को अस्वीकार करती हैं, कहती हैं कि उनका हरण राम से सामना किए बिना संभव नहीं और भय को सहमति में बदलने से इंकार करती हैं।'),
  ('scene-sita-carried-south', 'forest-is-called-to-witness', 'en', 'The forest is called to witness', 'As Ravana seizes and lifts her away, Sita cries to trees, river, mountain, birds, and animals to carry news to Rama. The landscape becomes an active network of witnesses.'),
  ('scene-sita-carried-south', 'forest-is-called-to-witness', 'hi', 'वन को साक्षी पुकारा जाता है', 'रावण के उठाकर ले जाते समय सीता वृक्षों, नदी, पर्वत, पक्षियों और पशुओं से राम तक समाचार पहुँचाने की पुकार करती हैं। भू-दृश्य साक्षियों का सक्रिय जाल बन जाता है।'),
  ('scene-sita-carried-south', 'panchavati-falls-away', 'en', 'The home falls away below', 'Panchavati recedes as Sita continues to resist, reason, threaten, and call for help. The story does not reduce the scene to silent removal.'),
  ('scene-sita-carried-south', 'panchavati-falls-away', 'hi', 'घर नीचे छूट जाता है', 'पंचवटी नीचे दूर होती जाती है और सीता विरोध, तर्क, चेतावनी तथा सहायता की पुकार जारी रखती हैं। कथा इस दृश्य को मौन ले जाए जाने तक सीमित नहीं करती।'),
  ('scene-jatayu-rises-sky-road', 'jatayu-wakes-to-sitas-call', 'en', 'Jatayu wakes to Sita''s call', 'Hearing Sita, Jatayu sees Ravana carrying her away. The guardian''s earlier promise returns at the moment it is most difficult to keep.'),
  ('scene-jatayu-rises-sky-road', 'jatayu-wakes-to-sitas-call', 'hi', 'जटायु सीता की पुकार से जागते हैं', 'सीता की पुकार सुनकर जटायु रावण को उन्हें ले जाते देखते हैं। पहले दिया रक्षा-वचन उसी क्षण लौटता है जब उसे निभाना सबसे कठिन है।'),
  ('scene-jatayu-rises-sky-road', 'jatayu-challenges-ravana', 'en', 'An elder challenges a king', 'Jatayu invokes age, friendship, kingship, and duty, urging Ravana to release Sita. He does not mistake unequal strength for permission to remain still.'),
  ('scene-jatayu-rises-sky-road', 'jatayu-challenges-ravana', 'hi', 'एक वृद्ध पक्षी राजा को चुनौती देता है', 'जटायु आयु, मित्रता, राजधर्म और कर्तव्य की बात करके रावण से सीता को छोड़ने को कहते हैं। असमान शक्ति उनके लिए निष्क्रिय रहने की अनुमति नहीं बनती।'),
  ('scene-jatayu-rises-sky-road', 'wings-break-the-flight', 'en', 'Wings break the flight''s certainty', 'Jatayu attacks the chariot, weapons, and Ravana himself, disrupting the abduction and bringing the struggle close to the ground. Sita watches resistance appear where there had been no defender.'),
  ('scene-jatayu-rises-sky-road', 'wings-break-the-flight', 'hi', 'पंख उड़ान की निश्चितता तोड़ते हैं', 'जटायु रथ, शस्त्र और स्वयं रावण पर आक्रमण कर हरण की गति तोड़ते और संघर्ष को धरती के पास ले आते हैं। जहाँ कोई रक्षक नहीं था, वहाँ सीता प्रतिरोध उभरते देखती हैं।'),
  ('scene-jatayu-rises-sky-road', 'jatayu-falls-after-resistance', 'en', 'Jatayu falls after resistance', 'Ravana cuts down the aged defender and resumes the southward journey. Sita embraces the fallen ally in grief before being forced onward.'),
  ('scene-jatayu-rises-sky-road', 'jatayu-falls-after-resistance', 'hi', 'प्रतिरोध के बाद जटायु गिरते हैं', 'रावण वृद्ध रक्षक को गिराकर दक्षिण की यात्रा फिर शुरू करता है। आगे ले जाए जाने से पहले सीता शोक में घायल साथी को गले लगाती हैं।'),
  ('scene-jatayu-rises-sky-road', 'sita-keeps-speaking-south', 'en', 'Sita keeps speaking to the world', 'Carried onward, Sita continues to condemn Ravana and call for Rama and Lakshmana. Her voice keeps the route populated by witnesses rather than empty distance.'),
  ('scene-jatayu-rises-sky-road', 'sita-keeps-speaking-south', 'hi', 'सीता संसार से बोलती रहती हैं', 'आगे ले जाए जाते हुए सीता रावण की निंदा और राम-लक्ष्मण को पुकारना जारी रखती हैं। उनकी आवाज़ मार्ग को खाली दूरी नहीं, साक्षियों से भरा संसार बनाए रखती है।'),
  ('scene-jatayu-rises-sky-road', 'ornaments-become-trail', 'en', 'Ornaments become a trail', 'Seeing five vanaras below, Sita drops cloth and ornaments in the hope that they can carry news. The district ends with evidence falling back into the world, not with the route erased.'),
  ('scene-jatayu-rises-sky-road', 'ornaments-become-trail', 'hi', 'आभूषण खोज-निशान बनते हैं', 'नीचे पाँच वानरों को देखकर सीता वस्त्र और आभूषण इस आशा से गिराती हैं कि वे समाचार पहुँचा सकें। जिला रास्ता मिटने पर नहीं, संसार में खोज-साक्ष्य गिरने पर समाप्त होता है।'),
  ('scene-leave-lanka', 'honour-the-allies', 'en', 'Before anyone leaves', 'Vibhishana asks what remains to be done. Rama''s first answer is not about himself: honour the vanaras and bears who risked their lives in the war.'),
  ('scene-leave-lanka', 'honour-the-allies', 'hi', 'प्रस्थान से पहले', 'विभीषण पूछते हैं कि अब क्या करना बाकी है। राम का पहला उत्तर अपने लिए नहीं है—उन वानरों और भालुओं का सम्मान हो जिन्होंने युद्ध में अपना जीवन दाँव पर लगाया।'),
  ('scene-leave-lanka', 'friends-ask-to-come', 'en', 'One more request', 'Rama releases his allies to their own homes. They ask instead to travel with him, see Ayodhya, witness the coronation, and only then depart.'),
  ('scene-leave-lanka', 'friends-ask-to-come', 'hi', 'एक और आग्रह', 'राम अपने साथियों को उनके घर लौटने की अनुमति देते हैं। वे आग्रह करते हैं कि पहले उनके साथ अयोध्या चलें, राज्याभिषेक देखें, फिर विदा हों।'),
  ('scene-leave-lanka', 'sita-and-lakshmana-board', 'en', 'The returning company gathers', 'Sita and Lakshmana board with Rama. Sugriva, Vibhishana, vanaras, bears, and rakshasa companions fill the extraordinary craft without being left behind.'),
  ('scene-leave-lanka', 'sita-and-lakshmana-board', 'hi', 'वापसी का दल जुटता है', 'सीता और लक्ष्मण राम के साथ चढ़ते हैं। सुग्रीव, विभीषण, वानर, भालू और राक्षस साथी भी उस अद्भुत विमान में स्थान पाते हैं।'),
  ('scene-leave-lanka', 'pushpaka-rises', 'en', 'Lanka falls away', 'At Rama''s command, the Pushpaka rises into the sky. For the first time since the exile began, home is not only a hope—it is the direction of travel.'),
  ('scene-leave-lanka', 'pushpaka-rises', 'hi', 'लंका पीछे छूटती है', 'राम के आदेश पर पुष्पक आकाश में उठता है। वनवास शुरू होने के बाद पहली बार घर केवल आशा नहीं, यात्रा की दिशा बन जाता है।'),
  ('scene-sky-road', 'battlefield-and-bridge', 'en', 'The cost below', 'Rama shows Sita Lanka, the battlefield, the ocean, and the bridge. Each place carries the memory of companions, losses, choices, and the effort made to find her.'),
  ('scene-sky-road', 'battlefield-and-bridge', 'hi', 'नीचे छूटी कीमत', 'राम सीता को लंका, युद्धभूमि, समुद्र और सेतु दिखाते हैं। हर स्थान साथियों, हानि, निर्णय और उन्हें खोजने के प्रयास की स्मृति लिए है।'),
  ('scene-sky-road', 'kishkindha-companions', 'en', 'The journey grows', 'At Kishkindha, Sita asks that Tara and the other vanara women join them. The homecoming expands again: it will be witnessed by the families behind the alliance.'),
  ('scene-sky-road', 'kishkindha-companions', 'hi', 'यात्रा का दल बढ़ता है', 'किष्किंधा में सीता चाहती हैं कि तारा और अन्य वानर स्त्रियाँ भी साथ चलें। घर-वापसी फिर बड़ी हो जाती है—अब गठबंधन के पीछे खड़े परिवार भी उसके साक्षी होंगे।'),
  ('scene-sky-road', 'places-become-memories', 'en', 'A story written across the land', 'Rishyamuka, Pampa, Panchavati, the Godavari, Chitrakuta, Yamuna, Ganga, and Shringavera appear below. The names are not a list: friendship, grief, abduction, searching, and endurance return with them.'),
  ('scene-sky-road', 'places-become-memories', 'hi', 'धरती पर लिखी कथा', 'ऋष्यमूक, पम्पा, पंचवटी, गोदावरी, चित्रकूट, यमुना, गंगा और शृंगवेरपुर नीचे उभरते हैं। ये केवल नाम नहीं—मित्रता, शोक, हरण, खोज और धैर्य फिर जीवित होते हैं।'),
  ('scene-sky-road', 'ayodhya-in-sight', 'en', 'Home appears', 'Ayodhya finally comes into view. Rama asks Sita to bow toward it, and the whole company rises to look at the city they have crossed an epic to reach.'),
  ('scene-sky-road', 'ayodhya-in-sight', 'hi', 'घर दिखाई देता है', 'अंततः अयोध्या दिखाई देती है। राम सीता से उसे प्रणाम करने को कहते हैं, और पूरा दल उस नगरी को देखने उठ खड़ा होता है जहाँ पहुँचने के लिए उन्होंने एक महाकाव्य पार किया है।'),
  ('scene-bharadvaja-hermitage', 'fourteen-years-complete', 'en', 'The vow reaches its edge', 'With the fourteen years complete, Rama reaches Bharadvaja''s hermitage and bows. Before asking about celebration or power, he asks whether Ayodhya is well, Bharata still protects it, and his mothers live.'),
  ('scene-bharadvaja-hermitage', 'fourteen-years-complete', 'hi', 'प्रतिज्ञा की अवधि पूरी', 'चौदह वर्ष पूरे होने पर राम भरद्वाज के आश्रम पहुँचकर प्रणाम करते हैं। उत्सव या सत्ता से पहले वे पूछते हैं—क्या अयोध्या कुशल है, क्या भरत अब भी उसकी रक्षा कर रहे हैं, क्या उनकी माताएँ जीवित हैं।'),
  ('scene-bharadvaja-hermitage', 'bharata-waits', 'en', 'The sandals still lead', 'Bharadvaja answers that Bharata waits with matted hair, honouring Rama''s sandals and ruling in obedience to his command. The household is safe.'),
  ('scene-bharadvaja-hermitage', 'bharata-waits', 'hi', 'पादुकाएँ अब भी आगे हैं', 'भरद्वाज बताते हैं कि भरत जटाएँ धारण किए राम की पादुकाओं का सम्मान करते हुए उनकी आज्ञा के अनुसार राज्य संभाल रहे हैं। राजपरिवार सुरक्षित है।'),
  ('scene-bharadvaja-hermitage', 'the-journey-is-known', 'en', 'Nothing was unseen', 'The sage recounts the exile''s great turns—Sita''s abduction, Sugriva''s alliance, Hanuman''s search, the bridge, and Ravana''s defeat. Rama arrives not as a rumour but as someone whose ordeal is understood.'),
  ('scene-bharadvaja-hermitage', 'the-journey-is-known', 'hi', 'कुछ भी अनदेखा नहीं रहा', 'ऋषि वनवास के बड़े मोड़ गिनाते हैं—सीता का हरण, सुग्रीव से मैत्री, हनुमान की खोज, सेतु और रावण की पराजय। राम किसी अफवाह की तरह नहीं, समझे गए संघर्ष के साथ लौटते हैं।'),
  ('scene-bharadvaja-hermitage', 'road-of-fruit', 'en', 'Hospitality for the whole company', 'Rama asks for one boon: let the road ahead bear fruit and honey for his companions. The trees flower out of season, and the weary vanaras find abundance on the final approach.'),
  ('scene-bharadvaja-hermitage', 'road-of-fruit', 'hi', 'पूरे दल के लिए आतिथ्य', 'राम एक वर माँगते हैं—आगे की राह पर उनके साथियों के लिए फल और मधु उपलब्ध हों। वृक्ष असमय फूल-फल उठते हैं और अंतिम पड़ाव पर थके वानरों को भरपूर आहार मिलता है।'),
  ('scene-hanuman-goes-ahead', 'read-bharatas-heart', 'en', 'A delicate mission', 'Rama sends Hanuman ahead not only to announce the return, but to observe Bharata''s face, words, and wishes. Fourteen years with a kingdom could have changed anyone.'),
  ('scene-hanuman-goes-ahead', 'read-bharatas-heart', 'hi', 'एक संवेदनशील दायित्व', 'राम हनुमान को केवल वापसी का समाचार देने नहीं, भरत के चेहरे, शब्द और इच्छा को समझने भी भेजते हैं। चौदह वर्ष और एक राज्य किसी को भी बदल सकते थे।'),
  ('scene-hanuman-goes-ahead', 'news-for-guha', 'en', 'An old friendship is remembered', 'Hanuman first reaches Guha at Shringavera and tells him that his friend Rama is safe and near. The return follows the same human bonds that once helped the exiles leave.'),
  ('scene-hanuman-goes-ahead', 'news-for-guha', 'hi', 'पुरानी मित्रता याद रहती है', 'हनुमान पहले शृंगवेरपुर में गुह के पास पहुँचकर बताते हैं कि उनके मित्र राम सुरक्षित और निकट हैं। वापसी उन्हीं मानवीय संबंधों से होकर गुजरती है जिन्होंने वनवास के आरंभ में सहारा दिया था।'),
  ('scene-hanuman-goes-ahead', 'nandigrama-waiting', 'en', 'The ruler who never took the throne', 'At Nandigrama, Hanuman finds Bharata thin from restraint, dressed like an ascetic, ruling with Rama''s sandals before him. The years of waiting are visible before a word is spoken.'),
  ('scene-hanuman-goes-ahead', 'nandigrama-waiting', 'hi', 'जिसने सिंहासन नहीं लिया', 'नंदिग्राम में हनुमान भरत को संयम से क्षीण, तपस्वी वेश में और सामने राम की पादुकाएँ रखकर शासन करते देखते हैं। एक शब्द बोले जाने से पहले ही वर्षों की प्रतीक्षा दिखाई देती है।'),
  ('scene-hanuman-goes-ahead', 'the-message-lands', 'en', 'Grief breaks into joy', 'Hanuman says that Rama has defeated Ravana, recovered Sita, and returned with Lakshmana and his allies. Bharata collapses in sudden joy, then rises to hear everything.'),
  ('scene-hanuman-goes-ahead', 'the-message-lands', 'hi', 'शोक आनंद में टूटता है', 'हनुमान बताते हैं कि राम ने रावण को पराजित किया, सीता को वापस पाया और लक्ष्मण व साथियों के साथ लौट आए हैं। भरत अचानक आनंद से मूर्छित हो जाते हैं, फिर उठकर पूरी कथा सुनना चाहते हैं।'),
  ('scene-bharata-hears', 'tell-me-how', 'en', 'How did this become possible?', 'Bharata does not stop at the headline that Rama lives. He asks Hanuman how Rama met the vanaras and how the years after Chitrakuta unfolded.'),
  ('scene-bharata-hears', 'tell-me-how', 'hi', 'यह सब कैसे संभव हुआ?', 'भरत केवल यह सुनकर नहीं रुकते कि राम जीवित हैं। वे हनुमान से पूछते हैं कि राम वानरों से कैसे मिले और चित्रकूट के बाद के वर्ष कैसे बीते।'),
  ('scene-bharata-hears', 'forest-turns', 'en', 'The road through loss', 'Hanuman tells of the forest dangers, Surpanakha, the golden deer, Sita''s abduction, and Jatayu''s fall. The reunion ahead is measured against what was taken away.'),
  ('scene-bharata-hears', 'forest-turns', 'hi', 'हानि से गुजरती राह', 'हनुमान वन के संकट, शूर्पणखा, स्वर्ण-मृग, सीता के हरण और जटायु के पतन की कथा कहते हैं। आने वाला मिलन अब उस सबके सामने दिखाई देता है जो छिन गया था।'),
  ('scene-bharata-hears', 'alliance-and-search', 'en', 'Strangers become the search', 'He recounts the meeting with Sugriva, the vanara search, Sampati''s clue, his own leap to Lanka, Sita in the ashoka grove, and the ring that proved Rama had found a path to her.'),
  ('scene-bharata-hears', 'alliance-and-search', 'hi', 'अजनबी खोज के साथी बनते हैं', 'वे सुग्रीव से भेंट, वानर दलों की खोज, संपाती के संकेत, अपनी लंका-छलाँग, अशोक-वाटिका में सीता और राम की मुद्रिका की कथा सुनाते हैं।'),
  ('scene-bharata-hears', 'bridge-battle-return', 'en', 'The whole road closes', 'The bridge, the battle, Ravana''s defeat, and the Pushpaka return bring the account to the present. Bharata folds his hands: after so long, the desire to see Rama can finally be fulfilled.'),
  ('scene-bharata-hears', 'bridge-battle-return', 'hi', 'पूरी राह एक साथ जुड़ती है', 'सेतु, युद्ध, रावण की पराजय और पुष्पक से वापसी कथा को वर्तमान तक ले आते हैं। भरत हाथ जोड़ते हैं—इतने लंबे समय बाद राम को देखने की इच्छा अब पूरी होगी।'),
  ('scene-ayodhya-prepares', 'city-awakens', 'en', 'Tell everyone', 'Bharata orders worship, music, and a welcome open to the royal household, soldiers, families, artists, and citizens. Rama''s return belongs to the city, not only the palace.'),
  ('scene-ayodhya-prepares', 'city-awakens', 'hi', 'सबको समाचार दो', 'भरत पूजा, संगीत और ऐसा स्वागत तैयार करने का आदेश देते हैं जिसमें राजपरिवार, सैनिक, परिवार, कलाकार और नागरिक सब शामिल हों। राम की वापसी केवल महल की नहीं, पूरे नगर की है।'),
  ('scene-ayodhya-prepares', 'prepare-the-road', 'en', 'A road made ready', 'Shatrughna has the route from Nandigrama levelled, watered, strewn with flowers, and lined with flags. The landscape itself becomes part of the welcome.'),
  ('scene-ayodhya-prepares', 'prepare-the-road', 'hi', 'राह सजती है', 'शत्रुघ्न नंदिग्राम से आने वाली राह समतल और जल-सिंचित करवाते हैं; फूल बिखरते हैं और ध्वज लगते हैं। भू-दृश्य स्वयं स्वागत का हिस्सा बन जाता है।'),
  ('scene-ayodhya-prepares', 'sandals-lead-procession', 'en', 'The promise goes first', 'Still dressed in bark, Bharata carries Rama''s sandals on his head as the queens, ministers, citizens, horses, chariots, and elephants move toward Nandigrama.'),
  ('scene-ayodhya-prepares', 'sandals-lead-procession', 'hi', 'प्रतिज्ञा सबसे आगे', 'अब भी वल्कल पहने भरत राम की पादुकाएँ सिर पर रखते हैं। रानियाँ, मंत्री, नागरिक, घोड़े, रथ और हाथी नंदिग्राम की ओर बढ़ते हैं।'),
  ('scene-ayodhya-prepares', 'brothers-meet', 'en', 'The distance ends', 'The Pushpaka descends. Rama lifts Bharata into an embrace; Bharata greets Sita, Lakshmana, and the allies, then places the sandals back at Rama''s feet and returns the kingdom held in trust.'),
  ('scene-ayodhya-prepares', 'brothers-meet', 'hi', 'दूरी समाप्त होती है', 'पुष्पक उतरता है। राम भरत को उठाकर गले लगाते हैं; भरत सीता, लक्ष्मण और साथियों का स्वागत करते हैं, फिर पादुकाएँ राम के चरणों में रखकर धरोहर की तरह संभाला राज्य लौटा देते हैं।'),
  ('scene-kingdom-returned', 'bharata-returns-burden', 'en', 'Take back what I guarded', 'Bharata tells Rama that the kingdom was never his possession and that he cannot carry its burden in Rama''s place. Rama answers, ''So be it.'''),
  ('scene-kingdom-returned', 'bharata-returns-burden', 'hi', 'जिसे संभाला, उसे वापस लो', 'भरत राम से कहते हैं कि राज्य कभी उनकी संपत्ति नहीं था और वे राम के स्थान पर उसका भार नहीं उठा सकते। राम स्वीकार करते हैं।'),
  ('scene-kingdom-returned', 'exile-clothes-fall-away', 'en', 'The signs of exile are removed', 'Rama, Lakshmana, Bharata, Sugriva, and Vibhishana bathe; the matted hair is cut and ceremonial clothes are prepared. Sita and the vanara women are adorned for the entry.'),
  ('scene-kingdom-returned', 'exile-clothes-fall-away', 'hi', 'वनवास के चिह्न उतरते हैं', 'राम, लक्ष्मण, भरत, सुग्रीव और विभीषण स्नान करते हैं; जटाएँ काटी जाती हैं और राजकीय वस्त्र तैयार होते हैं। सीता और वानर स्त्रियाँ नगर-प्रवेश के लिए सजती हैं।'),
  ('scene-kingdom-returned', 'city-entry', 'en', 'Ayodhya receives the whole story', 'Music and crowds accompany the entry. Rama publicly tells Ayodhya about Sugriva''s friendship, Hanuman''s prowess, and the work of the allies, so the victory is not reduced to one hero.'),
  ('scene-kingdom-returned', 'city-entry', 'hi', 'अयोध्या पूरी कथा का स्वागत करती है', 'संगीत और जनसमूह नगर-प्रवेश के साथ चलते हैं। राम अयोध्या को सुग्रीव की मित्रता, हनुमान के पराक्रम और सभी साथियों के कार्य बताते हैं, ताकि विजय केवल एक नायक की न रह जाए।'),
  ('scene-kingdom-returned', 'coronation-and-gifts', 'en', 'A crown, then gratitude', 'Vasishta and the gathered officiants install Rama with Sita beside him. Honours move outward to the allies; Sita gives Hanuman the pearl necklace, remembering his service.'),
  ('scene-kingdom-returned', 'coronation-and-gifts', 'hi', 'मुकुट, फिर कृतज्ञता', 'वसिष्ठ और अन्य आचार्य सीता के साथ राम का राज्याभिषेक करते हैं। सम्मान साथियों तक पहुँचता है; सीता हनुमान की सेवा याद कर उन्हें मोतियों का हार देती हैं।'),
  ('scene-kingdom-returned', 'rule-begins', 'en', 'The ending opens into duty', 'The companions eventually return to their own worlds, and governance begins. The selected telling closes with an idealized vision of Rama''s reign; Devam presents that as this source''s sacred narrative, not a modern historical statistic.'),
  ('scene-kingdom-returned', 'rule-begins', 'hi', 'अंत से कर्तव्य शुरू होता है', 'साथी अंततः अपने-अपने लोक लौटते हैं और शासन आरंभ होता है। चुना हुआ पाठ राम-राज्य की आदर्श छवि के साथ समाप्त होता है; देवम इसे इसी स्रोत की पवित्र कथा मानता है, आधुनिक ऐतिहासिक आँकड़ा नहीं।')
) as copy(moment_slug, beat_slug, language_code, title, narration)
join public.narrative_series series on series.slug = 'ramayana-dutt-consumer-v1'
join public.narrative_moments moment on moment.series_id = series.id and moment.slug = copy.moment_slug
join public.narrative_beats beat on beat.moment_id = moment.id and beat.slug = copy.beat_slug
on conflict (beat_id, language_code) do update set
  title = excluded.title,
  narration = excluded.narration,
  text_status = excluded.text_status,
  rights_lane = excluded.rights_lane,
  publication_state = excluded.publication_state,
  updated_at = now();

delete from public.narrative_moment_links link
using public.narrative_moments source, public.narrative_series series
where link.source_moment_id = source.id
  and source.series_id = series.id
  and series.slug = 'ramayana-dutt-consumer-v1'
  and link.label = 'generated narrative order';

